/**
 * Latest-position mailbox between Android's main-thread input owner and the display producer.
 *
 * MOVE coordinates are absolute, so coalescing older samples cannot change the requested physical
 * position. Timing evidence is merged conservatively while the current gesture generation keeps a
 * MOVE taken just before UP/CANCEL from being applied after that terminal event.
 */
internal data class NtkQueuedPhysicalMove(
    val generation: Long,
    val y: Float,
    val eventTimeMs: Long,
    val oldestEventTimeMs: Long,
    val newestEventTimeMs: Long,
    val receivedOldestNanos: Long,
    val receivedNewestNanos: Long,
    val eventCount: Int,
    val historySampleCount: Int,
)

internal class NtkPhysicalMoveMailbox {
    private val generation = AtomicLong(0L)
    private val pending = AtomicReference<NtkQueuedPhysicalMove?>(null)
    private val drainReserved = AtomicBoolean(false)

    fun beginGesture(): Long {
        pending.set(null)
        return advanceGeneration()
    }

    fun endGesture() {
        advanceGeneration()
        pending.set(null)
    }

    fun currentGeneration(): Long = generation.get()

    fun isCurrent(candidate: Long): Boolean = candidate > 0L && candidate == generation.get()

    /** Returns true only for the caller that must post the singleton drain runnable. */
    fun offer(sample: NtkQueuedPhysicalMove): Boolean {
        if (!isCurrent(sample.generation)) return false
        while (true) {
            val previous = pending.get()
            val merged = if (previous == null || previous.generation != sample.generation) {
                sample
            } else {
                NtkQueuedPhysicalMove(
                    generation = sample.generation,
                    y = sample.y,
                    eventTimeMs = maxOf(previous.eventTimeMs, sample.eventTimeMs),
                    oldestEventTimeMs = minOf(
                        previous.oldestEventTimeMs,
                        sample.oldestEventTimeMs,
                    ),
                    newestEventTimeMs = maxOf(
                        previous.newestEventTimeMs,
                        sample.newestEventTimeMs,
                    ),
                    receivedOldestNanos = minOf(
                        previous.receivedOldestNanos,
                        sample.receivedOldestNanos,
                    ),
                    receivedNewestNanos = maxOf(
                        previous.receivedNewestNanos,
                        sample.receivedNewestNanos,
                    ),
                    eventCount = previous.eventCount + sample.eventCount,
                    historySampleCount =
                        previous.historySampleCount + sample.historySampleCount,
                )
            }
            if (pending.compareAndSet(previous, merged)) break
        }
        return drainReserved.compareAndSet(false, true)
    }

    fun take(): NtkQueuedPhysicalMove? = pending.getAndSet(null)?.takeIf {
        isCurrent(it.generation)
    }

    /**
     * Releases the completed drain and closes the offer-vs-drain race. A true result means the
     * drain itself reserved the next post; otherwise the offering thread already owns that post.
     */
    fun finishDrainAndReserveNext(): Boolean {
        drainReserved.set(false)
        return pending.get() != null && drainReserved.compareAndSet(false, true)
    }

    fun onPostRejected() {
        drainReserved.set(false)
        pending.set(null)
    }

    private fun advanceGeneration(): Long = generation.updateAndGet { current ->
        if (current == Long.MAX_VALUE) 1L else current + 1L
    }
}

/**
 * Allocation-free rolling evidence for a potentially unbounded physical scroll gesture.
 *
 * ArrayList<Float> used to retain every callback/sample until the gesture finalized. Repeated
 * swipes can keep that gesture active for minutes, creating boxed Float garbage and an ever more
 * expensive terminal sort; HOME appeared to fix the reader because lifecycle teardown cleared the
 * lists. Keep the most recent fixed window instead. The authoritative SurfaceFlinger qualification
 * remains independent, while this diagnostic window still spans well over 45 seconds at 90 Hz.
 */
internal class NtkBoundedFloatSamples(private val capacity: Int) {
    private val values = FloatArray(capacity.also { require(it > 0) })
    private var writeIndex = 0
    var size: Int = 0
        private set

    fun add(value: Float) {
        values[writeIndex] = value
        writeIndex = (writeIndex + 1) % capacity
        if (size < capacity) size++
    }

    fun clear() {
        writeIndex = 0
        size = 0
    }

    fun snapshot(): ArrayList<Float> {
        val result = ArrayList<Float>(size)
        if (size == 0) return result
        val first = if (size == capacity) writeIndex else 0
        repeat(size) { offset ->
            result.add(values[(first + offset) % capacity])
        }
        return result
    }
}

/** Minimal immutable projection consumed by the post-submit frame-proof packer. */
internal interface NtkVisibleFrameProofItem {
    val index: Int
    val committedIdentity: ReaderSurfaceView.CommittedPageIdentity?
    val cardText: String?
    val top: Float
    val pageHeight: Float
}

internal data class NtkPackedVisibleFrameProof(
    val pageIndexes: IntArray,
    val pageIdentities: List<ReaderSurfaceView.CommittedPageIdentity>,
)

/**
 * Packs the exact submitted viewport in one pass over the producer-confined DrawState items.
 *
 * The normal input is already display ordered and unique, so both insertion searches append in
 * O(1). The sorted insertion fallback preserves the previous distinct+sorted semantics if a
 * defensive test or future layout source supplies duplicates or out-of-order items.
 */
internal fun packNtkVisibleFrameProof(
    items: List<NtkVisibleFrameProofItem>,
    viewportHeight: Int,
    viewportTopOffset: Float = 0f,
): NtkPackedVisibleFrameProof {
    if (items.isEmpty()) {
        return NtkPackedVisibleFrameProof(IntArray(0), emptyList())
    }
    val pageIndexes = IntArray(items.size)
    var pageIndexCount = 0
    var identityIndexes: IntArray? = null
    var pageIdentities: ArrayList<ReaderSurfaceView.CommittedPageIdentity>? = null
    val viewportBottom = viewportHeight.toFloat()
    for (item in items) {
        val itemTop = item.top - viewportTopOffset
        // Keep the former filter's exact predicate (including rejecting NaN geometry).
        if (!(itemTop < viewportBottom && itemTop + item.pageHeight > 0f)) continue
        if (item.cardText == null) {
            val found = sortedIntIndex(pageIndexes, pageIndexCount, item.index)
            if (found < 0) {
                val insertion = -found - 1
                if (insertion < pageIndexCount) {
                    System.arraycopy(
                        pageIndexes,
                        insertion,
                        pageIndexes,
                        insertion + 1,
                        pageIndexCount - insertion,
                    )
                }
                pageIndexes[insertion] = item.index
                pageIndexCount++
            }
        }
        val identity = item.committedIdentity ?: continue
        var indexes = identityIndexes
        var identities = pageIdentities
        if (indexes == null || identities == null) {
            indexes = IntArray(items.size)
            identities = ArrayList(items.size)
            identityIndexes = indexes
            pageIdentities = identities
        }
        val found = sortedIntIndex(indexes, identities.size, item.index)
        if (found >= 0) continue
        val insertion = -found - 1
        if (insertion < identities.size) {
            System.arraycopy(
                indexes,
                insertion,
                indexes,
                insertion + 1,
                identities.size - insertion,
            )
        }
        indexes[insertion] = item.index
        identities.add(
            insertion,
            if (identity.displayPageIndex == item.index) {
                identity
            } else {
                identity.copy(displayPageIndex = item.index)
            },
        )
    }
    val packedIndexes = if (pageIndexCount == pageIndexes.size) {
        pageIndexes
    } else {
        pageIndexes.copyOf(pageIndexCount)
    }
    return NtkPackedVisibleFrameProof(
        packedIndexes,
        pageIdentities ?: emptyList(),
    )
}

/** Returns the found index, or `-(insertionPoint + 1)` when absent. */
private fun sortedIntIndex(values: IntArray, size: Int, target: Int): Int {
    var low = 0
    var high = size - 1
    while (low <= high) {
        val middle = (low + high).ushr(1)
        val value = values[middle]
        when {
            value < target -> low = middle + 1
            value > target -> high = middle - 1
            else -> return middle
        }
    }
    return -low - 1
}

internal object NtkExpandedNativeTextureTransitionPolicy {
    fun mayCrossCard(
        cardText: String?,
        errorText: String?,
        nextCardText: String?,
        nextErrorText: String?,
        nextEpisodePath: String?,
        authorizedEpisodePaths: Set<String>,
    ): Boolean =
        cardText != null &&
            errorText == null &&
            nextCardText == null &&
            nextErrorText == null &&
            !nextEpisodePath.isNullOrEmpty() &&
            nextEpisodePath in authorizedEpisodePaths
}

/**
 * Bounded episode authority for native texture residency during continuous reading.
 *
 * The current episode, its immediate predecessor, and one not-yet-presented forward target are
 * the only paths that may own GPU uploads.  Keeping the forward target separate is important:
 * an old callback must not replace the predecessor after an A -> B -> A authority cycle, while a
 * user who scrolls upward in B must still be able to re-upload A until C is physically adopted.
 */
internal object NtkExpandedNativeTextureHistoryPolicy {
    data class State(
        val currentPath: String = "",
        val previousPath: String = "",
        val pendingForwardPath: String = "",
        val pendingForwardPredecessorPath: String = "",
        val pendingForwardRevision: Long = 0L,
        val deferredForwardPath: String = "",
        val deferredForwardPredecessorPath: String = "",
        val deferredForwardRevision: Long = 0L,
    ) {
        fun authorizedPaths(): LinkedHashSet<String> = linkedSetOf<String>().apply {
            if (currentPath.isNotEmpty()) add(currentPath)
            if (previousPath.isNotEmpty()) add(previousPath)
            if (pendingForwardPath.isNotEmpty()) add(pendingForwardPath)
        }
    }

    fun configured(currentPath: String): State =
        State(currentPath = currentPath.takeIf(String::isNotEmpty).orEmpty())

    fun authorizeForward(
        state: State,
        predecessorPath: String,
        targetPath: String,
        revision: Long,
    ): State {
        if (predecessorPath.isEmpty() || targetPath.isEmpty() || revision <= 0L ||
            targetPath == predecessorPath || targetPath == state.previousPath
        ) return state
        if (predecessorPath == state.currentPath) {
            if (targetPath == state.currentPath) return state
            if (state.pendingForwardPath.isNotEmpty() &&
                revision <= state.pendingForwardRevision
            ) return state
            val keepDeferred = state.deferredForwardPredecessorPath == targetPath
            return state.copy(
                pendingForwardPath = targetPath,
                pendingForwardPredecessorPath = predecessorPath,
                pendingForwardRevision = revision,
                deferredForwardPath = state.deferredForwardPath.takeIf { keepDeferred }.orEmpty(),
                deferredForwardPredecessorPath =
                    state.deferredForwardPredecessorPath.takeIf { keepDeferred }.orEmpty(),
                deferredForwardRevision = state.deferredForwardRevision.takeIf { keepDeferred }
                    ?: 0L,
            )
        }
        // A completed B can resolve C before B is physically presented. Keep C as metadata only;
        // authorizing its GPU uploads now would evict B's A->B transition authority.
        if (predecessorPath == state.pendingForwardPath) {
            if (targetPath == state.currentPath || targetPath == state.pendingForwardPath ||
                (state.deferredForwardPath.isNotEmpty() &&
                    revision <= state.deferredForwardRevision)
            ) return state
            return state.copy(
                deferredForwardPath = targetPath,
                deferredForwardPredecessorPath = predecessorPath,
                deferredForwardRevision = revision,
            )
        }
        return state
    }

    fun advanceAfterPhysicalCommit(
        state: State,
        targetPath: String,
        committedPath: String,
    ): State {
        if (targetPath.isEmpty() || committedPath != targetPath) return state
        if (targetPath == state.currentPath) return state
        if (targetPath != state.pendingForwardPath) return state
        val promoteDeferred = state.deferredForwardPredecessorPath == targetPath &&
            state.deferredForwardPath.isNotEmpty() &&
            state.deferredForwardPath != targetPath &&
            state.deferredForwardPath != state.currentPath
        return State(
            currentPath = targetPath,
            previousPath = state.currentPath,
            pendingForwardPath = state.deferredForwardPath.takeIf { promoteDeferred }.orEmpty(),
            pendingForwardPredecessorPath =
                state.deferredForwardPredecessorPath.takeIf { promoteDeferred }.orEmpty(),
            pendingForwardRevision = state.deferredForwardRevision.takeIf { promoteDeferred }
                ?: 0L,
        )
    }

    fun shouldBypassResumeFloorForReverse(
        activeDirection: Int,
        pointerDown: Boolean,
        dragging: Boolean,
        scrollbarDragging: Boolean,
        scrollerFinished: Boolean,
    ): Boolean = activeDirection == ReaderSurfaceView.DIRECTION_PREVIOUS &&
        (pointerDown || dragging || scrollbarDragging || !scrollerFinished)

    fun remapFloorAfterRemoval(
        floor: Int,
        startIndex: Int,
        removedCount: Int,
        remainingPageCount: Int,
    ): Int {
        if (remainingPageCount <= 0) return 0
        val endExclusive = startIndex.toLong() + removedCount.toLong()
        val shifted = when {
            floor < startIndex -> floor
            floor.toLong() >= endExclusive -> floor - removedCount
            else -> startIndex
        }
        return shifted.coerceIn(0, remainingPageCount - 1)
    }

    fun remapExactPageAfterRemoval(
        page: Int,
        startIndex: Int,
        removedCount: Int,
        remainingPageCount: Int,
    ): Int {
        if (page < 0 || remainingPageCount <= 0) return -1
        val endExclusive = startIndex.toLong() + removedCount.toLong()
        if (page.toLong() >= startIndex.toLong() && page.toLong() < endExclusive) {
            return -1
        }
        val shifted = if (page.toLong() >= endExclusive) page - removedCount else page
        return shifted.takeIf { it in 0 until remainingPageCount } ?: -1
    }
}

/** Preserves a real reverse MOVE when the latest-only UI window mailbox receives UP immediately. */
internal object NtkReverseWindowEvidencePolicy {
    data class Evidence(
        val directionHint: Int = 0,
        val reverseFirstPageHint: Int = -1,
    )

    fun capture(busy: Boolean, activeDirection: Int, firstVisiblePage: Int): Evidence = when {
        busy && activeDirection < 0 && firstVisiblePage >= 0 ->
            Evidence(directionHint = -1, reverseFirstPageHint = firstVisiblePage)
        busy && activeDirection > 0 -> Evidence(directionHint = 1)
        else -> Evidence()
    }

    fun merge(previous: Evidence?, latest: Evidence): Evidence {
        val previousReverse = previous?.reverseFirstPageHint?.takeIf { it >= 0 }
        val latestReverse = latest.reverseFirstPageHint.takeIf { it >= 0 }
        val reverseFirst = listOfNotNull(previousReverse, latestReverse).minOrNull() ?: -1
        return if (reverseFirst >= 0) {
            Evidence(directionHint = -1, reverseFirstPageHint = reverseFirst)
        } else {
            latest
        }
    }
}

/**
 * Keeps an immutable native rolling band independent from unrelated decoded-page deliveries.
 * A page can change the parked band only when it is already represented by that snapshot or its
 * document interval intersects the snapshot. Global HWUI/display-list generations are therefore
 * deliberately absent from this decision.
 */
internal object NtkNativeBandCachePolicy {
    fun shouldInvalidateForPage(
        cachedIncludesPage: Boolean,
        pageTop: Float,
        pageHeight: Float,
        bandOrigin: Float,
        bandBottom: Float,
    ): Boolean {
        if (cachedIncludesPage) return true
        if (!pageTop.isFinite() || !pageHeight.isFinite() ||
            !bandOrigin.isFinite() || !bandBottom.isFinite() ||
            pageHeight <= 0f || bandBottom <= bandOrigin
        ) return true
        return pageTop < bandBottom && pageTop + pageHeight > bandOrigin
    }
}

/**
 * Selects a page owner only from a defect-free committed frame which actually spans the reading
 * probe. A sparse frame whose first real page begins below the probe cannot claim that later page
 * as the user's position; doing so makes the public anchor jump backwards when the missing
 * predecessor is installed in the next frame.
 */
internal object NtkCommittedViewportProofPolicy {
    private const val PROGRESS_PROBE_RATIO = 0.35f

    fun readingIdentityIndex(
        visiblePageTopPx: FloatArray,
        physicalViewportPx: Int,
        identityCount: Int,
    ): Int {
        if (identityCount <= 0 || physicalViewportPx <= 0 ||
            visiblePageTopPx.size != identityCount
        ) return -1
        val probe = physicalViewportPx * PROGRESS_PROBE_RATIO
        var owner = -1
        for (index in visiblePageTopPx.indices) {
            val top = visiblePageTopPx[index]
            if (!top.isFinite()) return -1
            if (top > probe) break
            owner = index
        }
        return owner
    }

    fun isStable(proof: ReaderSurfaceView.CompletedDrawProof): Boolean {
        val coverage = proof.coverage
        return coverage.drawablePx > 0 && coverage.missingPx == 0 &&
            coverage.placeholderPx == 0 && coverage.visibleLoading == 0 &&
            coverage.visibleErrors == 0 &&
            readingIdentityIndex(
                proof.visiblePageTopPx,
                coverage.physicalViewportPx,
                proof.visiblePageIdentities.size,
            ) >= 0
    }
}

internal object NtkNativeSurfaceFrameRatePolicy {
    const val FORCE_HWUI_SYSTEM_PROPERTY = "mangaview.reader.force_hwui_for_test"

    fun isHwuiOverrideEnabled(): Boolean =
        java.lang.Boolean.getBoolean(FORCE_HWUI_SYSTEM_PROPERTY)

    fun isEmulatorRuntime(
        fingerprint: String,
        model: String,
        hardware: String,
        product: String,
    ): Boolean {
        return fingerprint.startsWith("generic", ignoreCase = true) ||
            fingerprint.contains("emulator", ignoreCase = true) ||
            model.contains("Emulator", ignoreCase = true) ||
            model.contains("Android SDK built for", ignoreCase = true) ||
            hardware.contains("ranchu", ignoreCase = true) ||
            hardware.contains("goldfish", ignoreCase = true) ||
            product.contains("sdk_gphone", ignoreCase = true)
    }

    fun shouldApplyLayerFrameRateVote(
        emulatorRuntime: Boolean,
        directWifiRendererProfile: Boolean,
    ): Boolean = emulatorRuntime && directWifiRendererProfile
}

internal object NtkDisplayTimingPolicy {
    private const val DEFAULT_REFRESH_RATE_HZ = 60f

    fun normalizedRefreshRate(refreshRate: Float?): Float =
        refreshRate?.takeIf { it.isFinite() && it > 1f } ?: DEFAULT_REFRESH_RATE_HZ

    fun frameBudgetMs(refreshRate: Float): Float =
        1000f / normalizedRefreshRate(refreshRate)
}

internal object NtkDirectCadenceWatchdogPolicy {
    fun delayMs(frameBudgetMs: Float, emulatorRuntime: Boolean): Long {
        val nominalPeriodMs = ceil(frameBudgetMs.toDouble()).toLong().coerceAtLeast(1L)
        // gfxstream's producer Choreographer often arrives just after one nominal period. An
        // 18-ms watchdog races that healthy callback, creating extra queueBuffer submissions and
        // mailbox drops. Give the host two periods; physical devices retain one-period grace.
        return if (emulatorRuntime) nominalPeriodMs * 2L + 1L else nominalPeriodMs + 1L
    }
}

/**
 * Owns one delayed producer wakeup while the Choreographer deadline moves every frame.
 *
 * Re-arming only advances [deadlineMs] and [generation]. It never asks Handler to remove or add a
 * message while an owner is already scheduled. When that owner's message becomes runnable it
 * either reposts itself for the remaining time or claims the latest generation as overdue.
 */
internal class NtkDirectCadenceDeadlineGate {
    private companion object {
        // Re-arming may move a healthy two-frame deadline, but duplicate callback registrations
        // must never postpone the sole recovery owner forever. This is comfortably beyond the
        // emulator's normal 35 ms grace and below the observed 100+ ms callback outage.
        const val MAX_OWNER_LIFETIME_MS = 96L
    }
    sealed class DrainDecision {
        data object Stale : DrainDecision()
        data class Repost(val delayMs: Long) : DrainDecision()
        data class Due(val generation: Long) : DrainDecision()
    }

    data class Snapshot(
        val scheduled: Boolean,
        val reservation: Long,
        val generation: Long,
        val deadlineMs: Long,
        val arms: Long,
        val scheduleRequests: Long,
        val reposts: Long,
        val due: Long,
        val stale: Long,
    )

    private var scheduled = false
    private var reservation = 0L
    private var nextReservation = 1L
    private var generation = 0L
    private var deadlineMs = 0L
    private var ownerStartedMs = 0L
    private var arms = 0L
    private var scheduleRequests = 0L
    private var reposts = 0L
    private var due = 0L
    private var stale = 0L

    /** Returns a new reservation only when the caller must post the single delayed owner. */
    @Synchronized
    fun arm(nowMs: Long, delayMs: Long): Long {
        arms++
        generation = nextPositive(generation)
        val safeDelay = delayMs.coerceAtLeast(1L)
        val requestedDeadline = if (nowMs > Long.MAX_VALUE - safeDelay) {
            Long.MAX_VALUE
        } else {
            nowMs + safeDelay
        }
        if (scheduled) {
            val ownerDeadline = if (ownerStartedMs > Long.MAX_VALUE - MAX_OWNER_LIFETIME_MS) {
                Long.MAX_VALUE
            } else {
                ownerStartedMs + MAX_OWNER_LIFETIME_MS
            }
            deadlineMs = minOf(requestedDeadline, ownerDeadline)
            return 0L
        }
        scheduled = true
        ownerStartedMs = nowMs
        deadlineMs = requestedDeadline
        reservation = nextReservation
        nextReservation = nextPositive(nextReservation)
        scheduleRequests++
        return reservation
    }

    @Synchronized
    fun drain(expectedReservation: Long, nowMs: Long): DrainDecision {
        if (!scheduled || expectedReservation <= 0L || reservation != expectedReservation) {
            stale++
            return DrainDecision.Stale
        }
        if (nowMs < deadlineMs) {
            val remainingMs = deadlineMs - nowMs
            reposts++
            return DrainDecision.Repost(remainingMs)
        }
        scheduled = false
        reservation = 0L
        ownerStartedMs = 0L
        due++
        return DrainDecision.Due(generation)
    }

    /** Rejects only the owner whose Handler post failed; stale failures cannot cancel a successor. */
    @Synchronized
    fun onPostRejected(expectedReservation: Long) {
        if (!scheduled || reservation != expectedReservation) return
        scheduled = false
        reservation = 0L
        ownerStartedMs = 0L
        generation = nextPositive(generation)
    }

    @Synchronized
    fun isCurrentGeneration(expectedGeneration: Long): Boolean =
        expectedGeneration > 0L && generation == expectedGeneration

    /** Invalidates an already-posted wakeup without scanning the Handler MessageQueue. */
    @Synchronized
    fun clear() {
        scheduled = false
        reservation = 0L
        deadlineMs = 0L
        ownerStartedMs = 0L
        generation = nextPositive(generation)
    }

    @Synchronized
    fun snapshot(): Snapshot = Snapshot(
        scheduled = scheduled,
        reservation = reservation,
        generation = generation,
        deadlineMs = deadlineMs,
        arms = arms,
        scheduleRequests = scheduleRequests,
        reposts = reposts,
        due = due,
        stale = stale,
    )

    private fun nextPositive(value: Long): Long = if (value == Long.MAX_VALUE) 1L else value + 1L
}

/**
 * Replaces, rather than adds to, the one producer-vsync callback that already owns an exact
 * adjacent-p0 content mutation. This is intentionally narrower than input catch-up: it requires
 * the host-emulator direct-Wi-Fi runway and an admitted immutable frame token.
 */
internal object NtkAdjacentExactP0FrameCatchupPolicy {
    fun shouldPost(
        emulatorRuntime: Boolean,
        directWifiRunway: Boolean,
        authorizedEpisode: Boolean,
        renderRunning: Boolean,
        directSurfaceReady: Boolean,
        frameSchedulingSuppressed: Boolean,
        callbackPosted: Boolean,
        contentCatchupPosted: Boolean,
        inputCatchupPosted: Boolean,
        hasAdmittedFrame: Boolean,
        nativeAttached: Boolean,
        surfaceValid: Boolean,
    ): Boolean = emulatorRuntime && directWifiRunway && authorizedEpisode && renderRunning &&
        directSurfaceReady && !frameSchedulingSuppressed && callbackPosted &&
        !contentCatchupPosted && !inputCatchupPosted && hasAdmittedFrame && nativeAttached &&
        surfaceValid
}

/**
 * Keeps a resumed host-emulator viewport private until it is either physically continuous or is
 * the exact, naturally short terminal source. Other renderer profiles retain progressive
 * first-pixel reveal.
 */
internal object NtkDeferredSurfaceRevealPolicy {
    fun shouldReveal(
        emulatorRuntime: Boolean,
        directWifiForwardOnlyResume: Boolean,
        visibleActualPixels: Boolean,
        continuousActualViewport: Boolean,
        exactTerminalTailActual: Boolean,
    ): Boolean {
        if (!visibleActualPixels) return false
        return if (emulatorRuntime && directWifiForwardOnlyResume) {
            continuousActualViewport || exactTerminalTailActual
        } else {
            true
        }
    }
}

/**
 * Native exact pixels may use sparse source indexes (for example auto-cut pages), but their
 * structural display-page indexes must remain contiguous. A missing structural page represents
 * an incomplete geometry snapshot, not a valid sparse viewport.
 */
internal object NtkDirectWifiExactVisibleStructurePolicy {
    fun shouldEnforce(
        emulatorRuntime: Boolean,
        realPixelsOnly: Boolean,
    ): Boolean = emulatorRuntime && realPixelsOnly

    fun isContiguous(displayPageIndexes: IntArray): Boolean {
        for (index in 1 until displayPageIndexes.size) {
            if (displayPageIndexes[index] != displayPageIndexes[index - 1] + 1) return false
        }
        return true
    }
}

/**
 * A short final image can fit between two MOVE samples.  Crossing its bottom and the following
 * transition card in one gesture would make that canonical source resident but never physically
 * present it.  Hold the exact bottom for the rest of the crossing gesture; a later gesture may
 * continue only after the compositor proof was accepted as a clean single-episode tail frame.
 */
internal object NtkPhysicalEpisodeTailHoldPolicy {
    fun mayAdoptAdjacentEpisode(
        predecessorIsExactTail: Boolean,
        predecessorTailAcknowledged: Boolean,
    ): Boolean = predecessorIsExactTail && predecessorTailAcknowledged

    /**
     * The immutable manifest identity proves that this is the final canonical source.  A following
     * display node is not required to prove the boundary: adjacent discovery can still be in flight,
     * or it can temporarily publish an identity-less runway node.  Only another display fragment of
     * the same final source postpones the boundary to that fragment.
     */
    fun isBoundaryAfterExactTail(successorIsSameTailFragment: Boolean): Boolean =
        !successorIsSameTailFragment

    fun isAcknowledgementObservable(
        presentedUptimeNanos: Long,
        nowUptimeNanos: Long,
        minimumDwellNanos: Long,
    ): Boolean = presentedUptimeNanos > 0L && minimumDwellNanos >= 0L &&
        nowUptimeNanos >= presentedUptimeNanos &&
        nowUptimeNanos - presentedUptimeNanos >= minimumDwellNanos

    fun isPriorGestureAcknowledgementObservable(
        acknowledgedGestureRevision: Long?,
        currentGestureRevision: Long,
        presentedUptimeNanos: Long,
        nowUptimeNanos: Long,
        minimumDwellNanos: Long,
    ): Boolean = acknowledgedGestureRevision != null &&
        acknowledgedGestureRevision < currentGestureRevision &&
        isAcknowledgementObservable(
            presentedUptimeNanos,
            nowUptimeNanos,
            minimumDwellNanos,
        )

    fun retainedSameGestureHoldLimit(
        direction: Int,
        forwardDirection: Int,
        requestedOffset: Float,
        holdLimit: Float,
        holdGestureRevision: Long,
        currentGestureRevision: Long,
        epsilonPx: Float,
    ): Float? = holdLimit.takeIf {
        direction == forwardDirection && requestedOffset.isFinite() && it.isFinite() &&
            epsilonPx >= 0f && holdGestureRevision == currentGestureRevision &&
            requestedOffset > it + epsilonPx
    }

    /**
     * A drawable-prefix stall may retain an absolute target from several earlier gestures. Once
     * the exact episode tail has been physically acknowledged, that target belongs to the old
     * episode's coordinate space; carrying it through the boundary can skip an entire newly
     * appended chapter. Preserve only the new gesture's real finger position at that edge.
     */
    fun targetAfterAcknowledgedEpisodeBoundary(
        requestedTarget: Float,
        physicalGestureTarget: Float,
        boundaryOffset: Float,
        priorGestureAcknowledgementObservable: Boolean,
        epsilonPx: Float,
    ): Float {
        if (!requestedTarget.isFinite() || !physicalGestureTarget.isFinite() ||
            !boundaryOffset.isFinite() || epsilonPx < 0f ||
            !priorGestureAcknowledgementObservable
        ) return requestedTarget
        val includesCarriedTravel = requestedTarget > physicalGestureTarget + epsilonPx
        val newGestureCrossesBoundary = physicalGestureTarget > boundaryOffset + epsilonPx
        return if (includesCarriedTravel && newGestureCrossesBoundary) {
            physicalGestureTarget
        } else {
            requestedTarget
        }
    }

    fun shouldHoldCrossing(
        direction: Int,
        forwardDirection: Int,
        currentOffset: Float,
        requestedOffset: Float,
        boundaryOffset: Float,
        tailAcknowledged: Boolean,
        heldInCurrentGesture: Boolean,
        epsilonPx: Float,
    ): Boolean {
        if (direction != forwardDirection || !currentOffset.isFinite() ||
            !requestedOffset.isFinite() || !boundaryOffset.isFinite() || epsilonPx < 0f
        ) return false
        val crosses = currentOffset <= boundaryOffset + epsilonPx &&
            requestedOffset > boundaryOffset + epsilonPx
        // Exact adjacent pages can be attached while the final predecessor image is still using
        // provisional geometry.  If that image later resolves to a different height, the same
        // physical coordinate can suddenly lie beyond its newly computed boundary without ever
        // satisfying `crosses`.  Treat that unacknowledged state as an escaped crossing and move
        // the next forward sample back to the exact tail.  The ordinary clean compositor proof is
        // still required before a later gesture may continue into the successor.
        val escapedUnacknowledgedTail = !tailAcknowledged &&
            currentOffset > boundaryOffset + epsilonPx &&
            requestedOffset > currentOffset + epsilonPx
        return (crosses || escapedUnacknowledgedTail) &&
            (heldInCurrentGesture || !tailAcknowledged)
    }

    fun isNewAcknowledgedBoundaryCrossing(
        currentOffset: Float,
        requestedOffset: Float,
        boundaryOffset: Float,
        tailAcknowledged: Boolean,
        heldInCurrentGesture: Boolean,
        epsilonPx: Float,
    ): Boolean = tailAcknowledged && !heldInCurrentGesture &&
        currentOffset.isFinite() && requestedOffset.isFinite() && boundaryOffset.isFinite() &&
        epsilonPx >= 0f && currentOffset <= boundaryOffset + epsilonPx &&
        requestedOffset > boundaryOffset + epsilonPx

    fun isEscapedTailGeometryCorrection(
        currentOffset: Float,
        boundedOffset: Float,
        holdLimit: Float?,
        epsilonPx: Float,
    ): Boolean = holdLimit != null && currentOffset.isFinite() && boundedOffset.isFinite() &&
        holdLimit.isFinite() && epsilonPx >= 0f &&
        currentOffset > holdLimit + epsilonPx &&
        boundedOffset < currentOffset - epsilonPx &&
        boundedOffset <= holdLimit + epsilonPx

    fun isCleanTailCommit(
        exactPresentation: Boolean,
        singleEpisodeViewport: Boolean,
        tailSourceIndex: Int,
        manifestPageCount: Int,
        pageBottomReached: Boolean,
        drawablePx: Int,
        missingPx: Int,
        placeholderPx: Int,
        visibleLoading: Int,
        visibleErrors: Int,
        visibleCards: Int,
        widthFillFailures: Int,
        lowResolutionItems: Int,
    ): Boolean = exactPresentation && singleEpisodeViewport && manifestPageCount > 0 &&
        tailSourceIndex == manifestPageCount - 1 && pageBottomReached && drawablePx > 0 &&
        missingPx == 0 && placeholderPx == 0 && visibleLoading == 0 && visibleErrors == 0 &&
        visibleCards == 0 && widthFillFailures == 0 && lowResolutionItems == 0
}

/**
 * Bounded hand-off between the native presentation producer and the main-thread reader listener.
 *
 * The producer can run at 90 Hz while the listener performs identity validation, telemetry and
 * accessibility publication. Posting one main-thread Runnable per native frame therefore turns a
 * short burst into an ever-growing UI queue. This mailbox keeps exactly one scheduled/running
 * owner, coalesces an unchanged semantic viewport to its latest proof, and retains only the
 * ordered transitions that the listener must observe immediately. Ordinary page/structure
 * progress occupies one latest slot so background publication cannot starve physical input.
 * The first proof is itself a replaceable activation slot: a burst of identical proofs before
 * main gets CPU time still activates from the newest physical frame.
 */
internal class CompletedDrawDispatchQueue(
    private val maxSemanticTransitions: Int,
    private val ordinaryCadenceNanos: Long,
) {
    init {
        require(maxSemanticTransitions > 0)
        require(ordinaryCadenceNanos > 0L)
    }

    data class Delivery(
        val proof: ReaderSurfaceView.CompletedDrawProof,
        val revealNativeSurface: Boolean,
    )

    data class OfferResult(
        val shouldPost: Boolean,
        val delayNanos: Long,
        val criticalOverflowed: Boolean,
    )

    data class Repost(
        val shouldPost: Boolean,
        val delayNanos: Long,
    )

    data class Snapshot(
        val offers: Long,
        val scheduleRequests: Long,
        val selected: Long,
        val delivered: Long,
        val staleDropped: Long,
        val sameSemanticCoalesced: Long,
        val ordinarySuperseded: Long,
        val overflowCoalesced: Long,
        val criticalOverflowFailures: Long,
        val postRejected: Long,
        val clears: Long,
        val maxQueueDepth: Int,
        val pendingSemanticTransitions: Int,
        val ordinaryPending: Boolean,
        val runnerScheduled: Boolean,
        val runnerRunning: Boolean,
        val maxConcurrentRunnerOwners: Int,
    )

    private data class Entry(
        val delivery: Delivery,
        val protectedTransition: Boolean,
    )

    private val semanticTransitions = ArrayDeque<Entry>()
    private var ordinary: Entry? = null
    private var lastSelectedProof: ReaderSurfaceView.CompletedDrawProof? = null
    private var lastDeliveredProof: ReaderSurfaceView.CompletedDrawProof? = null
    private var lastDeliveredStableViewportProof: ReaderSurfaceView.CompletedDrawProof? = null
    private var lastSelectedAtNanos = Long.MIN_VALUE
    private var runnerScheduled = false
    private var runnerRunning = false

    private var offers = 0L
    private var scheduleRequests = 0L
    private var selected = 0L
    private var delivered = 0L
    private var staleDropped = 0L
    private var sameSemanticCoalesced = 0L
    private var ordinarySuperseded = 0L
    private var overflowCoalesced = 0L
    private var criticalOverflowFailures = 0L
    private var postRejected = 0L
    private var clears = 0L
    private var maxQueueDepth = 0
    private var maxConcurrentRunnerOwners = 0

    @Synchronized
    fun offer(
        proof: ReaderSurfaceView.CompletedDrawProof,
        revealNativeSurface: Boolean,
        nowNanos: Long,
    ): OfferResult {
        offers++
        val next = Delivery(proof, revealNativeSurface)
        val tail = semanticTransitions.peekLast()
        val pendingOrdinary = ordinary
        var criticalOverflowed = false
        when {
            pendingOrdinary != null &&
                sameSemanticViewport(pendingOrdinary.delivery.proof, proof) &&
                !revealNativeSurface -> {
                ordinary = pendingOrdinary.copy(
                    delivery = next.copy(
                        revealNativeSurface =
                            pendingOrdinary.delivery.revealNativeSurface || revealNativeSurface,
                    ),
                )
                sameSemanticCoalesced++
            }
            pendingOrdinary == null &&
                tail != null && sameSemanticViewport(tail.delivery.proof, proof) -> {
                semanticTransitions.removeLast()
                semanticTransitions.addLast(
                    tail.copy(
                        delivery = next.copy(
                            revealNativeSurface =
                                tail.delivery.revealNativeSurface || revealNativeSurface,
                        ),
                    ),
                )
                sameSemanticCoalesced++
            }
            pendingOrdinary == null && tail == null && lastSelectedProof != null &&
                sameSemanticViewport(lastSelectedProof!!, proof) && !revealNativeSurface -> {
                ordinary = Entry(next, protectedTransition = false)
            }
            else -> {
                val previousProof = pendingOrdinary?.delivery?.proof ?: tail?.delivery?.proof ?:
                    lastSelectedProof
                if (isProtectedTransition(next, previousProof)) {
                    if (ordinary != null) {
                        ordinary = null
                        ordinarySuperseded++
                    }
                    // Returning to the identity of an older pending protected transition can
                    // happen after one ordinary frame. Replace that tail with the newest physical
                    // proof instead of enqueueing the same transition twice.
                    val currentTail = semanticTransitions.peekLast()
                    if (currentTail != null &&
                        sameSemanticViewport(currentTail.delivery.proof, proof)
                    ) {
                        semanticTransitions.removeLast()
                        semanticTransitions.addLast(
                            currentTail.copy(
                                delivery = next.copy(
                                    revealNativeSurface =
                                        currentTail.delivery.revealNativeSurface ||
                                            revealNativeSurface,
                                ),
                            ),
                        )
                        sameSemanticCoalesced++
                    } else {
                        criticalOverflowed = appendProtectedSemanticTransition(next)
                    }
                } else {
                    if (ordinary != null) ordinarySuperseded++
                    ordinary = Entry(next, protectedTransition = false)
                }
            }
        }
        maxQueueDepth = maxOf(maxQueueDepth, pendingDepthLocked())
        val reservation = reserveRunnerIfNeededLocked(nowNanos)
        return OfferResult(
            reservation.shouldPost,
            reservation.delayNanos,
            criticalOverflowed,
        )
    }

    /** Moves the single scheduled owner to running. A cancelled/duplicate callback is inert. */
    @Synchronized
    fun beginRun(): Boolean {
        if (runnerRunning || !runnerScheduled) return false
        runnerScheduled = false
        runnerRunning = true
        noteRunnerOwnersLocked()
        return true
    }

    /** Returns one due proof. Semantic transitions are never held behind ordinary cadence. */
    @Synchronized
    fun pollReady(nowNanos: Long): Delivery? {
        check(runnerRunning) { "completed-draw runner is not active" }
        semanticTransitions.pollFirst()?.let { entry ->
            selectLocked(entry.delivery, nowNanos)
            return entry.delivery
        }
        val pending = ordinary ?: return null
        val dueAt = cadenceDueAtLocked()
        if (nowNanos < dueAt) return null
        ordinary = null
        selectLocked(pending.delivery, nowNanos)
        return pending.delivery
    }

    /**
     * Atomically releases the running owner or reserves its only successor. Offers racing this
     * method either see runnerRunning=true and are covered by this repost, or reserve their own
     * wakeup after both flags become false; there is no lost-wakeup gap.
     */
    @Synchronized
    fun finishRun(nowNanos: Long): Repost {
        check(runnerRunning) { "completed-draw runner is not active" }
        runnerRunning = false
        if (pendingDepthLocked() == 0) {
            runnerScheduled = false
            return Repost(false, 0L)
        }
        runnerScheduled = true
        scheduleRequests++
        noteRunnerOwnersLocked()
        val delay = if (semanticTransitions.isNotEmpty()) {
            0L
        } else {
            (cadenceDueAtLocked() - nowNanos).coerceAtLeast(0L)
        }
        return Repost(true, delay)
    }

    @Synchronized
    fun recordDeliveryResult(
        accepted: Boolean,
        proof: ReaderSurfaceView.CompletedDrawProof? = null,
    ) {
        if (accepted) {
            delivered++
            if (proof != null &&
                (lastDeliveredProof == null || proof.frameToken > lastDeliveredProof!!.frameToken)
            ) {
                lastDeliveredProof = proof
            }
            if (proof != null && NtkCommittedViewportProofPolicy.isStable(proof) &&
                (lastDeliveredStableViewportProof == null ||
                    proof.frameToken > lastDeliveredStableViewportProof!!.frameToken)
            ) {
                lastDeliveredStableViewportProof = proof
            }
        } else {
            staleDropped++
        }
    }

    /** Last physical proof whose Activity listener completed successfully. */
    @Synchronized
    fun latestDeliveredProof(): ReaderSurfaceView.CompletedDrawProof? = lastDeliveredProof

    /** Last defect-free Activity-processed proof whose identities span the reading probe. */
    @Synchronized
    fun latestDeliveredStableViewportProof(): ReaderSurfaceView.CompletedDrawProof? =
        lastDeliveredStableViewportProof

    /** Releases a Handler reservation when post/postDelayed rejects during Looper teardown. */
    @Synchronized
    fun onPostRejected() {
        postRejected++
        runnerScheduled = false
    }

    /**
     * Clears lifecycle-scoped proofs. A callback already executing keeps ownership so a new offer
     * is consumed by that runner; a merely scheduled callback is removed by the caller first.
     */
    @Synchronized
    fun clearAfterScheduledCallbackRemoval() {
        semanticTransitions.clear()
        ordinary = null
        lastSelectedProof = null
        lastDeliveredProof = null
        lastDeliveredStableViewportProof = null
        lastSelectedAtNanos = Long.MIN_VALUE
        runnerScheduled = false
        clears++
    }

    @Synchronized
    fun snapshot(): Snapshot = Snapshot(
        offers = offers,
        scheduleRequests = scheduleRequests,
        selected = selected,
        delivered = delivered,
        staleDropped = staleDropped,
        sameSemanticCoalesced = sameSemanticCoalesced,
        ordinarySuperseded = ordinarySuperseded,
        overflowCoalesced = overflowCoalesced,
        criticalOverflowFailures = criticalOverflowFailures,
        postRejected = postRejected,
        clears = clears,
        maxQueueDepth = maxQueueDepth,
        pendingSemanticTransitions = semanticTransitions.size,
        ordinaryPending = ordinary != null,
        runnerScheduled = runnerScheduled,
        runnerRunning = runnerRunning,
        maxConcurrentRunnerOwners = maxConcurrentRunnerOwners,
    )

    private fun isProtectedTransition(
        delivery: Delivery,
        previousProof: ReaderSurfaceView.CompletedDrawProof?,
    ): Boolean {
        val proof = delivery.proof
        return delivery.revealNativeSurface || previousProof == null ||
            previousProof.surfaceLifecycleEpoch != proof.surfaceLifecycleEpoch ||
            !sameVisibleEpisodes(previousProof, proof) ||
            !samePresentationQualificationClass(previousProof, proof) ||
            proof.visiblePageIdentities.any { it.sourcePageIndex in 0 until 5 }
    }

    private fun appendProtectedSemanticTransition(delivery: Delivery): Boolean {
        var protectedEntryEvicted = false
        if (semanticTransitions.size >= maxSemanticTransitions) {
            // Every deque entry is a protected activation/episode/p0-p4/qualification transition.
            // Keep the fixed bound but retire the oldest proof so the newest physical viewport
            // cannot be stranded forever if the producer stops here. The hard counter/log remains
            // a fail-closed signal that an earlier semantic proof was not delivered.
            semanticTransitions.removeFirst()
            criticalOverflowFailures++
            protectedEntryEvicted = true
        }
        semanticTransitions.addLast(Entry(delivery, protectedTransition = true))
        return protectedEntryEvicted
    }

    private fun reserveRunnerIfNeededLocked(nowNanos: Long): Repost {
        if (pendingDepthLocked() == 0 || runnerScheduled || runnerRunning) {
            return Repost(false, 0L)
        }
        runnerScheduled = true
        scheduleRequests++
        noteRunnerOwnersLocked()
        val delay = if (semanticTransitions.isNotEmpty()) {
            0L
        } else {
            (cadenceDueAtLocked() - nowNanos).coerceAtLeast(0L)
        }
        return Repost(true, delay)
    }

    private fun selectLocked(delivery: Delivery, nowNanos: Long) {
        lastSelectedProof = delivery.proof
        lastSelectedAtNanos = nowNanos
        selected++
    }

    private fun cadenceDueAtLocked(): Long {
        if (lastSelectedAtNanos == Long.MIN_VALUE) return Long.MIN_VALUE
        val maximumBase = Long.MAX_VALUE - ordinaryCadenceNanos
        return lastSelectedAtNanos.coerceAtMost(maximumBase) + ordinaryCadenceNanos
    }

    private fun pendingDepthLocked(): Int = semanticTransitions.size + if (ordinary != null) 1 else 0

    private fun noteRunnerOwnersLocked() {
        val owners = (if (runnerScheduled) 1 else 0) + (if (runnerRunning) 1 else 0)
        maxConcurrentRunnerOwners = maxOf(maxConcurrentRunnerOwners, owners)
    }

    private fun sameVisibleEpisodes(
        first: ReaderSurfaceView.CompletedDrawProof,
        second: ReaderSurfaceView.CompletedDrawProof,
    ): Boolean {
        val firstIdentities = first.visiblePageIdentities
        val secondIdentities = second.visiblePageIdentities
        var firstIndex = 0
        var secondIndex = 0
        while (true) {
            firstIndex = nextDistinctEpisodePathIndex(firstIdentities, firstIndex)
            secondIndex = nextDistinctEpisodePathIndex(secondIdentities, secondIndex)
            val firstEnded = firstIndex >= firstIdentities.size
            val secondEnded = secondIndex >= secondIdentities.size
            if (firstEnded || secondEnded) return firstEnded == secondEnded
            if (firstIdentities[firstIndex].normalizedEpisodePath !=
                secondIdentities[secondIndex].normalizedEpisodePath
            ) return false
            firstIndex++
            secondIndex++
        }
    }

    private fun nextDistinctEpisodePathIndex(
        identities: List<ReaderSurfaceView.CommittedPageIdentity>,
        start: Int,
    ): Int {
        var candidate = start
        while (candidate < identities.size) {
            val path = identities[candidate].normalizedEpisodePath
            var seen = false
            for (prior in 0 until candidate) {
                if (identities[prior].normalizedEpisodePath == path) {
                    seen = true
                    break
                }
            }
            if (!seen) return candidate
            candidate++
        }
        return identities.size
    }

    private fun sameSemanticViewport(
        first: ReaderSurfaceView.CompletedDrawProof,
        second: ReaderSurfaceView.CompletedDrawProof,
    ): Boolean {
        if (first.surfaceLifecycleEpoch != second.surfaceLifecycleEpoch ||
            !first.visiblePageIndexes.contentEquals(second.visiblePageIndexes) ||
            !samePresentationQualificationClass(first, second)
        ) return false
        val firstIdentities = first.visiblePageIdentities
        val secondIdentities = second.visiblePageIdentities
        if (firstIdentities.size != secondIdentities.size) return false
        return firstIdentities.indices.all { index ->
            firstIdentities[index] == secondIdentities[index]
        }
    }

    /**
     * A newer frame with the same page identity is not interchangeable when its physical proof
     * or opaque-viewport class changed.  In particular, replacing an undelivered clean p0/episode
     * proof with a later missing/placeholder frame makes the listener reject the only clean proof.
     * Keep those frames as ordered transitions while still coalescing ordinary clean motion.
     */
    private fun samePresentationQualificationClass(
        first: ReaderSurfaceView.CompletedDrawProof,
        second: ReaderSurfaceView.CompletedDrawProof,
    ): Boolean {
        if (first.hardwareAccelerated != second.hardwareAccelerated ||
            first.registeredHwuiFrameCommitCallbackObserved !=
                second.registeredHwuiFrameCommitCallbackObserved ||
            first.surfaceQueueSubmissionObserved != second.surfaceQueueSubmissionObserved ||
            first.surfaceControlLatchObserved != second.surfaceControlLatchObserved ||
            first.runwayDefect != second.runwayDefect
        ) return false
        return viewportQualificationClass(first.coverage) ==
            viewportQualificationClass(second.coverage)
    }

    private fun viewportQualificationClass(coverage: ReaderSurfaceView.VisibleCoverageSnapshot): Int {
        var result = 0
        if (coverage.physicalViewportPx <= 0) result = result or (1 shl 0)
        if (coverage.viewportPx < coverage.physicalViewportPx) result = result or (1 shl 1)
        if (coverage.drawablePx < coverage.physicalViewportPx) result = result or (1 shl 2)
        if (coverage.missingPx != 0) result = result or (1 shl 3)
        if (coverage.placeholderPx != 0) result = result or (1 shl 4)
        if (coverage.visibleLoading != 0) result = result or (1 shl 5)
        if (coverage.visibleErrors != 0) result = result or (1 shl 6)
        if (coverage.visibleCards != 0) result = result or (1 shl 7)
        if (coverage.widthFillFailures != 0) result = result or (1 shl 8)
        if (coverage.lowResolutionItems != 0) result = result or (1 shl 9)
        if (coverage.directWifiForwardOnlyInitialResume) result = result or (1 shl 10)
        if (coverage.directWifiForwardOnlyTerminalTailActual) result = result or (1 shl 11)
        return result
    }
}

/**
 * Single-flight hand-off from the native presentation thread to the main thread.
 *
 * A BUFFER_QUEUE presentation is reported for every moving frame.  Posting a main-thread
 * reveal callback for every report is unnecessary after the first buffer has been exposed and,
 * when the main thread is briefly busy, creates an unbounded queue of no-op callbacks.  Keep the
 * newest attachment/structure identity in one slot and allow at most one scheduled callback.
 */
internal class NativeSurfaceRevealDispatchGate {
    data class Request(
        val attachEpoch: Long,
        val structureEpoch: Long,
    )

    data class OfferResult(
        val shouldPost: Boolean,
        val reservation: Long,
    )

    data class Snapshot(
        val offers: Long,
        val scheduleRequests: Long,
        val coalesced: Long,
        val alreadyRevealedSkipped: Long,
        val selected: Long,
        val staleOrRejected: Long,
        val clears: Long,
        val scheduled: Boolean,
        val pending: Boolean,
    )

    private var latest: Request? = null
    private var scheduled = false
    private var scheduledReservation = 0L
    private var nextReservation = 1L
    private var offers = 0L
    private var scheduleRequests = 0L
    private var coalesced = 0L
    private var alreadyRevealedSkipped = 0L
    private var selected = 0L
    private var staleOrRejected = 0L
    private var clears = 0L

    @Synchronized
    fun offer(request: Request, alreadyRevealed: Boolean): OfferResult {
        offers++
        if (alreadyRevealed) {
            alreadyRevealedSkipped++
            return OfferResult(false, 0L)
        }
        latest = request
        if (scheduled) {
            coalesced++
            return OfferResult(false, scheduledReservation)
        }
        scheduled = true
        scheduledReservation = nextReservation++.also {
            if (nextReservation <= 0L) nextReservation = 1L
        }
        scheduleRequests++
        return OfferResult(true, scheduledReservation)
    }

    /** Atomically releases the scheduled owner and consumes the newest request. */
    @Synchronized
    fun take(): Request? {
        if (!scheduled) return null
        scheduled = false
        scheduledReservation = 0L
        return latest.also {
            latest = null
            if (it != null) selected++
        }
    }

    /** A stale/rejected Handler reservation must not clear a newer reservation. */
    @Synchronized
    fun onPostRejected(reservation: Long) {
        if (!scheduled || scheduledReservation != reservation) return
        scheduled = false
        scheduledReservation = 0L
        staleOrRejected++
    }

    @Synchronized
    fun clear() {
        latest = null
        scheduled = false
        scheduledReservation = 0L
        clears++
    }

    @Synchronized
    fun snapshot(): Snapshot = Snapshot(
        offers = offers,
        scheduleRequests = scheduleRequests,
        coalesced = coalesced,
        alreadyRevealedSkipped = alreadyRevealedSkipped,
        selected = selected,
        staleOrRejected = staleOrRejected,
        clears = clears,
        scheduled = scheduled,
        pending = latest != null,
    )
}

/** Native submit contract shared by synchronous and deferred Kotlin ownership paths. */
internal object NtkNativeSubmitResultPolicy {
    private const val TRANSIENT_BACKPRESSURE = -2L

    fun isTransientBackpressure(result: Long): Boolean = result == TRANSIENT_BACKPRESSURE

    fun isTerminalFailure(result: Long): Boolean =
        result < 0L && !isTransientBackpressure(result)
}

class ReaderSurfaceView @JvmOverloads constructor(
    context: Context,
    attrs: AttributeSet? = null
) : FrameLayout(context, attrs), SurfaceHolder.Callback2 {
    data class ProgressPosition(
        val page: Int,
        val offset: Int
    )

    /**
     * Exact physical location of a document page inside the viewport.
     *
     * ProgressPosition deliberately remains integer-based because it is persisted as a bookmark
     * and crosses the Java listener boundary. Geometry mutations must not reuse that lossy value:
     * dropping even a fraction of a pixel on every late image-height resolve accumulates into a
     * visible idle jump. This private anchor owns the full-precision compositor coordinate.
     */
    private data class ViewportAnchor(
        val page: Int,
        val pageTopInViewportPx: Float,
    )

