    /**
     * Atomically installs a real authoritative-original tile page delivered after partial
     * adoption. Unlike the legacy setters, this carries immutable provenance into strict runway
     * and visible-coverage accounting and applies the proven source geometry immediately.
     */
    fun setPageAuthoritativeOriginalTiles(
        index: Int,
        pageWidth: Int,
        pageHeight: Int,
        tiles: List<ReaderTile>,
        proof: ReaderPreparedStore.PreparedOriginalProof,
        installGeneration: Int = 0,
    ): Boolean {
        if (!usableAuthoritativeOriginalTilePage(pageWidth, pageHeight, tiles, proof)) {
            Log.e(
                TAG,
                "reader_authoritative_tiles_reject page=$index reason=unusable," +
                    "pageSize=${pageWidth}x$pageHeight,proofSize=${proof.originalWidth}x${proof.originalHeight}," +
                    "tiles=${tiles.size}"
            )
            return false
        }
        var installed = false
        val request = synchronized(stateLock) {
            val page = pages.getOrNull(index)
            if (page == null) {
                Log.e(TAG, "reader_authoritative_tiles_reject page=$index reason=page_missing,count=${pages.size}")
                return false
            }
            if (stripAuthorityToken != 0L &&
                !isIndependentAdjacentRunwayOriginalLocked(
                    index,
                    page,
                    pageWidth,
                    pageHeight,
                    proof,
                )
            ) {
                Log.e(TAG, "reader_authoritative_tiles_reject page=$index reason=strip_authority")
                return false
            }
            val existingUsableOriginal = usableAuthoritativeOriginalTilePage(
                    page.width,
                    page.height,
                    page.tiles,
                    page.originalProof
                )
            val sameTileIdentity = hasSameTilesIdentity(page, tiles)
            val replaceRetainedGeneration =
                NtkAuthoritativeOriginalGenerationPolicy.mayReplaceRetainedOriginal(
                    existingUsableOriginal = existingUsableOriginal,
                    sameTileIdentity = sameTileIdentity,
                    sameCanonicalProof = page.originalProof == proof,
                    existingGeneration = page.authoritativeInstallGeneration,
                    incomingGeneration = installGeneration,
                )
            if (existingUsableOriginal && !sameTileIdentity && !replaceRetainedGeneration) {
                Log.d(
                    TAG,
                    "reader_authoritative_tiles_reject page=$index reason=late_duplicate_original"
                )
                return false
            }
            if (replaceRetainedGeneration) {
                Log.d(
                    TAG,
                    "reader_authoritative_tiles_replace_retained_generation page=$index " +
                        "from=${page.authoritativeInstallGeneration},to=$installGeneration",
                )
            }
            if (!usableAuthoritativeOriginalTilePage(pageWidth, pageHeight, tiles, proof)) {
                return@synchronized null
            }
            val targetWidth = max(1, pageWidth)
            val targetHeight = max(1, pageHeight)
            val incomingBitmaps = tiles.map(ReaderTile::bitmap)
            postNativeTexturePrewarmLocked(index, tiles)
            if (isSettledTilesDeliveryNoOpLocked(page, tiles, targetWidth, targetHeight)) {
                page.originalProof = proof
                if (installGeneration > 0) page.authoritativeInstallGeneration = installGeneration
                lastVisibleCoverageSnapshot = null
                installed = true
                return@synchronized null
            }

            rebuildLayoutLocked()
            val oldHeight = pageDrawHeightLocked(page)
            val oldTop = pageTopOrElseLocked(index, 0f)
            val viewportAnchor = viewportAnchorLocked()
            val newHeight = resolvedPageDrawHeightLocked(targetWidth, targetHeight)
            val hadDrawable = page.bitmap != null || page.tiles.isNotEmpty()
            val freezeLayoutForPhysicalInput =
                shouldFreezeGeometryForNextBoundaryLocked(index, oldTop, oldHeight, newHeight) ||
                    shouldDeferHeightChangingResolveLocked(
                        oldTop,
                        oldHeight,
                        newHeight,
                        hadDrawable,
                    ) ||
                    shouldDeferInitialDrawableSizeLocked(
                        oldTop,
                        oldHeight,
                        newHeight,
                        hadDrawable,
                    )
            invalidateRetainedPageNodeIfTilesChanged(index, page, tiles)
            retireCurrentPageDrawableLocked(page, incomingBitmaps)
            page.bitmap = null
            page.tiles = tiles
            page.width = targetWidth
            page.height = targetHeight
            page.originalProof = proof
            if (installGeneration > 0) page.authoritativeInstallGeneration = installGeneration
            clearPendingResolveLocked(page)
            if (freezeLayoutForPhysicalInput) {
                freezeAuthoritativeLayoutUntilInputSettlesLocked(
                    page,
                    oldHeight,
                )
            } else {
                clearDeferredLayoutGeometryLocked(page)
            }
            noteResolvedPageAspectLocked(page.width, page.height)
            page.loading = false
            page.cardText = null
            page.errorText = null
            deferInitialEmptyDraw = false
            markBlockedDrawableResolvedLocked(index)
            val appliedNewHeight = pageDrawHeightLocked(page)
            applyPageHeightChangeLocked(index, oldTop, oldHeight, appliedNewHeight - oldHeight)
            restoreViewportAnchorLocked(
                viewportAnchor,
                "page_authoritative_original_tiles",
                index,
                oldHeight,
                appliedNewHeight
            )
            maybeReleasePrependedReadyHoldLocked(index)
            applyLockedRestorePositionLocked()
            clampScrollLocked()
            installed = true
            if (shouldRenderPageResolveNowLocked(index)) {
                refreshVisibleCoverageAfterDrawableLocked(index)
                renderRequested = true
                scheduleFrameLocked()
                stateLock.notifyAll()
                windowRequestLocked(lastBusy)
            } else {
                null
            }
        }
        synchronized(stateLock) {
            if (installed) {
                reevaluateDeferredSurfaceRevealLocked("authoritative_tiles", index)
            }
        }
        dispatchWindowRequest(request)
        return installed
    }

    /**
     * The launch strip and appended exact runway share one Surface page table but not pixel
     * ownership. A non-slot adjacent page may therefore be replaced while the launch token is
     * live, provided its current committed identity proves the exact episode/source asset.
     */
    private fun isIndependentAdjacentRunwayOriginalLocked(
        index: Int,
        page: Page,
        pageWidth: Int,
        pageHeight: Int,
        proof: ReaderPreparedStore.PreparedOriginalProof?,
    ): Boolean {
        val identity = page.committedIdentity ?: return false
        return page.stripAuthority == 0L && page.stripSlots.isEmpty() &&
            page.adjacentExactOwner == null && page.adjacentExactPlan == null &&
            page.adjacentExactSlots.isEmpty() &&
            identity.displayPageIndex == index &&
            identity.normalizedEpisodePath.isNotBlank() &&
            identity.sourcePageIndex in 0 until identity.manifestPageCount &&
            identity.manifestDigest.isNotBlank() && identity.manifestPageCount > 0 &&
            ReaderPreparedStore.isCanonicalOriginalProof(
                proof,
                identity.canonicalAsset,
                pageWidth,
                pageHeight,
            )
    }

    data class AuthoritativeTileInstall(
        val index: Int,
        val pageWidth: Int,
        val pageHeight: Int,
        val tiles: List<ReaderTile>,
        val proof: ReaderPreparedStore.PreparedOriginalProof,
        val installGeneration: Int = 0,
    )

    data class InstallBatchResult(val installedPages: Set<Int>, val rejectedPages: Set<Int>)

    /** Installs one contiguous physical batch with one state lock and one frame request. */
    fun installAuthoritativeTileBatch(
        commands: List<AuthoritativeTileInstall>
    ): InstallBatchResult {
        if (commands.isEmpty()) return InstallBatchResult(emptySet(), emptySet())
        val installed = LinkedHashSet<Int>()
        val rejected = LinkedHashSet<Int>()
        val request = synchronized(stateLock) {
            if (stripAuthorityToken != 0L) {
                commands.forEach { rejected.add(it.index) }
                return@synchronized null
            }
            rebuildLayoutLocked()
            val viewportAnchor = viewportAnchorLocked()
            var firstChangedIndex = -1
            var firstOldHeight = 0f
            var firstNewHeight = 0f
            for (command in commands.sortedBy { it.index }) {
                if (!usableAuthoritativeOriginalTilePage(
                        command.pageWidth,
                        command.pageHeight,
                        command.tiles,
                        command.proof
                    )
                ) {
                    rejected.add(command.index)
                    continue
                }
                val page = pages.getOrNull(command.index)
                if (page == null) {
                    rejected.add(command.index)
                    continue
                }
                val existingUsableOriginal = usableAuthoritativeOriginalTilePage(
                        page.width,
                        page.height,
                        page.tiles,
                        page.originalProof
                    )
                val sameTileIdentity = hasSameTilesIdentity(page, command.tiles)
                val replaceRetainedGeneration =
                    NtkAuthoritativeOriginalGenerationPolicy.mayReplaceRetainedOriginal(
                        existingUsableOriginal = existingUsableOriginal,
                        sameTileIdentity = sameTileIdentity,
                        sameCanonicalProof = page.originalProof == command.proof,
                        existingGeneration = page.authoritativeInstallGeneration,
                        incomingGeneration = command.installGeneration,
                    )
                if (existingUsableOriginal && !sameTileIdentity && !replaceRetainedGeneration) {
                    Log.d(
                        TAG,
                        "reader_authoritative_tiles_reject page=${command.index} " +
                            "reason=late_duplicate_original_batch"
                    )
                    rejected.add(command.index)
                    continue
                }
                if (replaceRetainedGeneration) {
                    Log.d(
                        TAG,
                        "reader_authoritative_tiles_replace_retained_generation " +
                            "page=${command.index} from=${page.authoritativeInstallGeneration}," +
                            "to=${command.installGeneration}",
                    )
                }
                val targetWidth = max(1, command.pageWidth)
                val targetHeight = max(1, command.pageHeight)
                postNativeTexturePrewarmLocked(command.index, command.tiles)
                if (isSettledTilesDeliveryNoOpLocked(page, command.tiles, targetWidth, targetHeight)) {
                    page.originalProof = command.proof
                    if (command.installGeneration > 0) {
                        page.authoritativeInstallGeneration = command.installGeneration
                    }
                    installed.add(command.index)
                    continue
                }
                val oldHeight = pageDrawHeightLocked(page)
                val oldTop = pageTopOrElseLocked(command.index, 0f)
                val newHeight = resolvedPageDrawHeightLocked(targetWidth, targetHeight)
                val hadDrawable = page.bitmap != null || page.tiles.isNotEmpty()
                val freezeLayoutForPhysicalInput =
                    shouldFreezeGeometryForNextBoundaryLocked(
                        command.index,
                        oldTop,
                        oldHeight,
                        newHeight,
                    ) || shouldDeferHeightChangingResolveLocked(
                        oldTop,
                        oldHeight,
                        newHeight,
                        hadDrawable,
                    ) || shouldDeferInitialDrawableSizeLocked(
                        oldTop,
                        oldHeight,
                        newHeight,
                        hadDrawable,
                    )
                invalidateRetainedPageNodeIfTilesChanged(command.index, page, command.tiles)
                retireCurrentPageDrawableLocked(
                    page,
                    command.tiles.map(ReaderTile::bitmap),
                )
                page.bitmap = null
                page.tiles = command.tiles
                page.width = targetWidth
                page.height = targetHeight
                page.originalProof = command.proof
                if (command.installGeneration > 0) {
                    page.authoritativeInstallGeneration = command.installGeneration
                }
                clearPendingResolveLocked(page)
                if (freezeLayoutForPhysicalInput) {
                    freezeAuthoritativeLayoutUntilInputSettlesLocked(
                        page,
                        oldHeight,
                    )
                } else {
                    clearDeferredLayoutGeometryLocked(page)
                }
                noteResolvedPageAspectLocked(page.width, page.height)
                page.loading = false
                page.cardText = null
                page.errorText = null
                deferInitialEmptyDraw = false
                markBlockedDrawableResolvedLocked(command.index)
                val appliedNewHeight = pageDrawHeightLocked(page)
                if (firstChangedIndex < 0) {
                    firstChangedIndex = command.index
                    firstOldHeight = oldHeight
                    firstNewHeight = appliedNewHeight
                }
                applyPageHeightChangeLocked(
                    command.index,
                    oldTop,
                    oldHeight,
                    appliedNewHeight - oldHeight,
                )
                maybeReleasePrependedReadyHoldLocked(command.index)
                installed.add(command.index)
            }
            if (firstChangedIndex >= 0) {
                restoreViewportAnchorLocked(
                    viewportAnchor,
                    "authoritative_tile_batch",
                    firstChangedIndex,
                    firstOldHeight,
                    firstNewHeight
                )
                applyLockedRestorePositionLocked()
                clampScrollLocked()
            }
            if (installed.isNotEmpty()) {
                refreshVisibleCoverageAfterDrawableLocked(installed.last())
                renderRequested = true
                scheduleFrameLocked()
                stateLock.notifyAll()
                windowRequestLocked(lastBusy)
            } else {
                null
            }
        }
        synchronized(stateLock) {
            installed.lastOrNull()?.let { lastInstalled ->
                reevaluateDeferredSurfaceRevealLocked(
                    "authoritative_tile_batch",
                    lastInstalled,
                )
            }
        }
        dispatchWindowRequest(request)
        return InstallBatchResult(installed, rejected)
    }

    fun setPageTiles(index: Int, pageWidth: Int, pageHeight: Int, tiles: List<ReaderTile>) {
        setPageTiles(index, pageWidth, pageHeight, tiles, forceImmediateGeometry = false)
    }

    fun setPageTiles(
        index: Int,
        pageWidth: Int,
        pageHeight: Int,
        tiles: List<ReaderTile>,
        forceImmediateGeometry: Boolean
    ) {
        val request = synchronized(stateLock) {
            if (stripAuthorityToken != 0L) return@synchronized null
            val page = pages.getOrNull(index) ?: return
            // This legacy API carries no provenance. Callers that possess an original proof must
            // use setPageAuthoritativeOriginalTiles so an old proof can never bless new pixels.
            // Do not downgrade the currently presented exact owner merely because an identical
            // callback was redelivered or a different replacement is only parked for geometry
            // stability. Every path that actually installs different tile identities goes through
            // invalidateRetainedPageNodeIfTilesChanged(), which clears the proof at that mutation.
            val targetWidth = max(1, pageWidth)
            val targetHeight = max(1, pageHeight)
            val incomingBitmaps = tiles.map(ReaderTile::bitmap)
            postNativeTexturePrewarmLocked(index, tiles)
            if (isSettledTilesDeliveryNoOpLocked(page, tiles, targetWidth, targetHeight)) {
                return@synchronized null
            }
            val hasCurrentDrawableBeforeLayout = page.bitmap != null || page.tiles.isNotEmpty()
            if (!forceImmediateGeometry && hasCurrentDrawableBeforeLayout && shouldDeferDrawableReplacementLocked()) {
                retirePendingPageDrawableLocked(page, incomingBitmaps)
                page.pendingResolveType = PENDING_TILES
                page.pendingBitmap = null
                page.pendingTiles = tiles
                page.pendingWidth = targetWidth
                page.pendingHeight = targetHeight
                page.loading = false
                page.errorText = null
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
                return@synchronized null
            }
            rebuildLayoutLocked()
            val oldHeight = pageDrawHeightLocked(page)
            val oldTop = pageTopOrElseLocked(index, 0f)
            val viewportAnchor = viewportAnchorLocked()
            val newHeight = resolvedPageDrawHeightLocked(pageWidth, pageHeight)
            val hasCurrentDrawable = page.bitmap != null || page.tiles.isNotEmpty()
            if (!forceImmediateGeometry && !hasCurrentDrawable &&
                shouldFreezeOffscreenDrawableInstallLocked(index, oldTop, oldHeight)
            ) {
                invalidateRetainedPageNodeIfTilesChanged(index, page, tiles)
                retireCurrentPageDrawableLocked(page, incomingBitmaps)
                retirePendingPageDrawableLocked(page, incomingBitmaps)
                page.bitmap = null
                page.tiles = tiles
                page.width = max(1, width)
                page.height = max(1, oldHeight.toInt())
                page.pendingResolveType = PENDING_SIZE
                page.pendingBitmap = null
                page.pendingTiles = emptyList()
                page.pendingWidth = max(1, pageWidth)
                page.pendingHeight = max(1, pageHeight)
                page.loading = false
                page.cardText = null
                page.errorText = null
                deferInitialEmptyDraw = false
                markBlockedDrawableResolvedLocked(index)
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
                maybeReleasePrependedReadyHoldLocked(index)
                return@synchronized null
            }
            if (!forceImmediateGeometry &&
                shouldFreezeGeometryForNextBoundaryLocked(index, oldTop, oldHeight, newHeight)
            ) {
                invalidateRetainedPageNodeIfTilesChanged(index, page, tiles)
                retireCurrentPageDrawableLocked(page, incomingBitmaps)
                retirePendingPageDrawableLocked(page, incomingBitmaps)
                page.bitmap = null
                page.tiles = tiles
                page.width = max(1, width)
                page.height = max(1, oldHeight.toInt())
                page.pendingResolveType = PENDING_SIZE
                page.pendingBitmap = null
                page.pendingTiles = emptyList()
                page.pendingWidth = max(1, pageWidth)
                page.pendingHeight = max(1, pageHeight)
                page.loading = false
                page.cardText = null
                page.errorText = null
                deferInitialEmptyDraw = false
                markBlockedDrawableResolvedLocked(index)
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
                maybeReleasePrependedReadyHoldLocked(index)
                val renderNow = shouldRenderPageResolveNowLocked(index)
                if (renderNow) {
                    refreshVisibleCoverageAfterDrawableLocked(index)
                    renderRequested = true
                    scheduleFrameLocked()
                    stateLock.notifyAll()
                    return@synchronized windowRequestLocked(lastBusy)
                }
                return@synchronized null
            }
            if (!forceImmediateGeometry &&
                shouldDeferInitialDrawableSizeLocked(oldTop, oldHeight, newHeight, hasCurrentDrawable)
            ) {
                invalidateRetainedPageNodeIfTilesChanged(index, page, tiles)
                retireCurrentPageDrawableLocked(page, incomingBitmaps)
                retirePendingPageDrawableLocked(page, incomingBitmaps)
                page.bitmap = null
                page.tiles = tiles
                page.width = max(1, width)
                page.height = max(1, oldHeight.toInt())
                page.pendingResolveType = PENDING_SIZE
                page.pendingBitmap = null
                page.pendingTiles = emptyList()
                page.pendingWidth = max(1, pageWidth)
                page.pendingHeight = max(1, pageHeight)
                page.loading = false
                page.cardText = null
                page.errorText = null
                deferInitialEmptyDraw = false
                markBlockedDrawableResolvedLocked(index)
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
                maybeReleasePrependedReadyHoldLocked(index)
                val renderNow = shouldRenderPageResolveNowLocked(index)
                if (renderNow) {
                    refreshVisibleCoverageAfterDrawableLocked(index)
                    renderRequested = true
                    scheduleFrameLocked()
                    stateLock.notifyAll()
                    return@synchronized windowRequestLocked(lastBusy)
                }
                return@synchronized null
            }
            if (!forceImmediateGeometry && hasCurrentDrawable && shouldDeferDrawableReplacementLocked()) {
                retirePendingPageDrawableLocked(page, incomingBitmaps)
                page.pendingResolveType = PENDING_TILES
                page.pendingBitmap = null
                page.pendingTiles = tiles
                page.pendingWidth = max(1, pageWidth)
                page.pendingHeight = max(1, pageHeight)
                page.loading = false
                page.errorText = null
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
                return@synchronized null
            }
            if (!forceImmediateGeometry &&
                shouldDeferHeightChangingResolveLocked(oldTop, oldHeight, newHeight, hasCurrentDrawable)
            ) {
                retirePendingPageDrawableLocked(page, incomingBitmaps)
                if (hasCurrentDrawable) {
                    page.pendingResolveType = PENDING_TILES
                    page.pendingTiles = tiles
                    page.loading = false
                    page.errorText = null
                } else {
                    page.pendingResolveType = PENDING_TILES
                    page.pendingTiles = tiles
                }
                page.pendingBitmap = null
                page.pendingWidth = max(1, pageWidth)
                page.pendingHeight = max(1, pageHeight)
                deferInitialEmptyDraw = false
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
                return@synchronized null
            }
            invalidateRetainedPageNodeIfTilesChanged(index, page, tiles)
            retireCurrentPageDrawableLocked(page, incomingBitmaps)
            page.bitmap = null
            page.tiles = tiles
            page.width = targetWidth
            page.height = targetHeight
            clearPendingResolveLocked(page)
            // This path was not deferred, so exact source geometry replaces any prior temporary
            // footprint now rather than being applied a second time by the idle resolver.
            clearDeferredLayoutGeometryLocked(page)
            noteResolvedPageAspectLocked(page.width, page.height)
            page.loading = false
            page.cardText = null
            page.errorText = null
            deferInitialEmptyDraw = false
            markBlockedDrawableResolvedLocked(index)
            val appliedNewHeight = pageDrawHeightLocked(page)
            applyPageHeightChangeLocked(index, oldTop, oldHeight, appliedNewHeight - oldHeight)
            restoreViewportAnchorLocked(
                viewportAnchor,
                "page_tiles",
                index,
                oldHeight,
                appliedNewHeight,
            )
            maybeReleasePrependedReadyHoldLocked(index)
            applyLockedRestorePositionLocked()
            clampScrollLocked()
            val renderNow = shouldRenderPageResolveNowLocked(index)
            if (renderNow) {
                refreshVisibleCoverageAfterDrawableLocked(index)
                renderRequested = true
                scheduleFrameLocked()
                stateLock.notifyAll()
                windowRequestLocked(lastBusy)
            } else {
                null
            }
        }
        synchronized(stateLock) {
            reevaluateDeferredSurfaceRevealLocked("tiles", index)
        }
        dispatchWindowRequest(request)
    }

    fun clearPageBitmap(index: Int) {
        clearPageBitmap(index, allowIndependentAdjacentRunway = false)
    }

    private fun clearPageBitmap(
        index: Int,
        allowIndependentAdjacentRunway: Boolean,
    ): Boolean {
        var cleared = false
        val request = synchronized(stateLock) {
            val page = pages.getOrNull(index) ?: return@synchronized null
            if (stripAuthorityToken != 0L &&
                (!allowIndependentAdjacentRunway ||
                    !isIndependentAdjacentRunwayOriginalLocked(
                        index,
                        page,
                        page.width,
                        page.height,
                        page.originalProof,
                    ))
            ) {
                return@synchronized null
            }
            invalidateRetainedPageNodeStateLocked(index)
            rebuildLayoutLocked()
            val oldHeight = pageDrawHeightLocked(page)
            val oldTop = pageTopOrElseLocked(index, 0f)
            val viewportAnchor = viewportAnchorLocked()
            retireCurrentPageDrawableLocked(page)
            page.bitmap = null
            page.tiles = emptyList()
            page.loading = false
            page.cardText = null
            page.errorText = null
            clearPendingResolveLocked(page)
            cleared = true
            val newHeight = pageDrawHeightLocked(page)
            val heightDelta = newHeight - oldHeight
            if (abs(heightDelta) > HEIGHT_CHANGE_EPSILON_PX) {
                applyPageHeightChangeLocked(index, oldTop, oldHeight, heightDelta)
                restoreViewportAnchorLocked(viewportAnchor, "page_clear", index, oldHeight, newHeight)
                applyLockedRestorePositionLocked()
                clampScrollLocked()
            }
            if (shouldRenderPageResolveNowLocked(index)) {
                renderRequested = true
                scheduleFrameLocked()
                stateLock.notifyAll()
                if (abs(heightDelta) > HEIGHT_CHANGE_EPSILON_PX) {
                    Log.d(
                        TAG,
                        "reader_page_clear_height index=$index old=${oldHeight.toInt()} new=${newHeight.toInt()} " +
                            "offset=${scrollOffset.toInt()} lastBusy=$lastBusy"
                    )
                }
                windowRequestLocked(lastBusy)
            } else {
                null
            }
        }
        dispatchWindowRequest(request)
        return cleared
    }

    fun clearAllPages() {
        synchronized(stateLock) {
            if (stripAuthorityToken != 0L) return
            clearRetainedPageNodesStateLocked()
            clearPreparedStartAnchorLocked()
            for (page in pages) {
                retireCurrentPageDrawableLocked(page)
                page.bitmap = null
                page.tiles = emptyList()
                page.loading = false
                page.cardText = null
                page.errorText = null
                clearPendingResolveLocked(page)
                clearDeferredLayoutGeometryLocked(page)
            }
            hasDrawnContentFrame = false
            pendingBlockedForwardRequest = null
            blockedForwardDispatchPosted = false
            lastBlockedForwardPage = -1
            lastBlockedForwardRequestAtMs = 0L
            clearBlockedForwardIntentLocked()
            layoutDirty = true
            renderRequested = true
            scheduleFrameLocked()
            stateLock.notifyAll()
        }
    }

    fun stopRenderingAndClearPages() {
        mainHandler.removeCallbacksAndMessages(null)
        synchronized(stateLock) {
            // removeCallbacksAndMessages also removed a posted native-retirement drain. Reset its
            // latch before the clears below add holds, otherwise no later call can re-arm it.
            rollingAuthoritativeRecyclePosted = false
            scheduleRollingAuthoritativeRecycleLocked()
            invalidateFrameStatsFinalizeDeadlineLocked()
            if (stripAuthorityToken != 0L) return
            noStateRetryPosted = false
            clearRetainedPageNodesStateLocked()
            clearPreparedStartAnchorLocked()
            renderRunning = false
            renderRequested = false
            clearFramePipeLocked(preserveDirty = false)
            clearInputStateLocked()
            resetActiveFrameStatsLocked()
            for (page in pages) {
                retireCurrentPageDrawableLocked(page)
                page.bitmap = null
                page.tiles = emptyList()
                page.loading = false
                page.cardText = null
                page.errorText = null
                clearPendingResolveLocked(page)
                clearDeferredLayoutGeometryLocked(page)
            }
            hasDrawnContentFrame = false
            pendingBlockedForwardRequest = null
            blockedForwardDispatchPosted = false
            lastBlockedForwardPage = -1
            lastBlockedForwardRequestAtMs = 0L
            clearBlockedForwardIntentLocked()
            layoutDirty = true
            stopRenderThreadLocked()
            stateLock.notifyAll()
        }
    }

    fun setCommittedPageIdentities(
        startIndex: Int,
        identities: List<CommittedPageIdentity?>
    ) {
        if (startIndex < 0 || identities.isEmpty()) return
        var deferredInputRequest: WindowRequest? = null
        synchronized(stateLock) {
            var identityChanged = false
            identities.forEachIndexed { offset, identity ->
                val index = startIndex + offset
                val page = pages.getOrNull(index) ?: return@forEachIndexed
                val nextIdentity = identity?.copy(displayPageIndex = index)
                if (page.committedIdentity != nextIdentity) {
                    page.committedIdentity = nextIdentity
                    identityChanged = true
                }
            }
            if (identityChanged) {
                // Identity is part of CompletedDrawProof just as much as pixels and geometry are.
                // Rebinding an existing display index without advancing this epoch lets a queued
                // proof pass the structure check while no longer matching the page it claims.
                // Invalidate that proof and submit a fresh frame carrying the new exact identity.
                traversalStructureEpoch++
                if (traversalStructureEpoch <= 0L) traversalStructureEpoch = 1L
                physicalEpisodeTailProofRequestedKey = null
                if (desiredVersion == drawnVersion) advanceDesiredVersionLocked()
                pendingPixelReasons = pendingPixelReasons or DIRTY_INVALIDATION
                renderRequested = true
                scheduleFrameLocked()
            }
            if (directWifiExpandedNativeTextureRunway) {
                nativeTexturePrewarmDirty = true
                requestResidentNativeTexturePrewarmLocked()
            }
            // Exact pixels and their immutable identity arrive on independent actor callbacks.
            // Re-evaluate here as well as at pixel installation so either arrival order can
            // release a fully proven resumed viewport.
            reevaluateDeferredSurfaceRevealLocked(
                "identity",
                startIndex + identities.lastIndex,
            )
            if (hasLiveBlockedForwardIntentLocked()) {
                // A sealed manifest proves identity and geometry, not pixels. Keep the user's
                // destination alive, request the first exact missing body, and let the ordinary
                // drawable-prefix resume advance only through complete clean viewports. Jumping
                // directly to this coordinate exposed a blank p7..p12 before their install ACKs.
                scheduleBlockedForwardWindowRequestLocked()
                scheduleBlockedForwardIntentResumeLocked()
                deferredInputRequest = windowRequestLocked(
                    busy = lastBusy,
                    forceDispatch = true,
                )
            }
        }
        dispatchWindowRequest(deferredInputRequest, fromInput = true)
    }

    fun setPageBounds(index: Int, pageWidth: Int, pageHeight: Int) {
        val request = synchronized(stateLock) {
            if (stripAuthorityToken != 0L) return@synchronized null
            val page = pages.getOrNull(index) ?: return
            if (page.cardText != null || page.errorText != null || pageWidth <= 0 || pageHeight <= 0) return
            rebuildLayoutLocked()
            val oldHeight = pageDrawHeightLocked(page)
            val oldTop = pageTopOrElseLocked(index, 0f)
            val viewportAnchor = viewportAnchorLocked()
            val newHeight = resolvedPageDrawHeightLocked(pageWidth, pageHeight)
            val hasCurrentDrawable = page.bitmap != null || page.tiles.isNotEmpty()
            if (hasCurrentDrawable && abs(newHeight - oldHeight) <= ACTIVE_DRAWABLE_BOUNDS_DELTA_SUPPRESS_PX) {
                if (page.pendingResolveType == PENDING_BOUNDS || page.pendingResolveType == PENDING_SIZE) {
                    clearPendingResolveLocked(page)
                }
                return@synchronized null
            }
            if (!hasCurrentDrawable && shouldDeferOffscreenBoundsOnlyResolveLocked(oldTop)) {
                if (page.pendingResolveType != PENDING_BITMAP && page.pendingResolveType != PENDING_TILES) {
                    page.pendingResolveType = PENDING_BOUNDS
                    page.pendingBitmap = null
                    page.pendingTiles = emptyList()
                }
                page.pendingWidth = max(1, pageWidth)
                page.pendingHeight = max(1, pageHeight)
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
                return@synchronized null
            }
            if (
                shouldFreezeGeometryForNextBoundaryLocked(index, oldTop, oldHeight, newHeight) ||
                shouldDeferHeightChangingResolveLocked(oldTop, oldHeight, newHeight, hasCurrentDrawable) ||
                (!hasCurrentDrawable && shouldDeferInitialDrawableSizeLocked(oldTop, oldHeight, newHeight, false))
            ) {
                if (page.pendingResolveType != PENDING_BITMAP && page.pendingResolveType != PENDING_TILES) {
                    page.pendingResolveType = PENDING_BOUNDS
                    page.pendingBitmap = null
                    page.pendingTiles = emptyList()
                }
                page.pendingWidth = max(1, pageWidth)
                page.pendingHeight = max(1, pageHeight)
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
                return@synchronized null
            }
            // Only an applied geometry mutation invalidates the currently presented producer
            // scene. Bounds for an offscreen body are intentionally parked above; invalidating
            // before that decision rebuilt the visible native band for every prefetched page even
            // though neither its pixels nor layout had entered the render window.
            invalidatePreparedRenderSceneStateLocked()
            page.width = max(1, pageWidth)
            page.height = max(1, pageHeight)
            // A bounds callback can arrive in the quiet interval before the deferred resolver.
            // This immediate branch owns geometry, so cancel the old display-only footprint.
            clearDeferredLayoutGeometryLocked(page)
            if (page.pendingResolveType == PENDING_BOUNDS || page.pendingResolveType == PENDING_SIZE) {
                clearPendingResolveLocked(page)
            } else if (page.pendingResolveType == PENDING_BITMAP || page.pendingResolveType == PENDING_TILES) {
                page.pendingWidth = page.width
                page.pendingHeight = page.height
            }
            noteResolvedPageAspectLocked(page.width, page.height)
            applyPageHeightChangeLocked(index, oldTop, oldHeight, newHeight - oldHeight)
            restoreViewportAnchorLocked(viewportAnchor, "page_bounds", index, oldHeight, newHeight)
            applyLockedRestorePositionLocked()
            clampScrollLocked()
            if ((hasCurrentDrawable || (!shouldSuppressInitialEmptyRenderLocked()
                    && !shouldDeferInitialEmptyDrawLocked()))
                && shouldRenderPageResolveNowLocked(index)
            ) {
                renderRequested = true
                scheduleFrameLocked()
                stateLock.notifyAll()
                windowRequestLocked(lastBusy)
            } else {
                null
            }
        }
        dispatchWindowRequest(request)
    }

    fun preparePageCard(title: String) {
        if (!HostExactHardwareTilePool.supported(emulatorNativeSurfaceRuntime) ||
            !transitionCardPrewarmRequestedTitles.add(title)
        ) return
        val posted = mainHandler.post {
            val cardWidth = synchronized(stateLock) {
                preparedNativeTransitionCards[title]?.let { prepared ->
                    if (prepared.width == max(1, width)) return@post
                }
                max(1, width)
            }
            val card = createTransitionCardBitmap(cardWidth, title)
            val generation = transitionCardNativeGeneration.get()
            transitionCardPrewarmInFlightTitles.add(title)
            try {
                TRANSITION_CARD_NATIVE_EXECUTOR.execute {
                    val nativeToken = createNativeTransitionCardToken(card)
                    if (nativeToken == null) {
                        transitionCardPrewarmInFlightTitles.remove(title)
                        transitionCardPrewarmRequestedTitles.remove(title)
                        card.recycle()
                        return@execute
                    }
                    transitionCardNativePendingTokens.add(nativeToken)
                    if (transitionCardNativeGeneration.get() != generation) {
                        if (transitionCardNativePendingTokens.remove(nativeToken)) {
                            HostExactHardwareTilePool.retire(nativeToken)
                        }
                        transitionCardPrewarmInFlightTitles.remove(title)
                        card.recycle()
                        return@execute
                    }
                    val completionPosted = mainHandler.post {
                        if (!transitionCardNativePendingTokens.remove(nativeToken)) return@post
                        transitionCardPrewarmInFlightTitles.remove(title)
                        if (transitionCardNativeGeneration.get() != generation) {
                            HostExactHardwareTilePool.retire(nativeToken)
                            card.recycle()
                            return@post
                        }
                        var retained = false
                        val evicted = ArrayList<PreparedNativeTransitionCard>()
                        synchronized(stateLock) {
                            val waitingIndex = pages.indexOfFirst { page ->
                                page.cardText == title && page.nativeCardBitmap == null &&
                                    page.width == cardWidth
                            }
                            if (waitingIndex >= 0) {
                                val page = pages[waitingIndex]
                                page.nativeCardBitmap = nativeToken
                                invalidateRetainedPageNodeStateLocked(waitingIndex)
                                renderRequested = true
                                scheduleFrameLocked()
                                stateLock.notifyAll()
                                retained = true
                            } else if (cardWidth == max(1, width)) {
                                preparedNativeTransitionCards.put(
                                    title,
                                    PreparedNativeTransitionCard(
                                        title,
                                        cardWidth,
                                        card,
                                        nativeToken,
                                    ),
                                )?.let(evicted::add)
                                while (preparedNativeTransitionCards.size >
                                    MAX_PREPARED_NATIVE_TRANSITION_CARDS
                                ) {
                                    val iterator = preparedNativeTransitionCards.entries.iterator()
                                    if (!iterator.hasNext()) break
                                    evicted += iterator.next().value
                                    iterator.remove()
                                }
                                retained = true
                            }
                        }
                        evicted.forEach { stale ->
                            HostExactHardwareTilePool.retire(stale.nativeToken)
                            stale.softwareBitmap.recycle()
                        }
                        if (retained) {
                            val cached = synchronized(stateLock) {
                                preparedNativeTransitionCards[title]?.nativeToken === nativeToken
                            }
                            if (!cached) card.recycle()
                        } else {
                            HostExactHardwareTilePool.retire(nativeToken)
                            card.recycle()
                        }
                    }
                    if (!completionPosted) {
                        if (transitionCardNativePendingTokens.remove(nativeToken)) {
                            HostExactHardwareTilePool.retire(nativeToken)
                        }
                        transitionCardPrewarmInFlightTitles.remove(title)
                        transitionCardPrewarmRequestedTitles.remove(title)
                        card.recycle()
                    }
                }
            } catch (_: RuntimeException) {
                transitionCardPrewarmInFlightTitles.remove(title)
                transitionCardPrewarmRequestedTitles.remove(title)
                card.recycle()
            }
        }
        if (!posted) transitionCardPrewarmRequestedTitles.remove(title)
    }

    fun setPageCard(index: Int, title: String) {
        var stalePrepared: PreparedNativeTransitionCard? = null
        val request = synchronized(stateLock) {
            val page = pages.getOrNull(index) ?: return
            invalidateRetainedPageNodeStateLocked(index)
            rebuildLayoutLocked()
            val oldHeight = pageDrawHeightLocked(page)
            val oldTop = pageTopOrElseLocked(index, 0f)
            val viewportAnchor = viewportAnchorLocked()
            val cardWidth = max(1, width)
            val cardHeight = TRANSITION_CARD_PAGE_HEIGHT_PX.roundToInt()
            // The rolling native Surface renderer submits only Bitmap-backed items. Keep that
            // renderer backing separate from the real image slot: lifecycle/provenance checks
            // must never mistake a UI card for an original work image.
            retireCurrentPageDrawableLocked(page)
            val prepared = preparedNativeTransitionCards.remove(title)?.takeIf { candidate ->
                if (candidate.width == cardWidth) {
                    true
                } else {
                    stalePrepared = candidate
                    false
                }
            }
            page.bitmap = null
            page.cardBitmap = prepared?.softwareBitmap ?: createTransitionCardBitmap(cardWidth, title)
            page.nativeCardBitmap = prepared?.nativeToken
            if (prepared == null && title !in transitionCardPrewarmInFlightTitles) {
                page.cardBitmap?.let { card ->
                    prepareNativeTransitionCardAsync(page, card)
                }
            }
            page.tiles = emptyList()
            page.originalProof = null
            page.width = cardWidth
            page.height = cardHeight
            page.loading = false
            page.cardText = title
            page.errorText = null
            clearPendingResolveLocked(page)
            clearDeferredLayoutGeometryLocked(page)
            deferInitialEmptyDraw = false
            val newHeight = pageDrawHeightLocked(page)
            applyPageHeightChangeLocked(index, oldTop, oldHeight, newHeight - oldHeight)
            restoreViewportAnchorLocked(viewportAnchor, "page_card", index, oldHeight, newHeight)
            applyLockedRestorePositionLocked()
            clampScrollLocked()
            renderRequested = true
            scheduleFrameLocked()
            stateLock.notifyAll()
            windowRequestLocked(lastBusy)
        }
        stalePrepared?.let { stale ->
            HostExactHardwareTilePool.retire(stale.nativeToken)
            stale.softwareBitmap.recycle()
        }
        synchronized(stateLock) {
            reevaluateDeferredSurfaceRevealLocked("card", index)
        }
        dispatchWindowRequest(request)
    }

    private fun createTransitionCardBitmap(cardWidth: Int, title: String): Bitmap {
        val safeWidth = max(1, cardWidth)
        val safeHeight = TRANSITION_CARD_PAGE_HEIGHT_PX.roundToInt()
        return Bitmap.createBitmap(safeWidth, safeHeight, Bitmap.Config.ARGB_8888).also { bitmap ->
            val canvas = Canvas(bitmap)
            canvas.drawColor(Color.BLACK)
            drawTransitionCardText(
                canvas = canvas,
                width = safeWidth,
                centerY = safeHeight / 2f,
                title = title,
                labelPaint = Paint(Paint.ANTI_ALIAS_FLAG)
            )
        }
    }

    private fun createNativeTransitionCardToken(card: Bitmap): Bitmap? {
        if (!HostExactHardwareTilePool.supported(emulatorNativeSurfaceRuntime)) return null
        return runCatching {
            HostExactHardwareTilePool.copyStructuralBitmap(card)
        }.onFailure { failure ->
            Log.w(TAG, "reader_transition_card_native_copy_failed", failure)
        }.getOrNull()
    }

    /**
     * Structural-card AHardwareBuffer allocation/copy can block gfxstream for hundreds of
     * milliseconds. Keep the software card immediately available to HWUI, but build its native
     * immutable twin off the state lock and publish only if this exact Page/card identity remains
     * current.
     */
    private fun prepareNativeTransitionCardAsync(page: Page, card: Bitmap) {
        if (!HostExactHardwareTilePool.supported(emulatorNativeSurfaceRuntime)) return
        val generation = transitionCardNativeGeneration.get()
        TRANSITION_CARD_NATIVE_EXECUTOR.execute {
            val nativeToken = createNativeTransitionCardToken(card) ?: return@execute
            transitionCardNativePendingTokens.add(nativeToken)
            if (transitionCardNativeGeneration.get() != generation) {
                if (transitionCardNativePendingTokens.remove(nativeToken)) {
                    HostExactHardwareTilePool.retire(nativeToken)
                }
                return@execute
            }
            val posted = mainHandler.post {
                if (!transitionCardNativePendingTokens.remove(nativeToken)) return@post
                var adopted = false
                synchronized(stateLock) {
                    val currentIndex = pages.indexOfFirst { candidate -> candidate === page }
                    if (currentIndex >= 0 && page.cardBitmap === card &&
                        page.cardText != null && page.nativeCardBitmap == null
                    ) {
                        page.nativeCardBitmap = nativeToken
                        invalidateRetainedPageNodeStateLocked(currentIndex)
                        renderRequested = true
                        scheduleFrameLocked()
                        stateLock.notifyAll()
                        adopted = true
                    }
                }
                if (!adopted) HostExactHardwareTilePool.retire(nativeToken)
            }
            if (!posted && transitionCardNativePendingTokens.remove(nativeToken)) {
                HostExactHardwareTilePool.retire(nativeToken)
            }
        }
    }

    private fun drawTransitionCardText(
        canvas: Canvas,
        width: Int,
        centerY: Float,
        title: String,
        labelPaint: Paint
    ) {
        labelPaint.textAlign = Paint.Align.CENTER
        labelPaint.textSize = 38f
        labelPaint.color = Color.rgb(190, 190, 190)
        canvas.drawText("회차 전환", width / 2f, centerY - 28f, labelPaint)
        if (title.isNotEmpty()) {
            labelPaint.textSize = 54f
            labelPaint.color = Color.WHITE
            canvas.drawText(title, width / 2f, centerY + 40f, labelPaint)
        }
        labelPaint.textSize = 34f
        labelPaint.color = Color.rgb(190, 190, 190)
    }

    internal fun pageCardBackingBitmapForTest(index: Int): Bitmap? =
        synchronized(stateLock) {
            pages.getOrNull(index)?.takeIf { it.cardText != null }?.cardBitmap
        }

    internal fun pageImageBitmapPresentForTest(index: Int): Boolean =
        synchronized(stateLock) {
            pages.getOrNull(index)?.bitmap != null
        }

    fun setPageError(index: Int, message: String) {
        val request = synchronized(stateLock) {
            val page = pages.getOrNull(index) ?: return
            if (page.bitmap != null || page.tiles.isNotEmpty() || page.pendingBitmap != null || page.pendingTiles.isNotEmpty()) {
                Log.d(TAG, "reader_page_error_skip_drawable index=$index message=$message")
                return@synchronized null
            }
            if (inlineRealPixelsOnly) {
                // Keep the unresolved slot and its geometry honest. Error UI belongs outside the
                // pixel surface and must never cover missing source pixels.
                page.loading = false
                page.cardText = null
                page.errorText = null
                clearPendingResolveLocked(page)
                if (shouldRenderPageResolveNowLocked(index)) {
                    renderRequested = true
                    scheduleFrameLocked()
                    stateLock.notifyAll()
                    return@synchronized windowRequestLocked(lastBusy)
                }
                return@synchronized null
            }
            invalidateRetainedPageNodeStateLocked(index)
            rebuildLayoutLocked()
            val oldHeight = pageDrawHeightLocked(page)
            val oldTop = pageTopOrElseLocked(index, 0f)
            val viewportAnchor = viewportAnchorLocked()
            page.bitmap = null
            page.tiles = emptyList()
            page.width = width
            page.height = max(1, (height * 0.38f).toInt())
            page.loading = false
            page.cardText = null
            page.errorText = message
            clearPendingResolveLocked(page)
            clearDeferredLayoutGeometryLocked(page)
            deferInitialEmptyDraw = false
            val newHeight = pageDrawHeightLocked(page)
            applyPageHeightChangeLocked(index, oldTop, oldHeight, newHeight - oldHeight)
            restoreViewportAnchorLocked(viewportAnchor, "page_error", index, oldHeight, newHeight)
            applyLockedRestorePositionLocked()
            clampScrollLocked()
            renderRequested = true
            scheduleFrameLocked()
            stateLock.notifyAll()
            windowRequestLocked(lastBusy)
        }
        dispatchWindowRequest(request)
    }

    fun scrollToPage(index: Int) {
        scrollToPage(index, 0)
    }

    fun scrollToPage(index: Int, offset: Int) {
        val request = synchronized(stateLock) {
            val target = index.coerceIn(0, pages.lastIndex)
            rebuildLayoutLocked()
            activeScrollerOffsetShift = 0f
            setScrollOffsetLocked(pageTopOrElseLocked(target, 0f) - offset)
            clampScrollLocked()
            lastAnchor = -1
            renderRequested = true
            scheduleFrameLocked()
            stateLock.notifyAll()
            windowRequestLocked(false)
        }
        dispatchWindowRequest(request)
    }

    fun lockRestoredPageOffset(index: Int, offset: Int) {
        val request = synchronized(stateLock) {
            if (index !in 0 until pages.size) return
            if (physicalInputOwnsViewportLocked()) {
                // Discovery can finish after a real swipe has already moved or become a blocked
                // target. Re-arming the bookmark here used to pull 1743px back to 389px when p0
                // arrived, and could do the same after a normal edge-limited gesture.
                clearLockedRestorePositionLocked()
                clearDirectWifiForwardOnlyInitialResumeContractLocked()
                Log.i(
                    TAG,
                    "reader_restore_lock_skipped_physical_input index=$index " +
                        "pending=${preContentForwardIntentPx.toInt()} " +
                        "blocked=${if (blockedForwardIntentTarget.isFinite()) blockedForwardIntentTarget.toInt() else -1}",
                )
                return@synchronized windowRequestLocked(lastBusy)
            }
            val forwardOnlyResume = directWifiForwardOnlyInitialResumeEnabled &&
                surfaceAttachmentDeferredUntilActualPixels && !hasDrawnContentFrame
            if (forwardOnlyResume) {
                val nextOffset = min(0, offset)
                val resumeIdentityChanged =
                    directWifiForwardOnlyInitialResumePage != index ||
                        directWifiForwardOnlyInitialResumeOffset != nextOffset
                directWifiForwardOnlyInitialResumePage = index
                directWifiForwardOnlyInitialResumeOffset = nextOffset
                directWifiForwardOnlyInitialResumeRevealQualified = false
                if (resumeIdentityChanged) {
                    directWifiForwardOnlyTerminalTailRevealQualified = false
                }
            }
            lockedRestorePage = index
            // A positive offset exposes predecessor pixels above this page. The forward-only UX
            // deliberately did not request those pages, so start the exact resumed tail at the
            // top instead of manufacturing a placeholder viewport. The restored page can be the
            // first of several exact tail pages; requiring pages.lastIndex would strand that tail.
            lockedRestoreOffset = if (forwardOnlyResume) {
                directWifiForwardOnlyInitialResumeOffset
            } else {
                offset
            }
            lockedRestoreUntilMs = SystemClock.uptimeMillis() + RESTORE_POSITION_LOCK_MS
            applyLockedRestorePositionLocked()
            clampScrollLocked()
            lastAnchor = -1
            renderRequested = !shouldSuppressInitialEmptyRenderLocked()
            if (renderRequested) scheduleFrameLocked()
            stateLock.notifyAll()
            if (renderRequested) windowRequestLocked(false) else null
        }
        dispatchWindowRequest(request)
    }

    fun holdInitialRestoreRender(index: Int) {
        synchronized(stateLock) {
            if (index !in 0 until pages.size) return
            clearInitialRenderHoldLocked()
            renderRequested = true
            scheduleFrameLocked()
            stateLock.notifyAll()
        }
    }

    fun currentProgressPosition(): ProgressPosition? {
        return synchronized(stateLock) {
            progressPositionLocked()
        }
    }

    fun currentScrollPositionSnapshot(): ScrollPositionSnapshot? {
        return synchronized(stateLock) {
            val progress = progressPositionLocked() ?: return@synchronized null
            // A retained forward destination is network work, not moving pixels. Exposing it as
            // physical motion prevents lifecycle code from capturing a clean stationary viewport
            // and makes HOME appear permanently busy during a slow image response. The internal
            // controller keeps its own busy state for priority; this public snapshot describes
            // only a finger or OverScroller that is currently changing the viewport.
            val busy = isScrollBusyAfterSample(
                pointerDown = pointerDown,
                dragging = dragging,
                scrollerFinished = scroller.isFinished,
                blockedForwardIntentPending = false,
            )
            val maxScroll = maxScrollLocked().toInt()
            ScrollPositionSnapshot(progress.page, progress.offset, scrollOffset.toInt(), contentHeight.toInt(), maxScroll, busy)
        }
    }

    /** Identity and local reading coordinate captured from one current layout-lock epoch. */
    fun currentCommittedViewportAnchorSnapshot(): LifecycleViewportAnchorSnapshot? {
        // A native buffer can become physically current before its main-thread completed-draw
        // listener adopts the matching episode metadata. Exposing the live layout identity in
        // that interval let callers observe "new pixels + old Reader episode". Anchor public
        // committed state to the last proof the Activity actually processed, then rebase that
        // immutable identity through the current page table so prefix compaction remains safe.
        val deliveredProof = completedDrawDispatchQueue.latestDeliveredStableViewportProof()
        return synchronized(stateLock) {
            val progressPage = progressPositionLocked()?.page
            // Preserve the page that owns the reading probe, not merely a predecessor whose last
            // few pixels happen to touch the viewport top. If that predecessor's authoritative
            // height resolves during HOME, preserving its top moves the dominant next page even
            // though the first-page identity itself appears stable.
            val deliveredOwner = deliveredProof?.let { proof ->
                NtkCommittedViewportProofPolicy.readingIdentityIndex(
                    proof.visiblePageTopPx,
                    proof.coverage.physicalViewportPx,
                    proof.visiblePageIdentities.size,
                )
            } ?: -1
            val deliveredIdentity = deliveredProof?.visiblePageIdentities
                ?.getOrNull(deliveredOwner)
            val committedPage = deliveredIdentity?.let { proofIdentity ->
                pages.indexOfFirst { page ->
                    val current = page.committedIdentity
                    current != null &&
                        current.normalizedEpisodePath == proofIdentity.normalizedEpisodePath &&
                        current.sourcePageIndex == proofIdentity.sourcePageIndex &&
                        current.canonicalAsset == proofIdentity.canonicalAsset &&
                        current.manifestDigest == proofIdentity.manifestDigest &&
                        current.manifestPageCount == proofIdentity.manifestPageCount
                }.takeIf { it >= 0 }
            }
            val pageIndex = committedPage ?: progressPage
                ?: return@synchronized null
            val page = pages.getOrNull(pageIndex) ?: return@synchronized null
            val identity = page.committedIdentity ?: return@synchronized null
            val pageTop = pageTopOrElseLocked(pageIndex, Float.NaN)
            if (!pageTop.isFinite()) return@synchronized null
            LifecycleViewportAnchorSnapshot(
                identity = identity,
                pageTopInViewportPx = pageTop - scrollOffset,
                scrollOffsetPx = scrollOffset,
                page = pageIndex,
                busy = isScrollBusyAfterSample(
                    pointerDown = pointerDown,
                    dragging = dragging,
                    scrollerFinished = scroller.isFinished,
                    blockedForwardIntentPending = false,
                ),
            )
        }
    }

    /**
     * Reprojects the last physically committed page into the current layout before a lifecycle
     * redraw. Image dimensions and prefix compaction may change while HOME owns the display; an
     * absolute scroll coordinate cannot preserve what the user actually saw across that reflow.
     */
    fun restoreCommittedViewportForLifecycle(
        identity: CommittedPageIdentity,
        pageTopInViewportPx: Float,
        publishWindowRequest: Boolean = true,
    ): Boolean {
        if (!pageTopInViewportPx.isFinite()) return false
        val request: WindowRequest?
        val restored = synchronized(stateLock) {
            val target = pages.indexOfFirst { page ->
                val current = page.committedIdentity
                current != null &&
                    current.normalizedEpisodePath == identity.normalizedEpisodePath &&
                    current.sourcePageIndex == identity.sourcePageIndex &&
                    current.canonicalAsset == identity.canonicalAsset &&
                    current.manifestDigest == identity.manifestDigest &&
                    current.manifestPageCount == identity.manifestPageCount
            }
            if (target < 0) {
                request = null
                false
            } else {
                lifecycleViewportAnchorIdentity = identity
                lifecycleViewportAnchorPageTopPx = pageTopInViewportPx
                lifecycleRestoreInputPending = true
                rebuildLayoutLocked()
                val before = scrollOffset
                structuralScrollAdjustUntilMs = maxOf(
                    structuralScrollAdjustUntilMs,
                    SystemClock.uptimeMillis() + RESTORE_POSITION_LOCK_MS,
                )
                setStructuralScrollOffsetLocked(
                    pageTopOrElseLocked(target, 0f) - pageTopInViewportPx,
                )
                clampScrollLocked()
                lastAnchor = -1
                renderRequested = true
                scheduleFrameLocked()
                stateLock.notifyAll()
                // onPause preserves the exact coordinate but must not reopen decode/retirement
                // work while Launcher is waiting for this task's Surface transaction. onResume
                // publishes the same identity-bound request after the task owns the display.
                request = if (publishWindowRequest) windowRequestLocked(false) else null
                Log.d(
                    TAG,
                    "reader_lifecycle_physical_anchor_restore path=" +
                        "${identity.normalizedEpisodePath},source=${identity.sourcePageIndex}," +
                        "page=$target,top=$pageTopInViewportPx," +
                        "from=${before.toInt()},to=${scrollOffset.toInt()}",
                )
                true
            }
        }
        dispatchWindowRequest(request)
        return restored
    }

    /**
     * Removes the native child from the visible transaction graph at the Activity pause edge.
     *
     * Waiting for SurfaceView.surfaceDestroyed (normally delivered near onStop) leaves exact tile
     * layers active throughout the Launcher transition. On a host-GPU emulator those layers can
     * enter SurfaceFlinger's GPU fallback while network completions keep changing buffers, delaying
     * HOME by several seconds. Detach is asynchronous; this method only closes new submissions and
     * hides the child. Resume re-enters through the existing fresh-HWUI-commit reveal gate.
     */
    fun pauseNativePresentationForLifecycle() {
        check(Looper.myLooper() == Looper.getMainLooper())
        if (!rollingNativePresentationEnabled) return
        var detach: Pair<Long, Long>? = null
        synchronized(stateLock) {
            val attachedEpoch = rollingNativeAttachEpoch
            if (rollingNativeHandle != 0L && attachedEpoch > 0L) {
                detach = rollingNativeHandle to attachedEpoch
            }
            directSurfaceReady = false
            physicalMoveProducerReady = false
            retireDirectSurfaceSchedulingLocked()
            releaseRollingJavaChildSurfaceControlLocked()
            if (attachedEpoch > 0L) advanceRollingNativeSurfaceEpochLocked()
            rollingNativeAttachEpoch = 0L
            rollingNativeSurfaceIdentity = 0
            rollingNativeWidth = 0
            rollingNativeHeight = 0
            rollingNativeViewportWidth = 0
            rollingNativeViewportHeight = 0
            nativePresentationVisible = false
            nativeSurfaceContentRevealed = false
            nativePresentedStructureEpoch = 0L
            clearFramePipeLocked(preserveDirty = true)
            if (renderRunning && pages.isNotEmpty()) {
                nativeSurfaceRevealAfterFirstHwuiCommitPending = true
                nativeSurfaceRevealAfterPrepareEpoch = 0L
                // Keep the already-proven HWUI viewport as the visible owner until Android says
                // that the task-enter animation has finished. Creating a host-GPU Surface while
                // Launcher still owns that transition can stall both BufferQueues for seconds.
                lifecycleEnterAnimationPending = true
                lifecycleCleanHwuiRevealReady = false
            }
            stateLock.notifyAll()
        }
        nativeSurfaceView.alpha = 0f
        resetNativeSurfaceViewBandTransform()
        nativeSurfaceView.visibility = View.GONE
        detach?.let { (handle, epoch) ->
            NtkRollingNativeBridge.nativeDetach(handle, epoch)
        }
    }

    /** Opens a paused native reveal only after the task-enter compositor transition is finished. */
    fun completeLifecycleEnterAnimationForNativeReveal(reason: String): Boolean {
        check(Looper.myLooper() == Looper.getMainLooper())
        var revealEpoch = 0L
        val completed = synchronized(stateLock) {
            if (!lifecycleEnterAnimationPending) return@synchronized false
            lifecycleEnterAnimationPending = false
            if (nativeSurfaceRevealAfterFirstHwuiCommitPending &&
                lifecycleCleanHwuiRevealReady
            ) {
                nativeSurfaceRevealAfterFirstHwuiCommitPending = false
                lifecycleCleanHwuiRevealReady = false
                revealEpoch = lifecycleEpoch
            }
            stateLock.notifyAll()
            true
        }
        if (!completed) return false
        if (revealEpoch > 0L) {
            revealNativeSurfaceAfterFirstHwuiCommit(revealEpoch)
        } else {
            requestPendingNativeSurfaceHwuiCommit()
        }
        Log.d(
            TAG,
            "reader_lifecycle_enter_animation_complete reason=$reason," +
                "reveal=${revealEpoch > 0L},epoch=$revealEpoch",
        )
        return true
    }

    /**
     * Returns true only when the supplied committed-frame scroll coordinate exposed the physical
     * bottom of [displayPageIndex]. A continuously appended reader cannot use the surface's global
     * max scroll as an episode boundary, and merely seeing the final page is insufficient for a
     * tall webtoon image whose bottom may still be several viewports away.
     */
    fun isPageBottomReachedAtScroll(
        displayPageIndex: Int,
        committedScrollOffsetPx: Float,
    ): Boolean {
        return synchronized(stateLock) {
            if (!committedScrollOffsetPx.isFinite() || height <= 0 || displayPageIndex !in pages.indices) {
                return@synchronized false
            }
            rebuildLayoutLocked()
            val page = pages[displayPageIndex]
            val pageHeight = pageDrawHeightLocked(page)
            if (pageHeight <= 0f) return@synchronized false
            val pageBottom = pageTopOrElseLocked(displayPageIndex, Float.MAX_VALUE) + pageHeight
            val committedViewportBottom = committedScrollOffsetPx + height.toFloat()
            committedViewportBottom + BOUNDARY_EPSILON_PX >= pageBottom
        }
    }

    /**
     * Called only after ReaderV2Activity accepted the compositor proof with its normal immutable
     * identity and viewport checks.  The View repeats the tail-specific facts under stateLock so a
     * stale structure callback cannot release a newer episode boundary.
     */
    fun acknowledgeCleanPhysicalEpisodeTail(proof: CompletedDrawProof): Boolean {
        var newlyAcknowledgedDisplayPage = -1
        val acknowledged = synchronized(stateLock) {
            fun reject(reason: String): Boolean {
                val now = SystemClock.elapsedRealtime()
                if (physicalEpisodeTailHold != null &&
                    now - lastPhysicalEpisodeTailAckRejectLogAtMs >= 1_000L
                ) {
                    lastPhysicalEpisodeTailAckRejectLogAtMs = now
                    Log.d(
                        TAG,
                        "reader_physical_episode_tail_ack_reject reason=$reason," +
                            "proofEpoch=${proof.surfaceLifecycleEpoch}/${proof.structureEpoch}," +
                            "currentEpoch=$lifecycleEpoch/$traversalStructureEpoch," +
                            "scroll=${proof.scrollOffsetPx},hold=${physicalEpisodeTailHold?.scrollLimit}",
                    )
                }
                return false
            }
            if (proof.surfaceLifecycleEpoch != lifecycleEpoch ||
                proof.structureEpoch != traversalStructureEpoch || height <= 0
            ) return@synchronized reject("epoch_or_height")
            val identities = proof.visiblePageIdentities
            if (identities.isEmpty()) return@synchronized reject("empty_identities")
            val first = identities.first()
            val key = exactEpisodeTailKey(first) ?: return@synchronized reject("invalid_first_identity")
            val singleEpisodeViewport = identities.all { identity ->
                exactEpisodeTailKey(identity) == key
            }
            val tail = identities.maxByOrNull { identity -> identity.displayPageIndex }
                ?: return@synchronized false
            val current = pages.getOrNull(tail.displayPageIndex)?.committedIdentity
                ?: return@synchronized false
            val identityCurrent = current == tail
            rebuildLayoutLocked()
            val pageBottom = if (identityCurrent) {
                pageTopOrElseLocked(tail.displayPageIndex, Float.MAX_VALUE) +
                    pageDrawHeightLocked(pages[tail.displayPageIndex])
            } else {
                Float.MAX_VALUE
            }
            val pageBottomReached = proof.scrollOffsetPx.isFinite() &&
                proof.scrollOffsetPx + height + BOUNDARY_EPSILON_PX >= pageBottom
            val exactPresentation = proof.presentedUptimeNanos > 0L &&
                (proof.surfaceControlLatchObserved || proof.surfaceQueueSubmissionObserved ||
                    (proof.hardwareAccelerated &&
                        proof.registeredHwuiFrameCommitCallbackObserved)) && identityCurrent
            val coverage = proof.coverage
            if (proof.physicalGestureRevision <= 0L) {
                return@synchronized reject("missing_physical_gesture")
            }
            if (!NtkPhysicalEpisodeTailHoldPolicy.isCleanTailCommit(
                    exactPresentation = exactPresentation,
                    singleEpisodeViewport = singleEpisodeViewport,
                    tailSourceIndex = tail.sourcePageIndex,
                    manifestPageCount = tail.manifestPageCount,
                    pageBottomReached = pageBottomReached,
                    drawablePx = coverage.drawablePx,
                    missingPx = coverage.missingPx,
                    placeholderPx = coverage.placeholderPx,
                    visibleLoading = coverage.visibleLoading,
                    visibleErrors = coverage.visibleErrors,
                    visibleCards = coverage.visibleCards,
                    widthFillFailures = coverage.widthFillFailures,
                    lowResolutionItems = coverage.lowResolutionItems,
                )
            ) {
                if (physicalEpisodeTailHold?.key == key) {
                    physicalEpisodeTailProofRequestedKey = null
                }
                return@synchronized reject(
                    "clean_policy single=$singleEpisodeViewport,tail=${tail.sourcePageIndex}/" +
                        "${tail.manifestPageCount},current=$identityCurrent,bottom=$pageBottomReached," +
                        "coverage=${coverage.drawablePx}/${coverage.missingPx}/" +
                        "${coverage.placeholderPx}/${coverage.visibleLoading}/" +
                        "${coverage.visibleErrors}/${coverage.visibleCards}/" +
                        "${coverage.widthFillFailures}/${coverage.lowResolutionItems}",
                )
            }
            val added = !cleanPhysicalEpisodeTailGestureRevisions.containsKey(key)
            if (added) {
                // The commit callback can arrive after the next DOWN has already advanced the
                // live gesture revision. Attribute this tail proof to the immutable gesture that
                // authored the submitted frame; using the live revision makes the next gesture
                // look self-acknowledged and consumes one unnecessary additional swipe.
                cleanPhysicalEpisodeTailGestureRevisions[key] = proof.physicalGestureRevision
                cleanPhysicalEpisodeTailPresentedNanos[key] = proof.presentedUptimeNanos
                newlyAcknowledgedDisplayPage = tail.displayPageIndex
            }
            if (physicalEpisodeTailProofRequestedKey == key) {
                physicalEpisodeTailProofRequestedKey = null
            }
            while (cleanPhysicalEpisodeTailGestureRevisions.size >
                MAX_CLEAN_PHYSICAL_EPISODE_TAIL_KEYS
            ) {
                val iterator = cleanPhysicalEpisodeTailGestureRevisions.entries.iterator()
                if (!iterator.hasNext()) break
                val retired = iterator.next().key
                iterator.remove()
                cleanPhysicalEpisodeTailPresentedNanos.remove(retired)
            }
            if (added) {
                Log.d(
                    TAG,
                    "reader_physical_episode_tail_ack path=${key.normalizedEpisodePath} " +
                        "source=${tail.sourcePageIndex},page=${tail.displayPageIndex}," +
                        "scroll=${proof.scrollOffsetPx.toInt()},token=${proof.frameToken}," +
                        "gesture=${proof.physicalGestureRevision}",
                )
            }
            true
        }
        if (newlyAcknowledgedDisplayPage >= 0) {
            listener?.onCleanPhysicalEpisodeTailAcknowledged(newlyAcknowledgedDisplayPage)
        }
        return acknowledged
    }

    /**
     * A late page-height resolve can briefly place an already-appended successor inside a clean
     * native proof before the predecessor's short final source has itself been presented.  The
     * Activity must not turn that transient geometry into current-episode state.  Structural
     * identity is sufficient to find the predecessor, but only the compositor acknowledgement
     * above is sufficient to cross it.
     */
    fun isPhysicalAdjacentEpisodeAdoptionAllowed(
        displayPageIndex: Int,
        normalizedEpisodePath: String,
    ): Boolean = synchronized(stateLock) {
        val target = pages.getOrNull(displayPageIndex)?.committedIdentity
            ?: return@synchronized false
        val targetKey = exactEpisodeTailKey(target) ?: return@synchronized false
        if (targetKey.normalizedEpisodePath != normalizedEpisodePath) return@synchronized false
        var predecessor: CommittedPageIdentity? = null
        for (index in displayPageIndex - 1 downTo 0) {
            val identity = pages[index].committedIdentity ?: continue
            if (exactEpisodeTailKey(identity) == targetKey) continue
            predecessor = identity
            break
        }
        val previous = predecessor ?: return@synchronized true
        val previousKey = exactEpisodeTailKey(previous) ?: return@synchronized false
        NtkPhysicalEpisodeTailHoldPolicy.mayAdoptAdjacentEpisode(
            predecessorIsExactTail =
                previous.sourcePageIndex == previous.manifestPageCount - 1,
            predecessorTailAcknowledged =
                isPriorGestureCleanTailAcknowledgementObservableLocked(previousKey),
        )
    }

    /**
     * Guards ordinary scroll-position metadata updates with the same exact predecessor-tail proof
     * used by compositor-driven adoption.  Position callbacks may run while late page geometry is
     * being installed; allowing them to publish the successor first makes the reader report a
     * chapter that has not yet physically crossed its predecessor's clean tail.
     */
    fun isForwardEpisodeMetadataAdoptionAllowed(
        displayPageIndex: Int,
        currentEpisodePath: String,
        targetEpisodePath: String,
    ): Boolean = synchronized(stateLock) {
        val currentPath = currentEpisodePath.trim()
        val targetPath = targetEpisodePath.trim()
        if (currentPath.isEmpty() || targetPath.isEmpty() || currentPath == targetPath) {
            return@synchronized false
        }
        val target = pages.getOrNull(displayPageIndex)?.committedIdentity
            ?: return@synchronized false
        val targetKey = exactEpisodeTailKey(target) ?: return@synchronized false
        if (targetKey.normalizedEpisodePath != targetPath) return@synchronized false
        for (index in displayPageIndex - 1 downTo 0) {
            val identity = pages[index].committedIdentity ?: continue
            val path = identity.normalizedEpisodePath
            if (path == targetPath) continue
            // Only a directly adjacent transition can authorize this metadata change.  Encountering
            // another episode first means a stale position callback skipped an identity.
            if (path != currentPath) return@synchronized false
            val predecessorKey = exactEpisodeTailKey(identity)
                ?: return@synchronized false
            return@synchronized NtkPhysicalEpisodeTailHoldPolicy.mayAdoptAdjacentEpisode(
                predecessorIsExactTail =
                    identity.sourcePageIndex == identity.manifestPageCount - 1,
                predecessorTailAcknowledged =
                    isPriorGestureCleanTailAcknowledgementObservableLocked(predecessorKey),
            )
        }
        false
    }

    /** Must hold [stateLock]. Same-gesture ACKs keep the boundary closed until later input. */
    private fun isPriorGestureCleanTailAcknowledgementObservableLocked(
        key: ExactEpisodeTailKey,
    ): Boolean = NtkPhysicalEpisodeTailHoldPolicy.isPriorGestureAcknowledgementObservable(
        acknowledgedGestureRevision = cleanPhysicalEpisodeTailGestureRevisions[key],
        currentGestureRevision = physicalGestureRevision,
        presentedUptimeNanos = cleanPhysicalEpisodeTailPresentedNanos[key] ?: 0L,
        nowUptimeNanos = SystemClock.elapsedRealtimeNanos(),
        minimumDwellNanos = CLEAN_PHYSICAL_EPISODE_TAIL_MIN_DWELL_NANOS,
    )

    fun testScrollByPixels(deltaPx: Float) {
        val request = synchronized(stateLock) {
            statsAwaitingFirstInput = false
            rebuildLayoutLocked()
            val maxScroll = maxScrollLocked().coerceAtLeast(0f)
            lastScrollInteractionMs = SystemClock.uptimeMillis()
            activateScrollStatsLocked(lastScrollInteractionMs)
            setScrollOffsetLocked((scrollOffset + deltaPx).coerceIn(0f, maxScroll))
            scroller.forceFinished(true)
            renderRequested = true
            scheduleFrameLocked()
            Log.d(
                TAG,
                "reader_test_scroll delta=${fmt(deltaPx)} scroll=${fmt(scrollOffset)} max=${fmt(maxScroll)} " +
                    "pages=${pages.size} framePipe=$framePipe renderRunning=$renderRunning"
            )
            stateLock.notifyAll()
            windowRequestLocked(true)
        }
        dispatchWindowRequest(request)
    }

    /**
     * Oversized strict scenes transfer bitmap ownership to this View. A JNI GlobalRef keeps the
     * Java object reachable but does not prevent Bitmap.recycle(); the old fixed 250 ms timer could
     * therefore invalidate a queued native frame while a slow swap or retirement barrier still
     * owned its pixels. Mark the identity unavailable to every newer JNI handoff immediately, then
     * recycle only at the native worker's exact quiescent boundary.
     */
    fun clearRollingAuthoritativePage(index: Int): Boolean {
        var stripCleared = false
        val stripRequest = synchronized(stateLock) {
            val page = pages.getOrNull(index) ?: return false
            val authority = stripAuthorityToken
            if (authority != 0L && page.stripAuthority == authority) {
                val geometry = stripGeometry ?: return false
                val pageGeometry = geometry.pages.getOrNull(index) ?: return false
                if (page.stripEpisode != geometry.episode.value ||
                    page.stripAsset != pageGeometry.asset.canonicalAsset ||
                    page.stripSlots.size != pageGeometry.tiles.size
                ) return false

                // Geometry and exact encoded-body ownership outlive decoded pixels. Remove every
                // resident slot from the same immutable strip table that installed it, so reverse
                // traversal can repopulate the identical keys without rebinding the scene. Merely
                // clearing Page.tiles leaves stripSlots/cycles/coverage authoritative and strands
                // the HostExact token forever while the Session believes the page was evicted.
                val residentSlots = page.stripSlots
                if (residentSlots.none { it != null }) {
                    stripCleared = true
                    return@synchronized null
                }
                val residentGeometries = ArrayList<NtkStripTileGeometry>()
                residentSlots.forEachIndexed { slotIndex, tile ->
                    if (tile == null) return@forEachIndexed
                    val tileGeometry = pageGeometry.tiles.getOrNull(slotIndex)
                        ?.takeIf { geometryTile ->
                            geometryTile.key.slotIndex == slotIndex &&
                                geometryTile.key.pageIndex == index &&
                                geometryTile.key.episode == geometry.episode
                        }
                        ?: return false
                    residentGeometries += tileGeometry
                }
                retireCurrentPageDrawableLocked(page)
                residentGeometries.forEach { tileGeometry ->
                    stripResidentCycles.remove(tileGeometry.key)
                    stripResidentCoverage.remove(
                        tileGeometry.contentTopPx,
                        tileGeometry.contentBottomPx,
                    )
                }
                page.stripSlots = List(pageGeometry.tiles.size) { null }
                page.tiles = emptyList()
                page.bitmap = null
                page.loading = false
                page.errorText = null
                clearPendingResolveLocked(page)
                invalidateRetainedPageNodeStateLocked(index)
                lastVisibleCoverageSnapshot = null
                stripCleared = true
                val renderNow = shouldRenderPageResolveNowLocked(index)
                if (renderNow) {
                    renderRequested = true
                    scheduleFrameLocked()
                    stateLock.notifyAll()
                    return@synchronized windowRequestLocked(lastBusy)
                }
                stateLock.notifyAll()
                return@synchronized null
            }
            if (authority != 0L &&
                !isIndependentAdjacentRunwayOriginalLocked(
                    index,
                    page,
                    page.width,
                    page.height,
                    page.originalProof,
                )
            ) {
                // Exact-p0 slot resources have a separate owner/slot identity and cannot be
                // cleared through the launch-strip protocol above.
                return false
            }
            LinkedHashSet<Bitmap>().apply {
                page.bitmap?.takeUnless(Bitmap::isRecycled)?.let(::add)
                page.tiles.forEach { tile ->
                    tile.bitmap.takeUnless(Bitmap::isRecycled)?.let(::add)
                }
            }.toList().also { bitmaps ->
                // This call is immediately followed by the exact page clear, so arm the outgoing
                // hold even though the identities are still current in this critical section.
                retireSurfaceOwnedBitmapIdentitiesLocked(bitmaps, holdReferenced = true)
            }
            null
        }
        if (stripCleared) {
            dispatchWindowRequest(stripRequest)
            return true
        }
        if (!clearPageBitmap(index, allowIndependentAdjacentRunway = true)) return false
        return true
    }

    /**
     * Accepts terminal ownership of Bitmap identities that may already have crossed a JNI handoff.
     * A Java GlobalRef keeps the object reachable but cannot stop another owner from calling
     * Bitmap.recycle(), so every Activity/Session abandonment must join this same native-idle
     * retirement domain instead of recycling directly.
     */
    fun retireSurfaceOwnedBitmaps(bitmaps: Iterable<Bitmap>) {
        synchronized(stateLock) {
            retireSurfaceOwnedBitmapIdentitiesLocked(bitmaps)
        }
    }

    /** Must be called with [stateLock] held. */
    private fun retireSurfaceOwnedBitmapIdentitiesLocked(
        candidates: Iterable<Bitmap>,
        retained: Iterable<Bitmap> = emptyList(),
        holdReferenced: Boolean = false,
    ) {
        val retired = BitmapReleaseIdentityPolicy.uniqueCandidatesExcludingRetained(
            candidates,
            retained,
        ).filterNot(Bitmap::isRecycled)
        if (retired.isEmpty()) return
        surfaceOwnedRecycleCandidates.addAll(retired)
        // A final-owner request can arrive while a deferred replacement still displays the old
        // identity. Preserve that intent, but keep a valid current/shared identity usable by JNI.
        // Its eventual replacement/clear goes through holdBitmapIdentities... and arms the fence.
        val holds = if (holdReferenced || !renderRunning) {
            retired
        } else {
            retired.filterNot(::isBitmapCurrentlyReferencedLocked)
        }
        if (nativeRetirementHolds.addAll(holds)) {
            rollingNativeRetirementHoldGeneration += 1L
            rollingAuthoritativeRecycleRecheckMs =
                ROLLING_AUTHORITATIVE_RECYCLE_RECHECK_MS
        }
        scheduleRollingAuthoritativeRecycleLocked()
    }

    /**
     * Fences an outgoing drawable without assuming final ownership. Prepared-store resources are
     * borrowed: they need JNI retirement ordering, but only their actual owner may recycle them.
     */
    private fun holdBitmapIdentitiesForNativeRetirementLocked(
        candidates: Iterable<Bitmap>,
        retained: Iterable<Bitmap> = emptyList(),
    ) {
        val held = BitmapReleaseIdentityPolicy.uniqueCandidatesExcludingRetained(
            candidates,
            retained,
        ).filterNot(Bitmap::isRecycled)
        if (held.isEmpty()) return
        if (nativeRetirementHolds.addAll(held)) {
            rollingNativeRetirementHoldGeneration += 1L
            rollingAuthoritativeRecycleRecheckMs =
                ROLLING_AUTHORITATIVE_RECYCLE_RECHECK_MS
        }
        scheduleRollingAuthoritativeRecycleLocked()
    }

    /** Must be called with [stateLock] held. */
    private fun retireCurrentPageDrawableLocked(
        page: Page,
        retained: Iterable<Bitmap> = emptyList(),
    ) {
        retireReplacedPageDrawableLocked(
            buildList {
                page.bitmap?.let(::add)
                page.nativeCardBitmap?.let(::add)
                page.tiles.forEach { tile -> add(tile.bitmap) }
            },
            retained,
        )
    }

    /** Must be called with [stateLock] held. */
    private fun retirePendingPageDrawableLocked(
        page: Page,
        retained: Iterable<Bitmap> = emptyList(),
    ) {
        retireReplacedPageDrawableLocked(
            buildList {
                page.pendingBitmap?.let(::add)
                page.pendingTiles.forEach { tile -> add(tile.bitmap) }
            },
            retained,
        )
    }

    /** Must be called with [stateLock] held. */
    private fun retireReplacedPageDrawableLocked(
        candidates: Iterable<Bitmap>,
        retained: Iterable<Bitmap>,
    ) {
        val outgoing = BitmapReleaseIdentityPolicy.uniqueCandidatesExcludingRetained(
            candidates,
            retained,
        ).filterNot(Bitmap::isRecycled)
        if (outgoing.isEmpty()) return
        val pooled = outgoing.filter(HostExactHardwareTilePool::isActiveToken)
        if (pooled.isNotEmpty()) {
            // An accepted host-exact token crossed Session's externally-owned seam into this
            // Surface. Unlike a prepared-store Bitmap it has no cache owner to reclaim it after
            // replacement. Merely adding a native hold orphaned the pool slot forever because
            // Session correctly excluded external identities from its final-owner handoff.
            retireSurfaceOwnedBitmapIdentitiesLocked(pooled, holdReferenced = true)
        }
        val borrowed = outgoing.filterNot(HostExactHardwareTilePool::isActiveToken)
        if (borrowed.isNotEmpty()) {
            holdBitmapIdentitiesForNativeRetirementLocked(borrowed)
        }
    }

    /** Must be called with [stateLock] held. */
    private fun scheduleRollingAuthoritativeRecycleLocked() {
        if (nativeRetirementHolds.isEmpty() || rollingAuthoritativeRecyclePosted ||
            rollingNativeRetirementProbeInFlight
        ) {
            return
        }
        rollingAuthoritativeRecyclePosted = true
        if (!mainHandler.postDelayed(
                rollingAuthoritativeRecycleRunnable,
                rollingAuthoritativeRecycleRecheckMs,
            )
        ) {
            rollingAuthoritativeRecyclePosted = false
        }
    }

    /** Must be called with [stateLock] held. */
    private fun bitmapHasNativeRetirementFenceLocked(bitmap: Bitmap): Boolean {
        return bitmap in nativeRetirementHolds
    }

    /** Exact identity lookup maintained by Page setters; independent of page and tile count. */
    private fun isBitmapCurrentlyReferencedLocked(candidate: Bitmap): Boolean {
        return pageBitmapReferences.references(candidate)
    }

    /** Must be called with [stateLock] held. */
    private fun removeCurrentlyReferencedNativeRetirementHoldsLocked() {
        val iterator = nativeRetirementHolds.iterator()
        while (iterator.hasNext()) {
            val bitmap = iterator.next()
            // A detached View can still retain its immutable Page table until the Activity object
            // is collected. Once Session transferred final ownership into
            // surfaceOwnedRecycleCandidates, that Java reference is no longer a drawable owner:
            // renderRunning=false prohibits new submissions and the native destroy fence below
            // still protects every already-queued frame. Treating the dead Page table as current
            // here orphaned the whole host-exact pool across a rapid close/reopen.
            val terminalDetachedReference =
                !renderRunning && bitmap in surfaceOwnedRecycleCandidates
            if (isBitmapCurrentlyReferencedLocked(bitmap) && !terminalDetachedReference) {
                iterator.remove()
            }
        }
    }

    /**
     * Captures a native ownership query on main, then executes every potentially blocking JNI
     * call on the serial retirement owner. Candidates stay submit-fenced throughout the query.
     */
    private fun drainRollingAuthoritativeRecycles() {
        val probe = synchronized(stateLock) {
            rollingAuthoritativeRecyclePosted = false
            if (nativeRetirementHolds.isEmpty() || rollingNativeRetirementProbeInFlight) {
                return
            }

            removeCurrentlyReferencedNativeRetirementHoldsLocked()
            if (nativeRetirementHolds.isEmpty()) return

            val nativeOwnerStable = !nativeFrameSubmissionInFlight &&
                deferredNativeSceneSubmissionsInFlight.get() == 0 &&
                !nativeTexturePrewarmSubmissionInFlight &&
                rollingNativeDestroyInFlightCount == 0 &&
                !rollingNativeCreatePending && !rollingNativeRecoveryPending
            if (!nativeOwnerStable) {
                scheduleRollingAuthoritativeRecycleLocked()
                return
            }

            val candidates = nativeRetirementHolds.toList()
            val identities = IntArray(candidates.size) { index ->
                System.identityHashCode(candidates[index])
            }
            rollingNativeRetirementProbeInFlight = true
            NativeRetirementProbe(
                handle = rollingNativeHandle,
                candidates = candidates,
                resources = Array<Any>(candidates.size) { index -> candidates[index] },
                identities = identities,
                protectedAdmissionToken = if (
                    framePipe == FramePipe.INVALIDATION_POSTED
                ) inFlightToken else 0L,
                holdGeneration = rollingNativeRetirementHoldGeneration,
            )
        }
        if (ReaderBitmapRetirementDispatcher.dispatchWork {
                executeRollingAuthoritativeRecycleProbe(probe)
            }
        ) return

        synchronized(stateLock) {
            rollingNativeRetirementProbeInFlight = false
            scheduleRollingAuthoritativeRecycleLocked()
            stateLock.notifyAll()
        }
    }

    /** Serial retirement-worker phase; never runs on main or the display producer Looper. */
    private fun executeRollingAuthoritativeRecycleProbe(probe: NativeRetirementProbe) {
        // Page retirement is part of the rolling storage window, not speculative pixel work.
        // Deferring it for the entire gesture pins every consumed HostExact slot and forces later
        // visible pages to allocate new hardware buffers during motion. All renderer-queue probes
        // below use try-lock admission, and the bitmap ledger query returns null when busy, so this
        // background owner can make progress between frames without ever waiting in front of the
        // display producer.
        val drainStartedNs = SystemClock.elapsedRealtimeNanos()
        var identityScanNs = 0L
        var frameDiscardNs = 0L
        var discardNs = 0L
        var referenceMaskNs = 0L
        var poolRetirementNs = 0L
        var ordinaryRecycles: List<Bitmap> = emptyList()
        try {
            var discardedTokens: LongArray? = LongArray(0)
            if (probe.handle != 0L) {
                val frameDiscardStartedNs = SystemClock.elapsedRealtimeNanos()
                discardedTokens = runCatching {
                    NtkRollingNativeBridge.nativeDiscardQueuedFramesWithRetiredBitmaps(
                        probe.handle,
                        probe.resources,
                        probe.identities,
                        probe.protectedAdmissionToken,
                    )
                }.getOrNull()
                frameDiscardNs = SystemClock.elapsedRealtimeNanos() - frameDiscardStartedNs

                val discardStartedNs = SystemClock.elapsedRealtimeNanos()
                runCatching {
                    NtkRollingNativeBridge.nativeDiscardQueuedPrewarmBitmaps(
                        probe.handle,
                        probe.resources,
                        probe.identities,
                    )
                }.onFailure { failure ->
                    Log.w(TAG, "Unable to discard retired native prewarm references", failure)
                }
                discardNs = SystemClock.elapsedRealtimeNanos() - discardStartedNs
            }

            val referenceMaskStartedNs = SystemClock.elapsedRealtimeNanos()
            val referenced = if (probe.handle == 0L) {
                BooleanArray(probe.candidates.size)
            } else {
                runCatching {
                    NtkRollingNativeBridge.nativeBitmapReferenceMask(
                        probe.handle,
                        probe.identities,
                    )
                }.getOrNull()
            }
            referenceMaskNs = SystemClock.elapsedRealtimeNanos() - referenceMaskStartedNs

            synchronized(stateLock) {
                val holdCountBefore = nativeRetirementHolds.size
                discardedTokens?.forEach { token ->
                    if (token > 0L && pendingFrameCommits.remove(token) != null) {
                        nativeMailboxSupersededRetirements++
                    }
                    earlyNativeOutcomes.remove(token)
                    earlyFrameSyncedGeometryRequests.remove(token)
                    frameSyncedGeometryInFlightTokens.remove(token)
                    frameSyncedGeometrySubmissionOrder.remove(token)
                }
                val identityScanStartedNs = SystemClock.elapsedRealtimeNanos()
                val current = BooleanArray(probe.candidates.size) { index ->
                    val bitmap = probe.candidates[index]
                    isBitmapCurrentlyReferencedLocked(bitmap) &&
                        (renderRunning || bitmap !in surfaceOwnedRecycleCandidates)
                }
                identityScanNs = SystemClock.elapsedRealtimeNanos() - identityScanStartedNs
                probe.candidates.forEachIndexed { index, bitmap ->
                    if (current[index]) nativeRetirementHolds.remove(bitmap)
                }

                // A failed query or a renderer replacement is not permission to recycle. The
                // unchanged hold set retries after the active lifecycle settles.
                if (rollingNativeHandle == probe.handle && discardedTokens != null &&
                    referenced != null && referenced.size == probe.candidates.size
                ) {
                    val recyclable = ArrayList<Bitmap>(probe.candidates.size)
                    probe.candidates.forEachIndexed { index, bitmap ->
                        if (referenced[index] || current[index]) return@forEachIndexed
                        nativeRetirementHolds.remove(bitmap)
                        if (surfaceOwnedRecycleCandidates.remove(bitmap) && !bitmap.isRecycled) {
                            recyclable += bitmap
                        }
                    }
                    val poolRetirementStartedNs = SystemClock.elapsedRealtimeNanos()
                    val pooled = HostExactHardwareTilePool.retireAll(recyclable)
                    poolRetirementNs =
                        SystemClock.elapsedRealtimeNanos() - poolRetirementStartedNs
                    ordinaryRecycles = recyclable.filter { bitmap ->
                        bitmap !in pooled && !bitmap.isRecycled
                    }
                    ordinaryBitmapRetirementsInFlight += ordinaryRecycles.size
                }
                rollingNativeRetirementProbeInFlight = false
                val madeProgress = nativeRetirementHolds.size < holdCountBefore
                rollingAuthoritativeRecycleRecheckMs = if (
                    madeProgress ||
                    rollingNativeRetirementHoldGeneration != probe.holdGeneration
                ) {
                    ROLLING_AUTHORITATIVE_RECYCLE_RECHECK_MS
                } else {
                    (rollingAuthoritativeRecycleRecheckMs * 2L).coerceAtMost(
                        ROLLING_AUTHORITATIVE_RECYCLE_MAX_RECHECK_MS,
                    )
                }
                scheduleRollingAuthoritativeRecycleLocked()
                stateLock.notifyAll()
            }
            if (ordinaryRecycles.isNotEmpty()) {
                val retirementCount = ordinaryRecycles.size
                val accepted = ReaderBitmapRetirementDispatcher.dispatch(ordinaryRecycles) {
                    synchronized(stateLock) {
                        check(ordinaryBitmapRetirementsInFlight >= retirementCount)
                        ordinaryBitmapRetirementsInFlight -= retirementCount
                        stateLock.notifyAll()
                    }
                }
                if (!accepted) {
                    synchronized(stateLock) {
                        check(ordinaryBitmapRetirementsInFlight >= retirementCount)
                        ordinaryBitmapRetirementsInFlight -= retirementCount
                        stateLock.notifyAll()
                    }
                }
            }
        } finally {
            synchronized(stateLock) {
                if (rollingNativeRetirementProbeInFlight) {
                    rollingNativeRetirementProbeInFlight = false
                    scheduleRollingAuthoritativeRecycleLocked()
                    stateLock.notifyAll()
                }
            }
            val totalNs = SystemClock.elapsedRealtimeNanos() - drainStartedNs
            if (totalNs >= SLOW_NATIVE_RETIREMENT_DRAIN_NANOS) {
                Log.w(
                    TAG,
                    "reader_native_retirement_slow totalMs=${fmt(nsToMs(totalNs))} " +
                        "scanMs=${fmt(nsToMs(identityScanNs))} " +
                        "frameDiscardMs=${fmt(nsToMs(frameDiscardNs))} " +
                        "discardMs=${fmt(nsToMs(discardNs))} " +
                        "maskMs=${fmt(nsToMs(referenceMaskNs))} " +
                        "poolMs=${fmt(nsToMs(poolRetirementNs))} " +
                        "candidates=${probe.candidates.size}",
                )
            }
        }
    }

    /** Completes the ownership interval begun before an installed native handle is retired. */
    private fun completeRollingNativeDestroy() {
        synchronized(stateLock) {
            check(rollingNativeDestroyInFlightCount > 0) {
                "Native destroy completion did not own a renderer"
            }
            rollingNativeDestroyInFlightCount -= 1
            scheduleRollingAuthoritativeRecycleLocked()
            stateLock.notifyAll()
        }
    }

    /** Bounded qualification diagnostic; contains pipeline state only, never image data. */
    fun renderPipelineDiagnosticSnapshot(): String = synchronized(stateLock) {
        val nativeHandle = rollingNativeHandle
        val nativeWorkerQuiescent = !rollingNativeRetirementProbeInFlight &&
            rollingNativeDestroyInFlightCount == 0 &&
            (nativeHandle == 0L || NtkRollingNativeBridge.nativeIsQuiescent(nativeHandle))
        val nativePrewarmPending = nativeTexturePrewarmFlushPosted ||
            nativeTexturePrewarmSubmissionInFlight || nativeFrameSubmissionInFlight ||
            deferredNativeSceneSubmissionsInFlight.get() > 0
        val nativeLifecyclePending = rollingNativeRecoveryPending ||
            rollingNativeCreatePending || rollingNativeDestroyInFlightCount > 0 ||
            rollingNativeFatal || nativeHostBoundsReattachPending ||
            nativeSurfaceRevealAfterFirstHwuiCommitPending ||
            nativeSurfaceRevealAfterPrepareEpoch > 0L ||
            surfaceAttachmentDeferredUntilActualPixels ||
            (rollingNativePresentationEnabled && !rollingNativeFatal && directSurfaceReady &&
                rollingNativeAttachEpoch == 0L &&
                (rollingNativeHandle != 0L || rollingNativeRecoveryAttempts > 0))
        val tailHold = physicalEpisodeTailHold
        val tailAckRevision = tailHold?.key?.let(cleanPhysicalEpisodeTailGestureRevisions::get)
        val tailAckPresented = tailHold?.key?.let(cleanPhysicalEpisodeTailPresentedNanos::get)
        "pipe=$framePipe,inFlight=$inFlightToken,pending=${pendingFrameCommits.size}," +
            "earlyOutcomes=${earlyNativeOutcomes.size}," +
            "earlyGeometry=${earlyFrameSyncedGeometryRequests.size}," +
            "frameSyncedGeometry=${frameSyncedGeometryInFlightTokens.size}," +
            "noStateRetry=$noStateRetryPosted," +
            "noStateReason=$lastDrawStateNullReason," +
            "callbackPosted=$directFrameCallbackPosted,handler=${directRenderHandler != null}," +
            "choreographer=${directChoreographer != null},running=$renderRunning," +
            "directReady=$directSurfaceReady,surfaceValid=${rollingTextureSurface?.isValid == true}," +
            "native=${rollingNativeHandle != 0L},attach=$rollingNativeAttachEpoch," +
            "suppressed=$frameSchedulingSuppressed,requested=$renderRequested," +
            "versions=$desiredVersion/$drawnVersion/$committedVersion," +
            "pointer=$pointerDown,dragging=$dragging,scrolling=${!scroller.isFinished}," +
            "drawablePrefixLimit=$limitScrollToDrawablePrefix," +
            "gesture=$physicalGestureRevision,blockedIntent=$blockedForwardIntentTarget/" +
            "$blockedForwardIntentGestureRevision/$blockedForwardIntentExpiresAtMs," +
            "tailHold=${tailHold?.key?.normalizedEpisodePath.orEmpty()}/" +
            "${tailHold?.displayPageIndex ?: -1}/${tailHold?.scrollLimit ?: -1f}/" +
            "$physicalEpisodeTailHoldGestureRevision,tailAck=$tailAckRevision/" +
            "$tailAckPresented,tailProof=${physicalEpisodeTailProofRequestedKey != null}," +
            "direction=$activeInputDirection,reverseHint=$pendingReverseWindowFirstPageHint," +
            "prewarmPaused=$nativeTexturePrewarmPaused,prewarmDirty=$nativeTexturePrewarmDirty," +
            "prewarmDormant=$nativeTexturePrewarmDormant," +
            "prewarmPosted=$nativeTexturePrewarmFlushPosted," +
            "prewarmInFlight=$nativeTexturePrewarmSubmissionInFlight," +
            "frameSubmitInFlight=$nativeFrameSubmissionInFlight," +
            "deferredSceneSubmitInFlight=${deferredNativeSceneSubmissionsInFlight.get()}," +
            "retirementProbeInFlight=$rollingNativeRetirementProbeInFlight," +
            "prewarmPages=${nativeTexturePrewarmPendingPages.size}," +
            "bitmapRetireInFlight=$ordinaryBitmapRetirementsInFlight," +
            "poolMaintenanceIdle=${HostExactHardwareTilePool.isMaintenanceIdle()}/" +
            "${HostExactHardwareTilePool.maintenanceDiagnostic()}," +
            "nativeWorkerIdle=$nativeWorkerQuiescent," +
            "nativeDestroyInFlight=$rollingNativeDestroyInFlightCount," +
            "recoveryPending=$rollingNativeRecoveryPending," +
            "createPending=$rollingNativeCreatePending," +
            "fatal=$rollingNativeFatal,prewarmPending=$nativePrewarmPending," +
            "lifecyclePending=$nativeLifecyclePending,deferredAttach=" +
            "$surfaceAttachmentDeferredUntilActualPixels," +
            "reattachPending=$nativeHostBoundsReattachPending," +
            "revealPending=$nativeSurfaceRevealAfterFirstHwuiCommitPending/" +
            "$nativeSurfaceRevealAfterPrepareEpoch," +
            "nativeRevealed=$nativeSurfaceContentRevealed"
    }

    fun nativeRetirementStatsSnapshot(): NativeRetirementStatsSnapshot = synchronized(stateLock) {
        NativeRetirementStatsSnapshot(
            mailboxSuperseded = nativeMailboxSupersededRetirements,
            presentFailed = nativePresentFailedRetirements,
            lifecycleRetired = nativeLifecycleRetirements,
            unknown = nativeUnknownRetirements,
            rendererFatal = nativeRendererFatals,
            recreate = nativeRendererRecreates,
            permanentFallback = nativePermanentFallbacks,
            attachEpoch = rollingNativeAttachEpoch,
        )
    }

    fun nativeRetirementStatsSnapshotForTest(): NativeRetirementStatsSnapshot {
        return nativeRetirementStatsSnapshot()
    }

    /** Read-only idle fence used by stress tests before taking retirement counter deltas. */
    fun isNativePipelineQuiescentForTest(): Boolean = synchronized(stateLock) {
        val nativeHandle = rollingNativeHandle
        val nativeWorkerQuiescent = !rollingNativeRetirementProbeInFlight &&
            rollingNativeDestroyInFlightCount == 0 &&
            (nativeHandle == 0L || NtkRollingNativeBridge.nativeIsQuiescent(nativeHandle))
        // Dirty/pending-page ledgers can describe decoded pixels outside the currently admissible
        // runway. If no handler flush is posted and no JNI handoff is active, they are dormant
        // intent rather than work that can mutate GPU/PSS state. A later pixel/window event posts
        // a flush and immediately makes this fence false again.
        val nativePrewarmPending = nativeTexturePrewarmFlushPosted ||
            nativeTexturePrewarmSubmissionInFlight || nativeFrameSubmissionInFlight ||
            deferredNativeSceneSubmissionsInFlight.get() > 0
        val nativeLifecyclePending = rollingNativeRecoveryPending ||
            rollingNativeCreatePending || rollingNativeDestroyInFlightCount > 0 ||
            rollingNativeFatal || nativeHostBoundsReattachPending ||
            nativeSurfaceRevealAfterFirstHwuiCommitPending ||
            nativeSurfaceRevealAfterPrepareEpoch > 0L ||
            surfaceAttachmentDeferredUntilActualPixels ||
            (rollingNativePresentationEnabled && !rollingNativeFatal && directSurfaceReady &&
                rollingNativeAttachEpoch == 0L &&
                (rollingNativeHandle != 0L || rollingNativeRecoveryAttempts > 0))
        framePipe == FramePipe.IDLE && inFlightToken == 0L &&
            pendingFrameCommits.isEmpty() && earlyNativeOutcomes.isEmpty() &&
            earlyFrameSyncedGeometryRequests.isEmpty() &&
            frameSyncedGeometryInFlightTokens.isEmpty() &&
            !renderRequested && scroller.isFinished && !directFrameCallbackPosted &&
            !noStateRetryPosted && !nativePrewarmPending && !nativeLifecyclePending &&
            ordinaryBitmapRetirementsInFlight == 0 &&
            !rollingNativeRetirementProbeInFlight &&
            HostExactHardwareTilePool.isMaintenanceIdle() && nativeWorkerQuiescent
    }

    fun visibleCoverageSnapshot(): VisibleCoverageSnapshot? {
        return synchronized(stateLock) {
            lastVisibleCoverageSnapshot
        }
    }

    /** Rejects a completion that was submitted by an earlier physical gesture. */
    fun isCurrentPhysicalGestureRevision(revision: Long): Boolean =
        synchronized(stateLock) { revision == physicalGestureRevision }

    /**
     * Retires every pending commit token without clearing installed drawables. Used across
     * background/configuration boundaries so stale `actual:` semantics cannot survive without a
     * new draw from the new lifecycle epoch.
     */
    @JvmOverloads
    fun invalidateCommittedPresentationProof(scheduleIfVisible: Boolean = true) {
        synchronized(stateLock) {
            clearFramePipeLocked(preserveDirty = true)
            resetTraversalProofLocked(pages.size)
            advanceDesiredVersionLocked()
            renderRequested = true
            if (scheduleIfVisible && renderRunning && pages.isNotEmpty() && isShown &&
                windowVisibility == View.VISIBLE
            ) {
                scheduleFrameLocked()
            }
            stateLock.notifyAll()
        }
    }

    fun refreshVisibleCoverageSnapshot(): VisibleCoverageSnapshot? {
        return synchronized(stateLock) {
            refreshVisibleCoverageSnapshotLocked()
        }
    }

    private fun refreshVisibleCoverageSnapshotLocked(): VisibleCoverageSnapshot? {
        val state = buildDrawStateLocked(lastBusy, allowVisibleLoadingState = false)
            ?: return lastVisibleCoverageSnapshot
        val snapshot = visibleCoverageSnapshotFromState(state)
        lastVisibleCoverageSnapshot = snapshot
        return snapshot
    }

    private fun refreshVisibleCoverageAfterDrawableLocked(index: Int) {
        // The scheduled frame computes and publishes the same coverage snapshot. Rebuilding the
        // complete draw state synchronously for every page arriving under the finger duplicates
        // that work while holding stateLock and can delay the next input event. The drawable is
        // already installed and the frame is still scheduled immediately.
        if (lastBusy || pointerDown || dragging || !scroller.isFinished) return
        if (isNearVisibleLocked(index, BUSY_RESOLVE_RENDER_EXTRA_PAGES)) {
            refreshVisibleCoverageSnapshotLocked()
        }
    }

    private fun shouldRenderPageResolveNowLocked(
        index: Int,
        idleExtraPages: Int = BUSY_RESOLVE_RENDER_EXTRA_PAGES
    ): Boolean {
        if (!lastBusy) return isNearVisibleLocked(index, idleExtraPages)
        if (index !in pages.indices || width <= 0 || height <= 0) return false
        rebuildLayoutLocked()
        val pageTop = pageTopOrElseLocked(index, Float.MAX_VALUE)
        val pageBottom = pageTop + pageDrawHeightLocked(pages[index])
        val visibleTop = scrollOffset
        val visibleBottom = scrollOffset + height
        return pageBottom >= visibleTop - ACTIVE_SCROLL_RESOLVE_RENDER_MARGIN_PX &&
            pageTop <= visibleBottom + ACTIVE_SCROLL_RESOLVE_RENDER_MARGIN_PX
    }

    private fun shouldFreezeOffscreenDrawableInstallLocked(
        index: Int,
        pageTop: Float,
        pageHeight: Float
    ): Boolean {
        if (!isRecentGeometrySensitiveScrollLocked()) return false
        if (index !in pages.indices || width <= 0 || height <= 0) return false
        val pageBottom = pageTop + pageHeight
        val visibleTop = scrollOffset - ACTIVE_SCROLL_RESOLVE_RENDER_MARGIN_PX
        val visibleBottom = scrollOffset + height + ACTIVE_SCROLL_RESOLVE_RENDER_MARGIN_PX
        return pageBottom < visibleTop || pageTop > visibleBottom
    }

    fun pageReadinessSnapshot(): PageReadinessSnapshot {
        return synchronized(stateLock) {
            var drawable = 0
            var loading = 0
            var errors = 0
            var cards = 0
            var unresolved = 0
            val loadingIndexes = ArrayList<Int>()
            val unresolvedIndexes = ArrayList<Int>()
            for ((index, page) in pages.withIndex()) {
                val drawablePage = pageHasDrawableForReadinessLocked(page)
                when {
                    page.errorText != null -> errors++
                    page.cardText != null -> {
                        cards++
                        if (!inlineRealPixelsOnly) {
                            drawable++
                        } else {
                            unresolved++
                            unresolvedIndexes.add(index)
                        }
                    }
                    drawablePage -> drawable++
                    page.loading -> {
                        loading++
                        unresolved++
                        loadingIndexes.add(index)
                        unresolvedIndexes.add(index)
                    }
                    else -> {
                        unresolved++
                        unresolvedIndexes.add(index)
                    }
                }
            }
            PageReadinessSnapshot(
                pageCount = pages.size,
                drawablePages = drawable,
                loadingPages = loading,
                errorPages = errors,
                cardPages = cards,
                unresolvedPages = unresolved,
                loadingIndexes = loadingIndexes.joinToString("|"),
                unresolvedIndexes = unresolvedIndexes.joinToString("|")
            )
        }
    }

    fun traversalSnapshot(): TraversalSnapshot {
        return synchronized(stateLock) {
            val committed = ArrayList<Int>(traversalCommittedPages.size)
            val missing = ArrayList<Int>(traversalCommittedPages.size)
            traversalCommittedPages.forEachIndexed { index, seen ->
                if (seen) committed.add(index) else missing.add(index)
            }
            TraversalSnapshot(
                structureEpoch = traversalStructureEpoch,
                expectedPageCount = traversalExpectedPageCount,
                committedPageCount = committed.size,
                committedPageIndexes = committed.joinToString("|"),
                missingPageIndexes = missing.joinToString("|"),
                submittedFrames = traversalSubmittedFrames,
                committedFrames = traversalCommittedFrames,
                submittedViewportDefectFrames = traversalSubmittedViewportDefectFrames,
                submittedRunwayDefectFrames = traversalSubmittedRunwayDefectFrames,
                committedViewportDefectFrames = traversalCommittedViewportDefectFrames,
                committedRunwayDefectFrames = traversalCommittedRunwayDefectFrames
            )
        }
    }

    /** O(1) structure identity for commit validation; traversalSnapshot() remains the full audit. */
    fun currentTraversalStructureEpoch(): Long = synchronized(stateLock) {
        traversalStructureEpoch
    }

    /**
     * A visible SurfaceView can punch a black compositor hole even while its alpha is zero on
     * some devices. The Activity keeps explicit loading chrome until the first exact native
     * buffer is physically presented, rather than treating the earlier HWUI commit as final.
     */
    fun isNativeSurfaceRevealPendingForLoadingStatus(): Boolean = synchronized(stateLock) {
        rollingNativePresentationEnabled &&
            !nativeSurfaceContentRevealed &&
            !rollingNativeFatal
    }

    fun completedDrawDispatchTelemetrySnapshot(): CompletedDrawDispatchTelemetrySnapshot {
        val snapshot = completedDrawDispatchQueue.snapshot()
        return CompletedDrawDispatchTelemetrySnapshot(
            offers = snapshot.offers,
            scheduleRequests = snapshot.scheduleRequests,
            selected = snapshot.selected,
            delivered = snapshot.delivered,
            staleDropped = snapshot.staleDropped,
            sameSemanticCoalesced = snapshot.sameSemanticCoalesced,
            ordinarySuperseded = snapshot.ordinarySuperseded,
            overflowCoalesced = snapshot.overflowCoalesced,
            criticalOverflowFailures = snapshot.criticalOverflowFailures,
            postRejected = snapshot.postRejected,
            clears = snapshot.clears,
            maxQueueDepth = snapshot.maxQueueDepth,
            pendingSemanticTransitions = snapshot.pendingSemanticTransitions,
            ordinaryPending = snapshot.ordinaryPending,
            runnerScheduled = snapshot.runnerScheduled,
            runnerRunning = snapshot.runnerRunning,
            maxConcurrentRunnerOwners = snapshot.maxConcurrentRunnerOwners,
        )
    }

    private fun resetTraversalProofLocked(expectedPageCount: Int) {
        traversalStructureEpoch++
        if (traversalStructureEpoch <= 0L) traversalStructureEpoch = 1L
        traversalExpectedPageCount = max(0, expectedPageCount)
        traversalCommittedPages = BooleanArray(traversalExpectedPageCount)
        traversalSubmittedFrames = 0L
        traversalCommittedFrames = 0L
        traversalSubmittedViewportDefectFrames = 0L
        traversalSubmittedRunwayDefectFrames = 0L
        traversalCommittedViewportDefectFrames = 0L
        traversalCommittedRunwayDefectFrames = 0L
        nativeTexturePrewarmAnchorPage = -1
        nativeTexturePrewarmPendingPages.clear()
        requestResidentNativeTexturePrewarmLocked()
    }

    /** Append-only strip geometry does not invalidate pixels already committed for its prefix. */
    private fun extendTraversalProofLocked(expectedPageCount: Int) {
        val nextCount = max(0, expectedPageCount)
        if (nextCount <= traversalExpectedPageCount) return
        if (traversalStructureEpoch <= 0L) {
            resetTraversalProofLocked(nextCount)
            return
        }
        traversalCommittedPages = traversalCommittedPages.copyOf(nextCount)
        traversalExpectedPageCount = nextCount
    }

    /** Returns the final page intersecting the physical viewport plus the requested runway. */
    fun forwardRequestEndPage(aheadViewports: Float): Int {
        return synchronized(stateLock) {
            if (pages.isEmpty() || width <= 0 || height <= 0) return@synchronized -1
            rebuildLayoutLocked()
            val runwayPx = max(0f, aheadViewports) * height.toFloat()
            val endExclusive = min(contentHeight, scrollOffset + height.toFloat() + runwayPx)
            if (endExclusive <= 0f) return@synchronized 0
            val probe = min(
                max(0f, contentHeight - FORWARD_REQUEST_END_EPSILON_PX),
                max(0f, endExclusive - FORWARD_REQUEST_END_EPSILON_PX)
            )
            firstVisiblePageLocked(probe).coerceIn(0, pages.lastIndex)
        }
    }

    /** Returns the first page intersecting the physical viewport. */
    fun forwardRequestStartPage(): Int {
        return synchronized(stateLock) {
            if (pages.isEmpty() || width <= 0 || height <= 0) return@synchronized -1
            rebuildLayoutLocked()
            firstVisiblePageLocked(scrollOffset).coerceIn(0, pages.lastIndex)
        }
    }

    /**
     * Measures real, full-quality drawable pixels immediately beyond the physical viewport.
     * This reads the immutable bitmap/tile pages used by Canvas; it does not trigger work,
     * synthesize content, or treat loading/error cards as drawable runway.
     */
    fun forwardRunwaySnapshot(
        aheadViewports: Float = DEFAULT_FORWARD_RUNWAY_AHEAD_VIEWPORTS
    ): ForwardRunwaySnapshot? {
        return synchronized(stateLock) {
            forwardRunwaySnapshotLocked(aheadViewports)
        }
    }

    private fun forwardRunwaySnapshotLocked(aheadViewports: Float): ForwardRunwaySnapshot? {
        if (pages.isEmpty() || width <= 0 || height <= 0) return null
        rebuildLayoutLocked()
        val required = ceil(max(0f, aheadViewports) * height.toFloat()).toInt()
        val start = scrollOffset + height.toFloat()
        val end = min(contentHeight, start + required.toFloat())
        val available = ceil(max(0f, end - start)).toInt()
        if (stripAuthorityToken != 0L && stripGeometry != null) {
            val startPx = max(0L, floor(start.toDouble()).toLong())
            val endPx = minOf(stripGeometry!!.contentHeightPx, ceil(end.toDouble()).toLong())
            // Authoritative strip residency is an integer half-open interval. Measuring its
            // available tail with the legacy accumulated Float layout can differ by several
            // pixels after dozens of pages and report a gap even when no interval gap exists.
            val stripAvailable = (endPx - startPx).coerceAtLeast(0L)
                .coerceAtMost(Int.MAX_VALUE.toLong()).toInt()
            val drawable = stripResidentCoverage.coveredLength(startPx, endPx)
                .coerceAtMost(Int.MAX_VALUE.toLong()).toInt()
            val gap = stripResidentCoverage.firstGap(startPx, endPx)
            val missingPage = gap?.let { gapPx ->
                stripGeometry!!.pages.indexOfFirst { page -> gapPx < page.contentBottomPx }
                    .let { position -> if (position >= 0) position else pages.lastIndex }
            } ?: -1
            return ForwardRunwaySnapshot(
                requiredAheadPx = required,
                availableAheadPx = stripAvailable,
                drawableAheadPx = drawable,
                missingAheadPx = max(0, stripAvailable - drawable),
                lowResolutionItems = 0,
                firstMissingPage = missingPage,
                contentExhausted = endPx >= stripGeometry!!.contentHeightPx
            )
        }
        val minimumSourceWidth = minimumReadableSourceWidth(width, inlineRealPixelsOnly)
        var drawable = 0
        var lowResolution = 0
        var firstMissing = -1
        var index = firstVisiblePageLocked(start).coerceIn(0, pages.lastIndex)
        while (index > 0 && pageTopOrElseLocked(index, 0f) > start) index--
        while (index < pages.size) {
            val page = pages[index]
            val pageTop = pageTopOrElseLocked(index, 0f)
            val pageBottom = pageTop + pageDrawHeightLocked(page)
            if (pageTop >= end) break
            val overlapTop = max(start, pageTop)
            val overlapBottom = min(end, pageBottom)
            if (overlapBottom > overlapTop) {
                val adjacentPrefixBottom = adjacentExactPrefixBottomLocked(index)
                if (adjacentPrefixBottom != null) {
                    val exactBottom = min(overlapBottom, adjacentPrefixBottom)
                    if (exactBottom > overlapTop) {
                        drawable += ceil(exactBottom - overlapTop).toInt()
                    }
                    if (exactBottom < overlapBottom && firstMissing < 0) firstMissing = index
                    index++
                    continue
                }
                val sourceWidth = completeFullQualityDrawableSourceWidth(
                    page,
                    requireOriginalProof = inlineRealPixelsOnly
                )
                if (sourceWidth > 0) {
                    drawable += ceil(overlapBottom - overlapTop).toInt()
                    if (sourceWidth < minimumSourceWidth) lowResolution++
                } else {
                    if (page.bitmap != null || page.tiles.any { !it.bitmap.isRecycled }) {
                        lowResolution++
                    }
                    if (firstMissing < 0) firstMissing = index
                }
            }
            index++
        }
        val missing = max(0, available - drawable)
        return ForwardRunwaySnapshot(
            requiredAheadPx = required,
            availableAheadPx = available,
            drawableAheadPx = drawable,
            missingAheadPx = missing,
            lowResolutionItems = lowResolution,
            firstMissingPage = firstMissing,
            contentExhausted = end >= contentHeight
        )
    }

    private fun completeFullQualityDrawableSourceWidth(
        page: Page,
        requireOriginalProof: Boolean
    ): Int {
        if (page.loading || page.errorText != null || page.cardText != null) return 0
        if (requireOriginalProof) {
            return if (usableAuthoritativeOriginalTilePage(
                    page.width,
                    page.height,
                    page.tiles,
                    page.originalProof
                )
            ) {
                page.originalProof!!.originalWidth
            } else {
                0
            }
        }
        val bitmap = page.bitmap
        if (bitmap != null && !bitmap.isRecycled &&
            bitmap.config == Bitmap.Config.ARGB_8888 && !bitmap.isMutable
        ) {
            return bitmap.width
        }
        if (page.tiles.isEmpty()) return 0
        var expectedTop = 0
        var sourceWidth = 0
        var sourceHeight = 0
        for (tile in page.tiles) {
            val tileBitmap = tile.bitmap
            val sourceSpan = tile.sourceBottom - tile.sourceTop
            if (tile.sourceTop != expectedTop || sourceSpan <= 0 ||
                tile.sourceWidth <= 0 || tile.sourceHeight <= 0 ||
                (sourceWidth > 0 && tile.sourceWidth != sourceWidth) ||
                (sourceHeight > 0 && tile.sourceHeight != sourceHeight) ||
                !tileBitmap.hasImmutableExactPixelConfig() ||
                !tile.hasExactSourcePixelStorage()
            ) {
                return 0
            }
            sourceWidth = tile.sourceWidth
            sourceHeight = tile.sourceHeight
            expectedTop = tile.sourceBottom
        }
        return if (expectedTop == sourceHeight) sourceWidth else 0
    }

    fun requestVisibleCoverageFrame() {
        synchronized(stateLock) {
            if (pages.isNotEmpty()) {
                renderRequested = true
                scheduleFrameLocked()
                stateLock.notifyAll()
            }
        }
    }

    /**
     * Re-pulses the already-admitted HWUI fallback after a native Surface replacement.
     *
     * Multi-window transitions can accept an invalidation while the task is resumed but its
     * ViewRoot is not drawable yet. The admitted token and registered frame-commit callback must
     * survive that gap: replacing either on every retry can starve a legitimate slow commit. If
     * no token is currently admitted, schedule one; otherwise only invalidate the hierarchy so
     * the existing token is consumed when the ViewRoot finally becomes drawable.
     *
     * @return true while the native child is still waiting for its fresh complete HWUI commit.
     */
    fun requestPendingNativeSurfaceHwuiCommit(): Boolean {
        check(Looper.myLooper() == Looper.getMainLooper())
        val pending = synchronized(stateLock) {
            if (!rollingNativePresentationEnabled || rollingNativeFatal ||
                !nativeSurfaceRevealAfterFirstHwuiCommitPending || !renderRunning ||
                pages.isEmpty()
            ) {
                false
            } else {
                if (framePipe == FramePipe.IDLE) {
                    renderRequested = true
                    scheduleFrameLocked()
                }
                stateLock.notifyAll()
                true
            }
        }
        if (!pending) return false
        // Always pulse the hierarchy, including when scheduleFrameLocked() retained an existing
        // INVALIDATION_POSTED owner. That retained owner is the exact lost-wakeup case.
        invalidate()
        (parent as? View)?.invalidate()
        postInvalidateOnAnimation()
        return true
    }

    fun programmaticScrollActiveRemainingMs(nowMs: Long = SystemClock.uptimeMillis()): Long {
        return synchronized(stateLock) {
            (programmaticScrollStatsUntilMs - nowMs).coerceAtLeast(0L)
        }
    }

    fun frameStatsSnapshot(): FrameStatsSnapshot? {
        val snapshot = synchronized(stateLock) {
            if (lastFrameStatsSnapshot == null && statsActive) {
                finalizeActiveFrameStatsLocked(log = false)
            }
            lastFrameStatsSnapshot
        }
        return snapshot
    }

    /**
     * Atomically drains both the previously completed segment and the currently active segment.
     * Unlike [resetFrameStatsSnapshot], this does not arm a new-input boundary, so fling/tail
     * frames that arrive after the drain start a fresh segment and remain available to the next
     * drain instead of being discarded.
     */
    fun takeFrameStatsSnapshots(): List<FrameStatsSnapshot> {
        return synchronized(stateLock) {
            if (statsActive) finalizeActiveFrameStatsLocked(log = false)
            val snapshots = ArrayList<FrameStatsSnapshot>(completedFrameStatsSnapshots.size)
            snapshots.addAll(completedFrameStatsSnapshots)
            completedFrameStatsSnapshots.clear()
            lastFrameStatsSnapshot = null
            snapshots
        }
    }

    fun resetFrameStatsSnapshot() {
        synchronized(stateLock) {
            lastFrameStatsSnapshot = null
            completedFrameStatsSnapshots.clear()
            resetActiveFrameStatsLocked()
            statsAwaitingFirstInput = true
            pendingOldestInputNs = 0L
            pendingNewestInputNs = 0L
            pendingInputEvents = 0
            pendingHistorySamples = 0
            stateLock.notifyAll()
        }
    }

    override fun onAttachedToWindow() {
        super.onAttachedToWindow()
        refreshCachedDisplayTiming()
        if (!displayListenerRegistered) {
            displayManager?.registerDisplayListener(displayTimingListener, mainHandler)
            displayListenerRegistered = displayManager != null
        }
        synchronized(stateLock) {
            renderRunning = true
            if (rollingNativePresentationEnabled) {
                startRenderThreadLocked()
            }
            renderRequested = pages.isNotEmpty() && !shouldBlockInitialEmptyFrameLocked()
            if (renderRequested) scheduleFrameLocked()
            stateLock.notifyAll()
        }
    }

    override fun onSizeChanged(width: Int, height: Int, oldWidth: Int, oldHeight: Int) {
        super.onSizeChanged(width, height, oldWidth, oldHeight)
        var physicalMotionEnded = false
        var retiredNativeAttachment: Pair<Long, Long>? = null
        var scheduleNativeReattach = false
        var prepareNativeTargetsAfterLifecycleFence = false
        val request = synchronized(stateLock) {
            val reflowAnchor = if (width != oldWidth || height != oldHeight) {
                captureViewportReflowAnchorLocked(oldWidth, oldHeight)
            } else {
                null
            }
            if (width != oldWidth || height != oldHeight) {
                if (oldWidth > 0 && oldHeight > 0) {
                    physicalMotionEnded = interruptPhysicalScrollForLifecycleLocked()
                }
                materializeLayoutDeltasLocked()
                layoutDirty = true
                if (rollingNativePresentationEnabled && rollingNativeHandle != 0L &&
                    rollingNativeAttachEpoch > 0L
                ) {
                    // The old child buffer is sized/positioned for different task bounds.  Make
                    // the HWUI image authoritative before requesting another native attachment;
                    // otherwise onDraw() skips the fallback while the replacement Surface is
                    // still empty, producing a persistent white/black split-screen pane.
                    retireDirectSurfaceSchedulingLocked()
                    retiredNativeAttachment = rollingNativeHandle to rollingNativeAttachEpoch
                    advanceRollingNativeSurfaceEpochLocked()
                    rollingNativeAttachEpoch = 0L
                    physicalMoveProducerReady = false
                    releaseRollingJavaChildSurfaceControlLocked()
                    rollingNativeSurfaceIdentity = 0
                    rollingNativeWidth = 0
                    rollingNativeHeight = 0
                    rollingNativeViewportWidth = 0
                    rollingNativeViewportHeight = 0
                    nativePresentationVisible = false
                    nativeSurfaceContentRevealed = false
                    nativePresentedStructureEpoch = 0L
                    clearFramePipeLocked(preserveDirty = true)
                    nativeHostBoundsReattachPending = true
                    scheduleNativeReattach = true
                }
            }
            val scene = preparedRenderScene
            val directWidthMismatch = directPreparedBitmapGeneration == visualGeneration &&
                directPreparedBitmapWidth != width
            if (width > 0 && ((scene != null && scene.width != width) || directWidthMismatch)) {
                invalidatePreparedRenderSceneStateLocked()
            }
            val hasPendingPreparedAnchor = pendingPreparedStartPage in pages.indices
            if (hasPendingPreparedAnchor && width > 0 && height > 0) {
                val expectedWidth = pendingPreparedViewportWidth
                val expectedHeight = pendingPreparedViewportHeight
                if (width != expectedWidth || height != expectedHeight) {
                    Log.d(
                        TAG,
                        "reader_prepared_batch_viewport_changed expected=${expectedWidth}x$expectedHeight " +
                            "actual=${width}x$height pages=${pages.size}"
                    )
                }
                rebuildLayoutLocked()
                applyPreparedStartAnchorLocked(clearPending = true)
            } else {
                if (reflowAnchor != null && reflowAnchor.page in pages.indices) {
                    rebuildLayoutLocked()
                    setScrollOffsetLocked(
                        ReaderViewportReflowPolicy.restoredScrollOffset(
                            pageTopPx = pageTopOrElseLocked(reflowAnchor.page, 0f),
                            pageHeightPx = pageDrawHeightLocked(pages[reflowAnchor.page]),
                            viewportHeightPx = height,
                            anchor = reflowAnchor,
                        ),
                    )
                }
                clampScrollLocked()
            }
            if (width > 0 && height > 0) {
                // Freeze only arithmetic here. EGL/AHB creation remains forbidden until the first
                // complete exact HWUI commit, but the later renderer must retain the same compact
                // target that the former pre-pixel preparation path selected.
                captureNativeRenderTargetGeometryLocked(width, height)
                prepareNativeTargetsAfterLifecycleFence = true
            }
            lastAnchor = -1
            val hasPages = pages.isNotEmpty()
            renderRequested = hasPages && !shouldBlockInitialEmptyFrameLocked()
            if (renderRequested) scheduleFrameLocked()
            stateLock.notifyAll()
            if (hasPages) windowRequestLocked(lastBusy) else null
        }
        retiredNativeAttachment?.let { (handle, epoch) ->
            nativeSurfaceView.alpha = 0f
            resetNativeSurfaceViewBandTransform()
            NtkRollingNativeBridge.nativeDetach(handle, epoch)
        }
        if (prepareNativeTargetsAfterLifecycleFence) {
            // nativePrepare and nativeDetach share the native lifecycle queue. Enqueue detach first:
            // if the urgent-display worker consumed a different-size prepare against the still-live
            // old backend, prepareBackend treated that ordinary resize as a fatal target mismatch.
            synchronized(stateLock) {
                prepareRollingNativeRenderTargetsLocked(width, height)
            }
        }
        if (scheduleNativeReattach) {
            mainHandler.removeCallbacks(nativeHostBoundsReattachRunnable)
            mainHandler.postDelayed(
                nativeHostBoundsReattachRunnable,
                HOST_BOUNDS_REATTACH_SETTLE_MS,
            )
        }
        if (physicalMotionEnded) listener?.onPhysicalScrollMotionEnded()
        dispatchWindowRequest(request)
    }

    override fun onDetachedFromWindow() {
        if (displayListenerRegistered) {
            displayManager?.unregisterDisplayListener(displayTimingListener)
            displayListenerRegistered = false
        }
        mainHandler.removeCallbacksAndMessages(null)
        transitionCardNativeGeneration.incrementAndGet()
        transitionCardPrewarmRequestedTitles.clear()
        transitionCardPrewarmInFlightTitles.clear()
        val pendingTransitionCardTokens = transitionCardNativePendingTokens.toList()
        transitionCardNativePendingTokens.removeAll(pendingTransitionCardTokens.toSet())
        val preparedTransitionCards = ArrayList<PreparedNativeTransitionCard>()
        var nativeHandleToDestroy = 0L
        var nativeDestroyPosted = false
        val retiringThread = synchronized(stateLock) {
            rollingAuthoritativeRecyclePosted = false
            invalidateFrameStatsFinalizeDeadlineLocked()
            deferredSurfaceIdentityActivated = false
            nativeSurfaceRevealAfterFirstHwuiCommitPending = false
            lifecycleEnterAnimationPending = false
            lifecycleCleanHwuiRevealReady = false
            nativeOnlyExactSurfaceRevealPending = false
            nativeSurfaceRevealAfterPrepareEpoch = 0L
            noStateRetryPosted = false
            clearRetainedPageNodesStateLocked()
            clearPreparedStartAnchorLocked()
            preparedTransitionCards += preparedNativeTransitionCards.values
            preparedNativeTransitionCards.clear()
            renderRunning = false
            renderRequested = false
            rollingNativeCreateGeneration += 1L
            rollingNativeCreatePending = false
            clearFramePipeLocked(preserveDirty = false)
            clearInputStateLocked()
            resetActiveFrameStatsLocked()
            nativeHandleToDestroy = rollingNativeHandle
            rollingNativeHandle = 0L
            advanceRollingNativeSurfaceEpochLocked()
            rollingNativeAttachEpoch = 0L
            physicalMoveProducerReady = false
            rollingNativeSurfaceIdentity = 0
            rollingNativeWidth = 0
            rollingNativeHeight = 0
            rollingNativeViewportWidth = 0
            rollingNativeViewportHeight = 0
            rollingNativePreparedWidth = 0
            rollingNativePreparedHeight = 0
            rollingNativeFrozenViewportWidth = 0
            rollingNativeFrozenViewportHeight = 0
            rollingNativeFrozenTargetWidth = 0
            rollingNativeFrozenTargetHeight = 0
            nativePresentationVisible = false
            nativeSurfaceContentRevealed = false
            nativePresentedStructureEpoch = 0L
            rollingTextureSurface = null
            releaseRollingJavaChildSurfaceControlLocked()
            directSurfaceReady = false
            physicalMoveProducerReady = false
            if (nativeHandleToDestroy != 0L) {
                rollingNativeDestroyInFlightCount += 1
                nativeDestroyPosted = ReaderBitmapRetirementDispatcher.dispatchWork {
                    try {
                        NtkRollingNativeBridge.nativeDestroy(nativeHandleToDestroy)
                    } finally {
                        completeRollingNativeDestroy()
                    }
                }
            }
            scheduleRollingAuthoritativeRecycleLocked()
            val thread = stopRenderThreadLocked()
            stateLock.notifyAll()
            thread
        }
        resetNativeSurfaceViewBandTransform()
        (pendingTransitionCardTokens + preparedTransitionCards.map { it.nativeToken })
            .distinctBy(System::identityHashCode)
            .forEach(HostExactHardwareTilePool::retire)
        preparedTransitionCards.forEach { prepared -> prepared.softwareBitmap.recycle() }
        if (nativeHandleToDestroy != 0L && !nativeDestroyPosted) {
            try {
                NtkRollingNativeBridge.nativeDestroy(nativeHandleToDestroy)
            } finally {
                completeRollingNativeDestroy()
            }
        }
        retiringThread?.quitSafely()
        super.onDetachedFromWindow()
    }

    override fun surfaceCreated(holder: SurfaceHolder) {
        if (!rollingNativePresentationEnabled) return
        // The new Surface starts with no reader buffer. Keep the committed HWUI image exposed
        // until an exact native frame for this attachment is physically presented.
        nativeSurfaceView.alpha = 0f
        val surface = holder.surface
        val surfaceWidth = nativeSurfaceView.width
        val surfaceHeight = nativeSurfaceView.height
        synchronized(stateLock) {
            rollingTextureSurface = surface
            directSurfaceReady = surface.isValid
            if (directSurfaceReady && renderRunning && pages.isNotEmpty()) renderRequested = true
            stateLock.notifyAll()
        }
        val refreshRate = refreshCachedDisplayTiming()
        val frameRateCompatibility = if (emulatorNativeSurfaceRuntime) {
            // The host compositor content-detects a tiny proof layer as low-rate animation unless
            // the reader declares its actual Choreographer cadence. Devices retain DEFAULT so
            // normal adaptive-refresh policy remains untouched.
            Surface.FRAME_RATE_COMPATIBILITY_FIXED_SOURCE
        } else {
            Surface.FRAME_RATE_COMPATIBILITY_DEFAULT
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            surface.setFrameRate(
                refreshRate,
                frameRateCompatibility,
                Surface.CHANGE_FRAME_RATE_ONLY_IF_SEAMLESS
            )
        } else if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            surface.setFrameRate(
                refreshRate,
                frameRateCompatibility
            )
        }
        applyQualifiedNativeSurfaceFrameRateVote(refreshRate)
        val deferForBounds = synchronized(stateLock) { nativeHostBoundsReattachPending }
        if (deferForBounds) {
            mainHandler.removeCallbacks(nativeHostBoundsReattachRunnable)
            mainHandler.postDelayed(
                nativeHostBoundsReattachRunnable,
                HOST_BOUNDS_REATTACH_SETTLE_MS,
            )
        } else {
            attachRollingNativeSurface(surface, surfaceWidth, surfaceHeight)
        }
    }

    override fun surfaceChanged(
        holder: SurfaceHolder,
        format: Int,
        width: Int,
        height: Int
    ) {
        if (!rollingNativePresentationEnabled) return
        val viewportWidth = nativeSurfaceView.width.takeIf { it > 0 } ?: width
        val viewportHeight = nativeSurfaceView.height.takeIf { it > 0 } ?: height
        if (viewportWidth <= 0 || viewportHeight <= 0) return
        val surface = synchronized(stateLock) {
            val current = holder.surface
            rollingTextureSurface = current
            directSurfaceReady = current.isValid
            if (directSurfaceReady && renderRunning && pages.isNotEmpty()) renderRequested = true
            stateLock.notifyAll()
            current
        }
        val refreshRate = refreshCachedDisplayTiming()
        applyQualifiedNativeSurfaceFrameRateVote(refreshRate)
        val deferForBounds = synchronized(stateLock) { nativeHostBoundsReattachPending }
        if (deferForBounds) {
            mainHandler.removeCallbacks(nativeHostBoundsReattachRunnable)
            mainHandler.postDelayed(
                nativeHostBoundsReattachRunnable,
                HOST_BOUNDS_REATTACH_SETTLE_MS,
            )
        } else {
            // The emulator geometry path intentionally queues a 1x1 transparent parent buffer.
            // Its Surface callback dimensions are not the child layer's display destination.
            attachRollingNativeSurface(surface, viewportWidth, viewportHeight)
        }
    }

    override fun surfaceDestroyed(holder: SurfaceHolder) {
        var physicalMotionEnded = false
        var requireFreshHwuiBeforeNativeReplacement = false
        val detach = synchronized(stateLock) {
            physicalMotionEnded = interruptPhysicalScrollForLifecycleLocked()
            directSurfaceReady = false
            rollingTextureSurface = null
            releaseRollingJavaChildSurfaceControlLocked()
            // A producer-thread Choreographer callback can remain reserved when the window stops
            // delivering vsync. If that reservation survives this Surface, the replacement
            // attachment mistakes it for live work and strands its first admitted frame forever.
            // Retire every Surface-scoped callback while the old attachment is fenced so resume
            // always starts with an empty scheduling lane.
            retireDirectSurfaceSchedulingLocked()
            val value = rollingNativeHandle to maxOf(
                rollingNativeAttachEpoch,
                rollingNativeSurfaceEpochCounter
            )
            advanceRollingNativeSurfaceEpochLocked()
            rollingNativeAttachEpoch = 0L
            physicalMoveProducerReady = false
            rollingNativeSurfaceIdentity = 0
            rollingNativeWidth = 0
            rollingNativeHeight = 0
            rollingNativeViewportWidth = 0
            rollingNativeViewportHeight = 0
            rollingNativePreparedWidth = 0
            rollingNativePreparedHeight = 0
            nativePresentationVisible = false
            nativeSurfaceContentRevealed = false
            nativePresentedStructureEpoch = 0L
            clearFramePipeLocked(preserveDirty = true)
            // A holder loss leaves the Java SurfaceView in the hierarchy. Keeping that empty child
            // VISIBLE (even with alpha zero) lets Android recreate its BufferQueue as soon as the
            // task resumes. On Home/split-screen return that cold allocation can then occupy the
            // compositor/GPU lane before the retained HWUI pages publish their first correctly
            // sized frame. Re-enter through the same two-stage gate as cold launch instead: the
            // parent must commit one fresh, complete HWUI frame before the native child is made
            // visible and allowed to create/attach its replacement Surface.
            requireFreshHwuiBeforeNativeReplacement =
                rollingNativePresentationEnabled && renderRunning && pages.isNotEmpty() &&
                    nativeSurfaceView.visibility == View.VISIBLE
            if (requireFreshHwuiBeforeNativeReplacement) {
                nativeSurfaceRevealAfterFirstHwuiCommitPending = true
                nativeSurfaceRevealAfterPrepareEpoch = 0L
            }
            stateLock.notifyAll()
            value
        }
        nativeSurfaceView.alpha = 0f
        resetNativeSurfaceViewBandTransform()
        if (requireFreshHwuiBeforeNativeReplacement) {
            nativeSurfaceView.visibility = View.GONE
        }
        if (physicalMotionEnded) listener?.onPhysicalScrollMotionEnded()
        if (detach.first != 0L && detach.second > 0L) {
            NtkRollingNativeBridge.nativeDetach(detach.first, detach.second)
        }
    }

    override fun surfaceRedrawNeeded(holder: SurfaceHolder) {
        synchronized(stateLock) {
            if (directSurfaceReady && pages.isNotEmpty()) {
                renderRequested = true
                scheduleFrameLocked()
            }
        }
    }

    /** Stops a real gesture/fling when its display surface is no longer user-interactable. */
    fun interruptPhysicalScrollForLifecycle() {
        val ended = synchronized(stateLock) {
            interruptPhysicalScrollForLifecycleLocked()
        }
        if (ended) listener?.onPhysicalScrollMotionEnded()
    }

    /** Returns a non-zero identity for the next physical Surface attachment request. */
    private fun advanceRollingNativeSurfaceEpochLocked(): Long {
        activeNativeBandProof = null
        activeNativeBandDirectValidatedSceneId = 0L
        activeNativeBandDirectValidatedVisualGeneration = Long.MIN_VALUE
        activeNativeBandDirectValidatedStructureEpoch = 0L
        synchronized(activeNativeBandCandidateLock) {
            activeNativeBandCandidates.clear()
        }
        directActiveBandNativeFollowupTokens.clear()
        rollingNativeSurfaceEpochCounter += 1L
        if (rollingNativeSurfaceEpochCounter <= 0L) rollingNativeSurfaceEpochCounter = 1L
        return rollingNativeSurfaceEpochCounter
    }

    /** Releases only Java's wrapper reference; native retains its own ASurfaceControl reference. */
    private fun releaseRollingJavaChildSurfaceControlLocked() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            rollingJavaChildSurfaceControl?.release()
            rollingJavaGeometrySurfaceControl?.release()
        }
        rollingJavaChildSurfaceControl = null
        rollingJavaGeometrySurfaceControl = null
    }

    /** Restores ordinary SurfaceView geometry after a native band attachment retires. */
    private fun resetNativeSurfaceViewBandTransform() {
        check(Looper.myLooper() == Looper.getMainLooper())
        nativeSurfaceView.translationY = 0f
        nativeSurfaceView.scaleY = 1f
        nativeSurfaceView.pivotY = 0f
    }

    /**
     * The host-gpu emulator's child SurfaceControl did not inherit the rate vote placed on the
     * Java Surface/ANativeWindow and latched every second 60 Hz buffer. Vote on the actual child
     * layer as well. This is deliberately limited to the emulator direct-Wi-Fi renderer profile;
     * physical devices and mobile/SNI sessions retain their existing composition policy.
     */
    private fun applyQualifiedNativeSurfaceFrameRateVote(
        refreshRate: Float,
        vararg additionalSurfaceControls: SurfaceControl,
    ) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S ||
            !NtkNativeSurfaceFrameRatePolicy.shouldApplyLayerFrameRateVote(
                emulatorRuntime = emulatorNativeSurfaceRuntime,
                directWifiRendererProfile = synchronized(stateLock) {
                    directWifiExpandedNativeTextureRunway
                },
            )
        ) return
        val surfaceControls = ArrayList<SurfaceControl>(1 + additionalSurfaceControls.size)
        nativeSurfaceView.surfaceControl.takeIf { it.isValid }?.let(surfaceControls::add)
        additionalSurfaceControls.forEach { surfaceControl ->
            if (surfaceControl.isValid && surfaceControl !in surfaceControls) {
                surfaceControls.add(surfaceControl)
            }
        }
        if (surfaceControls.isEmpty()) return
        val compatibility = if (emulatorNativeSurfaceRuntime) {
            Surface.FRAME_RATE_COMPATIBILITY_FIXED_SOURCE
        } else {
            Surface.FRAME_RATE_COMPATIBILITY_DEFAULT
        }
        SurfaceControl.Transaction().use { transaction ->
            surfaceControls.forEach { surfaceControl ->
                transaction.setFrameRate(
                    surfaceControl,
                    refreshRate,
                    compatibility,
                    Surface.CHANGE_FRAME_RATE_ONLY_IF_SEAMLESS,
                )
            }
            transaction.apply()
        }
        Log.i(
            TAG,
            "reader_native_surface_control_frame_rate rate=$refreshRate," +
                "layers=${surfaceControls.size}",
        )
    }

    private fun attachRollingNativeSurface(
        surface: Surface,
        surfaceWidth: Int,
        surfaceHeight: Int
    ) {
        if (!rollingNativePresentationEnabled) return
        if (!surface.isValid || surfaceWidth <= 0 || surfaceHeight <= 0) return
        val surfaceIdentity = System.identityHashCode(surface)
        val request = synchronized(stateLock) {
            if (rollingNativeFatal || !renderRunning || !directSurfaceReady) return@synchronized null
            val target = nativeRenderTargetSizeLocked(surfaceWidth, surfaceHeight)
            // A strict cold reader may already be creating the EGL renderer on its dedicated
            // producer thread. Never race that work with a second main-thread nativeCreate.
            // Completion posts another attachment attempt when this Surface is still valid.
            if (rollingNativeHandle == 0L && rollingNativeCreatePending) {
                return@synchronized null
            }
            if (rollingNativeHandle == 0L) {
                rollingNativeCreateGeneration += 1L
                if (rollingNativeCreateGeneration <= 0L) {
                    rollingNativeCreateGeneration = 1L
                }
                rollingNativeHandle = NtkRollingNativeBridge.nativeCreate(
                    this,
                    rollingNativeCreateGeneration,
                    directWifiExpandedNativeTextureRunway,
                    emulatorNativeSurfaceRuntime,
                )
                if (rollingNativeHandle != 0L) {
                    NtkRollingNativeBridge.nativeSetDirectWifiTextureProfile(
                        rollingNativeHandle,
                        directWifiExpandedNativeTextureRunway,
                        emulatorNativeSurfaceRuntime,
                    )
                    if (nativeTexturePrewarmPaused) {
                        NtkRollingNativeBridge.nativeSetPrewarmPaused(
                            rollingNativeHandle,
                            true
                        )
                    }
                }
            }
            val handle = rollingNativeHandle
            if (handle == 0L) {
                rollingNativeFatal = true
                return@synchronized null
            }
            if (rollingNativeAttachEpoch > 0L &&
                rollingNativeSurfaceIdentity == surfaceIdentity &&
                rollingNativeWidth == target.first &&
                rollingNativeHeight == target.second &&
                rollingNativeViewportWidth == surfaceWidth &&
                rollingNativeViewportHeight == surfaceHeight
            ) return@synchronized null
            // Retire a fallback HWUI admission before replacing the physical native backend. The
            // attachment receives its own monotonic epoch: frame/content resets are deliberately
            // allowed to advance lifecycleEpoch without invalidating this still-live Surface.
            clearFramePipeLocked(preserveDirty = true)
            val surfaceEpoch = advanceRollingNativeSurfaceEpochLocked()
            longArrayOf(handle, surfaceEpoch, target.first.toLong(), target.second.toLong())
        } ?: return
        val refreshRate = cachedDisplayRefreshRate
        val refreshPeriodNanos = (1_000_000_000.0 / refreshRate.toDouble()).toLong()
        val frameSyncedSurfaces = if (emulatorNativeSurfaceRuntime &&
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE
        ) {
            val parentSurfaceControl = nativeSurfaceView.surfaceControl
            if (parentSurfaceControl.isValid) {
                var geometryContainer: SurfaceControl? = null
                runCatching {
                    geometryContainer = SurfaceControl.Builder()
                        .setName("NtkStripGeometry")
                        .setParent(parentSurfaceControl)
                        .setHidden(false)
                        .build()
                    val child = SurfaceControl.Builder()
                        .setName("NtkStripLayer")
                        .setParent(checkNotNull(geometryContainer))
                        .setBufferSize(request[2].toInt(), request[3].toInt())
                        .setOpaque(true)
                        .setHidden(true)
                        .build()
                    checkNotNull(geometryContainer) to child
                }.getOrElse {
                    geometryContainer?.release()
                    null
                }
            } else null
        } else null
        val frameSyncedGeometry = frameSyncedSurfaces?.first
        val frameSyncedChild = frameSyncedSurfaces?.second
        frameSyncedSurfaces?.let { surfaces ->
            // The Surface/parent vote does not propagate to app-created descendants on the host
            // emulator. Vote on both the moving container and its buffer child before either is
            // shown, otherwise SurfaceFlinger content detection can merge several 60 Hz crops.
            applyQualifiedNativeSurfaceFrameRateVote(
                refreshRate,
                surfaces.first,
                surfaces.second,
            )
        }
        if (emulatorNativeSurfaceRuntime &&
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE &&
            (frameSyncedChild == null || frameSyncedGeometry == null)
        ) {
            synchronized(stateLock) {
                renderRequested = pages.isNotEmpty()
                scheduleNoStateRetryLocked()
            }
            return
        }
        // Native geometry transactions move the child container directly; the SurfaceView parent
        // remains ordinary viewport geometry on every attachment.
        nativeSurfaceView.pivotY = 0f
        nativeSurfaceView.translationY = 0f
        nativeSurfaceView.scaleY = 1f
        val accepted = NtkRollingNativeBridge.nativeAttach(
            request[0],
            surface,
            frameSyncedChild,
            frameSyncedGeometry,
            request[2].toInt(),
            request[3].toInt(),
            request[1],
            refreshPeriodNanos
        )
        var childInstalled = false
        synchronized(stateLock) {
            if (accepted && rollingNativeHandle == request[0] &&
                rollingNativeSurfaceEpochCounter == request[1] && directSurfaceReady &&
                rollingTextureSurface === surface && surface.isValid &&
                System.identityHashCode(surface) == surfaceIdentity
            ) {
                // A decoded-page install can race nativeAttach() while that blocking native call
                // is outside stateLock. In that interval scheduleFrameLocked() legitimately
                // admits an HWUI token because rollingNativeAttachEpoch is still zero. Once the
                // attach completes, onDraw() sees nativePresentationVisible and skips the HWUI
                // renderer, while the native producer cannot consume the already-admitted HWUI
                // token. Retire only that posted admission (without advancing lifecycleEpoch or
                // discarding older submitted proofs) and issue a fresh producer-thread token.
                // This closes the prepared=0 cold race observed as zero native submissions for an
                // otherwise valid 112-page session.
                val racedHwuiAdmission = framePipe == FramePipe.INVALIDATION_POSTED &&
                    inFlightToken != 0L
                if (racedHwuiAdmission) {
                    val callback = inFlightCommitCallback
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q &&
                        callback != null && inFlightCommitCallbackRegistered
                    ) {
                        val observer = viewTreeObserver
                        if (observer.isAlive) observer.unregisterFrameCommitCallback(callback)
                    }
                    releasePostedAdmissionLocked(preserveDirty = true)
                }
                rollingNativeAttachEpoch = request[1]
                nativeOnlyExactSurfaceRevealPending = false
                physicalMoveProducerReady = true
                releaseRollingJavaChildSurfaceControlLocked()
                rollingJavaChildSurfaceControl = frameSyncedChild
                rollingJavaGeometrySurfaceControl = frameSyncedGeometry
                childInstalled = true
                rollingNativeSurfaceIdentity = surfaceIdentity
                rollingNativeWidth = request[2].toInt()
                rollingNativeHeight = request[3].toInt()
                rollingNativeViewportWidth = surfaceWidth
                rollingNativeViewportHeight = surfaceHeight
                nativePresentationVisible = false
                nativeSurfaceContentRevealed = false
                nativePresentedStructureEpoch = 0L
                Log.i(
                    TAG,
                    "reader_native_surface_attached render=${rollingNativeWidth}x$rollingNativeHeight " +
                        "viewport=${surfaceWidth}x$surfaceHeight sourceNative=" +
                        "$sourceNativeWebtoonCompositingEnabled"
                )
                if (pages.isNotEmpty()) {
                    renderRequested = true
                    scheduleFrameLocked()
                }
            } else if (!accepted && rollingNativeHandle == request[0]) {
                renderRequested = pages.isNotEmpty()
                scheduleNoStateRetryLocked()
            }
        }
        if (!childInstalled) {
            frameSyncedChild?.release()
            frameSyncedGeometry?.release()
            nativeSurfaceView.translationY = 0f
            nativeSurfaceView.scaleY = 1f
        }
    }

    private fun queuePhysicalMoveForProducer(event: MotionEvent): Boolean {
        // Before native attachment the HWUI fallback still owns the visible reader. Routing MOVE
        // samples to the producer in that interval made its drain reject them and silently threw
        // away real loading-screen swipes. Let the ordinary main-thread path retain/cap those
        // coordinates; switch lock-free only after the attachment publication barrier.
        if (!emulatorNativeSurfaceRuntime || scrollbarDragging ||
            !physicalMoveProducerReady
        ) return false
        val handler = directRenderHandler ?: return false
        val generation = physicalMoveMailbox.currentGeneration()
        if (generation <= 0L || !physicalMoveMailbox.isCurrent(generation)) return false
        var oldestEventTimeMs = event.eventTime
        var newestEventTimeMs = event.eventTime
        for (index in 0 until event.historySize) {
            val historical = event.getHistoricalEventTime(index)
            oldestEventTimeMs = minOf(oldestEventTimeMs, historical)
            newestEventTimeMs = maxOf(newestEventTimeMs, historical)
        }
        val receivedNanos = SystemClock.elapsedRealtimeNanos()
        val sample = NtkQueuedPhysicalMove(
            generation = generation,
            y = event.y,
            eventTimeMs = event.eventTime,
            oldestEventTimeMs = oldestEventTimeMs,
            newestEventTimeMs = newestEventTimeMs,
            receivedOldestNanos = receivedNanos,
            receivedNewestNanos = receivedNanos,
            eventCount = 1,
            historySampleCount = event.historySize,
        )
        HostExactHardwareTilePool.notePhysicalReaderInput()
        val shouldPost = physicalMoveMailbox.offer(sample)
        if (shouldPost && !handler.postAtFrontOfQueue(physicalMoveDrainRunnable)) {
            physicalMoveMailbox.onPostRejected()
            return false
        }
        return physicalMoveMailbox.isCurrent(generation)
    }

    /** Executes only on ReaderSurfaceProducer; main never owns stateLock for an emulator MOVE. */
    private val physicalMoveDrainRunnable = object : Runnable {
        override fun run() {
            val sample = physicalMoveMailbox.take()
            val request = if (sample == null) {
                null
            } else {
                synchronized(stateLock) {
                    if (!physicalMoveMailbox.isCurrent(sample.generation) || !pointerDown ||
                        !renderRunning || !directSurfaceReady
                    ) {
                        null
                    } else {
                        noteQueuedInputLocked(sample)
                        val moved = applyPhysicalDragPositionLocked(
                            sample.y,
                            sample.eventTimeMs * NANOS_PER_MILLISECOND,
                        )
                        if (moved) {
                            noteQueuedPhysicalPixelInputLocked(sample)
                            val postedFreshCallback = postDirectFrameCallbackLocked()
                            renderRequested = true
                            scheduleFrameLocked()
                            if (!postedFreshCallback) postLateDirectInputCatchupLocked()
                            stateLock.notifyAll()
                            windowRequestLocked(true)
                        } else {
                            suppressEdgeNoMovementScrollStatsLocked(SystemClock.uptimeMillis())
                            if (pendingReverseWindowFirstPageHint >= 0) {
                                windowRequestLocked(true)
                            } else {
                                null
                            }
                        }
                    }
                }
            }
            dispatchWindowRequest(request, fromInput = true)
            if (physicalMoveMailbox.finishDrainAndReserveNext()) {
                val handler = directRenderHandler
                if (handler == null || !handler.postAtFrontOfQueue(this)) {
                    physicalMoveMailbox.onPostRejected()
                }
            }
        }
    }

    override fun onTouchEvent(event: MotionEvent): Boolean {
        if (isEmpty() || preContentGestureActive) {
            return handlePreContentTouch(event)
        }
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> {
                physicalMoveMailbox.beginGesture()
                parent?.requestDisallowInterceptTouchEvent(true)
                // A rapid chained swipe can interrupt a fling while pixels are still moving. It
                // is one continuous presentation interval even though Android emits a new DOWN;
                // an already-finished scroller remains the ordinary stationary gesture boundary.
                val continuingPhysicalMotion = synchronized(stateLock) {
                    !scroller.isFinished && activeInputDirection != 0
                }
                val scrollbarRequest = synchronized(stateLock) {
                    if (lifecycleRestoreInputPending) {
                        lifecycleRestoreInputPending = false
                        lifecycleViewportAnchorIdentity = null
                        lifecycleViewportAnchorPageTopPx = Float.NaN
                        lifecycleFirstGestureProbeArmed = true
                        // Lifecycle coordinates may remain protected across late exact-size
                        // reflow, but a real DOWN is the ownership boundary. No restore fence may
                        // constrain the user's first gesture after returning from HOME.
                        clearLockedRestorePositionLocked()
                        structuralScrollAdjustUntilMs = 0L
                        Log.i(
                            "ViewerPerf",
                            "reader_lifecycle_first_input_release scroll=${scrollOffset.toInt()}," +
                                "max=${maxScrollLocked().toInt()}," +
                                "limit=${forwardScrollLimitLocked(scheduleBlocked = false).toInt()}",
                        )
                    }
                    // The host-GPU path serializes texture uploads with the compositor even when
                    // the renderer has no changed frame queued. Freeze opportunistic uploads for
                    // the physical gesture and let visible frames retain the entire GPU budget.
                    setNativeTexturePrewarmPausedLocked(true)
                    if (startScrollbarDragLocked(event.x, event.y)) {
                        // The scrollbar is an absolute seek, not another relative reading swipe.
                        clearLockedRestorePositionLocked()
                        clearBlockedForwardIntentLocked()
                        clearDirectWifiForwardOnlyInitialResumeContractLocked()
                        noteInputLocked(event)
                        lastScrollInteractionMs = event.eventTime
                        activateScrollStatsLocked(event.eventTime)
                        startPhysicalGestureFrameCadenceLocked()
                        scroller.forceFinished(true)
                        activeScrollerOffsetShift = 0f
                        activeInputDirection = 0
                        pointerDown = true
                        dragging = true
                        postDirectFrameCallbackLocked()
                        if (!lastBusy) {
                            lastBusy = true
                        }
                        renderRequested = true
                        scheduleFrameLocked()
                        stateLock.notifyAll()
                        windowRequestLocked(true)
                    } else {
                        null
                    }
                }
            if (scrollbarDragging) {
                listener?.onPhysicalScrollGestureStarted(false)
                velocityTracker?.recycle()
                velocityTracker = null
                dispatchWindowRequest(scrollbarRequest, fromInput = true)
                return true
            }
                velocityTracker?.recycle()
                velocityTracker = VelocityTracker.obtain().also { it.addMovement(event) }
                val downRequest = synchronized(stateLock) {
                    seedPreContentForwardIntentLocked()
                    lastScrollInteractionMs = event.eventTime
                    activateScrollStatsLocked(event.eventTime)
                    startPhysicalGestureFrameCadenceLocked()
                    if (!scroller.isFinished && activeInputDirection == DIRECTION_NEXT) {
                        val interruptedTarget = (
                            scroller.finalY.toFloat() + activeScrollerOffsetShift
                            ).coerceIn(scrollOffset, maxScrollLocked())
                        if (interruptedTarget > scrollOffset + SCROLL_OFFSET_EPSILON_PX) {
                            // A rapid second upward swipe is acceleration, not a request to throw
                            // away the first fling's unconsumed travel. Preserve only its bounded
                            // final coordinate; capForwardInputScrollLocked still requires clean
                            // exact pixels, and the first reverse MOVE clears this intent.
                            rememberBlockedForwardIntentLocked(interruptedTarget)
                            Log.d(
                                TAG,
                                "reader_interrupted_forward_fling_retained " +
                                    "from=${scrollOffset.toInt()},to=${interruptedTarget.toInt()}",
                            )
                        }
                    }
                    scroller.forceFinished(true)
                    activeScrollerOffsetShift = 0f
                    activeInputDirection = 0
                    downX = event.x
                    downY = event.y
                    if (physicalGestureRevision == Long.MAX_VALUE) {
                        physicalGestureRevision = 1L
                        directCallbackObservedPhysicalGestureRevision = 0L
                        cleanPhysicalEpisodeTailGestureRevisions.clear()
                        cleanPhysicalEpisodeTailPresentedNanos.clear()
                    } else {
                        physicalGestureRevision++
                    }
                    acknowledgedBoundaryCrossedInPhysicalGesture = false
                    if (continuingPhysicalMotion && nativeCadenceProofGestureRevision > 0L) {
                        nativeCadenceContinuationFromGestureRevision =
                            nativeCadenceProofGestureRevision
                        nativeCadenceContinuationToGestureRevision = physicalGestureRevision
                    } else {
                        nativeCadenceContinuationFromGestureRevision = 0L
                        nativeCadenceContinuationToGestureRevision = 0L
                    }
                    carryBlockedForwardIntentIntoGestureLocked()
                    resetDragTrackingLocked(event.y)
                    lastVelocitySampleMs = event.eventTime
                    pointerDown = true
                    dragging = false
                    // Keep one vsync callback armed while the finger is down. A MOVE can then use
                    // that already-requested callback instead of requesting after the current
                    // vsync deadline and falling into an every-other-vsync cadence.
                    postDirectFrameCallbackLocked()
                    boundaryArmedDirection = 0
                    if (!lastBusy) {
                        lastBusy = true
                    }
                    // DOWN changes no pixels.  Touch delivery is measured at the Reader dispatch
                    // boundary, while frame input latency starts with the first MOVE that actually
                    // changes the viewport.  Invalidating here submits an unchanged full-screen
                    // frame ahead of that MOVE and can make the real scrolling frame wait behind
                    // RenderThread/GPU work.
                    stateLock.notifyAll()
                    windowRequestLocked(true)
                }
                // Publish after the DOWN state transition but before a MOVE can be delivered.
                // The telemetry owner can now retain a live-fling baseline without accepting an
                // older delayed proof as part of the new gesture.
                listener?.onPhysicalScrollGestureStarted(continuingPhysicalMotion)
                dispatchWindowRequest(downRequest, fromInput = true)
                return true
            }
            MotionEvent.ACTION_MOVE -> {
                if (scrollbarDragging) {
                    val request = synchronized(stateLock) {
                        noteInputLocked(event)
                        val request = moveScrollbarDragLocked(event.y)
                        if (request != null) notePhysicalPixelInputLocked(event)
                        renderRequested = true
                        scheduleFrameLocked()
                        request
                    }
                    dispatchWindowRequest(request, fromInput = true)
                    return true
                }
                // The native emulator producer and Android input main thread must not compete for
                // the same large reader monitor on every MOVE. Publish the absolute finger
                // position lock-free; the display producer consumes the newest position before
                // its next admission and owns all layout/frame state mutations.
                if (queuePhysicalMoveForProducer(event)) {
                    velocityTracker?.addMovement(event)
                    return true
                }
                var sampleVelocity = false
                val requestBusyWindow = synchronized(stateLock) {
                    val shouldSampleVelocity = event.eventTime - lastVelocitySampleMs >= MOVE_VELOCITY_SAMPLE_MS
                    if (shouldSampleVelocity) {
                        lastVelocitySampleMs = event.eventTime
                        sampleVelocity = true
                    }
                    noteInputLocked(event)
                    val moved = applyPhysicalDragPositionLocked(
                        event.y,
                        event.eventTime * NANOS_PER_MILLISECOND
                    )
                    if (moved) {
                        notePhysicalPixelInputLocked(event)
                        // The physical MOVE has already updated the viewport one-to-one. Admit only
                        // that real position; do not manufacture intermediate scroll positions.
                        val postedFreshCallback = postDirectFrameCallbackLocked()
                        // The HWUI View path has no producer-thread Choreographer. Admit its
                        // display-list frame from the same physical MOVE instead.
                        renderRequested = true
                        scheduleFrameLocked()
                        if (!postedFreshCallback) {
                            // A callback that already observed the prior exact target may be
                            // replaced only inside the bounded same-vsync race policy below.
                            postLateDirectInputCatchupLocked()
                        }
                        stateLock.notifyAll()
                        sampleVelocity = true
                        true
                    } else {
                        val nowMs = SystemClock.uptimeMillis()
                        suppressEdgeNoMovementScrollStatsLocked(nowMs)
                        // A zero-pixel reverse MOVE at the local top can still request older
                        // source images that were intentionally evicted below the saved resume
                        // floor. Deliver that evidence while the gesture is busy; waiting for UP
                        // made the initial drag look dead and allowed an idle request to erase it.
                        if (pendingReverseWindowFirstPageHint >= 0) {
                            true
                        } else {
                            false
                        }
                    }
                }
                if (sampleVelocity) velocityTracker?.addMovement(event)
                // The urgent direct renderer can already be waiting for stateLock when this MOVE
                // wakes it. Do not retain the monitor while deriving the controller's page window:
                // on a busy emulator the main thread can be preempted in that work and invert the
                // renderer's priority for multiple display intervals. This explicit release point
                // lets the renderer snapshot the exact physical position first. The second capture
                // remains authoritative because windowRequestLocked re-reads the current state.
                val request = if (requestBusyWindow) {
                    synchronized(stateLock) { windowRequestLocked(true) }
                } else {
                    null
                }
                dispatchWindowRequest(request, fromInput = true)
                return true
            }
            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                // Invalidate a MOVE already taken by the producer before applying this terminal
                // event's exact Y. It may finish before us, but can never run afterward and move
                // the viewport back to an older coordinate.
                physicalMoveMailbox.endGesture()
                if (scrollbarDragging) {
                    val request = synchronized(stateLock) {
                        noteInputLocked(event)
                        val moveRequest = moveScrollbarDragLocked(event.y)
                        if (moveRequest != null) notePhysicalPixelInputLocked(event)
                        scrollbarDragging = false
                        pointerDown = false
                        dragging = false
                        activeInputDirection = 0
                        endPhysicalScrollTraceLocked()
                        val busyRequest = setBusyLocked(false)
                        // Releasing the pointer changes interaction state, not manga pixels. Any
                        // final position change above has already entered through setScrollOffsetLocked.
                        markPixelsDirtyLocked(DIRTY_SCROLLBAR, recordCausalMutation = false)
                        busyRequest ?: moveRequest
                    }
                    dispatchWindowRequest(request, fromInput = true)
                    return true
                }
                val tracker = velocityTracker
                var velocityY = 0
                var tap = false
                if (tracker != null) {
                    tracker.addMovement(event)
                    tracker.computeCurrentVelocity(1000, maxVelocity.toFloat())
                    velocityY = (-tracker.yVelocity)
                        .coerceIn(-maxVelocity.toFloat(), maxVelocity.toFloat())
                        .toInt()
                    tracker.recycle()
                }
                velocityTracker = null
                val result = synchronized(stateLock) {
                    noteInputLocked(event)
                    val upMoved = applyPhysicalDragPositionLocked(
                        event.y,
                        event.eventTime * NANOS_PER_MILLISECOND
                    )
                    if (upMoved) notePhysicalPixelInputLocked(event)
                    val wasReleased = event.actionMasked == MotionEvent.ACTION_UP
                    val wasTap = isTapGesture(
                        wasReleased,
                        event.x - downX,
                        event.y - downY,
                        touchSlop
                    )
                    // A real finger commonly produces sub-slop MOVE samples. The drag follower
                    // may already have consumed those samples, but Android still defines the
                    // gesture as a tap. Restore the exact DOWN viewport so toggling chrome never
                    // nudges the page by a few pixels.
                    if (wasTap && abs(scrollOffset - dragOriginScrollOffset) > SCROLL_OFFSET_EPSILON_PX) {
                        setScrollOffsetLocked(dragOriginScrollOffset)
                        scroller.forceFinished(true)
                        activeScrollerOffsetShift = 0f
                        renderRequested = true
                        scheduleFrameLocked()
                        stateLock.notifyAll()
                    }
                    tap = wasTap
                    pointerDown = false
                    dragging = false
                    // A blocked drag target is valid only while this physical gesture owns the
                    // viewport. Once UP/CANCEL arrives, later image publication must not restart
                    // motion from that stale absolute coordinate.
                    clearBlockedForwardIntentLocked()
                    val dragDistance = abs(event.y - downY)
                    val cancelledBoundaryDrag = event.actionMasked == MotionEvent.ACTION_CANCEL &&
                        shouldDispatchCancelledBoundaryLocked(dragDistance)
                    val canFling = shouldStartFling(dragDistance, velocityY, minVelocity, touchSlop)
                    val releaseDirection = directionForDelta(velocityY.toFloat()).let { direction ->
                        if (direction != 0) direction else activeInputDirection
                    }
                    val terminalMaxScroll = maxScrollLocked()
                    val terminalRemaining = terminalMaxScroll - scrollOffset
                    val snappedToTerminalEdge = wasReleased && !wasTap &&
                        releaseDirection == DIRECTION_NEXT &&
                        terminalRemaining > SCROLL_OFFSET_EPSILON_PX &&
                        terminalRemaining <= height / 6f
                    if (snappedToTerminalEdge) {
                        activeInputDirection = DIRECTION_NEXT
                        boundaryArmedDirection = DIRECTION_NEXT
                        setScrollOffsetLocked(terminalMaxScroll)
                        scroller.forceFinished(true)
                        activeScrollerOffsetShift = 0f
                        renderRequested = true
                        scheduleFrameLocked()
                        stateLock.notifyAll()
                    }
                    val dispatch = if (wasTap) {
                        boundaryArmedDirection = 0
                        setBusyLocked(false) to null
                    } else if (snappedToTerminalEdge) {
                        val request = setBusyLocked(false)
                        (request ?: windowRequestLocked(false)) to
                            boundaryRequestLocked(clearDirection = false)
                    } else if (wasReleased && canFling && abs(velocityY) > minVelocity) {
                        // The first scroller sample does not exist until this exact ACTION_UP.
                        // Preserve that one causal event so time spent waiting for a sparse
                        // release is not charged to an animation that had not started yet. The
                        // timing is consumed by the first submitted fling frame only; every
                        // successor has no input evidence and remains fail-closed.
                        notePhysicalPixelInputLocked(event, startsContinuousMotion = true)
                        val flingVelocity = (velocityY * FLING_SCROLL_MULTIPLIER)
                            .coerceIn(-maxVelocity.toFloat(), maxVelocity.toFloat())
                            .toInt()
                        val flingDirection = directionForDelta(flingVelocity.toFloat())
                        boundaryArmedDirection = flingDirection
                        activeInputDirection = boundaryArmedDirection
                        if (boundaryArmedDirection != 0) lastScrollInteractionMs = event.eventTime
                        if (isAtInputEdgeLocked(flingDirection)) {
                            suppressEdgeNoMovementScrollStatsLocked(SystemClock.uptimeMillis())
                            val request = setBusyLocked(false)
                            (request ?: windowRequestLocked(false)) to boundaryRequestLocked()
                        } else {
                        val busyRequest = setBusyLocked(true)
                        activeScrollerOffsetShift = 0f
                        scroller.fling(
                            0,
                            scrollOffset.toInt(),
                            0,
                            flingVelocity,
                            0,
                            0,
                            0,
                            maxScrollLocked().toInt()
                        )
                        val physicsFinalY = scroller.finalY.toFloat()
                        val maximumCompactedFinalY = scrollOffset +
                            height * BLOCKED_FORWARD_RESUME_MAX_VIEWPORT_FRACTION
                        val nearbyTailStop = if (flingDirection == DIRECTION_NEXT) {
                            physicalEpisodeTailHoldLimitLocked(
                                min(physicsFinalY, maximumCompactedFinalY),
                                flingDirection,
                            )
                        } else {
                            null
                        }
                        val compactionReason: String?
                        val compactedFinalY = when {
                            nearbyTailStop != null &&
                                nearbyTailStop > scrollOffset + SCROLL_OFFSET_EPSILON_PX -> {
                                compactionReason = "clean_tail_stop"
                                nearbyTailStop
                            }
                            acknowledgedBoundaryCrossedInPhysicalGesture &&
                                flingDirection == DIRECTION_NEXT -> {
                                compactionReason = "acknowledged_crossing"
                                min(physicsFinalY, maximumCompactedFinalY)
                                    .coerceAtLeast(scrollOffset)
                            }
                            else -> {
                                compactionReason = null
                                Float.NaN
                            }
                        }
                        if (compactedFinalY.isFinite()) {
                            // Reach a nearby exact tail stop promptly so its final pixels become
                            // observable, or continue a later acknowledged crossing with the same
                            // bounded animation. OverScroller still supplies the destination and
                            // no more than 1.5 viewports can be compacted, so this neither creates
                            // travel nor skips an unobserved runway.
                            val compactedDistance = compactedFinalY - scrollOffset
                            if (compactedDistance > SCROLL_OFFSET_EPSILON_PX) {
                                val compactedDurationMs = blockedForwardResumeDurationMs(
                                    compactedDistance,
                                    max(1, height),
                                )
                                scroller.startScroll(
                                    0,
                                    scrollOffset.toInt(),
                                    0,
                                    compactedDistance.roundToInt(),
                                    compactedDurationMs,
                                )
                                Log.d(
                                    TAG,
                                    "reader_episode_boundary_fling_compacted " +
                                        "reason=$compactionReason," +
                                        "from=${scrollOffset.toInt()}," +
                                        "physics=${physicsFinalY.toInt()}," +
                                        "target=${compactedFinalY.toInt()}," +
                                        "durationMs=$compactedDurationMs," +
                                        "gesture=$physicalGestureRevision",
                                )
                            }
                        }
                        acknowledgedBoundaryCrossedInPhysicalGesture = false
                        renderRequested = true
                        scheduleFrameLocked()
                        stateLock.notifyAll()
                        (busyRequest ?: windowRequestLocked(true)) to boundaryRequestLocked()
                        }
                    } else {
                        if (!upMoved && !canFling) {
                            suppressEdgeNoMovementScrollStatsLocked(SystemClock.uptimeMillis())
                        }
                        val request = setBusyLocked(false)
                        val shouldDispatchBoundary = wasReleased || cancelledBoundaryDrag
                        val boundary = if (shouldDispatchBoundary) boundaryRequestLocked() else null
                        if (!shouldDispatchBoundary) boundaryArmedDirection = 0
                        if (!canFling) activeInputDirection = 0
                        request to boundary
                    }
                    // A moved gesture with no accepted fling is already idle at ACTION_UP. Keep
                    // the final visible frame ahead by waiting for scroller completion, but do
                    // not leave native prewarm paused merely because pixels moved. Repeated short
                    // swipes otherwise keep the pause latched forever and force every newly
                    // decoded adjacent tile into its first visible frame as one large upload.
                    if (!pointerDown && scroller.isFinished) {
                        endPhysicalScrollTraceLocked()
                        setNativeTexturePrewarmPausedLocked(false)
                    }
                    // Always arm the benchmark-only observer on UP/CANCEL. At the terminal edge a
                    // valid gesture may move zero pixels, so there may be no trace cookie whose
                    // later close could otherwise produce the final-idle proof.
                    scheduleBenchmarkPhysicalMotionIdleCheckLocked()
                    scheduleBlockedForwardIntentResumeLocked()
                    dispatch
                }
                dispatchWindowRequest(result.first, fromInput = true)
                dispatchBoundaryRequest(result.second)
                if (tap) mainHandler.post { performClick() }
                return true
            }
        }
        return true
    }

    /**
     * The reader view is already visible while exact discovery is building its immutable page
     * table. Swipes in that interval are real relative input, not taps to discard. Retain only
     * bounded forward travel; no scroll coordinate or frame exists until the page table installs.
     */
    private fun handlePreContentTouch(event: MotionEvent): Boolean {
        synchronized(stateLock) {
            when (event.actionMasked) {
                MotionEvent.ACTION_DOWN -> {
                    preContentVelocityTracker?.recycle()
                    preContentVelocityTracker = VelocityTracker.obtain().also {
                        it.addMovement(event)
                    }
                    preContentGestureActive = true
                    preContentGestureDownY = event.y
                    preContentGestureDownTimeMs = event.eventTime
                    preContentGestureForwardTravel = 0f
                }
                MotionEvent.ACTION_MOVE -> if (preContentGestureActive) {
                    preContentVelocityTracker?.addMovement(event)
                    preContentGestureForwardTravel = max(
                        preContentGestureForwardTravel,
                        preContentGestureDownY - event.y,
                    )
                    if (preContentGestureForwardTravel > touchSlop) {
                        // A real pre-content drag now owns the viewport. Discovery and restore
                        // callbacks can race this gesture, so neither the current nor a later
                        // launch bookmark may pull the physical target back to the start.
                        clearLockedRestorePositionLocked()
                        clearDirectWifiForwardOnlyInitialResumeContractLocked()
                    }
                    val gestureDurationMs = (event.eventTime - preContentGestureDownTimeMs)
                        .coerceAtLeast(1L)
                    val distanceVelocity = (
                        preContentGestureForwardTravel * 1_000f / gestureDurationMs
                        ).coerceIn(0f, maxVelocity.toFloat()).roundToInt()
                    preContentForwardVelocityY = max(
                        preContentForwardVelocityY,
                        distanceVelocity,
                    )
                }
                MotionEvent.ACTION_UP -> if (preContentGestureActive) {
                    preContentVelocityTracker?.run {
                        addMovement(event)
                        computeCurrentVelocity(1000, maxVelocity.toFloat())
                        preContentForwardVelocityY = max(
                            preContentForwardVelocityY,
                            (-yVelocity)
                                .coerceIn(0f, maxVelocity.toFloat())
                                .roundToInt(),
                        )
                        recycle()
                    }
                    preContentVelocityTracker = null
                    preContentGestureForwardTravel = max(
                        preContentGestureForwardTravel,
                        preContentGestureDownY - event.y,
                    )
                    val releaseDurationMs = (event.eventTime - preContentGestureDownTimeMs)
                        .coerceAtLeast(1L)
                    val releaseDistanceVelocity = (
                        preContentGestureForwardTravel * 1_000f / releaseDurationMs
                        ).coerceIn(0f, maxVelocity.toFloat()).roundToInt()
                    preContentForwardVelocityY = max(
                        preContentForwardVelocityY,
                        releaseDistanceVelocity,
                    )
                    if (preContentGestureForwardTravel > touchSlop) {
                        clearLockedRestorePositionLocked()
                        clearDirectWifiForwardOnlyInitialResumeContractLocked()
                        val viewport = max(1, height).toFloat()
                        preContentForwardIntentPx = (
                            preContentForwardIntentPx + preContentGestureForwardTravel
                            ).coerceAtMost(viewport * PRE_CONTENT_FORWARD_INTENT_MAX_VIEWPORTS)
                    }
                    preContentGestureActive = false
                    preContentGestureDownTimeMs = 0L
                    preContentGestureForwardTravel = 0f
                    seedPreContentForwardIntentLocked()
                }
                MotionEvent.ACTION_CANCEL -> {
                    preContentVelocityTracker?.recycle()
                    preContentVelocityTracker = null
                    preContentGestureActive = false
                    preContentGestureDownTimeMs = 0L
                    preContentGestureForwardTravel = 0f
                }
            }
        }
        return true
    }

    override fun performClick(): Boolean {
        super.performClick()
        listener?.onTap()
        return true
    }

    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)
        val nativeSurfaceOwnsFrame = synchronized(stateLock) {
            val nativeAttached = directSurfaceReady && rollingNativeHandle != 0L &&
                rollingNativeAttachEpoch > 0L && !rollingNativeFatal
            nativeAttached && (
                (nativePresentationVisible && nativeSurfaceContentRevealed &&
                    nativePresentedStructureEpoch == traversalStructureEpoch) ||
                    // A HostExact page has no HWUI image: its Bitmap is only a 1x1 lease token.
                    // Once the native producer is attached, an incidental ViewRoot traversal must
                    // not steal its uniquely admitted frame token while the first SurfaceControl
                    // transaction is still being installed. The loading root stays unchanged
                    // until that real native latch raises the transparent child.
                    visibleActualPixelsRequireNativePresenterLocked()
                )
        }
        if (!nativeSurfaceOwnsFrame) {
            renderFrame(System.nanoTime(), canvas, directSurface = false)
        }
    }

    private fun renderFrame(
        frameTimeNanos: Long,
        canvas: Canvas?,
        directSurface: Boolean,
        frameTimelineVsyncId: Long = 0L,
        expectedPresentationTimeNanos: Long = 0L,
    ): Boolean {
        val callbackStartNs = System.nanoTime()
        val nativeSubmission = directSurface && canvas == null
        val work = prepareRenderWork(nativeSubmission) ?: return false
        val preparedAtNanos = System.nanoTime()
        val state = work.state ?: run {
            dispatchWindowRequest(work.request)
            dispatchBoundaryRequest(work.boundary)
            synchronized(stateLock) {
                if (shouldLogProgrammaticScrollDiagnosticLocked()) {
                    Log.d(TAG, "reader_test_scroll_draw_skipped state=null")
                }
            }
            return false
        }
        val timing = if (nativeSubmission) {
            submitNativeFrame(
                frameTimeNanos,
                callbackStartNs,
                state,
                work,
                frameTimelineVsyncId,
                expectedPresentationTimeNanos,
            )
        } else {
            drawState(
                frameTimeNanos,
                callbackStartNs,
                state,
                checkNotNull(canvas),
                work.mutation,
                work.physicalGestureRevision,
                work.physicalMotionTraceCookie,
            )
        }
        val submittedAtNanos = System.nanoTime()
        val finished = finishRenderedFrame(
            canvas = canvas,
            directSurface = directSurface,
            nativeSubmission = nativeSubmission,
            state = state,
            work = work,
            timing = timing,
            producerCallbackStartedNanos = callbackStartNs.takeIf { nativeSubmission } ?: 0L,
            expectedPresentationTimeNanos =
                expectedPresentationTimeNanos.takeIf { nativeSubmission } ?: 0L,
        )
        val finishedAtNanos = System.nanoTime()
        val prepareNanos = preparedAtNanos - callbackStartNs
        val submitNanos = submittedAtNanos - preparedAtNanos
        val finishNanos = finishedAtNanos - submittedAtNanos
        val totalNanos = finishedAtNanos - callbackStartNs
        if (nativeSubmission &&
            (prepareNanos >= 16_000_000L || submitNanos >= 16_000_000L ||
                finishNanos >= 16_000_000L)
        ) {
            val ordinal = ++directFrameStageDiagnostics
            if (ordinal == 1L || ordinal % 60L == 0L ||
                totalNanos >= 50_000_000L ||
                prepareNanos >= 100_000_000L || submitNanos >= 100_000_000L ||
                finishNanos >= 100_000_000L
            ) {
                Log.i(
                    "ViewerPerf",
                    "reader_direct_frame_stage_slow ordinal=$ordinal," +
                        "prepareMs=${prepareNanos / 1_000_000.0}," +
                        "submitMs=${submitNanos / 1_000_000.0}," +
                        "finishMs=${finishNanos / 1_000_000.0}," +
                        "totalMs=${totalNanos / 1_000_000.0},items=${state.items.size}",
                )
            }
        }
        return finished
    }

    private fun prepareRenderWork(
        reserveNativeCaptureLease: Boolean,
    ): RenderWork? {
        val callBeginNs = System.nanoTime()
        var lockAcquiredNs = callBeginNs
        var motionReadyNs = callBeginNs
        var resolvesReadyNs = callBeginNs
        var runwayReadyNs = callBeginNs
        var stateReadyNs = callBeginNs
        var lockReleasedNs = callBeginNs
        val result = synchronized(stateLock) {
        lockAcquiredNs = System.nanoTime()
        if (!renderRunning || frameSchedulingSuppressed ||
            framePipe != FramePipe.INVALIDATION_POSTED || inFlightToken == 0L
        ) return@synchronized null
        val admittedToken = inFlightToken
        val admittedEpoch = inFlightEpoch
        var request: WindowRequest? = null
        var boundary: BoundaryRequest? = null
        var scrolling = try {
            scroller.computeScrollOffset()
        } catch (_: ArrayIndexOutOfBoundsException) {
            scroller.forceFinished(true)
            false
        }
        if (scrolling) {
            lastScrollInteractionMs = SystemClock.uptimeMillis()
            val beforeScroll = scrollOffset
            val rawNext = scroller.currY.toFloat() + activeScrollerOffsetShift
            val rawDirection = directionForDelta(rawNext - scrollOffset)
            val direction = if (rawDirection != 0) rawDirection else activeInputDirection
            if (rawDirection != 0) {
                activeInputDirection = rawDirection
                boundaryArmedDirection = rawDirection
            }
            val boundedNext = capForwardInputScrollLocked(rawNext, direction)
            setScrollOffsetLocked(boundedNext)
            if (!(limitScrollToDrawablePrefix && direction == DIRECTION_NEXT)) {
                clampForwardScrollLocked()
            } else if (boundedNext < rawNext - SCROLL_OFFSET_EPSILON_PX) {
                // The current scroller sample is usually only a few pixels beyond the
                // drawable fence. Preserve its full physical destination before stopping the
                // unsafe animation; later exact pixels may resume only up to a clean viewport.
                val cleanTailHold = isCleanPhysicalEpisodeTailHoldAppliedLocked(boundedNext)
                if (!cleanTailHold) {
                    rememberBlockedForwardIntentLocked(
                        max(rawNext, scroller.finalY.toFloat() + activeScrollerOffsetShift)
                    )
                }
                scroller.forceFinished(true)
                activeScrollerOffsetShift = 0f
                if (!cleanTailHold) scheduleBlockedForwardIntentResumeLocked()
            }
            val movedByFrame = abs(scrollOffset - beforeScroll) > SCROLL_OFFSET_EPSILON_PX
            // A scroller tick mutates reader pixels just like a MOVE.  Preserve the
            // commit-aware version invariant even when no newer input/content version is
            // already pending; the frame built below must carry this exact scroll state.
            if (shouldAdvanceDesiredVersionForScrollerFrame(
                    movedByFrame,
                    desiredVersion,
                    drawnVersion
                )
            ) {
                advanceDesiredVersionLocked()
            }
            if (movedByFrame) {
                HostExactHardwareTilePool.notePhysicalReaderActivity()
                beginPhysicalScrollTraceLocked()
                pendingPixelReasons = pendingPixelReasons or DIRTY_ANIMATION
            }
            if (
                shouldFinishScrollerAtInputEdgeLocked(direction, rawNext) ||
                (!movedByFrame && isAtInputEdgeLocked(direction))
            ) {
                scroller.forceFinished(true)
                activeScrollerOffsetShift = 0f
                scrolling = false
                if (!movedByFrame) {
                    suppressEdgeNoMovementScrollStatsLocked(SystemClock.uptimeMillis())
                }
            }
            renderRequested = true
            request = windowRequestLocked(true)
            boundary = boundaryRequestLocked(clearDirection = false)
        } else if (scroller.isFinished) {
            val maxScroll = maxScrollLocked()
            val remaining = maxScroll - scrollOffset
            val snapToTerminalEdge = !pointerDown &&
                activeInputDirection == DIRECTION_NEXT &&
                remaining > SCROLL_OFFSET_EPSILON_PX &&
                remaining <= height / 6f
            if (snapToTerminalEdge) {
                setScrollOffsetLocked(maxScroll)
                advanceDesiredVersionLocked()
                pendingPixelReasons = pendingPixelReasons or DIRTY_ANIMATION
                renderRequested = true
                request = windowRequestLocked(true)
                boundary = boundaryRequestLocked(clearDirection = false)
            }
            activeScrollerOffsetShift = 0f
            activeInputDirection = 0
        }
        val wasBusy = lastBusy
        // OverScroller may return true for the terminal sample while simultaneously changing
        // isFinished to true. That sample still owns the final pixels below, but it must not
        // leave controller busy/prewarm-pause latched: no successor animation frame is armed
        // once isFinished is true.
        val physicalMotionNow = isScrollBusyAfterSample(
            pointerDown = pointerDown,
            dragging = dragging,
            scrollerFinished = scroller.isFinished,
            blockedForwardIntentPending = false,
        )
        val busyNow = isScrollBusyAfterSample(
            pointerDown = pointerDown,
            dragging = dragging,
            scrollerFinished = scroller.isFinished,
            blockedForwardIntentPending = hasLiveBlockedForwardIntentLocked(),
        )
        // A parked intent needs newly decoded/mirrored pixels to make progress. Keep controller
        // busy truthful without pausing the prewarm work which releases that intent.
        setNativeTexturePrewarmPausedLocked(physicalMotionNow)
        if (busyNow != lastBusy) {
            request = setBusyLocked(busyNow) ?: request
        } else if (busyNow) {
            request = windowRequestLocked(true) ?: request
        }
        if (wasBusy && !busyNow) {
            boundary = boundaryRequestLocked() ?: boundary
            scheduleBlockedForwardIntentResumeLocked()
        }
        motionReadyNs = System.nanoTime()
        if (!busyNow) {
            val nowMs = SystemClock.uptimeMillis()
            val recentScrollStats = nowMs <= programmaticScrollStatsUntilMs ||
                (lastScrollInteractionMs > 0L &&
                    nowMs - lastScrollInteractionMs <= PROGRAMMATIC_SCROLL_STATS_RECENT_MS)
            if (recentScrollStats) {
                if (hasPendingPageResolvesLocked()) schedulePendingResolveRetryLocked(markLayoutDirty = false)
            } else {
                applyPendingPageResolvesLocked()
            }
        }
        if (limitScrollToDrawablePrefix) {
            applyVisiblePendingDrawableResolvesLocked()
        }
        resolvesReadyNs = System.nanoTime()
        // Every original is already decoded. Keep only a bounded forward HWUI upload runway
        // moving with the latest downward viewport so page-boundary frames never pay first-use
        // bitmap preparation. The producer only enqueues immutable targets; driver work belongs
        // to the background lane and can never hold this physical frame or [stateLock].
        scheduleHwuiForwardRunwayPreparationLocked()
        runwayReadyNs = System.nanoTime()
        // A drag advances only when a real MOVE changes scrollOffset; that MOVE already sets
        // renderRequested and schedules its presentation frame. Treating the mere
        // `dragging` state as an animation submits unchanged full-screen frames between input
        // samples and can block the next MOVE/UP behind RenderThread backpressure.
        val animateScroll = scrolling || !scroller.isFinished
        val shouldDraw = (renderRequested || animateScroll) && pages.isNotEmpty()
        val deferInitialEmptyDraw = shouldDeferInitialEmptyDrawLocked()
        if (shouldDraw && deferInitialEmptyDraw) {
            val liveBitmaps = pages.count { page ->
                page.bitmap?.isRecycled == false || page.tiles.any { !it.bitmap.isRecycled }
            }
            val recycledTiles = pages.sumOf { page ->
                page.tiles.count { it.bitmap.isRecycled }
            }
            lastDrawStateNullReason =
                "defer_initial_empty:livePages=$liveBitmaps,recycledTiles=$recycledTiles," +
                    "strip=$stripAuthorityToken"
        }
        var state = if (shouldDraw && !deferInitialEmptyDraw) {
            buildDrawStateLocked(
                busy = busyNow,
                useRetainedNativeBandItems = reserveNativeCaptureLease,
            )
        } else {
            null
        }
        stateReadyNs = System.nanoTime()
        val exactStructureHeld = state?.let(::hasNonContiguousExactNativeStructure) == true
        if (exactStructureHeld) {
            val heldState = checkNotNull(state)
            val nowMs = SystemClock.uptimeMillis()
            if (nowMs - lastExactStructureHoldLogMs >= EXACT_STRUCTURE_HOLD_LOG_INTERVAL_MS) {
                lastExactStructureHoldLogMs = nowMs
                Log.d(
                    TAG,
                    "reader_native_exact_structure_hold visible=" +
                        heldState.items.joinToString("|") { it.index.toString() } +
                        ",scroll=${fmt(heldState.scrollOffset)},busy=$busyNow",
                )
            }
            boundary?.let { heldBoundary ->
                boundaryDispatchInFlight = false
                boundaryArmedDirection = heldBoundary.direction
                boundary = null
            }
            state = null
            lastDrawStateNullReason = "non_contiguous_exact_structure"
            renderRequested = true
        }
        if (state == null && shouldLogProgrammaticScrollDiagnosticLocked()) {
            Log.d(
                TAG,
                "reader_test_scroll_state_null shouldDraw=$shouldDraw renderRequested=$renderRequested " +
                    "animateScroll=$animateScroll pages=${pages.size} defer=$deferInitialEmptyDraw " +
                    "busy=$busyNow scroll=${fmt(scrollOffset)}"
            )
        }
        if (renderRequested && pages.isEmpty()) renderRequested = false
        val version = if (state != null) desiredVersion else 0L
        val mutation = if (shouldConsumePixelMutationTiming(
                hasDrawState = state != null,
                pendingWatermark = pendingPixelMutationWatermark
            )
        ) {
            consumePendingPixelMutationTimingLocked(inFlightInvalidationPostedNs)
        } else {
            null
        }
        val capturedPhysicalInput = if (state != null) {
            consumePendingPhysicalPixelInputLocked()
        } else {
            null
        }
        // A fling owns continuous animation demand after its release sample. Bind that exact
        // ACTION_UP to the first scroller frame, then leave every successor input-less so the
        // cadence classifier remains fail-closed for missed animation frames.
        val physicalInput = capturedPhysicalInput?.takeIf { input ->
            !animateScroll || input.startsContinuousMotion
        }
        if (state != null) {
            lastDrawStateNullReason = "none"
            renderRequested = false
            drawnVersion = version
        } else {
            if (renderRequested && pages.isNotEmpty() &&
                (!exactStructureHeld || !animateScroll)
            ) {
                scheduleNoStateRetryLocked()
            }
            // No reader draw was recorded, so there is no reader HWUI submission to prove.
            // Waiting for an unrelated root commit here held the only admission token for
            // another 1-3 vsyncs during touch input. Unregister this no-op callback and release
            // immediately; any racing callback is rejected by its now-stale unique token.
            val callback = inFlightCommitCallback
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q &&
                callback != null && inFlightCommitCallbackRegistered
            ) {
                val observer = viewTreeObserver
                if (observer.isAlive) observer.unregisterFrameCommitCallback(callback)
            }
            releasePostedAdmissionLocked(preserveDirty = true)
            if (exactStructureHeld && animateScroll) {
                scheduleFrameLocked()
            }
        }
        val nativeCaptureLease = reserveNativeCaptureLease && state != null
        if (nativeCaptureLease) {
            deferredNativeSceneSubmissionsInFlight.incrementAndGet()
        }
        val prepared = RenderWork(
            request,
            boundary,
            state,
            admittedToken,
            admittedEpoch,
            version,
            mutation,
            physicalInput,
            physicalGestureRevision,
            physicalMotionCadenceCookie,
            nativeCaptureLease,
        )
        lockReleasedNs = System.nanoTime()
        prepared
        }
        val callEndNs = System.nanoTime()
        if (reserveNativeCaptureLease && callEndNs - callBeginNs >= 50_000_000L) {
            Log.i(
                "ViewerPerf",
                "reader_prepare_frame_slow totalMs=${(callEndNs - callBeginNs) / 1_000_000.0}," +
                    "lockWaitMs=${(lockAcquiredNs - callBeginNs) / 1_000_000.0}," +
                    "motionMs=${(motionReadyNs - lockAcquiredNs) / 1_000_000.0}," +
                    "resolveMs=${(resolvesReadyNs - motionReadyNs) / 1_000_000.0}," +
                    "runwayMs=${(runwayReadyNs - resolvesReadyNs) / 1_000_000.0}," +
                    "stateMs=${(stateReadyNs - runwayReadyNs) / 1_000_000.0}," +
                    "finishMs=${(lockReleasedNs - stateReadyNs) / 1_000_000.0}",
            )
        }
        return result
    }

    private fun finishRenderedFrame(
        canvas: Canvas?,
        directSurface: Boolean,
        nativeSubmission: Boolean,
        state: DrawState,
        work: RenderWork,
        timing: DrawTiming,
        producerCallbackStartedNanos: Long,
        expectedPresentationTimeNanos: Long,
    ): Boolean {
    if (nativeSubmission && !timing.posted) {
        dispatchWindowRequest(work.request)
        dispatchBoundaryRequest(work.boundary)
        synchronized(stateLock) {
            restorePendingPhysicalPixelInputLocked(work.physicalInput)
            earlyNativeOutcomes.remove(work.frameToken)
            if (work.frameEpoch == lifecycleEpoch && work.frameToken == inFlightToken) {
                drawnVersion = latestSubmittedVersionLocked()
                releasePostedAdmissionLocked(preserveDirty = true)
                scheduleNoStateRetryLocked()
                stateLock.notifyAll()
            }
        }
        return false
    }
    dispatchWindowRequest(work.request)
    dispatchBoundaryRequest(work.boundary)
    val nowMs = SystemClock.uptimeMillis()
        val slowFrameLogBudget = IDLE_SLOW_FRAME_LOG_BUDGET_MS
    val renderWorkMs = timing.drawMs
    if (renderWorkMs > slowFrameLogBudget && nowMs - lastSlowFrameLogMs >= SLOW_FRAME_LOG_INTERVAL_MS) {
        lastSlowFrameLogMs = nowMs
        Log.d(
            TAG,
            "reader_slow_frame busy=${state.busy} items=${state.items.size} " +
                "visibleLoading=${state.visibleLoading} prepMs=${fmt(timing.lockWaitMs)} drawMs=${fmt(timing.drawMs)} " +
                "totalMs=${fmt(timing.totalMs)} visibleItems=${formatDrawItems(state)}"
        )
    }
    val coverage = coverageStats(state)
    if (listener?.shouldReportVisibleStats() != false) {
        if (lastVisibleLoading != state.visibleLoading) {
            lastVisibleLoading = state.visibleLoading
            Log.i(
                TAG,
                "reader_visible_loading=${state.visibleLoading} busy=${state.busy} " +
                    "items=${state.items.size} visibleItems=${formatDrawItems(state)}"
            )
            logCoverageIfNeeded(state, coverage, force = true)
        }
        logCoverageIfNeeded(state, coverage, force = false)
    }
    val completedCoverage = updateVisibleCoverageSnapshot(state, coverage)
    // DrawState items are producer-confined immutable values. Pack their submitted identity
    // once, then share that immutable result with traversal accounting and the pending commit
    // proof. The old Sequence/distinct/sort chains boxed indexes and built several transient
    // collections after every otherwise-fast native submission.
    val submittedVisiblePages = packNtkVisibleFrameProof(
        state.items,
        state.height,
        state.viewportItemTopOffset,
    )
    val traversalProof = frameTraversalProof(
        state,
        completedCoverage,
        submittedVisiblePages,
    )
    val rollingVisiblePageIndexes = submittedVisiblePages.pageIndexes
    // Identity belongs to the exact submitted pixels even when the generic traversal counter
    // is not armed for this frame. Keeping it only inside FrameTraversalProof made a valid
    // old-structure buffer fall back to live session indexes while a prefix removal was
    // crossing from the session control lane to the Surface main-thread callback.
    val rollingVisiblePageIdentities = submittedVisiblePages.pageIdentities
    val rollingFirstVisiblePageTopPx = rollingVisiblePageIdentities.firstOrNull()?.let { first ->
        state.items.firstOrNull { item -> item.index == first.displayPageIndex }?.let { item ->
            item.top - state.viewportItemTopOffset
        }
    } ?: Float.NaN
    val rollingVisiblePageTopPx = FloatArray(rollingVisiblePageIdentities.size) { identityIndex ->
        val identity = rollingVisiblePageIdentities[identityIndex]
        state.items.firstOrNull { item -> item.index == identity.displayPageIndex }?.let { item ->
            item.top - state.viewportItemTopOffset
        } ?: Float.NaN
    }
    if (traversalProof != null &&
        (traversalProof.viewportDefect || traversalProof.runwayDefect)
    ) {
        val runway = state.forwardRunway
        Log.w(
            TAG,
            "reader_traversal_pixel_defect viewport=${traversalProof.viewportDefect}," +
                "runway=${traversalProof.runwayDefect},scroll=${fmt(state.scrollOffset)}," +
                "coverage=drawable:${completedCoverage.drawablePx}/" +
                "${completedCoverage.physicalViewportPx},missing:${completedCoverage.missingPx}," +
                "placeholder:${completedCoverage.placeholderPx}," +
                "lowRes:${completedCoverage.lowResolutionItems}," +
                "runwayProof=${runway?.drawableAheadPx ?: -1}/" +
                "${runway?.availableAheadPx ?: -1}," +
                "runwayRequired=${runway?.requiredAheadPx ?: -1}," +
                "runwayMissing=${runway?.missingAheadPx ?: -1}," +
                "runwayLowRes=${runway?.lowResolutionItems ?: -1}," +
                "runwayFirstMissing=${runway?.firstMissingPage ?: -1}," +
                "items=${formatDrawItems(state)}"
        )
    }
    var hardwareCommitUnavailable = false
    var earlyNativeOutcome: EarlyNativeOutcome? = null
    var earlyFrameSyncedGeometryRequest: FrameSyncedGeometryRequest? = null
    val fallbackCommit = synchronized(stateLock) {
        if (work.frameEpoch != lifecycleEpoch || work.frameToken != inFlightToken ||
            framePipe != FramePipe.INVALIDATION_POSTED
        ) {
            false
        } else {
            val callback = inFlightCommitCallback
            val callbackRegistered = inFlightCommitCallbackRegistered
            val pendingProof = PendingCommittedDraw(
                work.frameToken,
                work.drawnVersion,
                canvas?.isHardwareAccelerated == true,
                completedCoverage,
                traversalProof,
                state.traversalEpoch,
                rollingVisiblePageIndexes,
                rollingVisiblePageIdentities,
                state.scrollOffset,
                rollingFirstVisiblePageTopPx,
                rollingVisiblePageTopPx,
                work.physicalInput?.oldestNs ?: 0L,
                work.physicalInput?.newestNs ?: 0L,
                work.physicalInput?.receivedOldestNs ?: 0L,
                work.physicalInput?.receivedNewestNs ?: 0L,
                work.physicalGestureRevision,
                producerCallbackStartedNanos,
                expectedPresentationTimeNanos,
            )
            if (callback == null) {
                drawnVersion = latestSubmittedVersionLocked()
                renderRequested = true
                releasePostedAdmissionLocked(preserveDirty = true)
                scheduleNoStateRetryLocked()
                false
            } else if (!directSurface && !callbackRegistered &&
                Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q && canvas?.isHardwareAccelerated == true
            ) {
                // Never turn Canvas-recording completion into a hardware submission proof.
                // Drop this admission and retry explicitly; the strict API35 path must bind a
                // real ViewTreeObserver frame-commit callback.
                hardwareCommitUnavailable = true
                drawnVersion = latestSubmittedVersionLocked()
                renderRequested = true
                releasePostedAdmissionLocked(preserveDirty = true)
                scheduleNoStateRetryLocked()
                false
            } else {
                recordSubmittedTraversalProofLocked(traversalProof)
                if (timing.nativeSupersededToken > 0L) {
                    nativeMailboxSupersededRetirements++
                    pendingFrameCommits.remove(timing.nativeSupersededToken)
                    earlyNativeOutcomes.remove(timing.nativeSupersededToken)
                    earlyFrameSyncedGeometryRequests.remove(timing.nativeSupersededToken)
                    frameSyncedGeometryInFlightTokens.remove(timing.nativeSupersededToken)
                    frameSyncedGeometrySubmissionOrder.remove(timing.nativeSupersededToken)
                }
                pendingFrameCommits[work.frameToken] = PendingFrameCommit(
                    frameEpoch = work.frameEpoch,
                    nativeSurfaceEpoch = timing.nativeSurfaceEpoch,
                    callback = callback,
                    callbackRegistered = callbackRegistered,
                    surfaceQueueSubmission = directSurface && !nativeSubmission,
                    surfaceControlSubmission = nativeSubmission,
                    proof = pendingProof
                )
                if (nativeSubmission) {
                    // Native OnComplete callbacks may be delivered in a different Binder order
                    // than their FIFO transaction submissions. Preserve the immutable submission
                    // order for cadence; semantic delivery remains callback-immediate.
                    frameSyncedGeometrySubmissionOrder[work.frameToken] = null
                }
                // The native renderer owns a different thread and can complete a very cheap
                // queueBuffer before nativeSubmit() returns to this method. Consume that exact
                // token's buffered proof now that its immutable Kotlin proof is registered.
                earlyNativeOutcome = earlyNativeOutcomes.remove(work.frameToken)
                earlyFrameSyncedGeometryRequest =
                    earlyFrameSyncedGeometryRequests.remove(work.frameToken)
                // Recording this display list completes the admission.  Its immutable proof now
                // waits independently for HWUI commit, so the next vsync is not serialized behind
                // host-GPU/RenderThread latency.
                releasePostedAdmissionLocked(preserveDirty = false)
                if (renderRequested || desiredVersion > drawnVersion || !scroller.isFinished) {
                    if (!scroller.isFinished) {
                        pendingPixelReasons = pendingPixelReasons or DIRTY_ANIMATION
                    }
                    scheduleFrameLocked()
                }
                !directSurface && !callbackRegistered
            }
        }
    }
    if (hardwareCommitUnavailable) {
        Log.e(TAG, "reader_frame_commit_callback_unavailable api=${Build.VERSION.SDK_INT}")
    }
    when (val early = earlyNativeOutcome) {
        is EarlyNativeOutcome.Presented -> completeOrBufferNativePresentation(
            work.frameToken,
            early.presentedUptimeNanos,
            early.presentationKind,
            allowBuffer = false,
        )
        is EarlyNativeOutcome.PresentFailed -> {
            // JNI ingress already counted this terminal outcome before buffering it.
            // Registration owns only the redrive; routing through the JNI callback again
            // would count one physical failure twice in before/after stress deltas.
            recoverDirectSurfaceSubmission(work.frameEpoch, work.frameToken)
        }
        null -> Unit
    }
    earlyFrameSyncedGeometryRequest?.let(::submitFrameSyncedGeometryRequest)
    timing.directActiveBandGeometry?.let { request ->
        if (timing.directActiveBandNativeFollowup) {
            synchronized(stateLock) {
                directActiveBandNativeFollowupTokens.add(request.token)
            }
        }
        val directAccepted = submitFrameSyncedGeometryRequest(request)
        if (directAccepted) {
            val ordinal = ++directActiveBandGeometrySubmissionCount
            if (ordinal == 1L || ordinal % 120L == 0L) {
                Log.i(
                    TAG,
                    "reader_active_band_direct_geometry ordinal=$ordinal," +
                        "token=${request.token},source=${request.sourceTop}",
                )
            }
        } else if (timing.directActiveBandNativeFollowup) {
            synchronized(stateLock) {
                directActiveBandNativeFollowupTokens.remove(request.token)
            }
        }
    }
    timing.deferredNativeScene?.let(::postDeferredNativeSceneSubmission)
    timing.deferredNativeGeometry?.let(::postDeferredNativeGeometrySubmission)
    if (fallbackCommit) {
        // API < 29/software fallback cannot provide a swap-chain callback. API 35 hardware,
        // which is the strict production path, always uses the pre-draw registered callback.
        mainHandler.post { onFrameCommitted(work.frameEpoch, work.frameToken) }
    }
    if (timing.posted) synchronized(stateLock) { lastPostedFrameEndNs = timing.postEndNs }
    val nowForStats = SystemClock.uptimeMillis()
    val edgeNoMovementSuppressed = nowForStats <= edgeNoMovementStatsSuppressedUntilMs
    val statsActive = !edgeNoMovementSuppressed &&
        (state.busy ||
            nowForStats <= programmaticScrollStatsUntilMs ||
            (nowForStats - lastScrollInteractionMs <= PROGRAMMATIC_SCROLL_STATS_RECENT_MS))
    recordFrameStats(timing, statsActive)
    if (timing.posted) synchronized(stateLock) {
        closeSubmittedPhysicalCallbackCadenceLocked(work.drawnVersion)
    }
        return true
    }

    private fun postDeferredNativeGeometrySubmission(
        submission: DeferredNativeGeometrySubmission,
    ) {
        val handler = synchronized(stateLock) {
            val pending = pendingFrameCommits[submission.token]
            if (pending?.surfaceControlSubmission == true &&
                pending.nativeSurfaceEpoch == submission.attachEpoch &&
                rollingNativeHandle == submission.handle &&
                rollingNativeAttachEpoch == submission.attachEpoch &&
                !rollingNativeFatal
            ) {
                frameSyncedGeometryCommitHandler ?: directRenderHandler
            } else {
                null
            }
        }
        if (handler == null) {
            releaseDeferredNativeGeometrySubmission(submission)
            return
        }
        if (!handler.post(submission)) {
            releaseDeferredNativeGeometrySubmission(submission)
            onNtkRollingFrameDropped(submission.token, NATIVE_FRAME_DROP_PRESENT_FAILED)
        }
    }

    private fun postDeferredNativeSceneSubmission(
        submission: DeferredNativeSceneSubmission,
    ) {
        val handler = synchronized(stateLock) {
            val pending = pendingFrameCommits[submission.token]
            if (pending?.surfaceControlSubmission == true &&
                pending.nativeSurfaceEpoch == submission.attachEpoch &&
                rollingNativeHandle == submission.handle &&
                rollingNativeAttachEpoch == submission.attachEpoch &&
                !rollingNativeFatal
            ) {
                frameSyncedGeometryCommitHandler ?: directRenderHandler
            } else {
                null
            }
        }
        if (handler == null || !handler.post(submission)) {
            val token = submission.token
            // The producer scene is only a local promise until nativeSubmit accepts this full
            // snapshot. A structure/lifecycle turn can retire the Kotlin proof between capture
            // and this post. Keeping that unsubmitted id cached makes every later frame choose
            // geometry-only reuse for a scene the native renderer has never seen, producing a
            // permanent dirty/no-state retry loop. This method runs on ReaderSurfaceProducer, the
            // sole owner of the producer-scene cache, so revoke the promise before retrying.
            clearNativeProducerScene(submission.producerSceneId)
            Log.w(
                TAG,
                "reader_deferred_native_scene_post_rejected token=${submission.token}," +
                    "attach=${submission.attachEpoch},pending=${synchronized(stateLock) {
                        pendingFrameCommits.containsKey(submission.token)
                    }}",
            )
            finishDeferredNativeSceneSubmission(submission)
            onNtkRollingFrameDropped(token, NATIVE_FRAME_DROP_PRESENT_FAILED)
        }
    }

    private fun executeDeferredNativeSceneSubmission(
        submission: DeferredNativeSceneSubmission,
    ) {
        val stillCurrent = synchronized(stateLock) {
            pendingFrameCommits[submission.token]?.let { pending ->
                pending.surfaceControlSubmission &&
                    pending.nativeSurfaceEpoch == submission.attachEpoch &&
                    rollingNativeHandle == submission.handle &&
                    rollingNativeAttachEpoch == submission.attachEpoch &&
                    !rollingNativeFatal && directSurfaceReady
            } == true
        }
        if (!stillCurrent) {
            val producerSceneId = submission.producerSceneId
            Log.w(
                TAG,
                "reader_deferred_native_scene_stale token=${submission.token}," +
                    "attach=${submission.attachEpoch}",
            )
            // executeDeferredNativeSceneSubmission owns the commit Looper. Return cache
            // retirement to ReaderSurfaceProducer before any later callback can reuse this id.
            directRenderHandler?.post {
                clearNativeProducerScene(producerSceneId)
            }
            finishDeferredNativeSceneSubmission(submission)
            return
        }
        val nativeAttachReady = runCatching {
            NtkRollingNativeBridge.nativeIsSurfaceAttached(
                submission.handle,
                submission.attachEpoch,
            )
        }.getOrDefault(false)
        if (!nativeAttachReady) {
            // nativeAttach() is deliberately an enqueue. A cold full-scene capture can reach this
            // serial commit Looper while EGL/AHardwareBuffer preparation is still completing.
            // Preserve this exact token and its immutable resources until the same attach epoch
            // becomes submit-capable; treating that bounded lifecycle gap as a present failure
            // loses the only first-pixel demand and leaves the surface permanently hidden.
            val handler = synchronized(stateLock) {
                pendingFrameCommits[submission.token]?.takeIf { pending ->
                    pending.surfaceControlSubmission &&
                        pending.nativeSurfaceEpoch == submission.attachEpoch &&
                        rollingNativeHandle == submission.handle &&
                        rollingNativeAttachEpoch == submission.attachEpoch &&
                        !rollingNativeFatal && directSurfaceReady
                }?.let { frameSyncedGeometryCommitHandler ?: directRenderHandler }
            }
            if (handler == null || !handler.postDelayed(submission, 4L)
            ) {
                val producerSceneId = submission.producerSceneId
                val token = submission.token
                directRenderHandler?.post {
                    clearNativeProducerScene(producerSceneId)
                }
                finishDeferredNativeSceneSubmission(submission)
                onNtkRollingFrameDropped(
                    token,
                    NATIVE_FRAME_DROP_PRESENT_FAILED,
                )
            }
            return
        }
        val packed = packDeferredNativeScene(submission)
        if (packed == null) {
            val producerSceneId = submission.producerSceneId
            val token = submission.token
            directRenderHandler?.post {
                clearNativeProducerScene(producerSceneId)
            }
            finishDeferredNativeSceneSubmission(submission)
            onNtkRollingFrameDropped(token, NATIVE_FRAME_DROP_PRESENT_FAILED)
            return
        }
        val packet = packed.packet
        val bitmapCount = packed.bitmapCount
        var overtaken = false
        val result = nativeSubmitOrderLock.withLock {
            if (submission.token < latestSynchronousNativeSubmitToken) {
                // Cold attach retries are posted with a small delay. A newer immutable scene can
                // become submit-capable during that delay, so never enqueue this older scene
                // behind it and roll the native FIFO/presentation proof back in time.
                overtaken = true
                0L
            } else {
                runCatching {
                    NtkRollingNativeBridge.nativeSubmit(
                        submission.handle,
                        submission.token,
                        submission.structureEpoch,
                        submission.width,
                        submission.height,
                        submission.viewportSourceTop,
                        submission.viewportSourceHeight,
                        submission.frameTimelineVsyncId,
                        submission.expectedPresentationTimeNanos,
                        submission.requiresGpuCompletionProof,
                        submission.producerSceneId,
                        bitmapCount,
                        packet.tileData,
                        packet.geometryData,
                        packet.resources,
                    ).also { submitResult ->
                        if (submitResult >= 0L) {
                            latestSynchronousNativeSubmitToken = submission.token
                        }
                    }
                }.getOrDefault(-1L)
            }
        }
        val terminalProducerSceneId = submission.producerSceneId
        val transientBackpressure =
            NtkNativeSubmitResultPolicy.isTransientBackpressure(result)
        if (overtaken) {
            directRenderHandler?.post {
                clearNativeProducerScene(terminalProducerSceneId)
            }
        } else if (result < 0L) {
            var recycledResources = 0
            for (index in 0 until bitmapCount) {
                if ((packet.resources[index] as? Bitmap)?.isRecycled == true) {
                    recycledResources++
                }
            }
            val message =
                "reader_deferred_native_scene_${if (transientBackpressure) {
                    "backpressured"
                } else {
                    "rejected"
                }} token=${submission.token},attach=${submission.attachEpoch}," +
                    "tiles=$bitmapCount,recycled=$recycledResources"
            if (transientBackpressure) Log.d(TAG, message) else Log.e(TAG, message)
            directRenderHandler?.post {
                clearNativeProducerScene(terminalProducerSceneId)
            }
        } else {
            noteFirstNativeSubmitAccepted(submission.token)
        }
        val terminalToken = submission.token
        releaseDeferredNativeScenePacket(packet, bitmapCount)
        if (overtaken) {
            retireDeferredNativeGeometryAsSuperseded(terminalToken)
        } else if (transientBackpressure) {
            retryDeferredNativeSubmissionAfterTransientBackpressure(terminalToken)
        } else if (NtkNativeSubmitResultPolicy.isTerminalFailure(result)) {
            onNtkRollingFrameDropped(terminalToken, NATIVE_FRAME_DROP_PRESENT_FAILED)
        } else if (result > 0L) {
            retireDeferredNativeGeometryAsSuperseded(result)
        }
        finishDeferredNativeSceneSubmission(submission)
    }

    private fun finishDeferredNativeSceneSubmission(
        submission: DeferredNativeSceneSubmission,
    ) {
        val commandsBefore = deferredNativeCommandsInFlight.getAndDecrement()
        check(commandsBefore > 0) { "Deferred scene did not own native command admission" }
        if (commandsBefore == 1) postNativeMailboxAdmissionWake()
        releaseNativeFrameCaptureLease()
        releaseDeferredNativeSceneSubmission(submission)
        // Scheduling retirement is not part of frame production. Return it asynchronously to the
        // state owner so releasing a lease can never wait behind page/source installation.
        mainHandler.post {
            synchronized(stateLock) {
                scheduleRollingAuthoritativeRecycleLocked()
                stateLock.notifyAll()
            }
        }
    }

    private fun releaseNativeFrameCaptureLease() {
        val before = deferredNativeSceneSubmissionsInFlight.getAndDecrement()
        check(before > 0) {
            "Native frame completion did not own a capture lease"
        }
    }

    private fun executeDeferredNativeGeometrySubmission(
        submission: DeferredNativeGeometrySubmission,
    ) {
        val stillCurrent = synchronized(stateLock) {
            pendingFrameCommits[submission.token]?.let { pending ->
                pending.surfaceControlSubmission &&
                    pending.nativeSurfaceEpoch == submission.attachEpoch &&
                    rollingNativeHandle == submission.handle &&
                    rollingNativeAttachEpoch == submission.attachEpoch &&
                    !rollingNativeFatal && directSurfaceReady
            } == true
        }
        if (!stillCurrent) return
        var overtaken = false
        val result = nativeSubmitOrderLock.withLock {
            if (submission.token < latestSynchronousNativeSubmitToken) {
                overtaken = true
                0L
            } else {
                runCatching {
                    NtkRollingNativeBridge.nativeSubmitProducerGeometry(
                        submission.handle,
                        submission.producerSceneId,
                        submission.token,
                        submission.structureEpoch,
                        submission.width,
                        submission.height,
                        submission.viewportSourceTop,
                        submission.viewportSourceHeight,
                        submission.producerSceneTranslationY,
                        submission.frameTimelineVsyncId,
                        submission.expectedPresentationTimeNanos,
                        submission.requiresGpuCompletionProof,
                    ).also { submitResult ->
                        if (submitResult >= 0L) {
                            latestSynchronousNativeSubmitToken = submission.token
                        }
                    }
                }.getOrDefault(-1L)
            }
        }
        if (overtaken) {
            retireDeferredNativeGeometryAsSuperseded(submission.token)
        } else if (NtkNativeSubmitResultPolicy.isTransientBackpressure(result)) {
            retryDeferredNativeSubmissionAfterTransientBackpressure(submission.token)
        } else if (NtkNativeSubmitResultPolicy.isTerminalFailure(result)) {
            onNtkRollingFrameDropped(submission.token, NATIVE_FRAME_DROP_PRESENT_FAILED)
        } else if (result > 0L) {
            retireDeferredNativeGeometryAsSuperseded(result)
        } else {
            noteFirstNativeSubmitAccepted(submission.token)
        }
    }

    /**
     * A -2 result means native accepted no frame and retained the preceding visible buffer. The
     * immutable Kotlin proof therefore owns no presentation failure; retire only that unsubmitted
     * token and preserve its dirty version for the ordinary bounded retry after mailbox capacity
     * returns. This is the deferred equivalent of finishRenderedFrame's synchronous rejection
     * branch.
     */
    private fun retryDeferredNativeSubmissionAfterTransientBackpressure(token: Long) {
        if (token <= 0L) return
        synchronized(stateLock) {
            val rejected = pendingFrameCommits.remove(token) ?: return
            earlyNativeOutcomes.remove(token)
            earlyFrameSyncedGeometryRequests.remove(token)
            frameSyncedGeometryInFlightTokens.remove(token)
            frameSyncedGeometrySubmissionOrder.remove(token)
            directActiveBandNativeFollowupTokens.remove(token)
            drawnVersion = latestSubmittedVersionLocked()
            if (rejected.frameEpoch == lifecycleEpoch && pages.isNotEmpty()) {
                renderRequested = true
                scheduleNoStateRetryLocked()
            }
            stateLock.notifyAll()
        }
    }

    private fun retireDeferredNativeGeometryAsSuperseded(token: Long) {
        if (token <= 0L) return
        synchronized(stateLock) {
            if (pendingFrameCommits.remove(token) != null) {
                nativeMailboxSupersededRetirements++
            }
            earlyNativeOutcomes.remove(token)
            earlyFrameSyncedGeometryRequests.remove(token)
            frameSyncedGeometryInFlightTokens.remove(token)
            frameSyncedGeometrySubmissionOrder.remove(token)
            stateLock.notifyAll()
        }
    }

    /**
     * Publishes only real, identity-bound pixels to the rolling native renderer. A rejected or
     * incomplete state leaves the preceding SurfaceControl buffer on screen and is retried; it
     * can never replace the screen with a placeholder/blank transaction.
     */
    private fun requiresSharedFrontGpuCompletionProof(
        state: DrawState,
        cleanPixels: Boolean,
    ): Boolean {
        if (!cleanPixels || state.height <= 0) return false
        var episodeKey: ExactEpisodeTailKey? = null
        var exactTailBottomReached = false
        val viewportBottom = state.height.toFloat()
        for (item in state.items) {
            val itemTop = viewportItemTop(state, item)
            if (!(itemTop < viewportBottom && itemTop + item.pageHeight > 0f)) continue
            if (item.cardText != null) return false
            val identity = item.committedIdentity ?: return false
            val key = exactEpisodeTailKey(identity) ?: return false
            if (episodeKey == null) {
                episodeKey = key
            } else if (episodeKey != key) {
                return false
            }
            if (identity.sourcePageIndex == identity.manifestPageCount - 1 &&
                itemTop + item.pageHeight <= viewportBottom + BOUNDARY_EPSILON_PX
            ) {
                exactTailBottomReached = true
            }
        }
        // Ordinary shared-front frames use producer hand-off evidence, matching BufferQueue swap
        // return semantics. Only the exact episode-tail frame that authorizes a chapter crossing
        // waits for GPU completion, so a fast next DOWN can never overtake its visible pixels.
        return episodeKey != null && exactTailBottomReached
    }

    private fun nativePageBitmap(item: DrawItem): Bitmap? =
        if (item.cardText != null) {
            item.nativeCardBitmap?.takeUnless(Bitmap::isRecycled) ?: item.cardBitmap
        } else {
            item.bitmap
        }

    private fun nativePageSourceWidth(item: DrawItem, resource: Bitmap): Int =
        if (item.cardText != null) item.sourceWidth else resource.width

    private fun nativePageSourceHeight(item: DrawItem, resource: Bitmap): Int =
        if (item.cardText != null) item.sourceHeight else resource.height

    /**
     * The host direct-tile presenter cannot sample the software-only structural-card bitmap. Its
     * immutable hardware twin is prepared off-main because allocation/copy can enter gfxstream.
     * Until that exact twin is published, reject the new frame before JNI so SurfaceControl keeps
     * the preceding complete buffer. Treating the software bitmap as a direct tile instead makes
     * an ordinary asynchronous hand-off look like permanent source corruption and fatally tears
     * down the renderer.
     */
    private fun nativeItemPixelsReadyForSubmission(
        item: DrawItem,
        directTiles: Boolean,
    ): Boolean {
        if (item.cardText != null) {
            val nativeCard = item.nativeCardBitmap
            return nativeCard != null && !nativeCard.isRecycled &&
                HostExactHardwareTilePool.nativeHandle(nativeCard) != 0L
        }
        if (!directTiles) return true
        val pageBitmap = item.bitmap
        return if (pageBitmap != null) {
            !pageBitmap.isRecycled && HostExactHardwareTilePool.nativeHandle(pageBitmap) != 0L
        } else {
            item.tiles.isEmpty() || item.tiles.none { tile ->
                tile.bitmap.isRecycled ||
                    HostExactHardwareTilePool.nativeHandle(tile.bitmap) == 0L
            }
        }
    }

    /**
     * A fixed native band intentionally spans several viewports, but a delayed mirror for pixels
     * thousands of pixels behind the crop must not veto the currently complete viewport. Omit only
     * non-native items that are safely outside the physical crop (including a conservative logical
     * guard for native scaling/rounding). They re-enter through normal page invalidation before a
     * reverse gesture can expose them. Returning the original immutable list keeps the hot path
     * allocation-free for the ordinary fully-ready case.
     */
    private fun nativeItemsReadyForCurrentFrame(state: DrawState): List<DrawItem> {
        val nativeItems = state.nativeBandItems.ifEmpty { state.items }
        if (!HostExactHardwareTilePool.supported(emulatorNativeSurfaceRuntime) ||
            nativeItems.isEmpty()
        ) return nativeItems
        val directTiles = state.nativeSubmissionSnapshot?.filterDirectWifiNativeTiles == true
        val guard = NATIVE_STRUCTURAL_CROP_GUARD_PX
        val hasSafelyOffscreenUnreadyItem = nativeItems.any { item ->
            if (nativeItemPixelsReadyForSubmission(item, directTiles)) return@any false
            val top = viewportItemTop(state, item)
            top >= state.height.toFloat() + guard || top + item.pageHeight <= -guard
        }
        if (!hasSafelyOffscreenUnreadyItem) return nativeItems
        return nativeItems.filterNot { item ->
            if (nativeItemPixelsReadyForSubmission(item, directTiles)) return@filterNot false
            val top = viewportItemTop(state, item)
            top >= state.height.toFloat() + guard || top + item.pageHeight <= -guard
        }
    }

    private fun nativeStructuralPixelsReady(
        state: DrawState,
        nativeItems: List<DrawItem>,
    ): Boolean {
        if (!HostExactHardwareTilePool.supported(emulatorNativeSurfaceRuntime)) return true
        val directTiles = state.nativeSubmissionSnapshot?.filterDirectWifiNativeTiles == true
        return nativeItems.all { item -> nativeItemPixelsReadyForSubmission(item, directTiles) }
    }

    private fun nativeStructuralUnreadyDiagnostic(
        state: DrawState,
        nativeItems: List<DrawItem>,
    ): String {
        if (!HostExactHardwareTilePool.supported(emulatorNativeSurfaceRuntime)) return "unsupported"
        val directTiles = state.nativeSubmissionSnapshot?.filterDirectWifiNativeTiles == true
        return nativeItems.mapNotNull { item ->
            if (item.cardText != null) {
                val token = item.nativeCardBitmap
                if (token == null || token.isRecycled ||
                    HostExactHardwareTilePool.nativeHandle(token) == 0L
                ) {
                    "${item.index}:card/${token != null}/${token?.isRecycled == true}"
                } else {
                    null
                }
            } else if (directTiles) {
                val pageBitmap = item.bitmap
                if (pageBitmap != null) {
                    if (pageBitmap.isRecycled ||
                        HostExactHardwareTilePool.nativeHandle(pageBitmap) == 0L
                    ) {
                        "${item.index}:bitmap/${pageBitmap.isRecycled}"
                    } else {
                        null
                    }
                } else {
                    val invalidTiles = item.tiles.count { tile ->
                        tile.bitmap.isRecycled ||
                            HostExactHardwareTilePool.nativeHandle(tile.bitmap) == 0L
                    }
                    if (invalidTiles > 0) {
                        "${item.index}:tiles=$invalidTiles/${item.tiles.size}"
                    } else {
                        null
                    }
                }
            } else {
                null
            }
        }.joinToString("|").ifEmpty { "none" }
    }

    private fun submitNativeFrame(
        frameTimeNs: Long,
        callbackStartNs: Long,
        state: DrawState,
        work: RenderWork,
        frameTimelineVsyncId: Long,
        expectedPresentationTimeNanos: Long,
    ): DrawTiming {
        val submitBeginNs = System.nanoTime()
        val nativeItems = nativeItemsReadyForCurrentFrame(state)
        val coverage = state.coverageSnapshot ?: coverageStats(state)
        val cleanPixels = state.hasDrawableContent && state.visibleLoading == 0 &&
            coverage.missingPx == 0 && coverage.placeholderPx == 0 &&
            coverage.lowResolutionItems == 0 && coverage.drawableItems > 0 &&
            nativeStructuralPixelsReady(state, nativeItems)
        val requiresGpuCompletionProof = state.requiresSharedFrontGpuCompletionProof ||
            (state.coverageSnapshot == null &&
                requiresSharedFrontGpuCompletionProof(state, cleanPixels))
        val coverageReadyNs = System.nanoTime()
        // buildDrawStateLocked already held stateLock while sealing the exact page/geometry epoch.
        // Reopening it here made an otherwise O(1) crop wait behind page installation and source
        // retirement. Native still validates this exact handle, attach epoch and producer scene.
        val nativeSnapshot = state.nativeSubmissionSnapshot
        val filterDirectWifiNativeTiles =
            nativeSnapshot?.filterDirectWifiNativeTiles == true
        val nativeHandleSnapshot = nativeSnapshot?.handle ?: 0L
        val nativeAttachEpochSnapshot = nativeSnapshot?.attachEpoch ?: 0L
        val nativeWidthSnapshot = nativeSnapshot?.width ?: 0
        val nativeHeightSnapshot = nativeSnapshot?.height ?: 0
        val nativeFatalSnapshot = nativeSnapshot?.fatal ?: false
        val nativeViewportWidthSnapshot = nativeSnapshot?.viewportWidth ?: 0
        val nativeViewportHeightSnapshot = nativeSnapshot?.viewportHeight ?: 0
        // The SurfaceControl parent remains display-sized. Geometry is expressed in the smaller
        // source-native render target and the child layer is scaled once at composition time.
        val nativeWidth = nativeWidthSnapshot
        val nativeHeight = nativeHeightSnapshot
        val native = if (nativeHandleSnapshot != 0L && nativeAttachEpochSnapshot > 0L &&
            nativeWidth > 0 && nativeHeight > 0 && !nativeFatalSnapshot &&
            nativeViewportWidthSnapshot == state.width &&
            nativeViewportHeightSnapshot == state.height
        ) {
            nativeHandleSnapshot
        } else {
            0L
        }
        val geometryScaleY = if (native != 0L && state.width > 0) {
            nativeWidth.toFloat() / state.width.toFloat()
        } else {
            1f
        }
        val nativeViewportSourceHeight = if (native != 0L) {
            (state.height.toFloat() * geometryScaleY).roundToInt()
                .coerceIn(1, nativeHeight)
        } else {
            state.height
        }
        val nativeViewportSourceTop = if (native != 0L) {
            ((state.scrollOffset - state.nativeBandOrigin) * geometryScaleY).roundToInt()
                .coerceIn(0, max(0, nativeHeight - nativeViewportSourceHeight))
        } else {
            0
        }
        val framebufferViewHeight = if (geometryScaleY > 0f) {
            nativeHeight.toFloat() / geometryScaleY
        } else {
            state.height.toFloat()
        }
        val nativeBandViewHeight = state.retainedNativeBandHeight
            .takeIf { it > 0f } ?: framebufferViewHeight
        // A retained rolling target is anchored at [nativeBandOrigin].  Coverage remains
        // viewport-relative through DrawState.viewportItemTopOffset, but the immutable producer
        // scene itself must stay band-relative.  Mixing the moving viewport offset into the
        // scene made every short page/tile membership boundary rebuild the entire 32 MiB target.
        // Keep its page geometry fixed and move only viewportSourceTop until the band step turns.
        val nativeSceneItemTopOffset = if (state.retainedNativeBandHeight > 0f) {
            0f
        } else {
            state.viewportItemTopOffset
        }
        val producerSceneTranslationY = if (cleanPixels && native != 0L) {
            nativeProducerSceneTranslationForState(
                handle = native,
                attachEpoch = nativeAttachEpochSnapshot,
                width = nativeWidth,
                height = nativeHeight,
                nativeItems = nativeItems,
                nativeBandViewHeight = nativeBandViewHeight,
                viewportItemTopOffset = nativeSceneItemTopOffset,
                geometryScaleY = geometryScaleY,
                filterDirectWifiNativeTiles = filterDirectWifiNativeTiles,
            )
        } else {
            null
        }
        val reuseProducerScene = producerSceneTranslationY != null
        val deferFullScenePreparation = cleanPixels && !reuseProducerScene && native != 0L &&
            emulatorNativeSurfaceRuntime
        val sceneProofReadyNs = System.nanoTime()
        var requiredTileCount = 0
        if (cleanPixels && !reuseProducerScene && !deferFullScenePreparation) {
            for (item in nativeItems) {
                val itemTop = item.top - nativeSceneItemTopOffset
                if (itemTop >= nativeBandViewHeight || itemTop + item.pageHeight <= 0f) continue
                val pageBitmap = nativePageBitmap(item)
                if (pageBitmap != null && !pageBitmap.isRecycled) {
                    requiredTileCount++
                } else {
                    for (tile in item.tiles) {
                        val bitmap = tile.bitmap
                        if (bitmap.isRecycled) continue
                        if (filterDirectWifiNativeTiles &&
                            !nativeTileIntersectsViewport(
                                item = item,
                                tile = tile,
                                geometryScaleY = geometryScaleY,
                                nativeHeight = nativeHeight,
                                viewportItemTopOffset = nativeSceneItemTopOffset,
                            )
                        ) continue
                        requiredTileCount++
                    }
                }
            }
        }
        ensureNativeFrameScratchCapacity(requiredTileCount)
        var bitmapCount = if (reuseProducerScene) nativeProducerSceneTileCount else 0
        if (cleanPixels && requiredTileCount > 0 && !reuseProducerScene) {
            for (item in nativeItems) {
                val itemTop = item.top - nativeSceneItemTopOffset
                if (itemTop >= nativeBandViewHeight || itemTop + item.pageHeight <= 0f) continue
                val pageTop = (item.top - nativeSceneItemTopOffset) * geometryScaleY
                val pageBitmap = nativePageBitmap(item)
                if (pageBitmap != null && !pageBitmap.isRecycled) {
                    val pageSourceWidth = nativePageSourceWidth(item, pageBitmap)
                    val pageSourceHeight = nativePageSourceHeight(item, pageBitmap)
                    packNativeFrameTile(
                        bitmapCount++, item.index, 0, 0, pageSourceHeight,
                        pageSourceWidth, pageSourceHeight, pageBitmap,
                        if (item.cardText != null) null else item.committedIdentity,
                        pageTop, item.pageHeight * geometryScaleY,
                    )
                } else {
                    for (slot in item.tiles.indices) {
                        val tile = item.tiles[slot]
                        val bitmap = tile.bitmap
                        if (bitmap.isRecycled) continue
                        if (filterDirectWifiNativeTiles &&
                            !nativeTileIntersectsViewport(
                                item = item,
                                tile = tile,
                                geometryScaleY = geometryScaleY,
                                nativeHeight = nativeHeight,
                                viewportItemTopOffset = nativeSceneItemTopOffset,
                            )
                        ) continue
                        packNativeFrameTile(
                            bitmapCount++, item.index, slot, tile.sourceTop, tile.sourceBottom,
                            tile.sourceWidth, tile.sourceHeight, bitmap,
                            item.committedIdentity,
                            pageTop, item.pageHeight * geometryScaleY,
                        )
                    }
                }
            }
        }
        val scenePackedNs = System.nanoTime()
        val cacheableProducerScene = !reuseProducerScene &&
            ((deferFullScenePreparation && nativeItems.isNotEmpty()) || bitmapCount > 0)
        // The SurfaceControl parent and the reader frame pipe intentionally have different
        // lifetimes. Page/session mutations advance frameEpoch without replacing the physical
        // Surface. Requiring attachEpoch == frameEpoch therefore rejected every frame following
        // the first content-state reset even though the attached Surface was still valid.
        val nativeSubmissionLease = if (reuseProducerScene) {
            // The cached native producer scene already owns its exact bitmap-ledger leases. A
            // geometry command transfers no Bitmap/resource ownership, so entering stateLock and
            // reopening the submit-to-retirement seam on every MOVE only adds contention with
            // page installation. Native validates the exact scene id and attachment atomically.
            work.nativeCaptureLease
        } else if (deferFullScenePreparation) {
            work.nativeCaptureLease
        } else if (cleanPixels && bitmapCount > 0 && native != 0L) {
            var retirementSafe = work.nativeCaptureLease
            for (index in 0 until bitmapCount) {
                val bitmap = nativeFrameBitmapScratch[index]
                val integerOffset = index * NATIVE_TILE_INT_STRIDE
                val sourceSpan = nativeFrameTileDataScratch[integerOffset + 3] -
                    nativeFrameTileDataScratch[integerOffset + 2]
                val sourceWidth = nativeFrameTileDataScratch[integerOffset + 4]
                val requiresExternalExactStorage = bitmap != null &&
                    (bitmap.width < sourceWidth || bitmap.height < sourceSpan)
                if (bitmap == null || bitmap.isRecycled ||
                    (requiresExternalExactStorage &&
                        nativeFrameTileDataScratch[integerOffset + 7] == 0)
                ) {
                    retirementSafe = false
                    break
                }
            }
            val eligibleBase = retirementSafe && !nativeFatalSnapshot &&
                nativeHandleSnapshot == native && nativeAttachEpochSnapshot > 0L
            if (eligibleBase && emulatorNativeSurfaceRuntime) {
                true
            } else if (eligibleBase) {
                synchronized(stateLock) {
                    val eligible = renderRunning && !rollingNativeFatal &&
                        rollingNativeHandle == native &&
                        rollingNativeAttachEpoch == nativeAttachEpochSnapshot &&
                    (!nativeFrameSubmissionInFlight &&
                            deferredNativeSceneSubmissionsInFlight.get() == 1)
                    if (eligible) nativeFrameSubmissionInFlight = true
                    eligible
                }
            } else {
                false
            }
        } else {
            false
        }
        val leaseReadyNs = System.nanoTime()
        val submittedProducerSceneId = when {
            reuseProducerScene -> nativeProducerSceneId
            cacheableProducerScene -> nextNativeProducerSceneId()
            else -> 0L
        }
        if (cacheableProducerScene && submittedProducerSceneId > 0L) {
            rememberActiveNativeBandCandidate(
                sceneId = submittedProducerSceneId,
                handle = native,
                attachEpoch = nativeAttachEpochSnapshot,
                structureEpoch = state.traversalEpoch,
                width = nativeWidth,
                height = nativeHeight,
                viewportSourceHeight = nativeViewportSourceHeight,
                bandOrigin = state.nativeBandOrigin,
                items = nativeItems,
            )
        }
        val deferredNativeScene = if (nativeSubmissionLease && !reuseProducerScene &&
            emulatorNativeSurfaceRuntime
        ) {
            if (cacheableProducerScene) {
                rememberPendingNativeProducerScene(
                    native,
                    nativeAttachEpochSnapshot,
                    nativeWidth,
                    nativeHeight,
                    submittedProducerSceneId,
                    nativeItems,
                    nativeBandViewHeight,
                    nativeSceneItemTopOffset,
                    filterDirectWifiNativeTiles,
                )
            }
            acquireDeferredNativeSceneSubmission(
                native,
                nativeAttachEpochSnapshot,
                submittedProducerSceneId,
                work.frameToken,
                state.traversalEpoch,
                nativeWidth,
                nativeHeight,
                nativeViewportSourceTop,
                nativeViewportSourceHeight,
                frameTimelineVsyncId,
                expectedPresentationTimeNanos,
                requiresGpuCompletionProof,
                nativeItems,
                nativeBandViewHeight,
                nativeSceneItemTopOffset,
                geometryScaleY,
                filterDirectWifiNativeTiles,
            )
        } else {
            null
        }
        // Host SurfaceFlinger legally merges position-only Java transactions for hundreds of
        // milliseconds. Geometry therefore stays on the native pulse-buffer path, which binds the
        // crop to real alternating buffer work and returns OnComplete present-fence evidence.
        val directActiveBandGeometry: FrameSyncedGeometryRequest? = null
        // The host path already proves that no earlier deferred command or native mailbox entry
        // can be pending before admitting this callback. Enqueue its O(1), buffer-free geometry
        // command directly from the producer so the following display deadline does not arrive
        // while a second Handler is merely forwarding the prior frame. Device renderers retain
        // the separate commit Looper because their native backend may synchronously enter EGL.
        val synchronousEmulatorNativeGeometry = nativeSubmissionLease && reuseProducerScene &&
            emulatorNativeSurfaceRuntime
        val deferredNativeGeometry = if (nativeSubmissionLease && reuseProducerScene &&
            !synchronousEmulatorNativeGeometry
        ) {
            acquireDeferredNativeGeometrySubmission(
                native,
                nativeAttachEpochSnapshot,
                submittedProducerSceneId,
                work.frameToken,
                state.traversalEpoch,
                nativeWidth,
                nativeHeight,
                nativeViewportSourceTop,
                nativeViewportSourceHeight,
                producerSceneTranslationY ?: 0f,
                frameTimelineVsyncId,
                expectedPresentationTimeNanos,
                requiresGpuCompletionProof,
            )
        } else {
            null
        }
        if (deferredNativeScene != null || deferredNativeGeometry != null) {
            deferredNativeGeometry?.ownsCommandAdmission = true
            deferredNativeCommandsInFlight.incrementAndGet()
        }
        val commandReadyNs = System.nanoTime()
        val nativeSubmitResult = if (deferredNativeScene != null || deferredNativeGeometry != null) {
            // The exact proof is registered before this immutable command is posted to the
            // dedicated commit Looper. No native mutex is entered from the display callback.
            0L
        } else if (synchronousEmulatorNativeGeometry) {
            try {
                if (!nativeSubmitOrderLock.tryLock()) {
                    // A deferred full-scene submission can hold the order fence while it copies
                    // exact resources into native ownership. Physical geometry is latest-only;
                    // never make the display callback wait behind that transfer. Returning
                    // transient rejection preserves the dirty coordinate and the ordinary
                    // no-state retry submits it after the scene owner releases the fence.
                    -2L
                } else {
                    try {
                        runCatching {
                            Trace.beginSection("ViewerSurfaceControlGeometrySubmission")
                            try {
                            NtkRollingNativeBridge.nativeSubmitProducerGeometry(
                                native,
                                submittedProducerSceneId,
                                work.frameToken,
                                state.traversalEpoch,
                                nativeWidth,
                                nativeHeight,
                                nativeViewportSourceTop,
                                nativeViewportSourceHeight,
                                producerSceneTranslationY ?: 0f,
                                frameTimelineVsyncId,
                                expectedPresentationTimeNanos,
                                requiresGpuCompletionProof,
                            ).also { submitResult ->
                                if (submitResult >= 0L) {
                                    latestSynchronousNativeSubmitToken = work.frameToken
                                }
                            }
                            } finally {
                                Trace.endSection()
                            }
                        }.getOrDefault(-1L)
                    } finally {
                        nativeSubmitOrderLock.unlock()
                    }
                }
            } finally {
                for (index in 0 until bitmapCount) {
                    nativeFrameBitmapScratch[index] = null
                    nativeFrameResourceScratch[index] = null
                }
                synchronized(stateLock) {
                    nativeFrameSubmissionInFlight = false
                    scheduleRollingAuthoritativeRecycleLocked()
                    stateLock.notifyAll()
                }
            }
        } else if (nativeSubmissionLease) {
            try {
                val result = runCatching {
                    Trace.beginSection("ViewerSurfaceControlSubmission")
                    try {
                        nativeSubmitOrderLock.withLock {
                            NtkRollingNativeBridge.nativeSubmit(
                                native,
                                work.frameToken,
                                state.traversalEpoch,
                                nativeWidth,
                                nativeHeight,
                                nativeViewportSourceTop,
                                nativeViewportSourceHeight,
                                frameTimelineVsyncId,
                                expectedPresentationTimeNanos,
                                requiresGpuCompletionProof,
                                submittedProducerSceneId,
                                bitmapCount,
                                nativeFrameTileDataScratch,
                                nativeFrameGeometryScratch,
                                nativeFrameResourceScratch,
                            ).also { submitResult ->
                                if (submitResult >= 0L) {
                                    latestSynchronousNativeSubmitToken = work.frameToken
                                }
                            }
                        }
                    } finally {
                        Trace.endSection()
                    }
                }.getOrDefault(-1L)
                if (result >= 0L && submittedProducerSceneId > 0L && !reuseProducerScene) {
                    rememberNativeProducerScene(
                        native,
                        nativeAttachEpochSnapshot,
                        nativeWidth,
                        nativeHeight,
                        submittedProducerSceneId,
                        bitmapCount,
                        nativeItems,
                        nativeBandViewHeight,
                        nativeSceneItemTopOffset,
                        filterDirectWifiNativeTiles,
                    )
                } else if (result < 0L && submittedProducerSceneId > 0L) {
                    clearNativeProducerScene()
                }
                result
            } finally {
                for (index in 0 until bitmapCount) {
                    nativeFrameBitmapScratch[index] = null
                    nativeFrameResourceScratch[index] = null
                }
                synchronized(stateLock) {
                    nativeFrameSubmissionInFlight = false
                    scheduleRollingAuthoritativeRecycleLocked()
                    stateLock.notifyAll()
                }
            }
        } else {
            for (index in 0 until bitmapCount) {
                nativeFrameBitmapScratch[index] = null
                nativeFrameResourceScratch[index] = null
            }
            -1L
        }
        val accepted = nativeSubmitResult >= 0L
        val diagnosticNowMs = SystemClock.uptimeMillis()
        val synchronouslyAccepted = accepted && deferredNativeScene == null &&
            deferredNativeGeometry == null
        if (synchronouslyAccepted && !firstNativeSubmitAccepted) {
            noteFirstNativeSubmitAccepted(work.frameToken)
            Log.i(
                TAG,
                    "reader_native_submit_first token=${work.frameToken} frameEpoch=${work.frameEpoch} " +
                    "attachEpoch=$nativeAttachEpochSnapshot tiles=$bitmapCount " +
                    "render=${nativeWidth}x$nativeHeight viewport=${state.width}x${state.height} " +
                    "traversal=${state.traversalEpoch}"
            )
        } else if (!accepted &&
            diagnosticNowMs - lastNativeSubmitDiagnosticLogMs >= NATIVE_SUBMIT_DIAGNOSTIC_INTERVAL_MS
        ) {
            lastNativeSubmitDiagnosticLogMs = diagnosticNowMs
            Log.d(
                TAG,
                "reader_native_submit_rejected token=${work.frameToken} frameEpoch=${work.frameEpoch} " +
                    "attachEpoch=$nativeAttachEpochSnapshot handle=${nativeHandleSnapshot != 0L} " +
                    "fatal=$nativeFatalSnapshot clean=$cleanPixels bitmaps=$bitmapCount " +
                    "structural=${nativeStructuralUnreadyDiagnostic(state, nativeItems)} " +
                    "coverage=$coverage nativeSize=${nativeWidthSnapshot}x${nativeHeightSnapshot} " +
                    "nativeViewport=${nativeViewportWidthSnapshot}x${nativeViewportHeightSnapshot} " +
                    "frameSize=${state.width}x${state.height}"
            )
        }
        if (work.nativeCaptureLease && deferredNativeScene == null) {
            releaseNativeFrameCaptureLease()
        }
        val submitEndNs = System.nanoTime()
        val submitElapsedNs = submitEndNs - submitBeginNs
        if (submitElapsedNs >= 50_000_000L ||
            (submitElapsedNs >= 16_000_000L &&
                Log.isLoggable("ReaderFrameGaps", Log.DEBUG))
        ) {
            Log.w(
                TAG,
                "reader_native_submit_stage_slow token=${work.frameToken}," +
                    "totalMs=${fmt(nsToMs(submitEndNs - submitBeginNs))}," +
                    "coverageMs=${fmt(nsToMs(coverageReadyNs - submitBeginNs))}," +
                    "sceneProofMs=${fmt(nsToMs(sceneProofReadyNs - coverageReadyNs))}," +
                    "packMs=${fmt(nsToMs(scenePackedNs - sceneProofReadyNs))}," +
                    "leaseMs=${fmt(nsToMs(leaseReadyNs - scenePackedNs))}," +
                    "commandMs=${fmt(nsToMs(commandReadyNs - leaseReadyNs))}," +
                    "submitMs=${fmt(nsToMs(submitEndNs - commandReadyNs))}," +
                    "reuse=$reuseProducerScene,deferredScene=${deferredNativeScene != null}," +
                    "deferredGeometry=${deferredNativeGeometry != null},tiles=$requiredTileCount",
            )
        }
        val mutation = work.mutation
        return DrawTiming(
            frameTimeNs = frameTimeNs,
            callbackStartNs = callbackStartNs,
            lockWaitMs = nsToMs(submitBeginNs - callbackStartNs),
            drawMs = nsToMs(submitEndNs - submitBeginNs),
            postMs = 0f,
            totalMs = nsToMs(submitEndNs - callbackStartNs),
            postEndNs = submitEndNs,
            posted = accepted,
            mutationWatermark = mutation?.watermark ?: 0L,
            mutationOldestToCallbackMs = causalPixelMutationAgeMs(
                mutation?.oldestNs ?: 0L,
                callbackStartNs
            ),
            mutationNewestToCallbackMs = causalPixelMutationAgeMs(
                mutation?.newestNs ?: 0L,
                callbackStartNs
            ),
            mutationOldestToPostMs = causalPixelMutationAgeMs(
                mutation?.oldestNs ?: 0L,
                submitEndNs
            ),
            mutationNewestToPostMs = causalPixelMutationAgeMs(
                mutation?.newestNs ?: 0L,
                submitEndNs
            ),
            nativeSurfaceEpoch = if (accepted) nativeAttachEpochSnapshot else 0L,
            nativeSupersededToken = nativeSubmitResult.coerceAtLeast(0L),
            deferredNativeScene = deferredNativeScene,
            deferredNativeGeometry = deferredNativeGeometry,
            directActiveBandGeometry = directActiveBandGeometry,
            directActiveBandNativeFollowup = deferredNativeScene != null,
            physicalGestureRevision = work.physicalGestureRevision,
            physicalMotionTraceCookie = work.physicalMotionTraceCookie,
            invalidationToCallbackMs = causalPixelMutationAgeMs(
                mutation?.invalidationPostedNs ?: 0L,
                callbackStartNs
            ),
            invalidationToPostMs = causalPixelMutationAgeMs(
                mutation?.invalidationPostedNs ?: 0L,
                submitEndNs
            )
        )
    }

    private fun noteFirstNativeSubmitAccepted(token: Long) {
        if (token <= 0L || firstNativeSubmitAccepted) return
        firstNativeSubmitAccepted = true
        Log.i(TAG, "reader_native_enqueue_first token=$token")
    }

    /** Direct-render-thread only; grows rarely and otherwise performs no allocation. */
    private fun ensureNativeFrameScratchCapacity(required: Int) {
        if (required <= nativeFrameBitmapScratch.size) return
        var capacity = max(NATIVE_FRAME_INITIAL_TILE_CAPACITY, nativeFrameBitmapScratch.size)
        while (capacity < required) capacity = capacity shl 1
        nativeFrameTileDataScratch = IntArray(capacity * NATIVE_TILE_INT_STRIDE)
        nativeFrameGeometryScratch = FloatArray(capacity * 2)
        nativeFrameBitmapScratch = arrayOfNulls(capacity)
        nativeFrameResourceScratch = arrayOfNulls(capacity)
    }

    private fun acquireDeferredNativeSceneSubmission(
        handle: Long,
        attachEpoch: Long,
        producerSceneId: Long,
        token: Long,
        structureEpoch: Long,
        width: Int,
        height: Int,
        viewportSourceTop: Int,
        viewportSourceHeight: Int,
        frameTimelineVsyncId: Long,
        expectedPresentationTimeNanos: Long,
        requiresGpuCompletionProof: Boolean,
        nativeItems: List<DrawItem>,
        nativeBandViewHeight: Float,
        viewportItemTopOffset: Float,
        geometryScaleY: Float,
        filterDirectWifiNativeTiles: Boolean,
    ): DeferredNativeSceneSubmission {
        var submission: DeferredNativeSceneSubmission? = null
        while (true) {
            val head = deferredNativeSceneSubmissionPool.get() ?: break
            val next = head.poolNext
            if (deferredNativeSceneSubmissionPool.compareAndSet(head, next)) {
                head.poolNext = null
                deferredNativeSceneSubmissionPoolSize.decrementAndGet()
                submission = head
                break
            }
        }
        return (submission ?: DeferredNativeSceneSubmission()).configure(
            handle,
            attachEpoch,
            producerSceneId,
            token,
            structureEpoch,
            width,
            height,
            viewportSourceTop,
            viewportSourceHeight,
            frameTimelineVsyncId,
            expectedPresentationTimeNanos,
            requiresGpuCompletionProof,
            nativeItems,
            nativeBandViewHeight,
            viewportItemTopOffset,
            geometryScaleY,
            filterDirectWifiNativeTiles,
        )
    }

    private fun releaseDeferredNativeSceneSubmission(
        submission: DeferredNativeSceneSubmission,
    ) {
        submission.nativeItems = emptyList()
        submission.viewportItemTopOffset = 0f
        while (true) {
            val size = deferredNativeSceneSubmissionPoolSize.get()
            if (size >= MAX_DEFERRED_NATIVE_SCENE_SUBMISSION_POOL) return
            if (deferredNativeSceneSubmissionPoolSize.compareAndSet(size, size + 1)) break
        }
        while (true) {
            val head = deferredNativeSceneSubmissionPool.get()
            submission.poolNext = head
            if (deferredNativeSceneSubmissionPool.compareAndSet(head, submission)) return
        }
    }

    private fun primeDeferredNativeSceneSubmissionPool() {
        while (deferredNativeSceneSubmissionPoolSize.get() <
            MAX_DEFERRED_NATIVE_SCENE_SUBMISSION_POOL
        ) {
            releaseDeferredNativeSceneSubmission(DeferredNativeSceneSubmission())
        }
    }

    private fun acquireDeferredNativeScenePacket(required: Int): DeferredNativeScenePacket {
        val packet = synchronized(deferredNativeScenePacketPoolLock) {
            deferredNativeScenePacketPool.pollFirst()
        } ?: DeferredNativeScenePacket(max(NATIVE_FRAME_INITIAL_TILE_CAPACITY, required))
        packet.ensureCapacity(required)
        return packet
    }

    private fun acquireDeferredNativeGeometrySubmission(
        handle: Long,
        attachEpoch: Long,
        producerSceneId: Long,
        token: Long,
        structureEpoch: Long,
        width: Int,
        height: Int,
        viewportSourceTop: Int,
        viewportSourceHeight: Int,
        producerSceneTranslationY: Float,
        frameTimelineVsyncId: Long,
        expectedPresentationTimeNanos: Long,
        requiresGpuCompletionProof: Boolean,
    ): DeferredNativeGeometrySubmission {
        var submission: DeferredNativeGeometrySubmission? = null
        while (true) {
            val head = deferredNativeGeometryPool.get() ?: break
            val next = head.poolNext
            if (deferredNativeGeometryPool.compareAndSet(head, next)) {
                head.poolNext = null
                deferredNativeGeometryPoolSize.decrementAndGet()
                submission = head
                break
            }
        }
        val owned = submission ?: DeferredNativeGeometrySubmission()
        return owned.configure(
            handle,
            attachEpoch,
            producerSceneId,
            token,
            structureEpoch,
            width,
            height,
            viewportSourceTop,
            viewportSourceHeight,
            producerSceneTranslationY,
            frameTimelineVsyncId,
            expectedPresentationTimeNanos,
            requiresGpuCompletionProof,
        )
    }

    private fun releaseDeferredNativeGeometrySubmission(
        submission: DeferredNativeGeometrySubmission,
    ) {
        if (submission.ownsCommandAdmission) {
            submission.ownsCommandAdmission = false
            val commandsBefore = deferredNativeCommandsInFlight.getAndDecrement()
            check(commandsBefore > 0) {
                "Deferred geometry did not own native command admission"
            }
            if (commandsBefore == 1) postNativeMailboxAdmissionWake()
        }
        while (true) {
            val size = deferredNativeGeometryPoolSize.get()
            if (size >= MAX_DEFERRED_NATIVE_GEOMETRY_POOL) return
            if (deferredNativeGeometryPoolSize.compareAndSet(size, size + 1)) break
        }
        while (true) {
            val head = deferredNativeGeometryPool.get()
            submission.poolNext = head
            if (deferredNativeGeometryPool.compareAndSet(head, submission)) return
        }
    }

    private fun primeDeferredNativeGeometryPool() {
        while (deferredNativeGeometryPoolSize.get() < MAX_DEFERRED_NATIVE_GEOMETRY_POOL) {
            releaseDeferredNativeGeometrySubmission(DeferredNativeGeometrySubmission())
        }
    }

    private val nativeMailboxAdmissionWakeRunnable = Runnable {
        nativeMailboxAdmissionWakePosted.set(false)
        synchronized(stateLock) {
            if (renderRunning && directSurfaceReady && !rollingNativeFatal &&
                framePipe == FramePipe.INVALIDATION_POSTED && inFlightToken != 0L &&
                !directFrameCallbackPosted
            ) {
                postDirectFrameCallbackLocked()
            }
        }
    }

    /**
     * The final posted command leaving the Kotlin handoff lane is a capacity edge. It wakes only
     * an already-reserved proof token; native presentation remains the second capacity edge when
     * the command was accepted but is still queued.
     */
    private fun postNativeMailboxAdmissionWake() {
        if (!nativeMailboxAdmissionWakePosted.compareAndSet(false, true)) return
        val handler = directRenderHandler
        if (handler == null || !handler.post(nativeMailboxAdmissionWakeRunnable)) {
            nativeMailboxAdmissionWakePosted.set(false)
        }
    }

    /** Commit-lane preparation of a full immutable scene; never runs on the physical producer. */
    private fun packDeferredNativeScene(
        submission: DeferredNativeSceneSubmission,
    ): PackedDeferredNativeScene? {
        var required = 0
        for (item in submission.nativeItems) {
            val itemTop = item.top - submission.viewportItemTopOffset
            if (itemTop >= submission.nativeBandViewHeight ||
                itemTop + item.pageHeight <= 0f
            ) continue
            val pageBitmap = nativePageBitmap(item)
            if (pageBitmap != null && !pageBitmap.isRecycled) {
                required++
            } else {
                for (tile in item.tiles) {
                    if (tile.bitmap.isRecycled) continue
                    if (submission.filterDirectWifiNativeTiles &&
                        !nativeTileIntersectsViewport(
                            item,
                            tile,
                            submission.geometryScaleY,
                            submission.height,
                            submission.viewportItemTopOffset,
                        )
                    ) continue
                    required++
                }
            }
        }
        if (required <= 0) return null
        val packet = acquireDeferredNativeScenePacket(required)
        var ordinal = 0
        for (item in submission.nativeItems) {
            val itemTop = item.top - submission.viewportItemTopOffset
            if (itemTop >= submission.nativeBandViewHeight ||
                itemTop + item.pageHeight <= 0f
            ) continue
            val pageTop = (item.top - submission.viewportItemTopOffset) *
                submission.geometryScaleY
            val pageHeight = item.pageHeight * submission.geometryScaleY
            val pageBitmap = nativePageBitmap(item)
            if (pageBitmap != null && !pageBitmap.isRecycled) {
                val pageSourceWidth = nativePageSourceWidth(item, pageBitmap)
                val pageSourceHeight = nativePageSourceHeight(item, pageBitmap)
                if (!packNativeFrameTileInto(
                        packet.tileData,
                        packet.geometryData,
                        packet.resources,
                        ordinal++,
                        item.index,
                        0,
                        0,
                        pageSourceHeight,
                        pageSourceWidth,
                        pageSourceHeight,
                        pageBitmap,
                        if (item.cardText != null) null else item.committedIdentity,
                        pageTop,
                        pageHeight,
                    )
                ) {
                    releaseDeferredNativeScenePacket(packet, ordinal)
                    return null
                }
            } else {
                for (slot in item.tiles.indices) {
                    val tile = item.tiles[slot]
                    val bitmap = tile.bitmap
                    if (bitmap.isRecycled) continue
                    if (submission.filterDirectWifiNativeTiles &&
                        !nativeTileIntersectsViewport(
                            item,
                            tile,
                            submission.geometryScaleY,
                            submission.height,
                            submission.viewportItemTopOffset,
                        )
                    ) continue
                    if (!packNativeFrameTileInto(
                            packet.tileData,
                            packet.geometryData,
                            packet.resources,
                            ordinal++,
                            item.index,
                            slot,
                            tile.sourceTop,
                            tile.sourceBottom,
                            tile.sourceWidth,
                            tile.sourceHeight,
                            bitmap,
                            item.committedIdentity,
                            pageTop,
                            pageHeight,
                        )
                    ) {
                        releaseDeferredNativeScenePacket(packet, ordinal)
                        return null
                    }
                }
            }
        }
        return if (ordinal > 0) {
            PackedDeferredNativeScene(packet, ordinal)
        } else {
            releaseDeferredNativeScenePacket(packet, 0)
            null
        }
    }

    private fun releaseDeferredNativeScenePacket(
        packet: DeferredNativeScenePacket,
        bitmapCount: Int,
    ) {
        packet.clearResources(bitmapCount)
        synchronized(deferredNativeScenePacketPoolLock) {
            if (deferredNativeScenePacketPool.size < MAX_DEFERRED_NATIVE_SCENE_PACKET_POOL) {
                deferredNativeScenePacketPool.addLast(packet)
            }
        }
    }

    /** Direct-render-thread only; scene ids never repeat within this View lifetime. */
    private fun nextNativeProducerSceneId(): Long {
        nativeProducerSceneSequence =
            if (nativeProducerSceneSequence == Long.MAX_VALUE) 1L
            else nativeProducerSceneSequence + 1L
        return nativeProducerSceneSequence
    }

    private fun rememberActiveNativeBandCandidate(
        sceneId: Long,
        handle: Long,
        attachEpoch: Long,
        structureEpoch: Long,
        width: Int,
        height: Int,
        viewportSourceHeight: Int,
        bandOrigin: Float,
        items: List<DrawItem>,
    ) {
        if (sceneId <= 0L || handle == 0L || attachEpoch <= 0L || structureEpoch <= 0L ||
            width <= 0 || height <= 0 || viewportSourceHeight <= 0 || items.isEmpty()
        ) return
        synchronized(activeNativeBandCandidateLock) {
            while (activeNativeBandCandidates.size >= MAX_ACTIVE_NATIVE_BAND_CANDIDATES) {
                activeNativeBandCandidates.entries.iterator().run {
                    if (hasNext()) {
                        next()
                        remove()
                    }
                }
            }
            activeNativeBandCandidates[sceneId] = ActiveNativeBandProof(
                sceneId = sceneId,
                handle = handle,
                attachEpoch = attachEpoch,
                structureEpoch = structureEpoch,
                width = width,
                height = height,
                viewportSourceHeight = viewportSourceHeight,
                bandOrigin = bandOrigin,
                items = items,
            )
        }
    }

    private fun sameActiveBandItemPixels(first: DrawItem, second: DrawItem): Boolean {
        if ((first.bitmap != null) != (second.bitmap != null) ||
            (first.cardBitmap != null) != (second.cardBitmap != null) ||
            first.nativeCardBitmap !== second.nativeCardBitmap ||
            first.sourceWidth != second.sourceWidth || first.sourceHeight != second.sourceHeight ||
            java.lang.Float.floatToRawIntBits(first.pageHeight) !=
                java.lang.Float.floatToRawIntBits(second.pageHeight) ||
            first.loading != second.loading || first.cardText != second.cardText ||
            first.errorText != second.errorText || first.tiles.size != second.tiles.size ||
            first.originalProof != second.originalProof ||
            first.stripAuthoritative != second.stripAuthoritative ||
            first.adjacentExactAuthoritative != second.adjacentExactAuthoritative ||
            first.stripAsset != second.stripAsset
        ) return false
        val firstIdentity = first.committedIdentity
        val secondIdentity = second.committedIdentity
        if (firstIdentity == null || secondIdentity == null ||
            firstIdentity.normalizedEpisodePath != secondIdentity.normalizedEpisodePath ||
            firstIdentity.sourcePageIndex != secondIdentity.sourcePageIndex ||
            firstIdentity.canonicalAsset != secondIdentity.canonicalAsset ||
            firstIdentity.manifestDigest != secondIdentity.manifestDigest ||
            firstIdentity.manifestPageCount != secondIdentity.manifestPageCount
        ) return false
        second.bitmap?.let { if (it.isRecycled) return false }
        second.cardBitmap?.let { if (it.isRecycled) return false }
        second.nativeCardBitmap?.let { if (it.isRecycled) return false }
        for (index in first.tiles.indices) {
            val left = first.tiles[index]
            val right = second.tiles[index]
            if (right.bitmap.isRecycled ||
                left.sourceTop != right.sourceTop || left.sourceBottom != right.sourceBottom ||
                left.sourceWidth != right.sourceWidth || left.sourceHeight != right.sourceHeight
            ) return false
        }
        return true
    }

    /** Returns a source crop only when the presented band exactly covers today's full viewport. */
    private fun activeNativeBandSourceTopForState(
        state: DrawState,
        handle: Long,
        attachEpoch: Long,
        nativeWidth: Int,
        nativeHeight: Int,
        viewportSourceHeight: Int,
        cleanPixels: Boolean,
    ): Int? {
        val active = activeNativeBandProof ?: return null
        if (!cleanPixels) return null
        if (active.handle != handle || active.attachEpoch != attachEpoch ||
            active.width != nativeWidth ||
            active.height != nativeHeight ||
            active.viewportSourceHeight != viewportSourceHeight
        ) return null
        if (state.nativeBandItems.isEmpty() || state.width <= 0 || state.height <= 0) {
            return null
        }
        val scaleY = nativeWidth.toFloat() / state.width.toFloat()
        val sourceTopFloat = (state.scrollOffset - active.bandOrigin) * scaleY
        if (!sourceTopFloat.isFinite() || sourceTopFloat < 0f ||
            sourceTopFloat > nativeHeight - viewportSourceHeight
        ) return null

        val viewportTop = state.scrollOffset
        val viewportBottom = viewportTop + state.height.toFloat()
        var currentVisibleCount = 0
        for (current in state.nativeBandItems) {
            val currentAbsoluteTop = state.nativeBandOrigin + current.top
            val currentAbsoluteBottom = currentAbsoluteTop + current.pageHeight
            if (currentAbsoluteBottom <= viewportTop || currentAbsoluteTop >= viewportBottom) continue
            currentVisibleCount++
            var matched = false
            for (applied in active.items) {
                val appliedAbsoluteTop = active.bandOrigin + applied.top
                if (abs(appliedAbsoluteTop - currentAbsoluteTop) >
                    ACTIVE_NATIVE_BAND_GEOMETRY_EPSILON_PX
                ) continue
                if (sameActiveBandItemPixels(applied, current)) {
                    matched = true
                    break
                }
            }
            if (!matched) return null
        }
        if (currentVisibleCount <= 0) return null
        var activeVisibleCount = 0
        for (applied in active.items) {
            val top = active.bandOrigin + applied.top
            if (top + applied.pageHeight > viewportTop && top < viewportBottom) activeVisibleCount++
        }
        if (activeVisibleCount != currentVisibleCount) return null
        if (activeNativeBandProof === active) {
            activeNativeBandDirectValidatedSceneId = active.sceneId
            activeNativeBandDirectValidatedVisualGeneration = state.visualGeneration
            activeNativeBandDirectValidatedStructureEpoch = state.traversalEpoch
        }
        return sourceTopFloat.roundToInt().coerceIn(
            0,
            max(0, nativeHeight - viewportSourceHeight),
        )
    }

    /**
     * Collision-free producer proof: every packed scalar and the exact JVM token object must
     * match. Hash/content identities remain useful native cache keys but are never the sole reuse
     * authority for the geometry-only path.
     */
    private fun nativeProducerSceneTranslationForState(
        handle: Long,
        attachEpoch: Long,
        width: Int,
        height: Int,
        nativeItems: List<DrawItem>,
        nativeBandViewHeight: Float,
        viewportItemTopOffset: Float,
        geometryScaleY: Float,
        filterDirectWifiNativeTiles: Boolean,
    ): Float? {
        if (nativeProducerSceneId <= 0L || nativeProducerSceneHandle != handle ||
            nativeProducerSceneAttachEpoch != attachEpoch ||
            nativeProducerSceneWidth != width || nativeProducerSceneHeight != height
        ) return null
        // nativeBandItemsLocked returns the same immutable List instance until pixels, layout,
        // band origin, or structure changes. The reuse window was sealed while that exact scene
        // was captured and proves that no page/tile can enter or leave the packed band. Inside it,
        // reference identity plus the scalar offset is a collision-free O(1) proof; rescanning
        // every Bitmap/native-handle pair on each MOVE only repeats work already proven at the
        // structural mutation boundary.
        val exactCachedBand = nativeProducerSceneBandItems === nativeItems &&
            nativeProducerSceneFilterDirectWifiNativeTiles == filterDirectWifiNativeTiles &&
            java.lang.Float.floatToRawIntBits(nativeProducerSceneBandViewHeight) ==
                java.lang.Float.floatToRawIntBits(nativeBandViewHeight)
        val sameOffset = java.lang.Float.floatToRawIntBits(
            nativeProducerSceneLastViewportItemTopOffset
        ) == java.lang.Float.floatToRawIntBits(viewportItemTopOffset)
        val insideStableMembership = viewportItemTopOffset >
            nativeProducerSceneReuseMinOffset + NATIVE_SCENE_REUSE_BOUNDARY_EPSILON_PX &&
            viewportItemTopOffset <
                nativeProducerSceneReuseMaxOffset - NATIVE_SCENE_REUSE_BOUNDARY_EPSILON_PX
        if (nativeProducerSceneTileCount != 0 && exactCachedBand &&
            (sameOffset || insideStableMembership)
        ) {
            val translationY = nativeProducerSceneBandTranslationY +
                (nativeProducerSceneLastViewportItemTopOffset - viewportItemTopOffset) *
                    geometryScaleY
            nativeProducerSceneBandTranslationY = translationY
            nativeProducerSceneLastViewportItemTopOffset = viewportItemTopOffset
            return translationY
        }
        if (nativeProducerSceneTileCount < 0) {
            // A deferred full scene is already serialized ahead of this frame on the commit
            // Looper, but its packed tile arrays deliberately never return to the producer.  The
            // one-viewport host target changes band-relative page tops on every MOVE, so list
            // identity alone cannot recognize that the pending scene owns the exact same bitmap
            // graph.  Compare that immutable graph directly and submit only its common geometry
            // translation.  Keep the original list as the origin: native producer storage is
            // immutable, therefore every later translation must remain relative to that scene.
            return pendingNativeProducerSceneTranslationForState(
                originalItems = nativeProducerSceneBandItems ?: return null,
                currentItems = nativeItems,
                nativeBandViewHeight = nativeBandViewHeight,
                originalViewportItemTopOffset = nativeProducerSceneViewportItemTopOffset,
                currentViewportItemTopOffset = viewportItemTopOffset,
                geometryScaleY = geometryScaleY,
                filterDirectWifiNativeTiles = filterDirectWifiNativeTiles,
                nativeHeight = height,
            )
        }
        if (nativeProducerSceneTileCount == 0) return null

        var ordinal = 0
        var commonTranslationY: Float? = null
        for (item in nativeItems) {
            val itemTop = item.top - viewportItemTopOffset
            if (itemTop >= nativeBandViewHeight || itemTop + item.pageHeight <= 0f) continue
            val pageTop = (item.top - viewportItemTopOffset) * geometryScaleY
            val pageHeight = item.pageHeight * geometryScaleY
            val pageBitmap = nativePageBitmap(item)
            if (pageBitmap != null && !pageBitmap.isRecycled) {
                val pageSourceWidth = nativePageSourceWidth(item, pageBitmap)
                val pageSourceHeight = nativePageSourceHeight(item, pageBitmap)
                val translationY = nativeProducerSceneTileTranslation(
                        ordinal,
                        item.index,
                        0,
                        0,
                        pageSourceHeight,
                        pageSourceWidth,
                        pageSourceHeight,
                        pageBitmap,
                        pageTop,
                        pageHeight,
                    ) ?: return null
                if (commonTranslationY == null) {
                    commonTranslationY = translationY
                } else if (abs(commonTranslationY - translationY) > 0.01f) {
                    return null
                }
                ordinal++
            } else {
                for (slot in item.tiles.indices) {
                    val tile = item.tiles[slot]
                    val bitmap = tile.bitmap
                    if (bitmap.isRecycled) continue
                    if (filterDirectWifiNativeTiles &&
                        !nativeTileIntersectsViewport(
                            item,
                            tile,
                            geometryScaleY,
                            height,
                            viewportItemTopOffset,
                        )
                    ) continue
                    val translationY = nativeProducerSceneTileTranslation(
                            ordinal,
                            item.index,
                            slot,
                            tile.sourceTop,
                            tile.sourceBottom,
                            tile.sourceWidth,
                            tile.sourceHeight,
                            bitmap,
                            pageTop,
                            pageHeight,
                        ) ?: return null
                    if (commonTranslationY == null) {
                        commonTranslationY = translationY
                    } else if (abs(commonTranslationY - translationY) > 0.01f) {
                        return null
                    }
                    ordinal++
                }
            }
        }
        return if (ordinal == nativeProducerSceneTileCount) {
            (commonTranslationY ?: 0f).also { translationY ->
                nativeProducerSceneBandItems = nativeItems
                nativeProducerSceneFilterDirectWifiNativeTiles =
                    filterDirectWifiNativeTiles
                nativeProducerSceneBandTranslationY = translationY
                nativeProducerSceneBandViewHeight = nativeBandViewHeight
                nativeProducerSceneLastViewportItemTopOffset = viewportItemTopOffset
                nativeProducerSceneViewportItemTopOffset = viewportItemTopOffset
            }
        } else {
            null
        }
    }

    /**
     * Allocation-free proof that two viewport-relative lists describe one immutable native scene.
     * Only [DrawItem.top] may differ, and every selected tile must remain selected under the
     * direct-Wi-Fi viewport filter.
     */
    private fun pendingNativeProducerSceneTranslationForState(
        originalItems: List<DrawItem>,
        currentItems: List<DrawItem>,
        nativeBandViewHeight: Float,
        originalViewportItemTopOffset: Float,
        currentViewportItemTopOffset: Float,
        geometryScaleY: Float,
        filterDirectWifiNativeTiles: Boolean,
        nativeHeight: Int,
    ): Float? {
        if (originalItems.size != currentItems.size || originalItems.isEmpty()) return null
        var commonTranslation: Float? = null
        var comparedVisibleItem = false
        for (index in originalItems.indices) {
            val original = originalItems[index]
            val current = currentItems[index]
            val originalTop = original.top - originalViewportItemTopOffset
            val currentTop = current.top - currentViewportItemTopOffset
            val originalVisible = originalTop < nativeBandViewHeight &&
                originalTop + original.pageHeight > 0f
            val currentVisible = currentTop < nativeBandViewHeight &&
                currentTop + current.pageHeight > 0f
            if (originalVisible != currentVisible) return null
            if (!originalVisible) continue
            comparedVisibleItem = true
            if (original.index != current.index ||
                original.bitmap !== current.bitmap ||
                original.cardBitmap !== current.cardBitmap ||
                original.nativeCardBitmap !== current.nativeCardBitmap ||
                original.tiles != current.tiles ||
                original.sourceWidth != current.sourceWidth ||
                original.sourceHeight != current.sourceHeight ||
                original.originalProof != current.originalProof ||
                original.stripAuthoritative != current.stripAuthoritative ||
                original.adjacentExactAuthoritative != current.adjacentExactAuthoritative ||
                original.stripAsset != current.stripAsset ||
                original.committedIdentity != current.committedIdentity ||
                original.loading != current.loading ||
                original.cardText != current.cardText ||
                original.errorText != current.errorText ||
                java.lang.Float.floatToRawIntBits(original.pageHeight) !=
                    java.lang.Float.floatToRawIntBits(current.pageHeight)
            ) return null
            original.bitmap?.let { if (it.isRecycled) return null }
            original.cardBitmap?.let { if (it.isRecycled) return null }
            original.nativeCardBitmap?.let { if (it.isRecycled) return null }
            if (filterDirectWifiNativeTiles) {
                for (tile in original.tiles) {
                    if (tile.bitmap.isRecycled ||
                        nativeTileIntersectsViewport(
                            original,
                            tile,
                            geometryScaleY,
                            nativeHeight,
                            originalViewportItemTopOffset,
                        ) != nativeTileIntersectsViewport(
                            current,
                            tile,
                            geometryScaleY,
                            nativeHeight,
                            currentViewportItemTopOffset,
                        )
                    ) return null
                }
            } else if (original.tiles.any { it.bitmap.isRecycled }) {
                return null
            }
            val translation = (
                (current.top - currentViewportItemTopOffset) -
                    (original.top - originalViewportItemTopOffset)
                ) * geometryScaleY
            if (commonTranslation == null) {
                commonTranslation = translation
            } else if (abs(commonTranslation - translation) > 0.01f) {
                return null
            }
        }
        return if (comparedVisibleItem) commonTranslation ?: 0f else null
    }

    /** Allocation-free exact comparison plus the current scene's common Y translation. */
    private fun nativeProducerSceneTileTranslation(
        ordinal: Int,
        page: Int,
        slot: Int,
        sourceTop: Int,
        sourceBottom: Int,
        sourceWidth: Int,
        sourceHeight: Int,
        bitmap: Bitmap,
        pageTop: Float,
        pageHeight: Float,
    ): Float? {
        if (ordinal !in 0 until nativeProducerSceneTileCount || bitmap.isRecycled ||
            nativeProducerSceneBitmaps[ordinal] !== bitmap
        ) return null
        val integerOffset = ordinal * NATIVE_TILE_INT_STRIDE
        val nativeHandle = HostExactHardwareTilePool.nativeHandle(bitmap)
        val resourceKind = nativeProducerSceneTileData[integerOffset + 7]
        val resourceMatches = if (nativeHandle != 0L) {
            resourceKind == 2 &&
                nativeProducerSceneTileData[integerOffset + 8] == nativeHandle.toInt() &&
                nativeProducerSceneTileData[integerOffset + 9] ==
                    (nativeHandle ushr 32).toInt()
        } else {
            resourceKind == 0 && nativeProducerSceneTileData[integerOffset + 8] == 0 &&
                nativeProducerSceneTileData[integerOffset + 9] == 0
        }
        if (!resourceMatches ||
            nativeProducerSceneTileData[integerOffset + 1] != slot ||
            nativeProducerSceneTileData[integerOffset + 2] != sourceTop ||
            nativeProducerSceneTileData[integerOffset + 3] != sourceBottom ||
            nativeProducerSceneTileData[integerOffset + 4] != sourceWidth ||
            nativeProducerSceneTileData[integerOffset + 5] != sourceHeight
        ) return null
        // Display page indexes are positional metadata, not resource identity. Forward-history
        // pruning may rebase [page] while retaining this exact JVM/native token, slot and span.
        // The common-Y proof below validates the matching layout shift; visible-frame proof
        // independently carries the rebased index.
        val geometryOffset = ordinal * 2
        if (java.lang.Float.floatToRawIntBits(
                nativeProducerSceneGeometry[geometryOffset + 1]
            ) != java.lang.Float.floatToRawIntBits(pageHeight)
        ) return null
        return pageTop - nativeProducerSceneGeometry[geometryOffset]
    }

    /**
     * Seals the open interval in which the exact resource membership of a native band is stable.
     * A later MOVE still changes geometry, but it cannot add or remove a packed page/tile until it
     * reaches one of these boundaries. This work runs only when a full scene is captured.
     */
    private fun sealNativeProducerSceneReuseWindow(
        nativeBandItems: List<DrawItem>,
        nativeBandViewHeight: Float,
        viewportItemTopOffset: Float,
        filterDirectWifiNativeTiles: Boolean,
    ) {
        var minimumOffset = Float.NEGATIVE_INFINITY
        var maximumOffset = Float.POSITIVE_INFINITY

        fun recordMembershipRange(top: Float, bottom: Float) {
            if (!top.isFinite() || !bottom.isFinite() || bottom <= top) return
            val selected = bottom > viewportItemTopOffset &&
                top < viewportItemTopOffset + nativeBandViewHeight
            if (selected) {
                minimumOffset = max(minimumOffset, top - nativeBandViewHeight)
                maximumOffset = min(maximumOffset, bottom)
            } else if (bottom <= viewportItemTopOffset) {
                minimumOffset = max(minimumOffset, bottom)
            } else if (top >= viewportItemTopOffset + nativeBandViewHeight) {
                maximumOffset = min(maximumOffset, top - nativeBandViewHeight)
            } else {
                // Fail closed if malformed geometry cannot be classified on one side.
                minimumOffset = viewportItemTopOffset
                maximumOffset = viewportItemTopOffset
            }
        }

        for (item in nativeBandItems) {
            val pageBitmap = nativePageBitmap(item)
            if (pageBitmap?.isRecycled == false) {
                recordMembershipRange(item.top, item.top + item.pageHeight)
                continue
            }
            if (!filterDirectWifiNativeTiles) {
                if (item.tiles.any { !it.bitmap.isRecycled }) {
                    recordMembershipRange(item.top, item.top + item.pageHeight)
                }
                continue
            }
            for (tile in item.tiles) {
                if (tile.bitmap.isRecycled || tile.sourceHeight <= 0) continue
                val tileTop = item.top + item.pageHeight *
                    tile.sourceTop.toFloat() / tile.sourceHeight.toFloat()
                val tileBottom = item.top + item.pageHeight *
                    tile.sourceBottom.toFloat() / tile.sourceHeight.toFloat()
                recordMembershipRange(tileTop, tileBottom)
            }
        }
        nativeProducerSceneBandViewHeight = nativeBandViewHeight
        nativeProducerSceneReuseMinOffset = minimumOffset
        nativeProducerSceneReuseMaxOffset = maximumOffset
        nativeProducerSceneLastViewportItemTopOffset = viewportItemTopOffset
    }

    /** Direct-render-thread promise for the exact full scene queued ahead on the commit FIFO. */
    private fun rememberPendingNativeProducerScene(
        handle: Long,
        attachEpoch: Long,
        width: Int,
        height: Int,
        sceneId: Long,
        nativeBandItems: List<DrawItem>,
        nativeBandViewHeight: Float,
        viewportItemTopOffset: Float,
        filterDirectWifiNativeTiles: Boolean,
    ) {
        for (index in 0 until nativeProducerSceneTileCount.coerceAtLeast(0)) {
            nativeProducerSceneBitmaps[index] = null
        }
        nativeProducerSceneHandle = handle
        nativeProducerSceneAttachEpoch = attachEpoch
        nativeProducerSceneWidth = width
        nativeProducerSceneHeight = height
        nativeProducerSceneId = sceneId
        // Negative means the exact same immutable band can queue geometry behind this FIFO scene,
        // while cross-band scalar matching waits for a later fully packed producer snapshot.
        nativeProducerSceneTileCount = -1
        nativeProducerSceneBandItems = nativeBandItems
        nativeProducerSceneFilterDirectWifiNativeTiles = filterDirectWifiNativeTiles
        nativeProducerSceneBandTranslationY = 0f
        nativeProducerSceneViewportItemTopOffset = viewportItemTopOffset
        sealNativeProducerSceneReuseWindow(
            nativeBandItems,
            nativeBandViewHeight,
            viewportItemTopOffset,
            filterDirectWifiNativeTiles,
        )
    }

    /** Direct-render-thread only; copies only the used prefix and reuses prior capacity. */
    private fun rememberNativeProducerScene(
        handle: Long,
        attachEpoch: Long,
        width: Int,
        height: Int,
        sceneId: Long,
        tileCount: Int,
        nativeBandItems: List<DrawItem>,
        nativeBandViewHeight: Float,
        viewportItemTopOffset: Float,
        filterDirectWifiNativeTiles: Boolean,
    ) {
        val integerCount = tileCount * NATIVE_TILE_INT_STRIDE
        val geometryCount = tileCount * 2
        if (nativeProducerSceneTileData.size < integerCount) {
            nativeProducerSceneTileData = IntArray(integerCount)
        }
        if (nativeProducerSceneGeometry.size < geometryCount) {
            nativeProducerSceneGeometry = FloatArray(geometryCount)
        }
        if (nativeProducerSceneBitmaps.size < tileCount) {
            nativeProducerSceneBitmaps = arrayOfNulls(tileCount)
        }
        nativeFrameTileDataScratch.copyInto(
            nativeProducerSceneTileData,
            endIndex = integerCount,
        )
        nativeFrameGeometryScratch.copyInto(
            nativeProducerSceneGeometry,
            endIndex = geometryCount,
        )
        for (index in 0 until tileCount) {
            nativeProducerSceneBitmaps[index] = nativeFrameBitmapScratch[index]
        }
        for (index in tileCount until nativeProducerSceneTileCount) {
            nativeProducerSceneBitmaps[index] = null
        }
        nativeProducerSceneHandle = handle
        nativeProducerSceneAttachEpoch = attachEpoch
        nativeProducerSceneWidth = width
        nativeProducerSceneHeight = height
        nativeProducerSceneId = sceneId
        nativeProducerSceneTileCount = tileCount
        nativeProducerSceneBandItems = nativeBandItems
        nativeProducerSceneFilterDirectWifiNativeTiles = filterDirectWifiNativeTiles
        nativeProducerSceneBandTranslationY = 0f
        nativeProducerSceneViewportItemTopOffset = viewportItemTopOffset
        sealNativeProducerSceneReuseWindow(
            nativeBandItems,
            nativeBandViewHeight,
            viewportItemTopOffset,
            filterDirectWifiNativeTiles,
        )
    }

    private fun clearNativeProducerScene(expectedSceneId: Long = 0L) {
        if (expectedSceneId > 0L && nativeProducerSceneId != expectedSceneId) return
        for (index in 0 until nativeProducerSceneTileCount) {
            nativeProducerSceneBitmaps[index] = null
        }
        nativeProducerSceneId = 0L
        nativeProducerSceneHandle = 0L
        nativeProducerSceneAttachEpoch = 0L
        nativeProducerSceneWidth = 0
        nativeProducerSceneHeight = 0
        nativeProducerSceneTileCount = 0
        nativeProducerSceneBandItems = null
        nativeProducerSceneFilterDirectWifiNativeTiles = false
        nativeProducerSceneBandTranslationY = 0f
        nativeProducerSceneBandViewHeight = 0f
        nativeProducerSceneReuseMinOffset = Float.NEGATIVE_INFINITY
        nativeProducerSceneReuseMaxOffset = Float.POSITIVE_INFINITY
        nativeProducerSceneLastViewportItemTopOffset = 0f
        nativeProducerSceneViewportItemTopOffset = 0f
    }

    /** Direct-render-thread only; writes one exact tile into the reusable JNI handoff arrays. */
    private fun packNativeFrameTile(
        ordinal: Int,
        page: Int,
        slot: Int,
        sourceTop: Int,
        sourceBottom: Int,
        sourceWidth: Int,
        sourceHeight: Int,
        bitmap: Bitmap,
        committedIdentity: CommittedPageIdentity?,
        pageTop: Float,
        pageHeight: Float,
    ) {
        packNativeFrameTileInto(
            nativeFrameTileDataScratch,
            nativeFrameGeometryScratch,
            nativeFrameResourceScratch,
            ordinal,
            page,
            slot,
            sourceTop,
            sourceBottom,
            sourceWidth,
            sourceHeight,
            bitmap,
            committedIdentity,
            pageTop,
            pageHeight,
        )
        nativeFrameBitmapScratch[ordinal] = bitmap
    }

    private fun packNativeFrameTileInto(
        tileData: IntArray,
        geometryData: FloatArray,
        resources: Array<Any?>,
        ordinal: Int,
        page: Int,
        slot: Int,
        sourceTop: Int,
        sourceBottom: Int,
        sourceWidth: Int,
        sourceHeight: Int,
        bitmap: Bitmap,
        committedIdentity: CommittedPageIdentity?,
        pageTop: Float,
        pageHeight: Float,
    ): Boolean {
        val integerOffset = ordinal * NATIVE_TILE_INT_STRIDE
        val nativeHandle = HostExactHardwareTilePool.nativeHandle(bitmap)
        val sourceSpan = sourceBottom - sourceTop
        if (bitmap.isRecycled ||
            ((bitmap.width < sourceWidth || bitmap.height < sourceSpan) && nativeHandle == 0L)
        ) return false
        val contentIdentity = nativeTextureContentIdentity(
            bitmap = bitmap,
            nativeHandle = nativeHandle,
            committedIdentity = committedIdentity,
            slot = slot,
            sourceTop = sourceTop,
            sourceBottom = sourceBottom,
            sourceWidth = sourceWidth,
            sourceHeight = sourceHeight,
        )
        tileData[integerOffset] = page
        tileData[integerOffset + 1] = slot
        tileData[integerOffset + 2] = sourceTop
        tileData[integerOffset + 3] = sourceBottom
        tileData[integerOffset + 4] = sourceWidth
        tileData[integerOffset + 5] = sourceHeight
        tileData[integerOffset + 6] = System.identityHashCode(bitmap)
        tileData[integerOffset + 7] = if (nativeHandle != 0L) 2 else 0
        tileData[integerOffset + 8] = nativeHandle.toInt()
        tileData[integerOffset + 9] = (nativeHandle ushr 32).toInt()
        tileData[integerOffset + 10] = contentIdentity.toInt()
        tileData[integerOffset + 11] = (contentIdentity ushr 32).toInt()
        val geometryOffset = ordinal * 2
        geometryData[geometryOffset] = pageTop
        geometryData[geometryOffset + 1] = pageHeight
        resources[ordinal] = bitmap
        return true
    }

    /** Mirrors the native renderer's draw-time rejection before its texture-upload loop. */
    private fun nativeTileIntersectsViewport(
        item: DrawItem,
        tile: ReaderTile,
        geometryScaleY: Float,
        nativeHeight: Int,
        viewportItemTopOffset: Float = 0f,
    ): Boolean {
        if (nativeHeight <= 0 || item.pageHeight <= 0f || tile.sourceHeight <= 0 ||
            tile.sourceTop < 0 || tile.sourceBottom <= tile.sourceTop ||
            tile.sourceBottom > tile.sourceHeight
        ) return true
        val pageTop = (item.top - viewportItemTopOffset) * geometryScaleY
        val pageHeight = item.pageHeight * geometryScaleY
        val tileTop = pageTop + pageHeight *
            tile.sourceTop.toFloat() / tile.sourceHeight.toFloat()
        val tileBottom = pageTop + pageHeight *
            tile.sourceBottom.toFloat() / tile.sourceHeight.toFloat()
        return tileBottom > 0f && tileTop < nativeHeight.toFloat()
    }


    private fun drawState(
        frameTimeNs: Long,
        callbackStartNs: Long,
        state: DrawState,
        canvas: Canvas,
        mutation: PixelMutationTiming?,
        physicalGestureRevision: Long,
        physicalMotionTraceCookie: Int,
    ): DrawTiming {
        val drawStartNs = System.nanoTime()
        var drawEndNs = drawStartNs
        try {
            Trace.beginSection("RSV.draw")
            if (!state.realPixelsOnly && !drawableContentCoversViewport(state)) {
                canvas.drawColor(PAGE_PLACEHOLDER_COLOR)
            }
            if (!state.empty) {
                val directPreparedBitmap = state.realPixelsOnly || state.directPreparedBitmapBatch
                if (directPreparedBitmap || !drawPreparedRenderScene(canvas, state)) {
                    var index = 0
                    while (index < state.items.size) {
                        drawItem(
                            canvas,
                            state,
                            state.items[index],
                            // Exact HWUI pages are immutable for the lifetime of their Bitmap
                            // identity. Record each page once and move only its RenderNode on
                            // physical scroll, matching RecyclerView's recycled-child display-list
                            // behavior. Pixel installation explicitly invalidates the identity-
                            // checked node, so this never reuses stale page contents.
                            allowRetainedPageNode = true
                        )
                        index++
                    }
                }
            }
            drawScrollbar(canvas, state)
            if (state.hasDrawableContent && !hasDrawnContentFrame) {
                hasDrawnContentFrame = true
            }
        } finally {
            Trace.endSection()
            drawEndNs = System.nanoTime()
        }
        val postEndNs = System.nanoTime()
        val mutationOldestToCallbackMs = causalPixelMutationAgeMs(
            mutation?.oldestNs ?: 0L,
            callbackStartNs
        )
        val mutationNewestToCallbackMs = causalPixelMutationAgeMs(
            mutation?.newestNs ?: 0L,
            callbackStartNs
        )
        val mutationOldestToPostMs = causalPixelMutationAgeMs(
            mutation?.oldestNs ?: 0L,
            postEndNs
        )
        val mutationNewestToPostMs = causalPixelMutationAgeMs(
            mutation?.newestNs ?: 0L,
            postEndNs
        )
        return DrawTiming(
            frameTimeNs = frameTimeNs,
            callbackStartNs = callbackStartNs,
            lockWaitMs = nsToMs(drawStartNs - callbackStartNs),
            drawMs = nsToMs(drawEndNs - drawStartNs),
            postMs = nsToMs(postEndNs - drawEndNs),
            totalMs = nsToMs(postEndNs - callbackStartNs),
            postEndNs = postEndNs,
            posted = true,
            mutationWatermark = mutation?.watermark ?: 0L,
            mutationOldestToCallbackMs = mutationOldestToCallbackMs,
            mutationNewestToCallbackMs = mutationNewestToCallbackMs,
            mutationOldestToPostMs = mutationOldestToPostMs,
            mutationNewestToPostMs = mutationNewestToPostMs,
            invalidationToCallbackMs = causalPixelMutationAgeMs(
                mutation?.invalidationPostedNs ?: 0L,
                callbackStartNs
            ),
            invalidationToPostMs = causalPixelMutationAgeMs(
                mutation?.invalidationPostedNs ?: 0L,
                postEndNs
            ),
            physicalGestureRevision = physicalGestureRevision,
            physicalMotionTraceCookie = physicalMotionTraceCookie,
        )
    }

    private fun drawableContentCoversViewport(state: DrawState): Boolean {
        if (state.empty || !state.hasDrawableContent || state.items.isEmpty()) return false
        val coverageTolerance = if (state.realPixelsOnly) 0f else DRAW_COVERAGE_EPSILON_PX
        var coveredUntil = 0f
        var sawDrawable = false
        for (item in state.items) {
            val itemTop = viewportItemTop(state, item)
            val visibleTop = max(0f, itemTop)
            val visibleBottom = min(state.height.toFloat(), itemTop + item.pageHeight)
            if (visibleBottom <= visibleTop) continue
            if (!itemHasDrawable(item)) return false
            if (!sawDrawable) {
                if (visibleTop > coverageTolerance) return false
                sawDrawable = true
            } else if (visibleTop - coveredUntil > coverageTolerance) {
                return false
            }
            coveredUntil = max(coveredUntil, visibleBottom)
            if (coveredUntil >= state.height - coverageTolerance) return true
        }
        return false
    }

    private fun lastVisibleCoverageIsClean(): Boolean {
        val coverage = lastVisibleCoverageSnapshot ?: return false
        return coverage.drawablePx > 0 &&
            coverage.missingPx == 0 &&
            coverage.placeholderPx == 0 &&
            coverage.visibleLoading == 0
    }

    private fun drawItem(
        canvas: Canvas,
        state: DrawState,
        item: DrawItem,
        allowRetainedPageNode: Boolean
    ) {
        val bitmap = item.bitmap
        val cardText = item.cardText
        val itemTop = viewportItemTop(state, item)
        if (cardText != null) {
            val visibleTop = max(0f, itemTop)
            val visibleBottom = min(state.height.toFloat(), itemTop + item.pageHeight)
            if (visibleBottom <= visibleTop) return
            val centerY = itemTop + item.pageHeight / 2f
            val save = canvas.save()
            canvas.clipRect(0f, visibleTop, state.width.toFloat(), visibleBottom)
            // Fill the complete structural slot. The old 12 px transparent margins retained
            // pixels from a previous Surface buffer at the exact episode boundary.
            paint.style = Paint.Style.FILL
            paint.color = Color.BLACK
            canvas.drawRect(
                0f,
                itemTop,
                state.width.toFloat(),
                itemTop + item.pageHeight,
                paint
            )
            drawTransitionCardText(
                canvas = canvas,
                width = state.width,
                centerY = centerY,
                title = cardText,
                labelPaint = textPaint
            )
            canvas.restoreToCount(save)
            return
        }
        val errorText = item.errorText
        if (errorText != null) {
            val visibleTop = max(0f, itemTop)
            val visibleBottom = min(state.height.toFloat(), itemTop + item.pageHeight)
            if (visibleBottom <= visibleTop) return
            val save = canvas.save()
            canvas.clipRect(0f, visibleTop, state.width.toFloat(), visibleBottom)
            paint.style = Paint.Style.FILL
            paint.color = PAGE_PLACEHOLDER_COLOR
            canvas.drawRect(0f, visibleTop, state.width.toFloat(), visibleBottom, paint)
            textPaint.textSize = 42f
            textPaint.color = Color.rgb(90, 90, 90)
            canvas.drawText(errorText, state.width / 2f, itemTop + item.pageHeight / 2f + 15f, textPaint)
            canvas.restoreToCount(save)
            return
        }
        if (allowRetainedPageNode && drawRetainedPageNode(canvas, state, item)) return
        if (bitmap != null && !bitmap.isRecycled) {
            drawBitmapVisibleCrop(
                canvas,
                bitmap,
                itemTop,
                item.pageHeight,
                state.width,
                state.height
            )
            return
        }
        if (item.tiles.isNotEmpty()) {
            drawTiles(canvas, state, item)
            return
        }
        if (state.realPixelsOnly) return
        paint.color = PAGE_PLACEHOLDER_COLOR
        dst.set(
            0f,
            max(0f, itemTop),
            state.width.toFloat(),
            min(state.height.toFloat(), itemTop + item.pageHeight),
        )
        canvas.drawRect(dst, paint)
    }

    private fun drawBitmapVisibleCrop(
        canvas: Canvas,
        bitmap: Bitmap,
        pageTop: Float,
        pageHeight: Float,
        viewWidth: Int,
        viewHeight: Int
    ) {
        if (bitmap.isRecycled || bitmap.width <= 0 || bitmap.height <= 0 || pageHeight <= 0f) return
        val visibleTop = max(0f, pageTop)
        val visibleBottom = min(viewHeight.toFloat(), pageTop + pageHeight)
        if (visibleBottom <= visibleTop) return

        val sourcePerDestination = bitmap.height / pageHeight
        val sourceTop = floor((visibleTop - pageTop) * sourcePerDestination)
            .toInt()
            .coerceIn(0, bitmap.height - 1)
        val sourceBottom = ceil((visibleBottom - pageTop) * sourcePerDestination)
            .toInt()
            .coerceIn(sourceTop + 1, bitmap.height)
        val destinationPerSource = pageHeight / bitmap.height.toFloat()
        val mappedTop = pageTop + sourceTop * destinationPerSource
        val mappedBottom = pageTop + sourceBottom * destinationPerSource

        src.set(0, sourceTop, bitmap.width, sourceBottom)
        dst.set(0f, mappedTop, viewWidth.toFloat(), mappedBottom)
        prepareBitmapPaint()
        paint.isFilterBitmap = bitmap.width != viewWidth
        val save = canvas.save()
        canvas.clipRect(0f, visibleTop, viewWidth.toFloat(), visibleBottom)
        canvas.drawBitmap(bitmap, src, dst, paint)
        canvas.restoreToCount(save)
    }

    private fun drawTiles(
        canvas: Canvas,
        state: DrawState,
        item: DrawItem
    ) {
        val itemTop = viewportItemTop(state, item)
        val visibleTop = max(0f, itemTop)
        val visibleBottom = min(state.height.toFloat(), itemTop + item.pageHeight)
        if (visibleBottom <= visibleTop) return
        prepareBitmapPaint()
        paint.isFilterBitmap = item.tiles.firstOrNull { !it.bitmap.isRecycled }
            ?.bitmap?.width != state.width
        val sourceHeight = item.tiles.firstOrNull()?.sourceHeight?.takeIf { it > 0 } ?: return
        val pageScale = item.pageHeight / sourceHeight.toFloat()
        val directTileDraw = abs(pageScale - 1f) <= DIRECT_TILE_DRAW_SCALE_EPSILON
        val visibleSourceTop = ((visibleTop - itemTop) / pageScale).coerceAtLeast(0f)
        var low = 0
        var high = item.tiles.size
        while (low < high) {
            val middle = (low + high) ushr 1
            if (item.tiles[middle].sourceBottom <= visibleSourceTop) {
                low = middle + 1
            } else {
                high = middle
            }
        }
        var tileIndex = low
        while (tileIndex < item.tiles.size) {
            val tile = item.tiles[tileIndex]
            tileIndex++
            val tileTop = itemTop + tile.sourceTop * pageScale
            val tileBottom = itemTop + tile.sourceBottom * pageScale
            if (tileBottom < visibleTop) continue
            if (tileTop > visibleBottom) break
            val bitmap = tile.bitmap
            if (bitmap.isRecycled || tile.sourceHeight <= 0) continue
            // Host exact pixels live in the paired HardwareBuffer and are drawn by the native
            // child Surface. The tiny Bitmap is only a generation-unique retirement token.
            if (HostExactHardwareTilePool.isActiveToken(bitmap)) continue
            val drawTop = max(visibleTop, tileTop)
            val drawBottom = min(visibleBottom, tileBottom)
            if (drawBottom <= drawTop || tileBottom <= tileTop) continue
            val drawWidth = state.width
            val dstLeft = (state.width - drawWidth) / 2
            val bitmapSourceTop = tile.bitmapSourceTop()
            val bitmapSourceBottom = bitmapSourceTop + tile.sourceSpan
            if (directTileDraw && bitmap.width == drawWidth) {
                val srcTop = (bitmapSourceTop + floor(drawTop - tileTop).toInt())
                    .coerceIn(bitmapSourceTop, bitmapSourceBottom - 1)
                val srcBottom = (bitmapSourceTop + ceil(drawBottom - tileTop).toInt())
                    .coerceIn(srcTop + 1, bitmapSourceBottom)
                val dstTopInt = floor(drawTop).toInt()
                val dstBottomInt = (dstTopInt + (srcBottom - srcTop)).coerceAtLeast(dstTopInt + 1)
                src.set(0, srcTop, tile.sourceWidth, srcBottom)
                dstInt.set(dstLeft, dstTopInt, dstLeft + drawWidth, dstBottomInt)
                canvas.drawBitmap(bitmap, src, dstInt, paint)
                continue
            }
            val srcTop = (bitmapSourceTop +
                (drawTop - tileTop) / (tileBottom - tileTop) * tile.sourceSpan)
                .toInt()
                .coerceIn(bitmapSourceTop, bitmapSourceBottom - 1)
            val srcBottom = (bitmapSourceTop +
                (drawBottom - tileTop) / (tileBottom - tileTop) * tile.sourceSpan)
                .toInt()
                .coerceIn(srcTop + 1, bitmapSourceBottom)
            src.set(0, srcTop, tile.sourceWidth, srcBottom)
            val dstTop = if (drawTop > visibleTop) drawTop - TILE_SEAM_OVERLAP_PX else drawTop
            val dstBottom = if (drawBottom < visibleBottom) drawBottom + TILE_SEAM_OVERLAP_PX else drawBottom
            val dstTopInt = floor(dstTop).toInt()
            val dstBottomInt = ceil(dstBottom).toInt().coerceAtLeast(dstTopInt + 1)
            dstInt.set(dstLeft, dstTopInt, dstLeft + drawWidth, dstBottomInt)
            canvas.drawBitmap(bitmap, src, dstInt, paint)
        }
    }

    override fun onVisibilityChanged(changedView: View, visibility: Int) {
        super.onVisibilityChanged(changedView, visibility)
        synchronized(stateLock) {
            if (visibility != View.VISIBLE || !isShown) {
                // An invalidate posted while an ancestor is INVISIBLE can retain an old
                // IntendedVsync until the reader is revealed. Do not let staging consume the
                // one frame slot needed by the first real, visible reader frame.
                if (hasFrameWorkLocked()) clearFramePipeLocked(preserveDirty = true)
                return
            }
            if (renderRunning && (renderRequested || desiredVersion > committedVersion) && pages.isNotEmpty() &&
                !shouldBlockInitialEmptyFrameLocked()
            ) {
                scheduleFrameLocked()
            }
        }
    }

    override fun onWindowVisibilityChanged(visibility: Int) {
        super.onWindowVisibilityChanged(visibility)
        if (visibility == View.VISIBLE) refreshCachedDisplayTiming()
        synchronized(stateLock) {
            if (visibility != View.VISIBLE || !isShown) {
                if (hasFrameWorkLocked()) clearFramePipeLocked(preserveDirty = true)
                return
            }
            if (renderRunning && (renderRequested || desiredVersion > committedVersion) && pages.isNotEmpty() &&
                !shouldBlockInitialEmptyFrameLocked()
            ) {
                scheduleFrameLocked()
            }
        }
    }

    private fun prepareBitmapPaint() {
        paint.alpha = 255
        paint.colorFilter = null
        paint.isDither = false
        paint.isFilterBitmap = false
    }

    private fun drawRetainedPageNode(canvas: Canvas, state: DrawState, item: DrawItem): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q || !canvas.isHardwareAccelerated) return false
        if (item.bitmap?.isRecycled == true) return false
        if (item.bitmap == null && item.tiles.none { !it.bitmap.isRecycled }) return false
        val entry = retainedPageNode(item, state.width) ?: return false
        entry.node.translationX = 0f
        entry.node.translationY = viewportItemTop(state, item)
        canvas.drawRenderNode(entry.node)
        return true
    }

    private fun drawPreparedRenderScene(canvas: Canvas, state: DrawState): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q || !canvas.isHardwareAccelerated) return false
        // Keep a captured scene alive through submission. Invalidators use state -> retained;
        // this path takes retained only and therefore cannot recreate the former ABBA cycle.
        return synchronized(retainedNodeLock) {
            val scene = state.preparedScene ?: return@synchronized false
            if (scene.generation != state.visualGeneration ||
                scene.pageCount != state.pageCount ||
                scene.width != state.width ||
                abs(scene.height - state.contentHeight) > PREPARED_SCENE_HEIGHT_EPSILON_PX
            ) {
                return@synchronized false
            }
            val viewportTop = state.scrollOffset
            val viewportBottom = viewportTop + state.height
            val chunks = scene.chunks
            var low = 0
            var high = chunks.size
            // Chunks are ordered and non-overlapping. Locate the first chunk whose bottom is
            // inside or beyond the viewport instead of scanning every prepared page each frame.
            while (low < high) {
                val middle = (low + high) ushr 1
                if (chunks[middle].bottom <= viewportTop) {
                    low = middle + 1
                } else {
                    high = middle
                }
            }
            var drew = false
            var index = low
            while (index < chunks.size) {
                val chunk = chunks[index]
                if (chunk.top >= viewportBottom) break
                if (!chunk.node.hasDisplayList()) return@synchronized false
                chunk.node.translationX = 0f
                chunk.node.translationY = chunk.top - state.scrollOffset
                canvas.drawRenderNode(chunk.node)
                drew = true
                index++
            }
            drew
        }
    }

    @android.annotation.TargetApi(Build.VERSION_CODES.Q)
    private fun retainedPageNode(item: DrawItem, drawWidth: Int): RetainedPageNode? {
        val safeWidth = max(1, drawWidth)
        val safeHeight = max(1, ceil(item.pageHeight).toInt())
        val liveTiles = if (item.tiles.none { it.bitmap.isRecycled }) {
            item.tiles
        } else {
            item.tiles.filter { !it.bitmap.isRecycled }
        }
        synchronized(retainedNodeLock) {
            if (liveTiles.any { HostExactHardwareTilePool.isActiveToken(it.bitmap) }) {
                retainedPageNodes.remove(item.index)?.node?.discardDisplayList()
                return null
            }
            val cached = retainedPageNodes[item.index]
            if (cached != null &&
                cached.width == safeWidth &&
                cached.height == safeHeight &&
                cached.bitmap === item.bitmap &&
                sameBitmapIdentity(cached.tileBitmaps, liveTiles)
            ) {
                if (cached.node.hasDisplayList()) return cached
                retainedPageNodes.remove(item.index)
            }
            if (item.bitmap == null && liveTiles.isEmpty()) {
                retainedPageNodes.remove(item.index)?.node?.discardDisplayList()
                return null
            }
            if (cached != null && retainedPageNodes[item.index] === cached) {
                retainedPageNodes.remove(item.index)
                cached.node.discardDisplayList()
            }
            val node = RenderNode("reader-page-${item.index}")
            node.setPosition(0, 0, safeWidth, safeHeight)
            val recording = node.beginRecording()
            try {
                prepareBitmapPaint()
                val bitmap = item.bitmap
                if (bitmap != null && !bitmap.isRecycled) {
                    recording.drawBitmap(
                        bitmap,
                        null,
                        RectF(0f, 0f, safeWidth.toFloat(), item.pageHeight),
                        paint
                    )
                } else {
                    val sourceHeight = liveTiles.firstOrNull()?.sourceHeight?.takeIf { it > 0 }
                        ?: return null
                    val pageScale = item.pageHeight / sourceHeight.toFloat()
                    for (tile in liveTiles) {
                        val top = tile.sourceTop * pageScale
                        val bottom = tile.sourceBottom * pageScale
                        if (bottom <= top) continue
                        val bitmapTop = tile.bitmapSourceTop()
                        recording.drawBitmap(
                            tile.bitmap,
                            Rect(
                                0,
                                bitmapTop,
                                tile.bitmap.width,
                                bitmapTop + tile.sourceSpan,
                            ),
                            RectF(0f, top, safeWidth.toFloat(), bottom),
                            paint
                        )
                    }
                }
            } finally {
                node.endRecording()
            }
            val entry = RetainedPageNode(
                node = node,
                bitmap = item.bitmap,
                tileBitmaps = liveTiles.map { it.bitmap },
                width = safeWidth,
                height = safeHeight
            )
            retainedPageNodes[item.index] = entry
            return entry
        }
    }

    private fun sameBitmapIdentity(cached: List<Bitmap>, tiles: List<ReaderTile>): Boolean {
        if (cached.size != tiles.size) return false
        for (index in cached.indices) {
            if (cached[index] !== tiles[index].bitmap) return false
        }
        return true
    }

    private fun buildPreparedBitmapPageNodes(
        bitmaps: List<Bitmap>,
        drawWidth: Int
    ): Map<Int, RetainedPageNode> {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) return emptyMap()
        return buildPreparedBitmapPageNodesApi29(bitmaps, drawWidth)
    }

    @android.annotation.TargetApi(Build.VERSION_CODES.Q)
    private fun buildPreparedBitmapScene(
        bitmaps: List<Bitmap>,
        drawWidth: Int
    ): PreparedRenderScene? {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q || bitmaps.isEmpty()) return null
        val safeWidth = max(1, drawWidth)
        var totalHeight = 0f
        val pageTops = FloatArray(bitmaps.size)
        val pageHeights = FloatArray(bitmaps.size)
        var allOpaque = true
        for (index in bitmaps.indices) {
            val bitmap = bitmaps[index]
            if (bitmap.isRecycled || bitmap.width <= 0 || bitmap.height <= 0) return null
            val pageHeight = max(1f, safeWidth * (bitmap.height / bitmap.width.toFloat()))
            pageTops[index] = totalHeight
            pageHeights[index] = pageHeight
            totalHeight += pageHeight
            if (index != bitmaps.lastIndex) totalHeight += pageGapPx
            allOpaque = allOpaque && !bitmap.hasAlpha()
        }
        val nodePaint = Paint().apply {
            alpha = 255
            colorFilter = null
            isDither = false
            isFilterBitmap = false
        }
        val chunks = ArrayList<PreparedRenderChunk>(bitmaps.size)
        var chunkStart = 0
        while (chunkStart < bitmaps.size) {
            val chunkEnd = chunkStart
            val chunkTop = pageTops[chunkStart]
            val chunkBottom = pageTops[chunkEnd] + pageHeights[chunkEnd]
            val node = RenderNode("reader-prepared-scene-$chunkStart")
            node.setPosition(0, 0, safeWidth, max(1, ceil(chunkBottom - chunkTop).toInt()))
            val recording = node.beginRecording()
            var failed: Throwable? = null
            try {
                for (index in chunkStart..chunkEnd) {
                    val localTop = pageTops[index] - chunkTop
                    val localBottom = localTop + pageHeights[index]
                    recording.drawBitmap(
                        bitmaps[index],
                        null,
                        RectF(0f, localTop, safeWidth.toFloat(), localBottom),
                        nodePaint
                    )
                }
            } catch (error: Throwable) {
                failed = error
            } finally {
                node.endRecording()
            }
            if (failed != null) {
                node.discardDisplayList()
                for (chunk in chunks) chunk.node.discardDisplayList()
                Log.d(TAG, "reader_prepared_scene_record_failed error=${failed.javaClass.simpleName}")
                return null
            }
            chunks.add(PreparedRenderChunk(node, chunkTop, chunkBottom))
            chunkStart = chunkEnd + 1
        }
        return PreparedRenderScene(chunks, bitmaps.size, safeWidth, max(1f, totalHeight), allOpaque)
    }

    @android.annotation.TargetApi(Build.VERSION_CODES.Q)
    private fun buildPreparedBitmapPageNodesApi29(
        bitmaps: List<Bitmap>,
        drawWidth: Int
    ): Map<Int, RetainedPageNode> {
        val safeWidth = max(1, drawWidth)
        val result = LinkedHashMap<Int, RetainedPageNode>(bitmaps.size)
        val nodePaint = Paint().apply {
            alpha = 255
            colorFilter = null
            isDither = false
            isFilterBitmap = false
        }
        try {
            for (index in bitmaps.indices) {
                val bitmap = bitmaps[index]
                if (bitmap.isRecycled || bitmap.width <= 0 || bitmap.height <= 0) {
                    throw IllegalStateException("prepared bitmap invalid at $index")
                }
                val pageHeight = max(1f, safeWidth * (bitmap.height / bitmap.width.toFloat()))
                val safeHeight = max(1, ceil(pageHeight).toInt())
                val node = RenderNode("reader-page-$index")
                node.setPosition(0, 0, safeWidth, safeHeight)
                val recording = node.beginRecording()
                try {
                    recording.drawBitmap(
                        bitmap,
                        null,
                        RectF(0f, 0f, safeWidth.toFloat(), pageHeight),
                        nodePaint
                    )
                } finally {
                    node.endRecording()
                }
                result[index] = RetainedPageNode(
                    node = node,
                    bitmap = bitmap,
                    tileBitmaps = emptyList(),
                    width = safeWidth,
                    height = safeHeight
                )
            }
            return result
        } catch (error: Throwable) {
            for (entry in result.values) entry.node.discardDisplayList()
            Log.d(TAG, "reader_prepared_node_record_failed error=${error.javaClass.simpleName}")
            return emptyMap()
        }
    }

    private fun discardRetainedPageNodesLocked() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            preparedRenderScene?.chunks?.forEach { it.node.discardDisplayList() }
            for (entry in retainedPageNodes.values) {
                entry.node.discardDisplayList()
            }
        }
        preparedRenderScene = null
        retainedPageNodes.clear()
    }

    /** Must be called with [stateLock] held. */
    private fun clearRetainedPageNodesStateLocked() {
        cachedNativeBandSnapshot = null
        advanceVisualGenerationLocked()
        synchronized(retainedNodeLock) {
            discardRetainedPageNodesLocked()
        }
    }

    /** Must be called with [stateLock] held. Lock order is always state -> retained node. */
    private fun invalidateRetainedPageNodeStateLocked(index: Int) {
        val cachedBandChanged = invalidateCachedNativeBandForPageLocked(index)
        val activeBandChanged = activeNativeBandProof?.items?.any { it.index == index } == true
        val preparedSceneChanged = preparedRenderScene != null
        // A decoded offscreen page is real resident state, but it is not a mutation of the scene
        // currently being presented. Advancing the global generation here discarded the exact
        // cached/active band even when the range-aware cache check above deliberately preserved
        // it, forcing a full SurfaceControl scene upload for every adjacent-prefetch completion.
        // When scrolling later selects that page, the band origin/membership key changes and the
        // latest Page object is packed normally. Software prepared scenes remain conservative
        // because their chunks do not yet expose a page-range key.
        val visibleSceneChanged = cachedBandChanged || activeBandChanged || preparedSceneChanged
        if (visibleSceneChanged) advanceVisualGenerationLocked()
        synchronized(retainedNodeLock) {
            if (visibleSceneChanged) discardPreparedRenderSceneLocked()
            val removed = retainedPageNodes.remove(index)
            if (removed != null && Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                removed.node.discardDisplayList()
            }
        }
    }

    /** Must be called with [stateLock] held. */
    private fun invalidatePreparedRenderSceneStateLocked() {
        advanceVisualGenerationLocked()
        synchronized(retainedNodeLock) {
            discardPreparedRenderSceneLocked()
        }
    }

    private fun discardPreparedRenderSceneLocked() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            preparedRenderScene?.chunks?.forEach { it.node.discardDisplayList() }
        }
        preparedRenderScene = null
    }

    private fun advanceVisualGenerationLocked(): Long {
        directPreparedBitmapGeneration = Long.MIN_VALUE
        directPreparedBitmapWidth = 0
        directPreparedBitmapOpaque = false
        visualGeneration = if (visualGeneration == Long.MAX_VALUE) 1L else visualGeneration + 1L
        return visualGeneration
    }

    /** Must hold [stateLock]. Invalidates only a band whose immutable pixel interval can change. */
    private fun invalidateCachedNativeBandForPageLocked(index: Int): Boolean {
        val cached = cachedNativeBandSnapshot ?: return false
        val page = pages.getOrNull(index)
        val pageTop = pageTopOrElseLocked(index, Float.NaN)
        val pageHeight = page?.let(::pageDrawHeightLocked) ?: Float.NaN
        val includesPage = cached.items.any { item -> item.index == index }
        if (NtkNativeBandCachePolicy.shouldInvalidateForPage(
                cachedIncludesPage = includesPage,
                pageTop = pageTop,
                pageHeight = pageHeight,
                bandOrigin = Float.fromBits(cached.bandOriginBits),
                bandBottom = Float.fromBits(cached.bandBottomBits),
            )
        ) {
            cachedNativeBandSnapshot = null
            return true
        }
        return false
    }

    private fun preparedSceneForDrawLocked(viewWidth: Int): PreparedRenderScene? {
        val scene = preparedRenderScene ?: return null
        if (scene.generation != visualGeneration ||
            scene.pageCount != pages.size ||
            scene.width != viewWidth ||
            abs(scene.height - contentHeight) > PREPARED_SCENE_HEIGHT_EPSILON_PX
        ) {
            return null
        }
        return scene
    }

    private fun drawScrollbar(canvas: Canvas, state: DrawState) {
        if (!scrollbarVisible && !scrollbarDragging) return
        if (state.height <= 0 || state.contentHeight <= state.height) return
        val thumb = scrollbarThumbRectLocked(state.scrollOffset, state.contentHeight, state.height, state.width)
        paint.style = Paint.Style.FILL
        paint.color = SCROLLBAR_TRACK_COLOR
        dst.set(
            state.width - SCROLLBAR_RIGHT_MARGIN_PX - SCROLLBAR_TRACK_WIDTH_PX,
            0f,
            state.width - SCROLLBAR_RIGHT_MARGIN_PX,
            state.height.toFloat()
        )
        canvas.drawRoundRect(dst, SCROLLBAR_TRACK_RADIUS_PX, SCROLLBAR_TRACK_RADIUS_PX, paint)
        paint.color = if (scrollbarDragging) SCROLLBAR_THUMB_ACTIVE_COLOR else SCROLLBAR_THUMB_COLOR
        canvas.drawRoundRect(thumb, SCROLLBAR_THUMB_RADIUS_PX, SCROLLBAR_THUMB_RADIUS_PX, paint)
        paint.color = SCROLLBAR_GRIP_COLOR
        val gripLeft = thumb.left + SCROLLBAR_GRIP_INSET_PX
        val gripRight = thumb.right - SCROLLBAR_GRIP_INSET_PX
        val gripCenterY = thumb.centerY()
        canvas.drawRoundRect(
            gripLeft,
            gripCenterY - SCROLLBAR_GRIP_GAP_PX,
            gripRight,
            gripCenterY - SCROLLBAR_GRIP_GAP_PX + SCROLLBAR_GRIP_HEIGHT_PX,
            SCROLLBAR_GRIP_RADIUS_PX,
            SCROLLBAR_GRIP_RADIUS_PX,
            paint
        )
        canvas.drawRoundRect(
            gripLeft,
            gripCenterY,
            gripRight,
            gripCenterY + SCROLLBAR_GRIP_HEIGHT_PX,
            SCROLLBAR_GRIP_RADIUS_PX,
            SCROLLBAR_GRIP_RADIUS_PX,
            paint
        )
        canvas.drawRoundRect(
            gripLeft,
            gripCenterY + SCROLLBAR_GRIP_GAP_PX,
            gripRight,
            gripCenterY + SCROLLBAR_GRIP_GAP_PX + SCROLLBAR_GRIP_HEIGHT_PX,
            SCROLLBAR_GRIP_RADIUS_PX,
            SCROLLBAR_GRIP_RADIUS_PX,
            paint
        )
    }

    private fun startScrollbarDragLocked(x: Float, y: Float): Boolean {
        rebuildLayoutLocked()
        val viewWidth = width
        val viewHeight = height
        val maxScroll = max(0f, contentHeight - viewHeight)
        if (!scrollbarVisible) return false
        if (viewWidth <= 0 || viewHeight <= 0 || maxScroll <= 0f) return false
        if (x < viewWidth - SCROLLBAR_TOUCH_WIDTH_PX) return false
        val thumb = scrollbarThumbRectLocked(scrollOffset, contentHeight, viewHeight, viewWidth)
        scrollbarDragging = true
        scrollbarDragOffset = if (y in thumb.top..thumb.bottom) {
            y - thumb.top
        } else {
            thumb.height() / 2f
        }
        moveScrollbarDragLocked(y)
        return true
    }

    private fun moveScrollbarDragLocked(y: Float): WindowRequest? {
        rebuildLayoutLocked()
        val viewHeight = height
        val viewWidth = width
        val maxScroll = max(0f, contentHeight - viewHeight)
        if (viewWidth <= 0 || viewHeight <= 0 || maxScroll <= 0f) return null
        val thumbHeight = scrollbarThumbHeightLocked(contentHeight, viewHeight)
        val trackRange = max(1f, viewHeight - thumbHeight)
        val targetTop = (y - scrollbarDragOffset).coerceIn(0f, trackRange)
        val nextScroll = (targetTop / trackRange) * maxScroll
        if (abs(nextScroll - scrollOffset) <= 0.5f) return null
        setScrollOffsetLocked(nextScroll)
        clampScrollLocked()
        beginPhysicalScrollTraceLocked()
        lastScrollInteractionMs = SystemClock.uptimeMillis()
        boundaryArmedDirection = 0
        renderRequested = true
        scheduleFrameLocked()
        stateLock.notifyAll()
        return windowRequestLocked(true)
    }

    private fun scrollbarThumbRectLocked(scroll: Float, totalContentHeight: Float, viewHeight: Int, viewWidth: Int): RectF {
        val thumbHeight = scrollbarThumbHeightLocked(totalContentHeight, viewHeight)
        val maxScroll = max(1f, totalContentHeight - viewHeight)
        val trackRange = max(1f, viewHeight - thumbHeight)
        val top = (scroll.coerceIn(0f, maxScroll) / maxScroll) * trackRange
        val right = viewWidth - SCROLLBAR_RIGHT_MARGIN_PX - ((SCROLLBAR_TRACK_WIDTH_PX - SCROLLBAR_THUMB_WIDTH_PX) / 2f)
        return RectF(
            right - SCROLLBAR_THUMB_WIDTH_PX,
            top,
            right,
            top + thumbHeight
        )
    }

    private fun scrollbarThumbHeightLocked(totalContentHeight: Float, viewHeight: Int): Float {
        if (totalContentHeight <= 0f || viewHeight <= 0) return SCROLLBAR_MIN_THUMB_HEIGHT_PX
        val proportional = viewHeight * (viewHeight / totalContentHeight)
        return proportional.coerceIn(SCROLLBAR_MIN_THUMB_HEIGHT_PX, viewHeight.toFloat())
    }

    /**
     * Returns one exact native-band projection for all scroll frames inside that band. The former
     * path rebuilt an ArrayList plus every DrawItem under stateLock for every MOVE even though only
     * viewportSourceTop changed. Besides duplicate work, those objects joined large decoded page
     * allocations in the same ART generation and repeatedly triggered long NativeAlloc GCs.
     */
    private fun nativeBandItemsLocked(
        viewWidth: Int,
        bandOrigin: Float,
        bandBottom: Float,
        physicalTailDrawLimit: Int?,
    ): List<DrawItem> {
        val bandOriginBits = java.lang.Float.floatToRawIntBits(bandOrigin)
        val bandBottomBits = java.lang.Float.floatToRawIntBits(bandBottom)
        val contentHeightBits = java.lang.Float.floatToRawIntBits(contentHeight)
        val cached = cachedNativeBandSnapshot
        if (cached != null &&
            cached.structureEpoch == traversalStructureEpoch &&
            cached.pageCount == pages.size &&
            cached.contentHeightBits == contentHeightBits &&
            cached.viewWidth == viewWidth &&
            cached.bandOriginBits == bandOriginBits &&
            cached.bandBottomBits == bandBottomBits &&
            cached.physicalTailDrawLimit == physicalTailDrawLimit &&
            cached.stripAuthorityToken == stripAuthorityToken
        ) {
            return cached.items
        }
        val items = buildNativeBandItemsLocked(
            bandOrigin,
            bandBottom,
            physicalTailDrawLimit,
        )
        cachedNativeBandSnapshot = NativeBandSnapshot(
            structureEpoch = traversalStructureEpoch,
            pageCount = pages.size,
            contentHeightBits = contentHeightBits,
            viewWidth = viewWidth,
            bandOriginBits = bandOriginBits,
            bandBottomBits = bandBottomBits,
            physicalTailDrawLimit = physicalTailDrawLimit,
            stripAuthorityToken = stripAuthorityToken,
            items = items,
        )
        return items
    }

    /** Must hold [stateLock]. Captures every native-admission scalar in the DrawState epoch. */
    private fun nativeSubmissionSnapshotLocked(
        nativeItems: List<DrawItem>,
        viewportItemTopOffset: Float = 0f,
        viewportHeight: Int = height,
    ): NativeSubmissionSnapshot {
        var sawTiledRealItem = false
        var everyTiledItemAuthorized = true
        for (item in nativeItems) {
            val itemTop = item.top - viewportItemTopOffset
            if (itemTop >= viewportHeight.toFloat() || itemTop + item.pageHeight <= 0f) continue
            if (item.cardText != null || item.bitmap != null || item.tiles.isEmpty()) continue
            sawTiledRealItem = true
            if (item.committedIdentity?.normalizedEpisodePath !in
                directWifiExpandedNativeTextureEpisodePaths
            ) {
                everyTiledItemAuthorized = false
                break
            }
        }
        return NativeSubmissionSnapshot(
            filterDirectWifiNativeTiles = directWifiExpandedNativeTextureRunway &&
                directWifiExpandedNativeTextureEpisodePaths.isNotEmpty() &&
                sawTiledRealItem && everyTiledItemAuthorized,
            handle = rollingNativeHandle,
            attachEpoch = rollingNativeAttachEpoch,
            width = rollingNativeWidth,
            height = rollingNativeHeight,
            fatal = rollingNativeFatal,
            viewportWidth = rollingNativeViewportWidth,
            viewportHeight = rollingNativeViewportHeight,
        )
    }

    /** Builds immutable page geometry for one retained native band, independent of the viewport. */
    private fun buildNativeBandItemsLocked(
        bandOrigin: Float,
        bandBottom: Float,
        physicalTailDrawLimit: Int?,
    ): List<DrawItem> {
        if (bandBottom <= bandOrigin || pages.isEmpty()) return emptyList()
        val result = ArrayList<DrawItem>()
        var index = firstVisiblePageLocked(bandOrigin)
        while (index > 0 && pageTopLocked(index) > bandOrigin) index--
        while (index < pages.size) {
            if (physicalTailDrawLimit != null && index > physicalTailDrawLimit) break
            val page = pages[index]
            val absoluteTop = pageTopLocked(index)
            val pageHeight = pageDrawHeightLocked(page)
            if (absoluteTop >= bandBottom) break
            if (absoluteTop + pageHeight > bandOrigin) {
                val item = DrawItem(
                    index = index,
                    bitmap = page.bitmap,
                    cardBitmap = page.cardBitmap,
                    nativeCardBitmap = page.nativeCardBitmap,
                    tiles = page.tiles,
                    sourceWidth = page.width,
                    sourceHeight = page.height,
                    originalProof = page.originalProof,
                    stripAuthoritative = stripAuthorityToken != 0L &&
                        page.stripAuthority == stripAuthorityToken,
                    adjacentExactAuthoritative = page.adjacentExactOwner != null,
                    stripAsset = page.stripAsset ?: page.adjacentExactOwner?.canonicalAsset,
                    committedIdentity = page.committedIdentity,
                    loading = page.loading,
                    cardText = page.cardText,
                    errorText = page.errorText,
                    top = absoluteTop - bandOrigin,
                    pageHeight = pageHeight,
                )
                if (itemHasDrawable(item)) result.add(item)
            }
            index++
        }
        return result
    }

    private fun buildDrawStateLocked(
        busy: Boolean = lastBusy,
        allowVisibleLoadingState: Boolean = false,
        useRetainedNativeBandItems: Boolean = false,
    ): DrawState? {
        val viewWidth = max(1, width)
        val viewHeight = max(1, height)
        if (pages.isEmpty()) {
            return DrawState(viewWidth, viewHeight, busy, true, 1, false, scrollOffset, contentHeight, 0, emptyList())
        }
        applyLockedRestorePositionLocked()
        clampScrollLocked()
        rebuildLayoutLocked()
        if (shouldHoldInitialAnchorRenderLocked()) {
            lastDrawStateNullReason = "initial_anchor_hold:$initialRenderHoldPage"
            if (shouldLogProgrammaticScrollDiagnosticLocked()) {
                Log.d(
                    TAG,
                    "reader_test_scroll_build_null reason=initial_anchor_hold " +
                        "holdPage=$initialRenderHoldPage drawable=${pageHasDrawableContentLocked(initialRenderHoldPage)} " +
                        "anyDrawable=${hasAnyDrawableContentLocked()}"
                )
            }
            renderRequested = true
            scheduleFrameLocked()
            return null
        }
        val physicalTailDrawLimit = heldPhysicalEpisodeTailDrawLimitLocked()
        // Only the direct native producer consumes band-relative DrawItems. Software/HWUI keeps
        // its historical viewport-relative list. Exact native pages deliberately omit unresolved
        // items; the resulting geometric hole remains visible to zero-tolerance coverage proof.
        val retainNativeItemsForViewport = useRetainedNativeBandItems &&
            rollingNativePresentationEnabled && sourceNativeWebtoonCompositingEnabled &&
            inlineRealPixelsOnly
        val nativeTarget = if (rollingNativePresentationEnabled &&
            sourceNativeWebtoonCompositingEnabled
        ) {
            nativeRenderTargetSizeLocked(viewWidth, viewHeight)
        } else {
            Pair(viewWidth, viewHeight)
        }
        val nativeScale = nativeTarget.first.toFloat() / viewWidth.toFloat()
        val framebufferViewSpan = if (nativeScale > 0f) {
            nativeTarget.second.toFloat() / nativeScale
        } else {
            viewHeight.toFloat()
        }
        val nativeBandSpan = framebufferViewSpan
        val nativeBandStep = emulatorNativeBandStep(nativeBandSpan, viewHeight.toFloat())
        // Anchor a multi-viewport target to one rolling step.  The old retained path forced the
        // origin to zero and then selected a moving target-sized window from the whole episode;
        // every short page entering that window changed scene membership and rebuilt all target
        // pixels.  A fixed band keeps both its list identity and page geometry immutable for the
        // full step, while viewportItemTopOffset/sourceTop alone advances visible pixels.
        val nativeBandOrigin = if (nativeBandSpan > viewHeight.toFloat()) {
            floor(scrollOffset / nativeBandStep) * nativeBandStep
        } else {
            scrollOffset
        }.coerceAtLeast(0f)
        val nativeBandItems = if (rollingNativePresentationEnabled &&
            sourceNativeWebtoonCompositingEnabled
        ) {
            nativeBandItemsLocked(
                viewWidth = viewWidth,
                bandOrigin = nativeBandOrigin,
                bandBottom = nativeBandOrigin + nativeBandSpan,
                physicalTailDrawLimit = physicalTailDrawLimit,
            )
        } else {
            emptyList()
        }
        val viewportItemTopOffset = if (retainNativeItemsForViewport) {
            scrollOffset - nativeBandOrigin
        } else {
            0f
        }
        var visibleLoading = 0
        var hasDrawableContent = false
        val items: List<DrawItem> = if (retainNativeItemsForViewport) {
            for (item in nativeBandItems) {
                val top = item.top - viewportItemTopOffset
                if (top < viewHeight.toFloat() && top + item.pageHeight > 0f &&
                    itemHasDrawable(item)
                ) {
                    hasDrawableContent = true
                }
            }
            nativeBandItems
        } else {
            val viewportItems = ArrayList<DrawItem>()
            var index = firstVisiblePageLocked(scrollOffset)
            while (index > 0 && pageTopLocked(index) - scrollOffset > 0f) {
                index--
            }
            while (index < pages.size) {
                // The input cap parks this frame at the outgoing episode's exact bottom. Floating
                // accumulation in a long appended layout can put the next episode a sub-pixel inside
                // the viewport even though its mathematical top equals that bottom. Do not submit a
                // foreign identity in the one frame whose purpose is to prove the outgoing tail; the
                // acknowledged next gesture removes this limit and renders the existing runway.
                if (physicalTailDrawLimit != null && index > physicalTailDrawLimit) break
                val page = pages[index]
                val laidOutTop = pageTopLocked(index) - scrollOffset
                val pageHeight = pageDrawHeightLocked(page)
                var top = laidOutTop
                val previousBottom = viewportItems.lastOrNull()?.let { it.top + it.pageHeight }
                if (!inlineRealPixelsOnly) {
                    if (previousBottom == null) {
                        if (top > COVERAGE_EDGE_FILL_PX && top < viewHeight) {
                            top = 0f
                        }
                    } else if (previousBottom < viewHeight) {
                        if (laidOutTop > previousBottom + COVERAGE_EDGE_FILL_PX ||
                            laidOutTop < previousBottom - COVERAGE_EDGE_FILL_PX
                        ) {
                            top = previousBottom
                        }
                    }
                }
                if (top > viewHeight) break
                val bottom = top + pageHeight
                if (bottom > 0f && top < viewHeight) {
                    val item = DrawItem(
                        index = index,
                        bitmap = page.bitmap,
                        cardBitmap = page.cardBitmap,
                        nativeCardBitmap = page.nativeCardBitmap,
                        tiles = page.tiles,
                        sourceWidth = page.width,
                        sourceHeight = page.height,
                        originalProof = page.originalProof,
                        stripAuthoritative = stripAuthorityToken != 0L &&
                            page.stripAuthority == stripAuthorityToken,
                        adjacentExactAuthoritative = page.adjacentExactOwner != null,
                        stripAsset = page.stripAsset ?: page.adjacentExactOwner?.canonicalAsset,
                        committedIdentity = page.committedIdentity,
                        loading = page.loading,
                        cardText = page.cardText,
                        errorText = page.errorText,
                        top = top,
                        pageHeight = pageHeight
                    )
                    val hasLiveDrawable = itemHasDrawable(item)
                    val isImagePlaceholder =
                        !hasLiveDrawable && page.cardText == null && page.errorText == null
                    if (inlineRealPixelsOnly && !hasLiveDrawable && page.cardText == null) {
                        index++
                        continue
                    }
                    if (shouldSkipLeadingStructuralPlaceholderLocked(
                            index,
                            top,
                            bottom,
                            viewHeight,
                            viewportItems.isEmpty()
                        )
                    ) {
                        index++
                        continue
                    }
                    if (!inlineRealPixelsOnly && isImagePlaceholder &&
                        top >= viewHeight - COVERAGE_EDGE_PLACEHOLDER_FILL_PX &&
                        ceil(min(viewHeight.toFloat(), bottom) - max(0f, top)).toInt() <=
                            COVERAGE_EDGE_PLACEHOLDER_FILL_PX &&
                        viewportItems.lastOrNull()?.let { itemHasDrawable(it) } == true
                    ) {
                        renderRequested = true
                        scheduleFrameLocked()
                        index++
                        continue
                    }
                    if (isImagePlaceholder) visibleLoading++
                    if (hasLiveDrawable) hasDrawableContent = true
                    viewportItems.add(item)
                }
                index++
            }
            viewportItems
        }
        // Never stretch the terminal bitmap to manufacture physical-viewport coverage. The
        // fixed page scale remains authoritative; any real uncovered pixels are background and
        // any not-yet-decoded pixels remain visible to coverage accounting.
        val visibleContentPxOverride = -1
        val compatiblePreparedScene = if (inlineRealPixelsOnly) {
            null
        } else {
            preparedSceneForDrawLocked(viewWidth)
        }
        // Progressive current pixels remain visible immediately. Once the exact forward runway
        // fills a short terminal restore, classify only the source-qualified combined viewport.
        // This live DrawState check also covers a p0 too short to fill the screen until p1/p2 arrive.
        // This source/geometry proof is renderer-independent. Restricting the first evaluation to
        // the emulator native Surface made the ordinary HWUI manga path wait on a latch that only
        // this function can set, so an exact tail + divider + exact next p0 was rejected forever.
        // Physical commit validation still happens downstream; this only classifies the immutable
        // draw state under the same strict identities on every producer.
        val forwardOnlyInitialResumeViewport =
            qualifyDirectWifiForwardOnlyInitialResumeRevealLocked()
        val forwardOnlyTerminalTailActual =
            directWifiForwardOnlyTerminalTailRevealQualified ||
                directWifiForwardOnlyTerminalTailActualLocked()
        val nativeSubmissionSnapshot = nativeSubmissionSnapshotLocked(
            nativeBandItems,
            viewportItemTopOffset,
            viewHeight,
        )
        val state = DrawState(
            viewWidth,
            viewHeight,
            busy,
            false,
            visibleLoading,
            hasDrawableContent,
            scrollOffset,
            contentHeight,
            pages.size,
            items,
            visibleContentPxOverride,
            compatiblePreparedScene,
            visualGeneration,
            !inlineRealPixelsOnly &&
                (BITMAP_SUBMISSION_MODE == BitmapSubmissionMode.DIRECT_VISIBLE_CROP ||
                    (directPreparedBitmapGeneration == visualGeneration &&
                        directPreparedBitmapWidth == viewWidth)),
            inlineRealPixelsOnly,
            traversalStructureEpoch,
            if (inlineRealPixelsOnly) {
                forwardRunwaySnapshotLocked(DEFAULT_FORWARD_RUNWAY_AHEAD_VIEWPORTS)
            } else {
                null
            },
            forwardOnlyInitialResumeViewport,
            forwardOnlyTerminalTailActual,
            // The expanded-runway bit is installed asynchronously after the exact manifest. A
            // slow current-page response can therefore leave it false for the very frame that
            // would skip that page (for example display 16 -> 19). Structural continuity belongs
            // to the host-emulator exact native surface itself; the helper below still requires
            // an authoritative exact item before it can hold a frame.
            NtkDirectWifiExactVisibleStructurePolicy.shouldEnforce(
                emulatorRuntime = emulatorNativeSurfaceRuntime,
                realPixelsOnly = inlineRealPixelsOnly,
            ),
            nativeBandOrigin,
            nativeBandItems,
            nativeSubmissionSnapshot,
            viewportItemTopOffset = viewportItemTopOffset,
            retainedNativeBandHeight = if (retainNativeItemsForViewport) {
                nativeBandSpan
            } else {
                0f
            },
        )
        val nowMs = SystemClock.uptimeMillis()
        val recentScroll = nowMs <= programmaticScrollStatsUntilMs ||
            nowMs - lastScrollInteractionMs <= PROGRAMMATIC_SCROLL_STATS_RECENT_MS
        val holdInitialViewport = shouldHoldInitialViewportRenderLocked()
        val firstInitialVisibleItemMissing = !hasDrawnContentFrame &&
            state.items.firstOrNull { itemIntersectsViewport(state, it) }
                ?.let { !itemHasDrawable(it) } == true
        val shouldHoldVisibleLoadingFrame = state.visibleLoading > 0 &&
            (limitScrollToDrawablePrefix ||
                (!recentScroll &&
                    (!hasDrawnContentFrame || holdInitialViewport || firstInitialVisibleItemMissing)))
        if (shouldHoldVisibleLoadingFrame) {
            val prefixState = drawablePrefixDrawStateOrNull(state, viewHeight)
            if (prefixState != null) {
                return sealDrawStateHotPathSnapshot(prefixState)
            }
            if (allowVisibleLoadingState) return sealDrawStateHotPathSnapshot(state)
            lastDrawStateNullReason = "visible_loading:${state.items.joinToString(",") { it.index.toString() }}"
            if (shouldLogProgrammaticScrollDiagnosticLocked()) {
                Log.d(
                    TAG,
                    "reader_test_scroll_build_null reason=visible_loading " +
                        "loading=${state.visibleLoading} drawn=$hasDrawnContentFrame viewportHold=$holdInitialViewport " +
                        "firstMissing=$firstInitialVisibleItemMissing recent=$recentScroll drawable=${state.hasDrawableContent} " +
                        "items=${state.items.joinToString("|") { item ->
                            val liveTiles = item.tiles.count { !it.bitmap.isRecycled }
                            "${item.index}:b=${item.bitmap != null}/${item.bitmap?.isRecycled == true}," +
                                "t=$liveTiles/${item.tiles.size},loading=${item.loading}," +
                                "card=${item.cardText != null},error=${item.errorText != null}"
                        }}"
                )
            }
            renderRequested = true
            scheduleVisibleLoadingHoldRetryLocked()
            return null
        }
        if (state.visibleLoading == 0 || !holdInitialViewport) {
            clearInitialRenderHoldLocked()
        }
        if (!inlineRealPixelsOnly && hasDrawnContentFrame && !state.hasDrawableContent && !recentScroll) {
            lastDrawStateNullReason = "no_drawable_after_draw:${state.items.size}"
            if (shouldLogProgrammaticScrollDiagnosticLocked()) {
                Log.d(
                    TAG,
                    "reader_test_scroll_build_null reason=no_drawable_after_draw " +
                        "loading=${state.visibleLoading} recent=$recentScroll items=${state.items.size}"
                )
            }
            renderRequested = true
            scheduleFrameLocked()
            return null
        }
        lastDrawStateNullReason = "none"
        return sealDrawStateHotPathSnapshot(state)
    }

    private fun shouldSkipLeadingStructuralPlaceholderLocked(
        index: Int,
        top: Float,
        bottom: Float,
        viewHeight: Int,
        leadingItem: Boolean
    ): Boolean {
        if (!leadingItem) return false
        if (SystemClock.uptimeMillis() > structuralScrollAdjustUntilMs) return false
        if (top >= 0f || bottom <= 0f) return false
        val visiblePx = ceil(min(viewHeight.toFloat(), bottom) - max(0f, top)).toInt()
        if (visiblePx <= 0) return false
        if (visiblePx > (viewHeight * PREPENDED_BOUNDARY_HOLD_MAX_FRACTION).toInt()) return false
        val page = pages.getOrNull(index) ?: return false
        if (page.cardText != null || page.errorText != null || page.bitmap != null || page.tiles.isNotEmpty()) {
            return false
        }
        if (!pageHasDrawableContentLocked(index + 1)) return false
        renderRequested = true
        scheduleFrameLocked()
        return true
    }

    private fun logCoverageIfNeeded(state: DrawState, coverage: CoverageStats, force: Boolean) {
        if (!force) {
            val now = SystemClock.uptimeMillis()
            val activeScroll = pointerDown || dragging || !scroller.isFinished || statsActive
            if (activeScroll) return
            val minInterval = if (state.busy || activeScroll) {
                ACTIVE_SCROLL_COVERAGE_LOG_INTERVAL_MS
            } else {
                BUSY_COVERAGE_LOG_INTERVAL_MS
            }
            if (now - lastCoverageLogMs < minInterval) return
        }
        if (force || coverage != lastCoverageLog) {
            lastCoverageLog = coverage
            lastCoverageLogMs = SystemClock.uptimeMillis()
            Log.i(
                TAG,
                "reader_visible_coverage drawablePx=${coverage.drawablePx} " +
                    "missingPx=${coverage.missingPx} placeholderPx=${coverage.placeholderPx} " +
                    "drawableItems=${coverage.drawableItems} items=${coverage.totalItems} " +
                    "lowResItems=${coverage.lowResolutionItems} minSourceWidth=${coverage.minDrawableSourceWidth}"
            )
            if (coverage.missingPx > COVERAGE_EDGE_FILL_PX) {
                Log.i(
                    TAG,
                    "reader_visible_gap scroll=${formatFloat(state.scrollOffset)} " +
                        "content=${formatFloat(state.contentHeight)} pages=${state.pageCount} " +
                        "busy=${state.busy} loading=${state.visibleLoading} " +
                        "items=${formatDrawItems(state)}"
                )
            }
        }
    }

    private fun updateVisibleCoverageSnapshot(state: DrawState, coverage: CoverageStats): VisibleCoverageSnapshot {
        val snapshot = visibleCoverageSnapshotFromState(state, coverage)
        var shouldPost = false
        var reservation = 0L
        synchronized(stateLock) {
            val previous = lastVisibleCoverageSnapshot
            lastVisibleCoverageSnapshot = snapshot
            if (snapshot.drawablePx > 0 &&
                snapshot.visibleLoading == 0 &&
                snapshot.missingPx == 0 &&
                snapshot.placeholderPx == 0 &&
                snapshot != previous
            ) {
                pendingVisibleCoverageDelivery = PendingVisibleCoverageDelivery(
                    snapshot,
                    lifecycleEpoch,
                )
                if (!visibleCoverageDispatchPosted) {
                    visibleCoverageDispatchPosted = true
                    visibleCoverageDispatchReservation++
                    if (visibleCoverageDispatchReservation <= 0L) {
                        visibleCoverageDispatchReservation = 1L
                    }
                    reservation = visibleCoverageDispatchReservation
                    shouldPost = true
                }
            }
        }
        if (shouldPost && !mainHandler.post(visibleCoverageDispatchRunnable)) {
            synchronized(stateLock) {
                if (visibleCoverageDispatchPosted &&
                    visibleCoverageDispatchReservation == reservation
                ) {
                    visibleCoverageDispatchPosted = false
                    pendingVisibleCoverageDelivery = null
                }
            }
        }
        return snapshot
    }

    private fun drainVisibleCoverageDispatch() {
        check(Looper.myLooper() == Looper.getMainLooper())
        val delivery = synchronized(stateLock) {
            visibleCoverageDispatchPosted = false
            pendingVisibleCoverageDelivery.also { pendingVisibleCoverageDelivery = null }
        } ?: return
        val current = synchronized(stateLock) {
            delivery.lifecycleEpoch == lifecycleEpoch &&
                delivery.snapshot == lastVisibleCoverageSnapshot
        }
        if (current) listener?.onVisibleCoverageChanged(delivery.snapshot)
    }

    private fun visibleCoverageSnapshotFromState(
        state: DrawState,
        coverage: CoverageStats = coverageStats(state)
    ): VisibleCoverageSnapshot {
        val visibleContentPx = visibleContentPx(state)
        var visibleErrors = 0
        var visibleCards = 0
        for (item in state.items) {
            if (!itemIntersectsViewport(state, item)) continue
            if (item.errorText != null) visibleErrors++
            if (item.cardText != null) visibleCards++
        }
        return VisibleCoverageSnapshot(
            viewportPx = visibleContentPx,
            drawablePx = coverage.drawablePx,
            missingPx = coverage.missingPx,
            placeholderPx = coverage.placeholderPx,
            drawableItems = coverage.drawableItems,
            totalItems = coverage.totalItems,
            visibleLoading = state.visibleLoading,
            visibleErrors = visibleErrors,
            visibleCards = visibleCards,
            busy = state.busy,
            pageCount = state.pageCount,
            lowResolutionItems = coverage.lowResolutionItems,
            minDrawableSourceWidth = coverage.minDrawableSourceWidth,
            physicalViewportPx = state.height,
            directWifiForwardOnlyInitialResume = state.directWifiForwardOnlyInitialResume,
            directWifiForwardOnlyTerminalTailActual =
                state.directWifiForwardOnlyTerminalTailActual
        )
    }

    private fun viewportItemTop(state: DrawState, item: DrawItem): Float =
        item.top - state.viewportItemTopOffset

    private fun itemIntersectsViewport(state: DrawState, item: DrawItem): Boolean {
        val top = viewportItemTop(state, item)
        return top < state.height.toFloat() && top + item.pageHeight > 0f
    }

    private fun formatDrawItems(state: DrawState): String {
        if (state.items.isEmpty()) return "none"
        return state.items.joinToString(separator = "|") { item ->
            val top = viewportItemTop(state, item)
            val bottom = top + item.pageHeight
            val displayState = when {
                itemHasDrawable(item) -> "draw"
                item.loading -> "load"
                else -> "empty"
            }
            "${item.index}:${formatFloat(top)}-${formatFloat(bottom)}:$displayState"
        }
    }

    private fun formatFloat(value: Float): String {
        return String.format(Locale.US, "%.1f", value)
    }

    /**
     * Seals all managed-object derivations before the physical producer leaves stateLock. The
     * producer then reaches accepted-scene JNI without allocating coverage or episode-tail keys,
     * so a concurrent ART collection cannot select the frame hot path as its suspension point.
     */
    private fun sealDrawStateHotPathSnapshot(state: DrawState): DrawState {
        val coverage = coverageStats(state)
        val cleanPixels = state.hasDrawableContent && state.visibleLoading == 0 &&
            coverage.missingPx == 0 && coverage.placeholderPx == 0 &&
            coverage.lowResolutionItems == 0 && coverage.drawableItems > 0
        return state.copy(
            coverageSnapshot = coverage,
            requiresSharedFrontGpuCompletionProof =
                requiresSharedFrontGpuCompletionProof(state, cleanPixels),
        )
    }

    private fun coverageStats(state: DrawState): CoverageStats {
        state.coverageSnapshot?.let { return it }
        if (state.empty) return CoverageStats(0, visibleContentPx(state), 0, 0, 0, 0, 0)
        val visibleContentPx = visibleContentPx(state)
        var drawablePx = 0
        var placeholderPx = 0
        var drawableItems = 0
        var lowResolutionItems = 0
        var minDrawableSourceWidth = Int.MAX_VALUE
        var coveredPx = 0
        var coveredUntilPx = 0
        var totalVisibleItems = 0
        val minimumReadableSourceWidth = minimumReadableSourceWidth(state.width, state.realPixelsOnly)
        for (item in state.items) {
            val itemTop = viewportItemTop(state, item)
            val top = floor(max(0f, itemTop)).toInt().coerceIn(0, visibleContentPx)
            val bottom = ceil(min(visibleContentPx.toFloat(), itemTop + item.pageHeight))
                .toInt().coerceIn(top, visibleContentPx)
            if (bottom <= top) continue
            totalVisibleItems++
            // Adjacent float page edges can round outward to the same physical pixel. Counting
            // every item span independently double-counts that boundary (and can cancel a real
            // gap elsewhere). Accumulate the ordered vertical union instead. Draw items are built
            // in display order, so only the portion after the prior covered edge is new coverage.
            val uniqueTop = max(top, coveredUntilPx)
            val uniquePx = max(0, bottom - uniqueTop)
            coveredUntilPx = max(coveredUntilPx, bottom)
            if (uniquePx <= 0) continue
            coveredPx += uniquePx
            if (state.realPixelsOnly &&
                (item.stripAuthoritative || item.adjacentExactAuthoritative)
            ) {
                val sourceWidth = authoritativeStripSourceWidth(item)
                val tilePx = if (sourceWidth > 0) {
                    min(
                        uniquePx,
                        authoritativeStripDrawablePx(item, itemTop, top, bottom),
                    )
                } else {
                    0
                }
                drawablePx += tilePx
                placeholderPx += max(0, uniquePx - tilePx)
                if (tilePx > 0) {
                    drawableItems++
                    minDrawableSourceWidth = min(minDrawableSourceWidth, sourceWidth)
                    if (sourceWidth < minimumReadableSourceWidth) lowResolutionItems++
                }
                continue
            }
            if (itemHasDrawable(item)) {
                val sourceWidth = drawableSourceWidth(
                    item,
                    requireOriginalProof = state.realPixelsOnly
                )
                if (!state.realPixelsOnly || sourceWidth > 0) {
                    drawablePx += uniquePx
                    drawableItems++
                    minDrawableSourceWidth = min(minDrawableSourceWidth, sourceWidth)
                    if (sourceWidth < minimumReadableSourceWidth) lowResolutionItems++
                } else {
                    placeholderPx += uniquePx
                    lowResolutionItems++
                }
            } else {
                placeholderPx += uniquePx
            }
        }
        val rawMissingPx = max(0, visibleContentPx - coveredPx)
        val missingTolerancePx = if (state.realPixelsOnly) 0 else COVERAGE_EDGE_FILL_PX
        val missingPx = if (rawMissingPx <= missingTolerancePx && placeholderPx == 0 && drawablePx > 0) {
            0
        } else {
            rawMissingPx
        }
        val boundedPlaceholderPx = placeholderPx.coerceIn(0, visibleContentPx)
        val boundedDrawablePx = (
            if (missingPx == 0) {
                max(drawablePx, visibleContentPx - boundedPlaceholderPx)
            } else {
                drawablePx
            }
        ).coerceIn(0, visibleContentPx)
        return CoverageStats(
            drawablePx = boundedDrawablePx,
            missingPx = missingPx,
            placeholderPx = boundedPlaceholderPx,
            drawableItems = drawableItems,
            totalItems = totalVisibleItems,
            lowResolutionItems = lowResolutionItems,
            minDrawableSourceWidth = if (minDrawableSourceWidth == Int.MAX_VALUE) 0 else minDrawableSourceWidth
        )
    }

    private fun visibleContentPx(state: DrawState): Int {
        if (state.visibleContentPxOverride > 0) {
            return state.visibleContentPxOverride.coerceIn(0, state.height)
        }
        return ceil(
            min(
                state.height.toFloat(),
                max(0f, state.contentHeight - state.scrollOffset)
            )
        ).toInt().coerceIn(0, state.height)
    }

    private fun drawablePrefixDrawStateOrNull(state: DrawState, viewHeight: Int): DrawState? {
        if (!limitScrollToDrawablePrefix || state.items.isEmpty()) return null
        val prefixItems = ArrayList<DrawItem>()
        for (item in state.items) {
            if (!itemHasDrawable(item)) break
            prefixItems.add(item)
        }
        if (prefixItems.isEmpty()) return null
        return state.copy(
            visibleLoading = 0,
            hasDrawableContent = true,
            items = prefixItems,
            visibleContentPxOverride = viewHeight,
            coverageSnapshot = null,
            requiresSharedFrontGpuCompletionProof = false,
        )
    }

    private fun authoritativeStripSourceWidth(item: DrawItem): Int {
        if ((!item.stripAuthoritative && !item.adjacentExactAuthoritative) ||
            item.sourceWidth <= 0 || item.sourceHeight <= 0 ||
            item.stripAsset.isNullOrBlank() ||
            !ReaderPreparedStore.isCanonicalOriginalProof(
                item.originalProof,
                item.stripAsset,
                item.sourceWidth,
                item.sourceHeight
            )
        ) return 0
        for (tile in item.tiles) {
            val span = tile.sourceBottom - tile.sourceTop
            if (tile.sourceTop < 0 || span <= 0 || tile.sourceBottom > item.sourceHeight ||
                tile.sourceWidth != item.sourceWidth || tile.sourceHeight != item.sourceHeight ||
                !tile.bitmap.hasImmutableExactPixelConfig() ||
                !tile.hasExactSourcePixelStorage()
            ) return 0
        }
        return if (item.tiles.isEmpty()) 0 else item.sourceWidth
    }

    /** Counts the union of real resident tile rows intersecting this physical viewport page. */
    private fun authoritativeStripDrawablePx(
        item: DrawItem,
        itemTop: Float,
        visibleTop: Int,
        visibleBottom: Int,
    ): Int {
        if (visibleBottom <= visibleTop || item.pageHeight <= 0f || item.sourceHeight <= 0) return 0
        var covered = 0
        var cursor = visibleTop
        for (tile in item.tiles) {
            val tileTop = floor(itemTop + tile.sourceTop * item.pageHeight / item.sourceHeight).toInt()
            val tileBottom = ceil(itemTop + tile.sourceBottom * item.pageHeight / item.sourceHeight).toInt()
            val start = max(cursor, max(visibleTop, tileTop))
            val end = min(visibleBottom, tileBottom)
            if (end > start) {
                covered += end - start
                cursor = end
                if (cursor >= visibleBottom) break
            }
        }
        return covered.coerceIn(0, visibleBottom - visibleTop)
    }

    private fun itemHasDrawable(item: DrawItem): Boolean {
        if (item.cardText != null) return true
        val bitmap = item.bitmap
        if (bitmap != null && !bitmap.isRecycled) return true
        return item.tiles.any { !it.bitmap.isRecycled }
    }

    private fun drawableSourceWidth(item: DrawItem, requireOriginalProof: Boolean): Int {
        if (item.cardText != null) return Int.MAX_VALUE
        if (requireOriginalProof) {
            return if (usableAuthoritativeOriginalTilePage(
                    item.sourceWidth,
                    item.sourceHeight,
                    item.tiles,
                    item.originalProof
                )
            ) {
                item.originalProof!!.originalWidth
            } else {
                0
            }
        }
        val bitmap = item.bitmap
        if (bitmap != null && !bitmap.isRecycled) return bitmap.width
        return item.tiles
            .asSequence()
            .filter { !it.bitmap.isRecycled }
            .map { if (it.sourceWidth > 0) it.sourceWidth else it.bitmap.width }
            .minOrNull() ?: 0
    }

    private fun frameTraversalProof(
        state: DrawState,
        coverage: VisibleCoverageSnapshot,
        submittedVisiblePages: NtkPackedVisibleFrameProof,
    ): FrameTraversalProof? {
        if (!state.realPixelsOnly || state.pageCount <= 0 || state.traversalEpoch <= 0L) {
            return null
        }
        val physicalViewport = coverage.physicalViewportPx
        val exactStructureContinuous = !hasNonContiguousExactNativeStructure(state)
        var sawVisibleItem = false
        var everyVisibleItemAuthoritative = true
        for (item in state.items) {
            if (!itemIntersectsViewport(state, item)) continue
            sawVisibleItem = true
            val authoritative = if (item.cardText != null) {
                true
            } else if (item.stripAuthoritative || item.adjacentExactAuthoritative) {
                authoritativeStripSourceWidth(item) > 0
            } else {
                usableAuthoritativeOriginalTilePage(
                    item.sourceWidth,
                    item.sourceHeight,
                    item.tiles,
                    item.originalProof,
                )
            }
            if (!authoritative) {
                everyVisibleItemAuthoritative = false
                break
            }
        }
        val authoritativeVisible = exactStructureContinuous && sawVisibleItem &&
            everyVisibleItemAuthoritative
        val viewportDefect = physicalViewport <= 0 ||
            coverage.viewportPx < physicalViewport ||
            coverage.drawablePx < physicalViewport ||
            coverage.missingPx != 0 || coverage.placeholderPx != 0 ||
            coverage.visibleLoading != 0 || coverage.visibleErrors != 0 ||
            coverage.widthFillFailures != 0 ||
            coverage.lowResolutionItems != 0 || !authoritativeVisible
        val runway = state.forwardRunway
        val runwayDefect = runway == null || runway.missingAheadPx != 0 ||
            runway.lowResolutionItems != 0 ||
            (!runway.contentExhausted && runway.availableAheadPx < runway.requiredAheadPx)
        val visibleIndexes = if (viewportDefect) {
            IntArray(0)
        } else {
            submittedVisiblePages.pageIndexes
        }
        val visibleIdentities = if (viewportDefect) {
            emptyList()
        } else {
            submittedVisiblePages.pageIdentities
        }
        return FrameTraversalProof(
            structureEpoch = state.traversalEpoch,
            visiblePageIndexes = visibleIndexes,
            visiblePageIdentities = visibleIdentities,
            viewportDefect = viewportDefect,
            runwayDefect = runwayDefect
        )
    }

    private fun hasNonContiguousExactNativeStructure(state: DrawState): Boolean {
        if (!state.enforceContiguousExactStructure) return false
        var sawExactItem = false
        var sawVisibleItem = false
        var previousIndex = 0
        var nonContiguous = false
        for (item in state.items) {
            if (!itemIntersectsViewport(state, item)) continue
            if (sawVisibleItem && item.index != previousIndex + 1) nonContiguous = true
            previousIndex = item.index
            sawVisibleItem = true
            if (item.stripAuthoritative || item.adjacentExactAuthoritative ||
                item.committedIdentity != null
            ) {
                sawExactItem = true
            }
        }
        return sawExactItem && nonContiguous
    }

    private fun recordSubmittedTraversalProofLocked(proof: FrameTraversalProof?) {
        if (proof == null || proof.structureEpoch != traversalStructureEpoch ||
            traversalExpectedPageCount <= 0
        ) {
            return
        }
        traversalSubmittedFrames++
        if (proof.viewportDefect) traversalSubmittedViewportDefectFrames++
        if (proof.runwayDefect) traversalSubmittedRunwayDefectFrames++
    }

    private fun recordCommittedTraversalProofLocked(proof: FrameTraversalProof?) {
        if (proof == null || proof.structureEpoch != traversalStructureEpoch ||
            traversalExpectedPageCount <= 0
        ) {
            return
        }
        traversalCommittedFrames++
        if (proof.viewportDefect) traversalCommittedViewportDefectFrames++
        if (proof.runwayDefect) traversalCommittedRunwayDefectFrames++
        if (!proof.viewportDefect) {
            proof.visiblePageIndexes.forEach { index ->
                if (index in traversalCommittedPages.indices) {
                    traversalCommittedPages[index] = true
                }
            }
        }
    }

    private fun shouldHoldInitialAnchorRenderLocked(): Boolean {
        val page = initialRenderHoldPage
        if (page !in 0 until pages.size) return false
        val now = SystemClock.uptimeMillis()
        if (now > initialRenderHoldUntilMs) {
            clearInitialRenderHoldLocked()
            return false
        }
        if (isRecentScrollStatsActiveLocked(now) && hasAnyDrawableContentLocked()) {
            clearInitialRenderHoldLocked()
            return false
        }
        if (!pageHasDrawableContentLocked(page)) return true
        return false
    }

    private fun shouldHoldInitialViewportRenderLocked(): Boolean {
        val now = SystemClock.uptimeMillis()
        if (isRecentScrollStatsActiveLocked(now) && hasAnyDrawableContentLocked()) return false
        return now <= max(initialRenderHoldUntilMs, initialViewportHoldUntilMs)
    }

    private fun shouldDeferDrawableReplacementLocked(): Boolean {
        val now = SystemClock.uptimeMillis()
        return lastBusy ||
            pointerDown ||
            dragging ||
            !scroller.isFinished ||
            isRecentScrollStatsActiveLocked(now)
    }

    private fun clearInitialRenderHoldLocked() {
        initialRenderHoldPage = -1
        initialRenderHoldUntilMs = 0L
        initialViewportHoldUntilMs = 0L
    }

    private fun shouldSuppressInitialEmptyRenderLocked(): Boolean {
        val page = initialRenderHoldPage
        return page in 0 until pages.size &&
            SystemClock.uptimeMillis() <= initialRenderHoldUntilMs &&
            !pageHasDrawableContentLocked(page)
    }

    private fun shouldDeferInitialEmptyDrawLocked(): Boolean {
        if (!deferInitialEmptyDraw || pages.isEmpty()) return false
        if (hasAnyDrawableContentLocked()) {
            deferInitialEmptyDraw = false
            return false
        }
        return true
    }

    private fun shouldBlockInitialEmptyFrameLocked(): Boolean {
        return shouldSuppressInitialEmptyRenderLocked() || shouldDeferInitialEmptyDrawLocked()
    }

    private fun hasAnyDrawableContentLocked(): Boolean {
        for (index in pages.indices) {
            if (pageHasDrawableContentLocked(index)) return true
        }
        return false
    }

    private fun isRecentScrollStatsActiveLocked(nowMs: Long): Boolean {
        return nowMs <= programmaticScrollStatsUntilMs ||
            (lastScrollInteractionMs > 0L &&
                nowMs - lastScrollInteractionMs <= PROGRAMMATIC_SCROLL_STATS_RECENT_MS)
    }

    private fun pageHasDrawableContentLocked(index: Int): Boolean {
        val page = pages.getOrNull(index) ?: return false
        if (page.cardText != null || page.errorText != null) return true
        val bitmap = page.bitmap
        if (bitmap != null && !bitmap.isRecycled) return true
        return page.tiles.any { !it.bitmap.isRecycled }
    }

    /** Null means this is not an adjacent sparse page; otherwise returns its drawable prefix Y. */
    private fun adjacentExactPrefixBottomLocked(index: Int): Float? {
        val page = pages.getOrNull(index) ?: return null
        val owner = page.adjacentExactOwner ?: return null
        val plan = page.adjacentExactPlan ?: return pageTopOrElseLocked(index, 0f)
        if (owner.planDigest != plan.planDigest || owner.sourceKey != plan.sourceKey ||
            page.adjacentExactSlots.size != plan.tiles.size ||
            !ReaderPreparedStore.isCanonicalOriginalProof(
                page.originalProof,
                owner.canonicalAsset,
                plan.sourceWidth,
                plan.sourceHeight,
            )
        ) return pageTopOrElseLocked(index, 0f)
        val sourceBottom = contiguousAdjacentExactSourceBottom(plan, page.adjacentExactSlots)
        return pageTopOrElseLocked(index, 0f) +
            pageDrawHeightLocked(page) * sourceBottom / plan.sourceHeight.toFloat()
    }

    private fun pageHasCompleteDrawableContentLocked(index: Int): Boolean {
        val page = pages.getOrNull(index) ?: return false
        val plan = page.adjacentExactPlan
        val pixelsComplete = if (page.adjacentExactOwner != null && plan != null) {
            contiguousAdjacentExactSourceBottom(plan, page.adjacentExactSlots) ==
                plan.sourceHeight
        } else {
            pageHasDrawableContentLocked(index)
        }
        return pixelsComplete && pageHasDirectPresenterResourcesLocked(page)
    }

    /** Direct SurfaceControl layers can bind only immutable HostExact hardware resources. */
    private fun pageHasDirectPresenterResourcesLocked(page: Page): Boolean {
        if (!emulatorNativeSurfaceRuntime || !directWifiExpandedNativeTextureRunway) return true
        val path = page.committedIdentity?.normalizedEpisodePath ?: return true
        if (path !in directWifiExpandedNativeTextureEpisodePaths) return true
        if (page.cardText != null) {
            val nativeCard = page.nativeCardBitmap ?: return false
            return !nativeCard.isRecycled && HostExactHardwareTilePool.nativeHandle(nativeCard) != 0L
        }
        page.bitmap?.let { bitmap ->
            return !bitmap.isRecycled && HostExactHardwareTilePool.nativeHandle(bitmap) != 0L
        }
        return page.tiles.isNotEmpty() && page.tiles.all { tile ->
            !tile.bitmap.isRecycled && HostExactHardwareTilePool.nativeHandle(tile.bitmap) != 0L
        }
    }

    private fun pageHasDrawablePrefixContentLocked(index: Int): Boolean {
        return pageHasDrawableContentLocked(index)
    }

    fun requestRender() {
        synchronized(stateLock) {
            if (pages.isEmpty()) return
            if (shouldBlockInitialEmptyFrameLocked()) {
                renderRequested = false
                stateLock.notifyAll()
                return
            }
            // Focus/resume/controller bookkeeping does not change reader pixels.  The staged
            // activation path already carries a real dirty version; only bootstrap a draw when
            // this surface has never produced content, otherwise merely service existing work.
            if (!hasDrawnContentFrame) renderRequested = true
            if (!renderRequested && desiredVersion <= committedVersion && scroller.isFinished) {
                return
            }
            scheduleFrameLocked()
            stateLock.notifyAll()
        }
    }

    private fun shouldLogProgrammaticScrollDiagnosticLocked(): Boolean {
        val nowMs = SystemClock.uptimeMillis()
        if (nowMs > programmaticScrollStatsUntilMs) return false
        if (nowMs - lastTestScrollDiagnosticLogMs < TEST_SCROLL_DIAGNOSTIC_LOG_INTERVAL_MS) return false
        lastTestScrollDiagnosticLogMs = nowMs
        return true
    }

    private fun activateScrollStatsLocked(eventTimeMs: Long) {
        edgeNoMovementStatsSuppressedUntilMs = 0L
        programmaticScrollStatsUntilMs = max(
            programmaticScrollStatsUntilMs,
            eventTimeMs + PROGRAMMATIC_SCROLL_STATS_ACTIVE_MS
        )
    }

    /**
     * A physical ACTION_DOWN starts a new moving cadence.  Preserve samples collected by earlier
     * gestures in the same immutable sweep, but do not turn the stationary UP-to-DOWN interval
     * into a fabricated missed frame.  Every callback interval after the first rendered frame of
     * this gesture is still measured exactly.
     */
    private fun startPhysicalGestureFrameCadenceLocked() {
        // A previous finger-down segment may have ended in a stationary hold. Never bridge that
        // idle wall-clock interval into the next physical motion interval.
        endPhysicalScrollTraceLocked()
        statsLastCallbackStartNs = 0L
        statsLastPostEndNs = 0L
        statsLastCallbackGestureRevision = 0L
        statsLastCallbackMotionCookie = 0
        pendingPhysicalPixelInputOldestNs = 0L
        pendingPhysicalPixelInputNewestNs = 0L
        pendingPhysicalPixelInputReceivedOldestNs = 0L
        pendingPhysicalPixelInputReceivedNewestNs = 0L
        pendingPhysicalPixelInputStartsContinuousMotion = false
    }

    private fun isEmpty(): Boolean = !pagesAvailableForInput

    private fun clearInputStateLocked() {
        velocityTracker?.recycle()
        velocityTracker = null
        pointerDown = false
        dragging = false
        scroller.forceFinished(true)
        endPhysicalScrollTraceLocked()
        pendingPhysicalPixelInputOldestNs = 0L
        pendingPhysicalPixelInputNewestNs = 0L
        pendingPhysicalPixelInputReceivedOldestNs = 0L
        pendingPhysicalPixelInputReceivedNewestNs = 0L
        pendingPhysicalPixelInputStartsContinuousMotion = false
        setNativeTexturePrewarmPausedLocked(false)
    }

    private fun interruptPhysicalScrollForLifecycleLocked(): Boolean {
        val hadPhysicalMotion = pointerDown || dragging || !scroller.isFinished ||
            physicalScrollTraceCookie != 0 || hasLiveBlockedForwardIntentLocked()
        clearInputStateLocked()
        // HOME/backgrounding is an explicit interruption boundary. A fling parked behind an
        // undecoded page must not silently resume after the Activity captured its viewport.
        clearBlockedForwardIntentLocked()
        lastBusy = false
        activeScrollerOffsetShift = 0f
        activeInputDirection = 0
        pendingReverseWindowFirstPageHint = -1
        pendingWindowRequest = pendingWindowRequest?.copy(
            directionHint = 0,
            reverseFirstPageHint = -1,
        )
        boundaryArmedDirection = 0
        statsLastCallbackStartNs = 0L
        statsLastPostEndNs = 0L
        statsLastCallbackGestureRevision = 0L
        statsLastCallbackMotionCookie = 0
        return hadPhysicalMotion
    }

    private fun setBusyLocked(busy: Boolean): WindowRequest? {
        if (lastBusy == busy) return null
        lastBusy = busy
        if (busy) {
            val nowMs = SystemClock.uptimeMillis()
            lastScrollInteractionMs = nowMs
            activateScrollStatsLocked(nowMs)
        }
        // Busy/progress are controller state, not reader pixels. Only a full-quality page resolve
        // released by the transition is visual and therefore allowed to request a GPU frame.
        if (!busy && applyPendingPageResolvesLocked()) {
            markPixelsDirtyLocked(DIRTY_CONTENT)
        }
        return windowRequestLocked(busy)
    }

    /**
     * Reconciles controller motion after a page-table operation deliberately stops OverScroller.
     * A live pointer remains busy; otherwise the forced stop must emit its busy -> idle lifecycle
     * edge synchronously because no subsequent animation sample is guaranteed to exist.
     */
    private fun settleForcedStructuralMotionLocked(): WindowRequest? {
        val stillMoving = isScrollBusyAfterSample(
            pointerDown = pointerDown,
            dragging = dragging,
            scrollerFinished = scroller.isFinished,
            blockedForwardIntentPending = false,
        )
        if (!stillMoving) {
            activeScrollerOffsetShift = 0f
            activeInputDirection = 0
            endPhysicalScrollTraceLocked()
            setNativeTexturePrewarmPausedLocked(false)
        }
        return setBusyLocked(stillMoving)
    }

    private fun markPixelsDirtyLocked(reason: Int, recordCausalMutation: Boolean = true) {
        if (recordCausalMutation) recordPixelMutationLocked(reason, System.nanoTime())
        if (desiredVersion <= drawnVersion) advanceDesiredVersionLocked()
        pendingPixelReasons = pendingPixelReasons or reason
        renderRequested = true
        scheduleFrameLocked()
    }

    private fun recordPixelMutationLocked(reason: Int, mutationNs: Long) {
        check(pixelMutationWatermark != Long.MAX_VALUE) {
            "pixel mutation watermark overflow"
        }
        pixelMutationWatermark++
        pendingPixelMutationWatermark = pixelMutationWatermark
        pendingPixelMutationOldestNs = mergeOldestPixelMutationNs(
            pendingPixelMutationOldestNs,
            mutationNs
        )
        pendingPixelMutationNewestNs = mergeNewestPixelMutationNs(
            pendingPixelMutationNewestNs,
            mutationNs
        )
        pendingPixelMutationReasons = pendingPixelMutationReasons or reason
    }

    private fun consumePendingPixelMutationTimingLocked(
        invalidationPostedNs: Long
    ): PixelMutationTiming? {
        if (pendingPixelMutationWatermark <= 0L || pendingPixelMutationOldestNs <= 0L) return null
        val timing = PixelMutationTiming(
            watermark = pendingPixelMutationWatermark,
            oldestNs = pendingPixelMutationOldestNs,
            newestNs = pendingPixelMutationNewestNs,
            reasons = pendingPixelMutationReasons,
            invalidationPostedNs = invalidationPostedNs
        )
        pendingPixelMutationWatermark = 0L
        pendingPixelMutationOldestNs = 0L
        pendingPixelMutationNewestNs = 0L
        pendingPixelMutationReasons = 0
        return timing
    }

    private fun advanceDesiredVersionLocked() {
        if (desiredVersion == Long.MAX_VALUE) {
            check(framePipe == FramePipe.IDLE && inFlightToken == 0L && pendingFrameCommits.isEmpty()) {
                "reader frame version overflow while a frame is in flight"
            }
            desiredVersion = 0L
            drawnVersion = 0L
            committedVersion = 0L
        }
        desiredVersion++
    }

    private fun scheduleFrameLocked(): Boolean {
        if (!renderRunning) return false
        if (frameSchedulingSuppressed) return false
        if (pages.isEmpty()) return false
        if (shouldBlockInitialEmptyFrameLocked()) {
            return false
        }
        if (surfaceAttachmentDeferredUntilActualPixels) {
            if (hasRevealableActualPixelsLocked()) postSurfaceRevealLocked()
            return false
        }
        if (nativeOnlyExactSurfaceRevealPending &&
            !(directSurfaceReady && rollingNativeHandle != 0L && rollingNativeAttachEpoch > 0L)
        ) {
            // The host exact Bitmap is an immutable 1x1 lease token, not a drawable. Do not submit
            // an empty HWUI frame and misclassify its commit as real image presentation while the
            // native SurfaceControl presenter is being created.
            return false
        }
        if (!isShown || windowVisibility != View.VISIBLE) {
            // Staging is allowed to build immutable draw state, but it must not enqueue a hidden
            // Choreographer callback. Activation will request a fresh callback after the same-root
            // host becomes VISIBLE.
            return false
        }
        // Record a real pending mutation even while older submissions await commit. This makes a
        // post-draw content install observable without serializing the next display interval on
        // RenderThread/GPU latency.
        if (renderRequested && desiredVersion <= drawnVersion) {
            advanceDesiredVersionLocked()
            pendingPixelReasons = pendingPixelReasons or DIRTY_INVALIDATION
        }
        if (framePipe != FramePipe.IDLE) {
            statsCoalescedRequests++
            return false
        }
        if (!canAdmitPendingFrameCommit(pendingFrameCommits.size)) {
            // Bound retained proofs/callbacks. The oldest commit callback re-enters this scheduler
            // as soon as one GPU slot retires, while all newer input/content remains coalesced in
            // desiredVersion/renderRequested.
            statsCoalescedRequests++
            return false
        }
        if (!renderRequested && scroller.isFinished) return false

        val epoch = lifecycleEpoch
        val token = nextFrameToken++.also {
            if (nextFrameToken <= 0L) nextFrameToken = 1L
        }
        val callback = Runnable { onFrameCommitted(epoch, token) }
        inFlightEpoch = epoch
        inFlightToken = token
        inFlightCommitCallback = callback
        inFlightCommitCallbackRegistered = false
        inFlightInvalidationPostedNs = 0L
        framePipe = FramePipe.INVALIDATION_POSTED
        if (directSurfaceReady && rollingNativeHandle != 0L &&
            rollingNativeAttachEpoch > 0L && !rollingNativeFatal
        ) {
            // The producer-thread Choreographer owns this token. Registering an HWUI invalidation
            // as well races the same token through two render paths and reintroduces ViewRoot/
            // RenderThread backpressure at every page boundary.
            val callbackReady = postDirectFrameCallbackLocked()
            if (!callbackReady && !directFrameCallbackPosted) {
                // A missing producer/handler or a rejected Handler post must not leave the sole
                // admission in INVALIDATION_POSTED with no callback able to consume it. Restore
                // dirty demand and retry from a fresh token after the producer lifecycle settles.
                releasePostedAdmissionLocked(preserveDirty = true)
                scheduleNoStateRetryLocked()
                return false
            }
            return true
        }
        val postHwuiFrame = Runnable {
            var shouldInvalidate = false
            synchronized(stateLock) {
                if (renderRunning && lifecycleEpoch == epoch && inFlightEpoch == epoch &&
                    inFlightToken == token && framePipe == FramePipe.INVALIDATION_POSTED
                ) {
                    // Register during the one-shot pre-draw stage of the traversal that records
                    // this reader. Registering here (before invalidation) can bind to an unrelated
                    // root commit already in flight, while registering from onDraw is too late for
                    // API 35 HWUI and strands the immutable proof forever.
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q && isHardwareAccelerated) {
                        unregisterInFlightCommitPreDrawListenerLocked()
                        val observer = viewTreeObserver
                        if (observer.isAlive) {
                            val listener = object : ViewTreeObserver.OnPreDrawListener {
                                override fun onPreDraw(): Boolean {
                                    val currentObserver = viewTreeObserver
                                    synchronized(stateLock) {
                                        if (inFlightCommitPreDrawListener !== this) {
                                            if (currentObserver.isAlive) {
                                                currentObserver.removeOnPreDrawListener(this)
                                            }
                                            return true
                                        }
                                        inFlightCommitPreDrawListener = null
                                        if (currentObserver.isAlive) {
                                            currentObserver.removeOnPreDrawListener(this)
                                        }
                                        if (renderRunning && lifecycleEpoch == epoch &&
                                            inFlightEpoch == epoch && inFlightToken == token &&
                                            framePipe == FramePipe.INVALIDATION_POSTED &&
                                            !inFlightCommitCallbackRegistered
                                        ) {
                                            val callback = inFlightCommitCallback
                                            if (callback != null && currentObserver.isAlive) {
                                                currentObserver.registerFrameCommitCallback(callback)
                                                inFlightCommitCallbackRegistered = true
                                            }
                                        }
                                    }
                                    return true
                                }
                            }
                            inFlightCommitPreDrawListener = listener
                            observer.addOnPreDrawListener(listener)
                        }
                    }
                    inFlightInvalidationPostedNs = System.nanoTime()
                    shouldInvalidate = true
                }
            }
            if (shouldInvalidate) postInvalidateOnAnimation()
        }
        if (Looper.myLooper() == Looper.getMainLooper()) {
            postHwuiFrame.run()
        } else {
            mainHandler.post(postHwuiFrame)
        }
        return true
    }

    /** Must be called with [stateLock] held. */
    private fun hasContinuousActualViewportPixelsLocked(): Boolean {
        if (width <= 0 || height <= 0 || pages.isEmpty()) return false
        val geometry = stripGeometry
        if (stripAuthorityToken > 0L && geometry != null) {
            val viewportTop = max(0L, floor(scrollOffset.toDouble()).toLong())
            val viewportBottom = minOf(
                geometry.contentHeightPx,
                viewportTop + height.toLong(),
            )
            return viewportBottom > viewportTop &&
                stripResidentCoverage.continuousEndFrom(viewportTop) >= viewportBottom
        }
        if (currentViewportDrawableOpaqueLocked()) return true
        return qualifyDirectWifiForwardOnlyInitialResumeRevealLocked()
    }

    /** Must be called with [stateLock] held. */
    private fun hasVisibleActualPixelsLocked(): Boolean {
        if (width <= 0 || height <= 0 || pages.isEmpty()) return false
        rebuildLayoutLocked()
        val viewportTop = scrollOffset
        val viewportBottom = viewportTop + height
        for (index in pages.indices) {
            val page = pages[index]
            val top = pageTopOrElseLocked(index, 0f)
            val bottom = top + pageDrawHeightLocked(page)
            if (bottom <= viewportTop) continue
            if (top >= viewportBottom) break
            if (min(viewportBottom, bottom) <= max(viewportTop, top)) continue
            if (page.committedIdentity != null && pageHasCompleteActualPixelsLocked(page)) {
                return true
            }
        }
        return false
    }

    /** Must be called with [stateLock] held. */
    private fun hasRevealableActualPixelsLocked(): Boolean {
        val visibleActualPixels = hasVisibleActualPixelsLocked()
        val scopedResume = emulatorNativeSurfaceRuntime &&
            directWifiForwardOnlyInitialResumeEnabled
        val exactTerminalTailActual = scopedResume &&
            directWifiForwardOnlyTerminalTailActualLocked()
        if (exactTerminalTailActual) {
            directWifiForwardOnlyTerminalTailRevealQualified = true
        }
        return NtkDeferredSurfaceRevealPolicy.shouldReveal(
            emulatorRuntime = emulatorNativeSurfaceRuntime,
            directWifiForwardOnlyResume = directWifiForwardOnlyInitialResumeEnabled,
            visibleActualPixels = visibleActualPixels,
            continuousActualViewport = scopedResume &&
                hasContinuousActualViewportPixelsLocked(),
            exactTerminalTailActual = exactTerminalTailActual,
        )
    }

    /** True when the visible exact image can only be drawn by the host native tile presenter. */
    private fun visibleActualPixelsRequireNativePresenterLocked(): Boolean {
        if (!emulatorNativeSurfaceRuntime || width <= 0 || height <= 0 || pages.isEmpty()) {
            return false
        }
        rebuildLayoutLocked()
        val viewportTop = scrollOffset
        val viewportBottom = viewportTop + height
        var sawNativeExactPixels = false
        for (index in pages.indices) {
            val page = pages[index]
            val top = pageTopOrElseLocked(index, 0f)
            val bottom = top + pageDrawHeightLocked(page)
            if (bottom <= viewportTop) continue
            if (top >= viewportBottom) break
            if (min(viewportBottom, bottom) <= max(viewportTop, top) ||
                page.committedIdentity == null || !pageHasCompleteActualPixelsLocked(page)
            ) continue
            if (page.bitmap?.let(HostExactHardwareTilePool::isActiveToken) == true) {
                sawNativeExactPixels = true
                continue
            }
            if (page.tiles.isNotEmpty() && page.tiles.all {
                    HostExactHardwareTilePool.isActiveToken(it.bitmap)
                }
            ) {
                sawNativeExactPixels = true
                continue
            }
            return false
        }
        return sawNativeExactPixels
    }

    /**
     * Proof deliveries temporarily retain viewport-space layout bounds while their pending source
     * bounds settle. Validate completeness from the immutable tile source geometry itself.
     */
    private fun hasCompleteFullQualityTilePixelsLocked(page: Page): Boolean {
        val first = page.tiles.firstOrNull() ?: return false
        val sourceWidth = first.sourceWidth
        val sourceHeight = first.sourceHeight
        if (sourceWidth <= 0 || sourceHeight <= 0 || first.sourceTop != 0) return false
        var coveredBottom = 0
        for (tile in page.tiles) {
            val bitmap = tile.bitmap
            val span = tile.sourceBottom - tile.sourceTop
            if (tile.sourceWidth != sourceWidth || tile.sourceHeight != sourceHeight ||
                tile.sourceTop < 0 || tile.sourceTop > coveredBottom || span <= 0 ||
                tile.sourceBottom > sourceHeight || bitmap.isRecycled ||
                !tile.hasExactSourcePixelStorage()
            ) {
                return false
            }
            coveredBottom = max(coveredBottom, tile.sourceBottom)
        }
        return coveredBottom == sourceHeight
    }

    /** Re-checks the attachment gate after every complete image-resource installation. */
    private fun reevaluateDeferredSurfaceRevealLocked(reason: String, changedIndex: Int) {
        if (!surfaceAttachmentDeferredUntilActualPixels) return
        if (hasRevealableActualPixelsLocked()) {
            Log.d(
                TAG,
                "reader_surface_progressive_reveal_ready reason=$reason,index=$changedIndex," +
                    "scroll=${scrollOffset.toInt()},viewport=${width}x$height"
            )
            postSurfaceRevealLocked()
            return
        }
        val now = SystemClock.uptimeMillis()
        if (now - lastSurfaceRevealProbeMs < SURFACE_REVEAL_PROBE_LOG_INTERVAL_MS) return
        lastSurfaceRevealProbeMs = now
        rebuildLayoutLocked()
        val viewportTop = scrollOffset
        val viewportBottom = viewportTop + height
        val visible = pages.indices.asSequence()
            .map { index ->
                val page = pages[index]
                val top = pageTopOrElseLocked(index, 0f)
                Triple(index, top, top + pageDrawHeightLocked(page))
            }
            .filter { (_, top, bottom) -> bottom > viewportTop && top < viewportBottom }
            .joinToString(";") { (index, top, bottom) ->
                val page = pages[index]
                val kind = when {
                    page.cardText != null -> "card"
                    page.errorText != null -> "error"
                    page.bitmap?.isRecycled == false -> "bitmap"
                    hasCompleteFullQualityTilePixelsLocked(page) ->
                        "fullTiles:${page.tiles.size}"
                    page.tiles.isNotEmpty() -> "partialTiles:${page.tiles.size}"
                    else -> "missing"
                }
                "$index:$kind:${top.toInt()}-${bottom.toInt()}:${page.width}x${page.height}"
            }
        Log.d(
            TAG,
            "reader_surface_reveal_wait reason=$reason,index=$changedIndex," +
                "scroll=${viewportTop.toInt()},viewport=${width}x$height," +
                "stripAuthority=$stripAuthorityToken,visible=$visible"
        )
    }

    /** Must be called with [stateLock] held. */
    private fun postSurfaceRevealLocked() {
        if (!surfaceAttachmentDeferredUntilActualPixels ||
            !deferredSurfaceIdentityActivated ||
            surfaceRevealPosted
        ) return
        surfaceRevealPosted = true
        mainHandler.post {
            var nativePresenterRequired = false
            var revealEpoch = 0L
            val reveal = synchronized(stateLock) {
                surfaceRevealPosted = false
                if (!surfaceAttachmentDeferredUntilActualPixels ||
                    !hasRevealableActualPixelsLocked()
                ) {
                    false
                } else {
                    surfaceAttachmentDeferredUntilActualPixels = false
                    nativePresenterRequired = rollingNativePresentationEnabled &&
                        nativeSurfaceView.visibility != View.VISIBLE &&
                        visibleActualPixelsRequireNativePresenterLocked()
                    if (nativePresenterRequired) {
                        // A HostExact Bitmap is only a 1x1 native lease token. Retire any HWUI
                        // admission captured before that fact became visible; otherwise its later
                        // root callback can be published as an actual image although no Bitmap
                        // pixels were submitted. The replacement native latch owns the new
                        // lifecycle epoch and is the only valid first-pixel proof.
                        clearFramePipeLocked(preserveDirty = true)
                    }
                    revealEpoch = lifecycleEpoch
                    nativeOnlyExactSurfaceRevealPending = nativePresenterRequired
                    // Software/Hardware Bitmap pages prove their first pixels through HWUI. Host
                    // exact tokens contain no Bitmap pixels, so their native Surface latch is the
                    // sole presentation proof and starts immediately from the decoded tile.
                    nativeSurfaceRevealAfterFirstHwuiCommitPending =
                        rollingNativePresentationEnabled &&
                            nativeSurfaceView.visibility != View.VISIBLE &&
                            !nativePresenterRequired
                    renderRequested = true
                    true
                }
            }
            if (!reveal) return@post
            if (nativePresenterRequired) {
                revealNativeSurfaceAfterFirstHwuiCommit(revealEpoch)
            }
            // Software-backed pixels can publish through HWUI immediately. For host exact pixels
            // this only refreshes surrounding chrome; scheduleFrameLocked remains closed until the
            // real native attachment is ready.
            invalidate()
            (parent as? View)?.invalidate()
            postInvalidateOnAnimation()
            synchronized(stateLock) {
                if (renderRunning && pages.isNotEmpty()) {
                    renderRequested = true
                    scheduleFrameLocked()
                    stateLock.notifyAll()
                }
            }
            Log.d(
                TAG,
                "reader_surface_actual_viewport_admitted producerPrepared=" +
                    "${nativeSurfaceView.visibility == View.VISIBLE}," +
                    "attached=$isAttachedToWindow,size=${width}x$height"
            )
        }
    }

    /**
     * Stage two of the cold producer transition. The listener receives the clean HWUI proof first,
     * allowing current-episode bodies to proceed before any host EGL/BufferQueue work begins.
     */
    private fun revealNativeSurfaceAfterFirstHwuiCommit(expectedLifecycleEpoch: Long) {
        check(Looper.myLooper() == Looper.getMainLooper())
        if (!rollingNativePresentationEnabled) return
        val reveal = synchronized(stateLock) {
            val eligible = renderRunning &&
                lifecycleEpoch == expectedLifecycleEpoch &&
                !surfaceAttachmentDeferredUntilActualPixels &&
                isAttachedToWindow &&
                nativeSurfaceView.visibility != View.VISIBLE
            if (!eligible) {
                nativeSurfaceRevealAfterPrepareEpoch = 0L
                false
            } else if (rollingNativeHandle == 0L) {
                nativeSurfaceRevealAfterPrepareEpoch = expectedLifecycleEpoch
                prepareRollingNativeRendererLocked()
                false
            } else {
                nativeSurfaceRevealAfterPrepareEpoch = 0L
                true
            }
        }
        if (!reveal) return
        // Visibility creates the Surface, but alpha remains zero until its first exact buffer is
        // latched. The already-committed HWUI reader stays visible during asynchronous EGL setup.
        nativeSurfaceView.alpha = 0f
        nativeSurfaceView.visibility = View.VISIBLE
        nativeSurfaceView.requestLayout()
        invalidate()
        (parent as? View)?.invalidate()
        postInvalidateOnAnimation()
        Log.d(
            TAG,
            "reader_native_surface_revealed_after_hwui_commit " +
                "epoch=$expectedLifecycleEpoch,size=${width}x$height"
        )
    }

    /** Commits the already-clamped physical position even when no newer model mutation exists. */
    fun requestCurrentPositionCommit() {
        synchronized(stateLock) {
            if (pages.isEmpty() || shouldBlockInitialEmptyFrameLocked()) return
            // Reaching an edge is a real viewport change whose final native submission can race the
            // boundary callback. requestRender() intentionally ignores a clean model; this explicit
            // path creates one new frame version so the displayed tail can be identity/coverage
            // qualified without inventing movement or changing the scroll coordinate.
            markPixelsDirtyLocked(DIRTY_INVALIDATION, recordCausalMutation = false)
            stateLock.notifyAll()
        }
    }

    private fun onFrameCommitted(
        epoch: Long,
        token: Long,
        surfaceControlLatchObserved: Boolean = false,
        surfaceControlPresentedUptimeNanos: Long = 0L,
        nativePresentationKind: Int = NATIVE_PRESENTATION_NONE,
        allowNativeProducerThread: Boolean = false,
        orderedGeometryCadence: Boolean = false,
    ) {
        if (!allowNativeProducerThread && Looper.myLooper() != Looper.getMainLooper()) {
            mainHandler.post {
                onFrameCommitted(
                    epoch,
                    token,
                    surfaceControlLatchObserved,
                    surfaceControlPresentedUptimeNanos,
                    nativePresentationKind,
                    allowNativeProducerThread = false,
                    orderedGeometryCadence = orderedGeometryCadence,
                )
            }
            return
        }
        var completed: CompletedDrawProof? = null
        var revealNativeSurfaceAfterCompletedHwui = false
        var submissionOrderedCadence = false
        synchronized(stateLock) {
            if (epoch != lifecycleEpoch) return
            val submission = pendingFrameCommits.remove(token)
            if (submission == null) {
                // Defensive fail-closed recovery for a callback that somehow arrives before the
                // matching onDraw installs its immutable proof. It must never qualify an unrelated
                // root commit or monopolize the sole posted-invalidation admission.
                if (token == inFlightToken && epoch == inFlightEpoch) {
                    releasePostedAdmissionLocked(preserveDirty = true)
                    scheduleNoStateRetryLocked()
                }
                stateLock.notifyAll()
                return
            }
            val pending = submission.proof
            submissionOrderedCadence = submission.surfaceControlSubmission
            val matchingReaderDraw = submission.frameEpoch == epoch &&
                pending.frameToken == token && pending.drawnVersion > 0L
            val surfaceQueueObserved = nativePresentationKind == NATIVE_PRESENTATION_BUFFER_QUEUE
            val sharedFrontSubmissionObserved =
                nativePresentationKind == NATIVE_PRESENTATION_SHARED_FRONT_SUBMISSION
            val exactNativePresentationObserved = surfaceControlLatchObserved ||
                surfaceQueueObserved || sharedFrontSubmissionObserved

            if (matchingReaderDraw) {
                Trace.beginSection(
                    when {
                        surfaceControlLatchObserved -> "ViewerSurfaceControlLatch"
                        surfaceQueueObserved -> "ViewerSurfaceQueueSubmission"
                        sharedFrontSubmissionObserved -> "ViewerSharedFrontSubmission"
                        submission.surfaceQueueSubmission -> "ViewerSurfaceQueueSubmission"
                        else -> "ViewerHwuiFrameCommit"
                    }
                )
                try {
                    committedVersion = maxOf(committedVersion, pending.drawnVersion)
                    // The dedicated Surface path proves the exact buffer only after
                    // unlockCanvasAndPost succeeds. The legacy path remains restricted to its
                    // registered HWUI frame-commit callback.
                    if (Build.VERSION.SDK_INT >= 35 &&
                        ((pending.hardwareAccelerated && submission.callbackRegistered) ||
                            submission.surfaceQueueSubmission ||
                            (submission.surfaceControlSubmission && exactNativePresentationObserved))
                    ) {
                        recordCommittedTraversalProofLocked(pending.traversal)
                    }
                    if (submission.surfaceControlSubmission && exactNativePresentationObserved &&
                        pending.coverage.drawableItems > 0
                    ) {
                        hasDrawnContentFrame = true
                    }
                    completedDrawSequence++
                    val completedAtNanos = SystemClock.elapsedRealtimeNanos()
                    val registeredHwuiCommitObserved =
                        Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q &&
                            pending.hardwareAccelerated && submission.callbackRegistered
                    if (emulatorNativeSurfaceRuntime && registeredHwuiCommitObserved &&
                        !submission.surfaceQueueSubmission &&
                        !submission.surfaceControlSubmission
                    ) {
                        rawEmulatorHwuiCommitCount++
                        val previousRawCommit = rawEmulatorHwuiLastCommitNanos
                        if (previousRawCommit > 0L && completedAtNanos > previousRawCommit) {
                            val interval = completedAtNanos - previousRawCommit
                            rawEmulatorHwuiIntervalCount++
                            if (interval > 25_000_000L) rawEmulatorHwuiSlowIntervalCount++
                        }
                        rawEmulatorHwuiLastCommitNanos = completedAtNanos
                        val receivedAt = pending.physicalInputReceivedNewestNanos
                        if (receivedAt > 0L && completedAtNanos >= receivedAt) {
                            val age = completedAtNanos - receivedAt
                            rawEmulatorHwuiPhysicalInputCommitCount++
                            rawEmulatorHwuiPhysicalInputAgeNanos += age
                            rawEmulatorHwuiPhysicalInputMaxAgeNanos = maxOf(
                                rawEmulatorHwuiPhysicalInputMaxAgeNanos,
                                age,
                            )
                            if (rawEmulatorHwuiPhysicalInputCommitCount == 1L ||
                                rawEmulatorHwuiPhysicalInputCommitCount % 60L == 0L
                            ) {
                                Log.i(
                                    "ViewerPerf",
                                    "reader_raw_hwui_commit commits=$rawEmulatorHwuiCommitCount," +
                                        "intervals=$rawEmulatorHwuiIntervalCount," +
                                        "slow25ms=$rawEmulatorHwuiSlowIntervalCount," +
                                        "physical=$rawEmulatorHwuiPhysicalInputCommitCount," +
                                        "inputAgeAvgMs=" +
                                        (rawEmulatorHwuiPhysicalInputAgeNanos / 1_000_000.0 /
                                            rawEmulatorHwuiPhysicalInputCommitCount) +
                                        ",inputAgeMaxMs=" +
                                        (rawEmulatorHwuiPhysicalInputMaxAgeNanos / 1_000_000.0) +
                                        ",token=$token,pending=${pendingFrameCommits.size}",
                                )
                            }
                        }
                    }
                    val exactPresentationObservedAtNanos =
                        surfaceControlPresentedUptimeNanos.takeIf {
                            submission.surfaceControlSubmission &&
                                exactNativePresentationObserved && it > 0L
                        } ?: completedAtNanos.takeIf {
                            emulatorNativeSurfaceRuntime && registeredHwuiCommitObserved &&
                                !submission.surfaceQueueSubmission &&
                                !submission.surfaceControlSubmission
                        } ?: 0L
                    completed = CompletedDrawProof(
                        sequence = completedDrawSequence,
                        completedUptimeNanos = completedAtNanos,
                        hardwareAccelerated = pending.hardwareAccelerated,
                        coverage = pending.coverage,
                        frameToken = token,
                        desiredVersion = desiredVersion,
                        drawnVersion = pending.drawnVersion,
                        committedVersion = committedVersion,
                        structureEpoch = pending.structureEpoch,
                        visiblePageIndexes = pending.visiblePageIndexes.copyOf(),
                        visiblePageIdentities = pending.visiblePageIdentities,
                        runwayDefect = pending.traversal?.runwayDefect == true,
                        registeredHwuiFrameCommitCallbackObserved =
                            registeredHwuiCommitObserved,
                        surfaceQueueSubmissionObserved =
                            submission.surfaceQueueSubmission || surfaceQueueObserved ||
                                sharedFrontSubmissionObserved,
                        surfaceControlLatchObserved =
                            submission.surfaceControlSubmission && surfaceControlLatchObserved,
                        surfaceLifecycleEpoch = epoch,
                        presentedUptimeNanos = exactPresentationObservedAtNanos,
                        scrollOffsetPx = pending.scrollOffsetPx,
                        firstVisiblePageTopPx = pending.firstVisiblePageTopPx,
                        physicalInputOldestNanos = pending.physicalInputOldestNanos,
                        physicalInputNewestNanos = pending.physicalInputNewestNanos,
                        physicalInputReceivedOldestNanos =
                            pending.physicalInputReceivedOldestNanos,
                        physicalInputReceivedNewestNanos =
                            pending.physicalInputReceivedNewestNanos,
                        physicalGestureRevision = pending.physicalGestureRevision,
                        producerCallbackStartedNanos = pending.producerCallbackStartedNanos,
                        expectedPresentationTimeNanos = pending.expectedPresentationTimeNanos,
                        visiblePageTopPx = pending.visiblePageTopPx.copyOf(),
                    )
                    val cleanCommittedHwuiActualPixels =
                        nativeSurfaceRevealAfterFirstHwuiCommitPending &&
                            !submission.surfaceQueueSubmission &&
                            !submission.surfaceControlSubmission &&
                            pending.hardwareAccelerated &&
                            submission.callbackRegistered &&
                            pending.coverage.drawableItems > 0 &&
                            pending.coverage.missingPx == 0 &&
                            pending.coverage.placeholderPx == 0 &&
                            pending.coverage.visibleLoading == 0 &&
                            pending.coverage.visibleErrors == 0 &&
                            (pending.coverage.visibleCards == 0 ||
                                pending.coverage.directWifiForwardOnlyInitialResume) &&
                            pending.coverage.lowResolutionItems == 0
                    if (cleanCommittedHwuiActualPixels) {
                        if (lifecycleEnterAnimationPending) {
                            lifecycleCleanHwuiRevealReady = true
                        } else {
                            nativeSurfaceRevealAfterFirstHwuiCommitPending = false
                            revealNativeSurfaceAfterCompletedHwui = true
                        }
                    }
                } finally {
                    Trace.endSection()
                }
            } else {
                drawnVersion = latestSubmittedVersionLocked()
                if (pages.isNotEmpty()) renderRequested = true
            }
            if (desiredVersion <= committedVersion) pendingPixelReasons = 0

            // A physical trace represents pixel-producing motion, not the entire time a finger
            // remains down.  Host input can deliver sparse MOVE events, so keeping the interval
            // open after the exact physical version has latched fabricates a long compositor gap
            // even though only later content work remains. Do not close while the last actual
            // offset mutation is outstanding: a real render stall remains measured.
            if (shouldClosePhysicalMotionInterval(
                    traceActive = physicalScrollTraceCookie != 0,
                    scrollerFinished = scroller.isFinished,
                    requiredVersion = physicalMotionRequiredVersion,
                    committedVersion = committedVersion
                )
            ) {
                endPhysicalScrollTraceLocked()
                statsLastCallbackStartNs = 0L
                statsLastPostEndNs = 0L
                statsLastCallbackGestureRevision = 0L
                statsLastCallbackMotionCookie = 0
            }

            val needsImmediateFrame = renderRequested || desiredVersion > drawnVersion ||
                !scroller.isFinished
            if (needsImmediateFrame) {
                if (desiredVersion > drawnVersion) {
                    renderRequested = true
                }
                if (!scroller.isFinished) pendingPixelReasons = pendingPixelReasons or DIRTY_ANIMATION
                if (framePipe == FramePipe.INVALIDATION_POSTED && inFlightToken != 0L) {
                    // Native-mailbox backpressure can intentionally preserve one unsubmitted
                    // Kotlin admission. Presentation of its predecessor is the idle-motion wake
                    // that makes native capacity available; re-arm that exact token rather than
                    // allocating a replacement token or polling on a timer.
                    postDirectFrameCallbackLocked()
                } else {
                    scheduleFrameLocked()
                }
            }
            stateLock.notifyAll()
        }
        completed?.let { proof ->
            if (orderedGeometryCadence || submissionOrderedCadence) {
                takeCompletedGeometryCadencePrefix(proof).forEach(
                    ::publishQualifiedNativePresentationCadence,
                )
            } else {
                publishQualifiedNativePresentationCadence(proof)
            }
            publishBenchmarkAdjacentP0CandidateIfEligible(proof)
            val offer = completedDrawDispatchQueue.offer(
                proof,
                revealNativeSurfaceAfterCompletedHwui,
                SystemClock.elapsedRealtimeNanos(),
            )
            if (offer.criticalOverflowed) {
                // A fixed-capacity queue must never silently discard a first-seen episode/p0-p4
                // transition. Rejecting the proof is fail-closed and this hard metric makes the
                // capacity defect visible in production and regression traces.
                Log.e(
                    "ViewerPerf",
                    "reader_completed_draw_dispatch_critical_overflow " +
                        "epoch=${proof.surfaceLifecycleEpoch},structure=${proof.structureEpoch}," +
                        "visible=${proof.visiblePageIndexes.joinToString("|")}",
                )
            }
            if (offer.shouldPost) {
                val accepted = if (offer.delayNanos <= 0L) {
                    mainHandler.post(completedDrawDispatchRunnable)
                } else {
                    val delayMillis = ceil(offer.delayNanos / 1_000_000.0)
                        .toLong()
                        .coerceAtLeast(1L)
                    mainHandler.postDelayed(completedDrawDispatchRunnable, delayMillis)
                }
                if (!accepted) completedDrawDispatchQueue.onPostRejected()
            }
        }
    }

    /**
     * Publishes every exact compositor cadence proof before the semantic main-thread mailbox.
     *
     * The mailbox intentionally collapses unchanged page identities for accessibility and
     * episode events, but a physical scroll can produce dozens of distinct positions while the
     * same two pages remain visible. This gate repeats the immutable pixel/lifecycle checks that
     * are available at the Surface owner and emits cadence only; the Activity still owns all
     * episode, first-image, boundary, and accessibility semantics.
     */
    private fun publishQualifiedNativePresentationCadence(proof: CompletedDrawProof) {
        val presentedNanos = proof.presentedUptimeNanos
        val coverage = proof.coverage
        val exactEmulatorHwuiPresentation = emulatorNativeSurfaceRuntime &&
            proof.registeredHwuiFrameCommitCallbackObserved &&
            !proof.surfaceQueueSubmissionObserved &&
            !proof.surfaceControlLatchObserved
        if (presentedNanos <= 0L || proof.frameToken <= 0L || proof.drawnVersion <= 0L ||
            proof.committedVersion < proof.drawnVersion ||
            (!proof.surfaceControlLatchObserved && !proof.surfaceQueueSubmissionObserved &&
                !exactEmulatorHwuiPresentation) ||
            coverage.physicalViewportPx <= 0 ||
            coverage.viewportPx < coverage.physicalViewportPx ||
            coverage.drawablePx < coverage.physicalViewportPx ||
            coverage.missingPx != 0 || coverage.placeholderPx != 0 ||
            coverage.visibleLoading != 0 || coverage.visibleErrors != 0 ||
            coverage.visibleCards != 0 || coverage.widthFillFailures != 0 ||
            coverage.lowResolutionItems != 0
        ) return
        val visible = proof.visiblePageIndexes
        val identities = proof.visiblePageIdentities
        if (visible.isEmpty() || identities.size != visible.size ||
            identities.indices.any { index ->
                val identity = identities[index]
                identity.displayPageIndex != visible[index] ||
                    identity.displayPageIndex < 0 || identity.sourcePageIndex < 0 ||
                    identity.normalizedEpisodePath.isBlank() ||
                    identity.canonicalAsset.isBlank() || identity.manifestDigest.isBlank() ||
                    identity.manifestPageCount <= identity.sourcePageIndex
            }
        ) return

        val velocity = synchronized(stateLock) {
            if (proof.surfaceLifecycleEpoch != lifecycleEpoch ||
                proof.physicalGestureRevision <= 0L ||
                proof.physicalGestureRevision != physicalGestureRevision ||
                !proof.scrollOffsetPx.isFinite() ||
                presentedNanos <= nativeCadenceProofPresentedNanos
            ) return@synchronized null
            val sameGesture =
                nativeCadenceProofGestureRevision == proof.physicalGestureRevision
            val continuedGesture = isContinuousNativeCadenceGesturePair(
                previousProofGesture = nativeCadenceProofGestureRevision,
                currentProofGesture = proof.physicalGestureRevision,
                continuationFromGesture = nativeCadenceContinuationFromGestureRevision,
                continuationToGesture = nativeCadenceContinuationToGestureRevision,
            )
            val sameMotion = nativeCadenceProofLifecycleEpoch == proof.surfaceLifecycleEpoch &&
                (sameGesture || continuedGesture) &&
                nativeCadenceProofPresentedNanos > 0L &&
                nativeCadenceProofScrollOffsetPx.isFinite()
            val elapsedNanos = presentedNanos - nativeCadenceProofPresentedNanos
            val result = if (sameMotion && elapsedNanos > 0L) {
                ((proof.scrollOffsetPx - nativeCadenceProofScrollOffsetPx).toDouble() *
                    1_000_000_000.0 / elapsedNanos.toDouble()).toFloat()
            } else {
                0f
            }
            nativeCadenceProofLifecycleEpoch = proof.surfaceLifecycleEpoch
            nativeCadenceProofGestureRevision = proof.physicalGestureRevision
            nativeCadenceProofPresentedNanos = presentedNanos
            nativeCadenceProofScrollOffsetPx = proof.scrollOffsetPx
            if (continuedGesture) {
                nativeCadenceContinuationFromGestureRevision = 0L
                nativeCadenceContinuationToGestureRevision = 0L
            }
            result
        } ?: return
        ViewerTelemetry.nativePresentationCadence(
            presentedNanos,
            velocity,
            cachedDisplayRefreshRate,
            proof.physicalInputOldestNanos,
            proof.physicalInputNewestNanos,
            proof.physicalInputReceivedOldestNanos,
            proof.physicalInputReceivedNewestNanos,
            proof.frameToken,
            proof.scrollOffsetPx,
            visible.first(),
            visible.last(),
            proof.producerCallbackStartedNanos,
            proof.expectedPresentationTimeNanos,
            when {
                proof.surfaceControlLatchObserved -> NATIVE_PRESENTATION_SURFACE_CONTROL
                proof.surfaceQueueSubmissionObserved -> NATIVE_PRESENTATION_BUFFER_QUEUE
                else -> NATIVE_PRESENTATION_NONE
            },
        )
    }

    /** Drains semantic transitions promptly while ordinary same-viewport frames remain bounded. */
    private fun drainCompletedDrawDispatch() {
        check(Looper.myLooper() == Looper.getMainLooper())
        if (!completedDrawDispatchQueue.beginRun()) return
        var deliveries = 0
        var repost: CompletedDrawDispatchQueue.Repost
        try {
            while (deliveries < MAX_COMPLETED_DRAW_DELIVERIES_PER_RUN) {
                val delivery = completedDrawDispatchQueue.pollReady(
                    SystemClock.elapsedRealtimeNanos(),
                ) ?: break
                val proof = delivery.proof
                // A pause, Surface replacement, or page-table mutation may retire a proof while
                // it waits in the bounded mailbox. Both identities must still match immediately
                // before the Activity can publish `actual:` semantics or reveal the native child.
                val lifecycleAndStructureCurrent = synchronized(stateLock) {
                    isCompletedDrawProofLifecycleCurrent(
                        proof.surfaceLifecycleEpoch,
                        lifecycleEpoch,
                    ) && proof.structureEpoch == traversalStructureEpoch
                }
                if (!lifecycleAndStructureCurrent) {
                    Log.w(
                        "ViewerPerf",
                        "reader_ntk_strict_proof_lifecycle_skip " +
                            "proofEpoch=${proof.surfaceLifecycleEpoch},currentEpoch=$lifecycleEpoch," +
                            "proofStructure=${proof.structureEpoch}," +
                            "currentStructure=$traversalStructureEpoch",
                    )
                }
                try {
                    if (lifecycleAndStructureCurrent) {
                        Trace.beginSection("ViewerCompletedDrawListener")
                        try {
                            listener?.onCompletedDraw(proof)
                        } finally {
                            Trace.endSection()
                        }
                        if (delivery.revealNativeSurface) {
                            revealNativeSurfaceAfterFirstHwuiCommit(
                                proof.surfaceLifecycleEpoch,
                            )
                        }
                    }
                } finally {
                    completedDrawDispatchQueue.recordDeliveryResult(
                        lifecycleAndStructureCurrent,
                        proof,
                    )
                }
                deliveries++
            }
        } finally {
            repost = completedDrawDispatchQueue.finishRun(
                SystemClock.elapsedRealtimeNanos(),
            )
        }
        if (!repost.shouldPost) return
        val accepted = if (repost.delayNanos <= 0L) {
            mainHandler.post(completedDrawDispatchRunnable)
        } else {
            val delayMillis = ceil(repost.delayNanos / 1_000_000.0)
                .toLong()
                .coerceAtLeast(1L)
            mainHandler.postDelayed(completedDrawDispatchRunnable, delayMillis)
        }
        if (!accepted) completedDrawDispatchQueue.onPostRejected()
    }

    /**
     * Stops benchmark input from the native-present producer instead of waiting behind the main
     * listener queue. The benchmark receiver still requires the later strict Activity/UI proof
     * and its identical presented timestamp, so this fast candidate cannot weaken qualification.
     * The non-benchmark implementation returns false and R8 removes this path from release.
     */
    private fun publishBenchmarkAdjacentP0CandidateIfEligible(proof: CompletedDrawProof) {
        if (!BenchmarkAdjacentCommitSignal.isEnabled()) return
        val presentedAtNanos = proof.presentedUptimeNanos
        if (presentedAtNanos <= 0L || proof.frameToken <= 0L || proof.drawnVersion <= 0L ||
            proof.committedVersion < proof.drawnVersion || proof.structureEpoch <= 0L
        ) return
        val exactPresentationProofs = listOf(
            proof.hardwareAccelerated && proof.registeredHwuiFrameCommitCallbackObserved,
            proof.surfaceQueueSubmissionObserved,
            proof.surfaceControlLatchObserved,
        ).count { it }
        if (exactPresentationProofs != 1) return
        val coverage = proof.coverage
        if (coverage.physicalViewportPx <= 0 ||
            coverage.viewportPx < coverage.physicalViewportPx ||
            coverage.drawablePx < coverage.physicalViewportPx ||
            coverage.drawableItems <= 0 || coverage.missingPx != 0 ||
            coverage.placeholderPx != 0 || coverage.visibleLoading != 0 ||
            coverage.visibleErrors != 0 || coverage.widthFillFailures != 0 ||
            coverage.lowResolutionItems != 0
        ) return
        val lifecycleAndStructureCurrent = synchronized(stateLock) {
            proof.surfaceLifecycleEpoch == lifecycleEpoch &&
                proof.structureEpoch == traversalStructureEpoch
        }
        if (!lifecycleAndStructureCurrent) return
        val visible = proof.visiblePageIndexes
            .filter { it >= 0 }
            .distinct()
            .sorted()
        val identities = proof.visiblePageIdentities
        if (visible.isEmpty() || identities.size != visible.size ||
            identities.map { it.displayPageIndex } != visible
        ) return
        val generation = ViewerTelemetry.activeGeneration()
        if (generation <= 0L) return
        identities.asSequence()
            .filter { it.sourcePageIndex == 0 }
            .forEach { identity ->
                BenchmarkAdjacentCommitSignal.publish(
                    identity.normalizedEpisodePath,
                    identity.sourcePageIndex,
                    presentedAtNanos,
                    generation,
                )
            }
    }

    private fun releasePostedAdmissionLocked(preserveDirty: Boolean) {
        unregisterInFlightCommitPreDrawListenerLocked()
        framePipe = FramePipe.IDLE
        inFlightToken = 0L
        inFlightEpoch = 0L
        inFlightCommitCallback = null
        inFlightCommitCallbackRegistered = false
        inFlightInvalidationPostedNs = 0L
        if (preserveDirty && pages.isNotEmpty()) {
            renderRequested = true
        }
    }

    /** Must be called with [stateLock] held. */
    private fun unregisterInFlightCommitPreDrawListenerLocked() {
        val listener = inFlightCommitPreDrawListener ?: return
        inFlightCommitPreDrawListener = null
        val remove = Runnable {
            val observer = viewTreeObserver
            if (observer.isAlive) observer.removeOnPreDrawListener(listener)
        }
        if (Looper.myLooper() == Looper.getMainLooper()) {
            remove.run()
        } else {
            mainHandler.post(remove)
        }
    }

    private fun latestSubmittedVersionLocked(): Long {
        var latest = committedVersion
        for (submission in pendingFrameCommits.values) {
            latest = maxOf(latest, submission.proof.drawnVersion)
        }
        return latest
    }

    private fun hasFrameWorkLocked(): Boolean {
        return framePipe != FramePipe.IDLE || inFlightToken != 0L || pendingFrameCommits.isNotEmpty()
    }

    private fun scheduleNoStateRetryLocked() {
        if (noStateRetryPosted || !renderRunning || pages.isEmpty()) return
        val nowMs = SystemClock.uptimeMillis()
        if (nowMs - lastNoStateReasonLogMs >= 1_000L) {
            lastNoStateReasonLogMs = nowMs
            Log.d(
                TAG,
                "reader_draw_state_retry reason=$lastDrawStateNullReason," +
                    "requested=$renderRequested,versions=$desiredVersion/$drawnVersion/$committedVersion," +
                    "scroll=${fmt(scrollOffset)},pages=${pages.size}",
            )
        }
        noStateRetryPosted = true
        noStateRetryGeneration += 1L
        if (noStateRetryGeneration <= 0L) noStateRetryGeneration = 1L
        val retryGeneration = noStateRetryGeneration
        // A direct-surface failure is produced on ReaderSurfaceProducer. Posting its sole wakeup
        // to main can strand dirty demand behind a burst of structure/install callbacks even
        // though the producer Looper and native worker are idle. Keep the retry on the producer
        // owner when that lifecycle is live; the fallback/HWUI path remains main-owned.
        val retryHandler = if (
            directSurfaceReady && directRenderHandler != null &&
            rollingNativeHandle != 0L && rollingNativeAttachEpoch > 0L
        ) {
            checkNotNull(directRenderHandler)
        } else {
            mainHandler
        }
        val retry = Runnable {
            synchronized(stateLock) {
                if (!noStateRetryPosted || noStateRetryGeneration != retryGeneration) {
                    return@synchronized
                }
                noStateRetryPosted = false
                noStateRetryGeneration += 1L
                if (!renderRunning || frameSchedulingSuppressed || pages.isEmpty()) return@synchronized
                if (!renderRequested && desiredVersion <= committedVersion && scroller.isFinished) {
                    return@synchronized
                }
                scheduleFrameLocked()
            }
        }
        val posted = retryHandler.postDelayed(retry, NO_STATE_FRAME_RETRY_MS)
        val backupPosted = retryHandler !== mainHandler && runCatching {
            NO_STATE_RETRY_EXECUTOR.schedule(
                retry,
                NO_STATE_FRAME_RETRY_MS + 17L,
                TimeUnit.MILLISECONDS,
            )
            true
        }.getOrDefault(false)
        if (!posted && !backupPosted) noStateRetryPosted = false
    }

    private fun clearFramePipeLocked(preserveDirty: Boolean) {
        // Remove only this dispatcher's wakeup before releasing its scheduled owner. A callback
        // already running keeps runnerRunning=true and will either consume a new-lifecycle offer
        // or atomically release ownership, so lifecycle teardown cannot create a lost wakeup.
        mainHandler.removeCallbacks(completedDrawDispatchRunnable)
        completedDrawDispatchQueue.clearAfterScheduledCallbackRemoval()
        mainHandler.removeCallbacks(nativeSurfaceRevealDispatchRunnable)
        nativeSurfaceRevealDispatchGate.clear()
        mainHandler.removeCallbacks(visibleCoverageDispatchRunnable)
        pendingVisibleCoverageDelivery = null
        visibleCoverageDispatchPosted = false
        lifecycleEpoch++
        if (lifecycleEpoch <= 0L) lifecycleEpoch = 1L
        val callback = inFlightCommitCallback
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q &&
            callback != null && inFlightCommitCallbackRegistered
        ) {
            val observer = viewTreeObserver
            if (observer.isAlive) observer.unregisterFrameCommitCallback(callback)
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q && pendingFrameCommits.isNotEmpty()) {
            val observer = viewTreeObserver
            if (observer.isAlive) {
                for (submission in pendingFrameCommits.values) {
                    if (submission.callbackRegistered) {
                        observer.unregisterFrameCommitCallback(submission.callback)
                    }
                }
            }
        }
        pendingFrameCommits.clear()
        earlyNativeOutcomes.clear()
        earlyFrameSyncedGeometryRequests.clear()
        frameSyncedGeometryInFlightTokens.clear()
        frameSyncedGeometrySubmissionOrder.clear()
        releasePostedAdmissionLocked(preserveDirty = false)
        drawnVersion = committedVersion
        if (preserveDirty && pages.isNotEmpty()) {
            renderRequested = true
            pendingPixelReasons = pendingPixelReasons or DIRTY_INVALIDATION
        } else if (!preserveDirty) {
            renderRequested = false
            pendingPixelReasons = 0
            pendingPixelMutationWatermark = 0L
            pendingPixelMutationOldestNs = 0L
            pendingPixelMutationNewestNs = 0L
            pendingPixelMutationReasons = 0
        }
    }

    private fun shouldFinishScrollerAtInputEdgeLocked(direction: Int, rawNext: Float): Boolean {
        if (direction == 0 || pages.isEmpty() || height <= 0) return false
        return when (direction) {
            DIRECTION_NEXT -> {
                val maxScroll = effectiveMaxScrollLocked(maxScrollLocked())
                scrollOffset >= maxScroll - BOUNDARY_EPSILON_PX &&
                    rawNext >= maxScroll - BOUNDARY_EPSILON_PX
            }
            DIRECTION_PREVIOUS -> {
                scrollOffset <= BOUNDARY_EPSILON_PX &&
                    rawNext <= BOUNDARY_EPSILON_PX
            }
            else -> {
                false
            }
        }
    }

    /**
     * The reader owns a Surface producer that is independent from ViewRoot's window buffer.
     * Creating this lane only after the View is attached keeps cold-entry work demand-bound while
     * preventing RenderThread/BLAST backpressure from blocking input delivery on the main thread.
     */
    private fun createAsyncHandlerCompat(looper: Looper): Handler =
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            Handler.createAsync(looper)
        } else {
            Handler(looper)
        }

    private fun startRenderThreadLocked() {
        if (directRenderThread != null) return
        primeDeferredNativeSceneSubmissionPool()
        primeDeferredNativeGeometryPool()
        val thread = HandlerThread(
            "ReaderSurfaceProducer",
            if (emulatorNativeSurfaceRuntime) {
                // Perfetto showed both main input and this producer runnable for 100+ ms while
                // the native renderer/instrumentation owners at URGENT_DISPLAY kept running.
                // They form one display-critical chain, so keep their scheduler class equal.
                NATIVE_SURFACE_PRODUCER_THREAD_PRIORITY
            } else {
                Process.THREAD_PRIORITY_URGENT_DISPLAY
            }
        )
        thread.start()
        // Choreographer installs a sync barrier while awaiting the display pulse. Recovery and
        // cadence-watchdog messages are precisely what must run when that pulse is lost; a normal
        // Handler leaves them trapped behind the barrier indefinitely. The producer owns no UI
        // ordering contract, so make all of its control messages asynchronous.
        val handler = createAsyncHandlerCompat(thread.looper)
        directRenderThread = thread
        directRenderHandler = handler
        val commitThread = HandlerThread(
            "ReaderSurfaceCommit",
            // This lane is the second half of the display chain: an admitted geometry command must
            // reach SurfaceControl before the same vsync deadline. The producer uses the still
            // higher urgent-audio nice value below, so commit cannot preempt frame construction;
            // keeping commit merely at DISPLAY instead let default/VM work postpone an already
            // complete frame for 100+ ms.
            Process.THREAD_PRIORITY_URGENT_DISPLAY,
        ).apply { start() }
        frameSyncedGeometryCommitThread = commitThread
        frameSyncedGeometryCommitHandler = createAsyncHandlerCompat(commitThread.looper)
        val ackThread = HandlerThread(
            "ReaderSurfaceLatch",
            // This lane performs no rendering or JNI work. It only retires an already-committed
            // SurfaceFlinger identity, so sharing it with scene submission would turn a prompt
            // compositor callback into a false 100-1000 ms presentation interval.
            Process.THREAD_PRIORITY_URGENT_DISPLAY,
        ).apply { start() }
        frameSyncedGeometryAckThread = ackThread
        frameSyncedGeometryAckHandler = createAsyncHandlerCompat(ackThread.looper)
        val prewarmThread = HandlerThread(
            "ReaderSurfacePrewarm",
            Process.THREAD_PRIORITY_BACKGROUND,
        ).apply { start() }
        nativeTexturePrewarmThread = prewarmThread
        nativeTexturePrewarmHandler = createAsyncHandlerCompat(prewarmThread.looper)
        handler.post {
            synchronized(stateLock) {
                if (directRenderThread !== thread) return@synchronized
                directChoreographer = Choreographer.getInstance()
                if (framePipe == FramePipe.INVALIDATION_POSTED && inFlightToken != 0L) {
                    postDirectFrameCallbackLocked()
                }
                stateLock.notifyAll()
            }
        }
    }

    private fun computeNativeRenderTargetSizeLocked(
        viewportWidth: Int,
        viewportHeight: Int
    ): Pair<Int, Int> {
        var widestKnownSourceWidth = 0
        for (page in pages) {
            widestKnownSourceWidth = max(widestKnownSourceWidth, page.width)
            page.bitmap?.let { bitmap ->
                if (!bitmap.isRecycled) {
                    widestKnownSourceWidth = max(widestKnownSourceWidth, bitmap.width)
                }
            }
            for (tile in page.tiles) {
                widestKnownSourceWidth = max(widestKnownSourceWidth, tile.sourceWidth)
            }
        }
        val viewportTarget = sourceNativeRenderTargetSize(
            sourceNativeWebtoonCompositingEnabled,
            viewportWidth,
            viewportHeight,
            widestKnownSourceWidth
        )
        if (!emulatorNativeSurfaceRuntime) return viewportTarget
        // The host SurfaceControl backend presents one immutable rolling band and advances
        // ordinary physical input by changing only its source crop. Size the band by bytes rather
        // than a fixed viewport count: a fixed nine-screen target is cheap on a small emulator but
        // is roughly 50 MiB per AHardwareBuffer at this reader's 800x1733 source viewport. Two such
        // targets plus textures can monopolize the host GL translator and deschedule even the
        // urgent display producer. A three-viewport band is also too short: a 100-900 ms host GPU
        // composition can finish after physical input has already crossed its two-screen runway,
        // immediately forcing another full composition. Perfetto then showed that a six-screen,
        // ~33 MiB target made gfxstream stop a guest vCPU inside otherwise constant-time producer
        // bookkeeping and took 393 ms to prepare one successor (100 ms upload plus 74 ms fence
        // export). Four common viewports retain the same two complete forward screens while
        // cutting each target/import by one third. Cap small displays at six; this remains
        // independent of episode length and unusually tall webtoon chapters.
        val rollingBandViewports = emulatorNativeBandViewportCount(
            viewportTarget.first,
            viewportTarget.second,
        )
        val rollingBandHeight = min(
            EMULATOR_NATIVE_MAX_BAND_HEIGHT_PX.toLong(),
            viewportTarget.second.toLong() * rollingBandViewports.toLong(),
        ).coerceAtLeast(viewportTarget.second.toLong()).toInt()
        return Pair(viewportTarget.first, rollingBandHeight)
    }

    /** Captures target dimensions only; it cannot allocate, attach, upload or publish pixels. */
    private fun captureNativeRenderTargetGeometryLocked(
        viewportWidth: Int,
        viewportHeight: Int,
    ) {
        if (!rollingNativePresentationEnabled || rollingNativeAttachEpoch != 0L ||
            viewportWidth <= 0 || viewportHeight <= 0 ||
            (rollingNativeFrozenViewportWidth == viewportWidth &&
                rollingNativeFrozenViewportHeight == viewportHeight &&
                rollingNativeFrozenTargetWidth > 0 && rollingNativeFrozenTargetHeight > 0)
        ) return
        val target = computeNativeRenderTargetSizeLocked(viewportWidth, viewportHeight)
        rollingNativeFrozenViewportWidth = viewportWidth
        rollingNativeFrozenViewportHeight = viewportHeight
        rollingNativeFrozenTargetWidth = target.first
        rollingNativeFrozenTargetHeight = target.second
        Log.d(
            TAG,
            "reader_native_target_geometry_frozen render=${target.first}x${target.second} " +
                "viewport=${viewportWidth}x$viewportHeight"
        )
    }

    private fun nativeRenderTargetSizeLocked(
        viewportWidth: Int,
        viewportHeight: Int,
    ): Pair<Int, Int> {
        if (rollingNativeFrozenViewportWidth == viewportWidth &&
            rollingNativeFrozenViewportHeight == viewportHeight &&
            rollingNativeFrozenTargetWidth > 0 && rollingNativeFrozenTargetHeight > 0
        ) {
            return Pair(rollingNativeFrozenTargetWidth, rollingNativeFrozenTargetHeight)
        }
        return computeNativeRenderTargetSizeLocked(viewportWidth, viewportHeight)
    }

    /**
     * Queues the production GPU target allocation while the strict SurfaceView is still detached.
     * There is intentionally no Surface or Bitmap argument: this can allocate render targets but
     * cannot attach, submit, or draw before actual image pixels are ready.
     */
    private fun prepareRollingNativeRenderTargetsLocked(
        viewportWidth: Int,
        viewportHeight: Int
    ) {
        val target = nativeRenderTargetSizeLocked(viewportWidth, viewportHeight)
        if (!renderRunning || rollingNativeFatal ||
            rollingNativeHandle == 0L || rollingNativeAttachEpoch != 0L ||
            viewportWidth <= 0 || viewportHeight <= 0 ||
            (rollingNativePreparedWidth == target.first &&
                rollingNativePreparedHeight == target.second)
        ) return
        val handle = rollingNativeHandle
        val accepted = try {
            NtkRollingNativeBridge.nativePrepare(handle, target.first, target.second)
        } catch (failure: Throwable) {
            Log.e(
                TAG,
                "reader_native_targets_prepare_failed render=${target.first}x${target.second} " +
                    "viewport=${viewportWidth}x$viewportHeight",
                failure
            )
            false
        }
        if (accepted && rollingNativeHandle == handle && rollingNativeAttachEpoch == 0L) {
            rollingNativePreparedWidth = target.first
            rollingNativePreparedHeight = target.second
            Log.d(
                TAG,
                "reader_native_targets_prepare_queued render=${target.first}x${target.second} " +
                    "viewport=${viewportWidth}x$viewportHeight"
            )
        }
    }

    /**
     * Starts the native renderer/EGL lane only after a complete exact HWUI viewport committed.
     * It cannot delay the first actual pixels and never submits a placeholder/fake frame. Must be
     * called with [stateLock] held.
     */
    private fun prepareRollingNativeRendererLocked() {
        if (!rollingNativePresentationEnabled || !renderRunning || rollingNativeFatal ||
            rollingNativeHandle != 0L ||
            rollingNativeCreatePending
        ) return
        val handler = directRenderHandler ?: return
        rollingNativeCreatePending = true
        rollingNativeCreateGeneration += 1L
        if (rollingNativeCreateGeneration <= 0L) rollingNativeCreateGeneration = 1L
        val generation = rollingNativeCreateGeneration
        Log.d(TAG, "reader_native_cold_prepare_started generation=$generation")
        val posted = handler.post {
            val createdHandle = try {
                NtkRollingNativeBridge.nativeCreate(
                    this,
                    generation,
                    directWifiExpandedNativeTextureRunway,
                    emulatorNativeSurfaceRuntime,
                )
            } catch (failure: Throwable) {
                Log.e(TAG, "reader_native_cold_prepare_failed generation=$generation", failure)
                0L
            }
            val installed = synchronized(stateLock) {
                val ownsAttempt = rollingNativeCreatePending &&
                    rollingNativeCreateGeneration == generation
                // nativeCreate returns after starting the EGL owner. A very fast worker failure
                // can post its main callback before this producer installs the returned pointer;
                // sample the renderer's atomic fatal bit while stateLock prevents that callback
                // from observing a transient handle=0. A failure after this sample is ordered
                // behind the handle installation and is accepted by the normal identity fence.
                val failedBeforeInstall = createdHandle != 0L &&
                    NtkRollingNativeBridge.nativeHasFailed(createdHandle)
                if (ownsAttempt) rollingNativeCreatePending = false
                if (ownsAttempt && renderRunning && isAttachedToWindow &&
                    !rollingNativeFatal && rollingNativeHandle == 0L && createdHandle != 0L &&
                    !failedBeforeInstall
                ) {
                    rollingNativeHandle = createdHandle
                    NtkRollingNativeBridge.nativeSetDirectWifiTextureProfile(
                        createdHandle,
                        directWifiExpandedNativeTextureRunway,
                        emulatorNativeSurfaceRuntime,
                    )
                    if (nativeTexturePrewarmPaused) {
                        NtkRollingNativeBridge.nativeSetPrewarmPaused(createdHandle, true)
                    }
                    val prepareWidth = width
                    val prepareHeight = height
                    if (prepareWidth > 0 && prepareHeight > 0) {
                        // The first complete exact HWUI viewport has already committed. Allocate
                        // the fixed AHB ring without competing with the first real frame.
                        prepareRollingNativeRenderTargetsLocked(prepareWidth, prepareHeight)
                    }
                    stateLock.notifyAll()
                    true
                } else {
                    if (ownsAttempt && (createdHandle == 0L || failedBeforeInstall)) {
                        rollingNativeFatal = true
                    }
                    stateLock.notifyAll()
                    false
                }
            }
            if (!installed) {
                if (createdHandle != 0L) NtkRollingNativeBridge.nativeDestroy(createdHandle)
                return@post
            }
            Log.d(TAG, "reader_native_cold_prepare_completed generation=$generation")
            synchronized(stateLock) {
                // A very fast response may have installed pixels during EGL creation. Preserve
                // the same demand-bounded behavior by enqueueing only those resident pages now.
                postResidentNativeTexturePrewarmLocked()
            }
            mainHandler.post {
                val revealEpoch = synchronized(stateLock) {
                    nativeSurfaceRevealAfterPrepareEpoch
                }
                if (revealEpoch > 0L) {
                    revealNativeSurfaceAfterFirstHwuiCommit(revealEpoch)
                } else {
                    attachPreparedRollingNativeSurfaceIfReady(generation)
                }
            }
        }
        if (!posted) {
            rollingNativeCreatePending = false
            rollingNativeCreateGeneration += 1L
            Log.w(TAG, "reader_native_cold_prepare_post_rejected generation=$generation")
        }
    }

    private fun attachPreparedRollingNativeSurfaceIfReady(generation: Long) {
        val ready = synchronized(stateLock) {
            val surface = rollingTextureSurface
            if (rollingNativeCreateGeneration != generation || !renderRunning ||
                !isAttachedToWindow || !directSurfaceReady || surface?.isValid != true ||
                rollingNativeHandle == 0L
            ) return@synchronized null
            Triple(checkNotNull(surface), width, height)
        } ?: return
        attachRollingNativeSurface(ready.first, ready.second, ready.third)
    }

    /** Must be called with [stateLock] held. Keeps the producer thread but retires one Surface. */
    private fun retireDirectSurfaceSchedulingLocked() {
        physicalMoveMailbox.endGesture()
        directRenderHandler?.removeCallbacks(physicalMoveDrainRunnable)
        directRenderHandler?.removeCallbacks(nativeMailboxAdmissionWakeRunnable)
        nativeMailboxAdmissionWakePosted.set(false)
        directRenderHandler?.removeCallbacks(directFramePostRunnable)
        directRenderHandler?.removeCallbacks(directEmulatorFrameRunnable)
        directCadenceDeadlineGate.clear()
        directRenderHandler?.removeCallbacks(directLateInputCatchup)
        directRenderHandler?.removeCallbacks(directAdjacentExactP0Catchup)
        val choreographer = directChoreographer
        if (choreographer != null && directFrameCallbackPosted) {
            removeReservedDirectDisplayCallback(choreographer)
        }
        nativeTexturePrewarmHandler?.removeCallbacks(::flushResidentNativeTexturePrewarm)
        directFrameCallbackPosted = false
        directLateInputCatchupPosted = false
        directAdjacentExactP0CatchupPosted = false
        directAdjacentExactP0CatchupEpoch = 0L
        directAdjacentExactP0CatchupToken = 0L
        directAdjacentExactP0CatchupAttachEpoch = 0L
        directAdjacentExactP0CatchupOwner = null
        directCallbackObservedDragTargetRevision = 0L
        directCallbackObservedPhysicalGestureRevision = 0L
        directCallbackObservedAtNanos = 0L
        directCallbackHadAdmission = false
        directEmulatorNextFrameDeadlineNanos = 0L
    }

    private fun stopRenderThreadLocked(): HandlerThread? {
        val thread = directRenderThread ?: return null
        retireDirectSurfaceSchedulingLocked()
        frameSyncedGeometryCommitThread?.quitSafely()
        frameSyncedGeometryCommitHandler = null
        frameSyncedGeometryCommitThread = null
        frameSyncedGeometryAckThread?.quitSafely()
        frameSyncedGeometryAckHandler = null
        frameSyncedGeometryAckThread = null
        nativeTexturePrewarmThread?.quitSafely()
        nativeTexturePrewarmHandler = null
        nativeTexturePrewarmThread = null
        directChoreographer = null
        directRenderHandler = null
        directRenderThread = null
        return thread
    }

    private val directFrameCallback: Choreographer.FrameCallback =
        Choreographer.FrameCallback { frameTimeNanos ->
        Trace.beginSection("ViewerDirectChoreographer")
        try {
            renderDirectSurfaceFrame(frameTimeNanos)
        } finally {
            Trace.endSection()
        }
    }

    private fun removeReservedDirectDisplayCallback(choreographer: Choreographer) {
        if (emulatorNativeSurfaceRuntime) {
            directRenderHandler?.removeCallbacks(directEmulatorFrameRunnable)
        } else {
            choreographer.removeFrameCallback(directFrameCallback)
        }
    }

    /**
     * The host emulator's display-event receiver can stall even while this urgent producer is
     * runnable. Submit the one real reserved frame from an absolute producer deadline instead of
     * waiting in that Binder-backed ingress. Native still queues the real buffer transaction and
     * its compositor callback remains the only presentation proof.
     */
    private val directEmulatorFrameRunnable = Runnable {
        val nowNanos = System.nanoTime()
        val scheduled = synchronized(stateLock) {
            if (!directFrameCallbackPosted || !renderRunning || !directSurfaceReady ||
                directChoreographer == null
            ) {
                null
            } else {
                val periodNanos = directFramePeriodNanos()
                val expectedPresentationNanos = maxOf(
                    directEmulatorNextFrameDeadlineNanos,
                    nowNanos + DIRECT_EMULATOR_PRODUCER_WAKE_AHEAD_NANOS,
                )
                Pair(expectedPresentationNanos - periodNanos, expectedPresentationNanos)
            }
        } ?: return@Runnable
        val frameTimeNanos = scheduled.first
        val expectedPresentationNanos = scheduled.second
        Trace.beginSection("ViewerDirectEmulatorDeadline")
        try {
            renderDirectSurfaceFrame(
                frameTimeNanos,
                expectedPresentationTimeNanos = expectedPresentationNanos,
            )
        } finally {
            Trace.endSection()
        }
    }

    /**
     * A MOVE can reach the main thread just after the producer callback observed the prior target
     * and re-armed itself for the next vsync. Execute at most one producer-loop catch-up for that
     * exact revision race. If a due Choreographer callback observes the MOVE first, the revision
     * check turns this runnable into a no-op.
     */
    private val directLateInputCatchup: Runnable = Runnable {
        Trace.beginSection("ViewerDirectLateInputCatchup")
        try {
            val shouldRender = synchronized(stateLock) {
                directLateInputCatchupPosted = false
                val targetStillUnobserved =
                    dragTargetRevision != directCallbackObservedDragTargetRevision
                val newGestureTargetStillUnobserved =
                    physicalGestureRevision != directCallbackObservedPhysicalGestureRevision
                val canReplaceCallback = renderRunning && directSurfaceReady &&
                    directFrameCallbackPosted && pointerDown && dragging &&
                    (!directCallbackHadAdmission || newGestureTargetStillUnobserved) &&
                    targetStillUnobserved &&
                    rollingNativeHandle != 0L &&
                    rollingNativeAttachEpoch > 0L &&
                    rollingTextureSurface?.isValid == true
                if (canReplaceCallback) {
                    directChoreographer?.let(::removeReservedDirectDisplayCallback)
                    directRenderHandler?.removeCallbacks(directFramePostRunnable)
                    directFrameCallbackPosted = false
                }
                canReplaceCallback
            }
            if (shouldRender) {
                renderDirectSurfaceFrame(System.nanoTime())
            }
        } finally {
            Trace.endSection()
        }
    }

    /** Replaces one pending producer callback for the exact content token captured at install. */
    private val directAdjacentExactP0Catchup: Runnable = Runnable {
        Trace.beginSection("ViewerDirectAdjacentExactP0Catchup")
        try {
            val shouldRender = synchronized(stateLock) {
                val expectedEpoch = directAdjacentExactP0CatchupEpoch
                val expectedToken = directAdjacentExactP0CatchupToken
                val expectedAttachEpoch = directAdjacentExactP0CatchupAttachEpoch
                val expectedOwner = directAdjacentExactP0CatchupOwner
                directAdjacentExactP0CatchupPosted = false
                directAdjacentExactP0CatchupEpoch = 0L
                directAdjacentExactP0CatchupToken = 0L
                directAdjacentExactP0CatchupAttachEpoch = 0L
                directAdjacentExactP0CatchupOwner = null
                val ownerStillAuthorized = expectedOwner != null &&
                    directWifiExpandedNativeTextureRunway &&
                    expectedOwner.normalizedEpisodePath in
                        directWifiExpandedNativeTextureEpisodePaths &&
                    pages.any { it.adjacentExactOwner == expectedOwner }
                val canReplaceCallback = emulatorNativeSurfaceRuntime && renderRunning &&
                    directSurfaceReady && !frameSchedulingSuppressed &&
                    directFrameCallbackPosted && !directLateInputCatchupPosted &&
                    ownerStillAuthorized &&
                    framePipe == FramePipe.INVALIDATION_POSTED &&
                    inFlightEpoch == expectedEpoch && inFlightToken == expectedToken &&
                    expectedToken != 0L && rollingNativeAttachEpoch == expectedAttachEpoch &&
                    expectedAttachEpoch > 0L && rollingNativeHandle != 0L &&
                    !rollingNativeFatal && rollingTextureSurface?.isValid == true
                if (canReplaceCallback) {
                    directChoreographer?.let(::removeReservedDirectDisplayCallback)
                    // scheduleFrameLocked may still have its registration message queued. Remove
                    // it before renderDirectSurfaceFrame reserves the moving successor; otherwise
                    // the stale message can register that successor a second time.
                    directRenderHandler?.removeCallbacks(directFramePostRunnable)
                    directFrameCallbackPosted = false
                }
                canReplaceCallback
            }
            if (shouldRender) renderDirectSurfaceFrame(System.nanoTime())
        } finally {
            Trace.endSection()
        }
    }

    /**
     * A host-backed emulator can occasionally stop delivering producer-thread Choreographer
     * callbacks for 60-100 ms even though EGL submission, app CPU and the main thread are idle.
     * Keep the device Choreographer path unchanged. The emulator uses its producer Handler as the
     * cadence authority, while this deadline remains a demand-bounded recovery guard for either
     * path. No callback is fabricated while the reader is stationary. The Handler side owns one
     * moving deadline; normal frames only update that O(1) gate and never scan the MessageQueue.
     */
    private fun armDirectCadenceWatchdog(expectedChoreographer: Choreographer) {
        val delayMs = directCadenceWatchdogDelayMs()
        var ownerHandler: Handler? = null
        val reservation = synchronized(stateLock) {
            // Bind the owner reservation to the same producer lifecycle as the callback. Without
            // this lock, teardown could clear the gate and retire the old Looper between reading
            // directRenderHandler and arming it, leaving a new lifecycle behind a dropped owner.
            if (expectedChoreographer !== directChoreographer ||
                !directFrameCallbackPosted || !renderRunning || !directSurfaceReady
            ) {
                return@synchronized 0L
            }
            ownerHandler = directRenderHandler ?: return@synchronized 0L
            directCadenceDeadlineGate.arm(SystemClock.uptimeMillis(), delayMs)
        }
        if (reservation == 0L) return
        val handler = ownerHandler ?: run {
            directCadenceDeadlineGate.onPostRejected(reservation)
            return
        }
        val wakeup = object : Runnable {
            override fun run() {
                drainDirectCadenceWatchdog(reservation, this)
            }
        }
        if (!handler.postDelayed(wakeup, delayMs)) {
            directCadenceDeadlineGate.onPostRejected(reservation)
        }
    }

    private fun drainDirectCadenceWatchdog(reservation: Long, wakeup: Runnable) {
        when (val decision = directCadenceDeadlineGate.drain(
            reservation,
            SystemClock.uptimeMillis(),
        )) {
            NtkDirectCadenceDeadlineGate.DrainDecision.Stale -> return
            is NtkDirectCadenceDeadlineGate.DrainDecision.Repost -> {
                val handler = directRenderHandler
                if (handler == null || !handler.postDelayed(wakeup, decision.delayMs)) {
                    directCadenceDeadlineGate.onPostRejected(reservation)
                }
                return
            }
            is NtkDirectCadenceDeadlineGate.DrainDecision.Due -> {
                recoverOverdueDirectCadence(decision.generation)
            }
        }
    }

    private fun recoverOverdueDirectCadence(generation: Long) {
        Trace.beginSection("ViewerDirectCadenceWatchdog")
        try {
            val shouldRecover = synchronized(stateLock) {
                if (!directCadenceDeadlineGate.isCurrentGeneration(generation) ||
                    !directFrameCallbackPosted
                ) {
                    false
                } else {
                    val hasAdmittedFrame =
                        framePipe == FramePipe.INVALIDATION_POSTED && inFlightToken != 0L
                    val hasCurrentDemand = hasAdmittedFrame || shouldKeepDirectCadenceArmedLocked()
                    val canRender = renderRunning && directSurfaceReady &&
                        rollingTextureSurface?.isValid == true

                    directChoreographer?.let(::removeReservedDirectDisplayCallback)
                    directFrameCallbackPosted = false
                    canRender && hasCurrentDemand
                }
            }
            if (shouldRecover) {
                renderDirectSurfaceFrame(System.nanoTime())
            }
        } finally {
            Trace.endSection()
        }
    }

    /**
     * Choreographer may enter DisplayEventReceiver/Binder while registering the next producer
     * vsync. Running that call while holding [stateLock] makes a real MOVE wait behind an emulator
     * display-service stall. Reserve the unique callback under the lock, then perform the platform
     * registration as the next producer-loop message with no reader state lock held.
     */
    private val directFramePostRunnable: Runnable = Runnable {
        val choreographer = synchronized(stateLock) {
            if (!directFrameCallbackPosted || !renderRunning || !directSurfaceReady) {
                null
            } else {
                directChoreographer
            }
        }
        if (choreographer == null) {
            synchronized(stateLock) {
                directFrameCallbackPosted = false
            }
            return@Runnable
        }
        postReservedDirectFrameCallback(choreographer)
    }

    /**
     * Registers an already-reserved callback without holding [stateLock].
     *
     * The generic path reaches this method through [directFramePostRunnable], because callers can
     * be on the main/session thread. The recurring producer callback invokes it directly after
     * releasing [stateLock], so decoded-image/prewarm messages already queued on the same Looper
     * cannot postpone the next display-vsync registration.
     */
    private fun postReservedDirectFrameCallback(choreographer: Choreographer) {
        val stillCurrent = synchronized(stateLock) {
            directFrameCallbackPosted && renderRunning && directSurfaceReady &&
                choreographer === directChoreographer
        }
        if (!stillCurrent) {
            synchronized(stateLock) {
                if (choreographer !== directChoreographer || !renderRunning || !directSurfaceReady) {
                    directFrameCallbackPosted = false
                }
            }
            return
        }
        try {
            if (emulatorNativeSurfaceRuntime) {
                val handler = directRenderHandler
                val nowNanos = System.nanoTime()
                val deadlineNanos = synchronized(stateLock) {
                    if (!directFrameCallbackPosted || !renderRunning || !directSurfaceReady ||
                        choreographer !== directChoreographer
                    ) {
                        0L
                    } else {
                        val periodNanos = directFramePeriodNanos()
                        val earliestDeadline =
                            nowNanos + DIRECT_EMULATOR_PRODUCER_WAKE_AHEAD_NANOS
                        var next = directEmulatorNextFrameDeadlineNanos
                        if (next <= 0L) next = nowNanos + periodNanos
                        while (next <= earliestDeadline) next += periodNanos
                        directEmulatorNextFrameDeadlineNanos = next
                        next
                    }
                }
                if (handler == null || deadlineNanos <= 0L) {
                    synchronized(stateLock) { directFrameCallbackPosted = false }
                    return
                }
                val wakeAheadNanos = DIRECT_EMULATOR_PRODUCER_WAKE_AHEAD_NANOS
                val delayNanos = (deadlineNanos - wakeAheadNanos - nowNanos).coerceAtLeast(0L)
                val wakeUptimeMillis = SystemClock.uptimeMillis() +
                    ((delayNanos + NANOS_PER_MILLISECOND - 1L) / NANOS_PER_MILLISECOND)
                if (!handler.postAtTime(directEmulatorFrameRunnable, wakeUptimeMillis)) {
                    synchronized(stateLock) { directFrameCallbackPosted = false }
                    return
                }
            } else {
                choreographer.postFrameCallback(directFrameCallback)
            }
            // The emulator has its own absolute producer deadline. Device Choreographer retains
            // the bounded recovery watchdog for a lost platform callback.
            if (!emulatorNativeSurfaceRuntime) armDirectCadenceWatchdog(choreographer)
        } catch (failure: Throwable) {
            synchronized(stateLock) {
                directFrameCallbackPosted = false
            }
            Log.e(TAG, "reader_direct_frame_callback_post_failed", failure)
        }
    }

    private fun postDirectFrameCallbackLocked(): Boolean {
        if (!renderRunning || !directSurfaceReady || directFrameCallbackPosted ||
            rollingNativeHandle == 0L || rollingNativeAttachEpoch == 0L
        ) return false
        val hasAdmittedFrame = framePipe == FramePipe.INVALIDATION_POSTED && inFlightToken != 0L
        if (!hasAdmittedFrame && !shouldKeepDirectCadenceArmedLocked()) return false
        val choreographer = directChoreographer ?: return false
        val handler = directRenderHandler ?: return false
        directFrameCallbackPosted = true
        // Validate the Choreographer here so teardown cannot reserve an impossible callback, but
        // make the platform call in directFramePostRunnable after stateLock has been released.
        if (choreographer !== directChoreographer || !handler.post(directFramePostRunnable)) {
            directFrameCallbackPosted = false
            return false
        }
        return true
    }

    private fun postLateDirectInputCatchupLocked(): Boolean {
        if (emulatorNativeSurfaceRuntime) {
            // The emulator already owns one VsyncCallback for every moving frame. Posting a
            // front-of-queue replacement for nearly every MOVE would submit a second transaction
            // in the same timeline. The reserved callback consumes the latest exact revision.
            return false
        }
        val refreshPeriodNanos =
            (frameBudgetMs() * NANOS_PER_MILLISECOND.toFloat()).toLong().coerceAtLeast(1L)
        if (!NtkLateInputCatchupPolicy.shouldPost(
                renderRunning = renderRunning,
                directSurfaceReady = directSurfaceReady,
                callbackPosted = directFrameCallbackPosted,
                callbackHadAdmission = directCallbackHadAdmission,
                catchupPosted = directLateInputCatchupPosted ||
                    directAdjacentExactP0CatchupPosted,
                newPhysicalGesture =
                    physicalGestureRevision != directCallbackObservedPhysicalGestureRevision,
                pointerDown = pointerDown,
                dragging = dragging,
                targetRevision = dragTargetRevision,
                callbackObservedTargetRevision = directCallbackObservedDragTargetRevision,
                callbackObservedAtNanos = directCallbackObservedAtNanos,
                nowNanos = System.nanoTime(),
                refreshPeriodNanos = refreshPeriodNanos
            )
        ) {
            return false
        }
        val handler = directRenderHandler ?: return false
        directLateInputCatchupPosted = true
        if (!handler.postAtFrontOfQueue(directLateInputCatchup)) {
            directLateInputCatchupPosted = false
            return false
        }
        return true
    }

    private fun shouldKeepDirectCadenceArmedLocked(): Boolean {
        return pointerDown || dragging || scrollbarDragging || !scroller.isFinished
    }

    /** Cheap admission hint; submitNativeFrame repeats full identity/pixel comparison. */
    private fun hasActiveNativeBandCropRunwayLocked(): Boolean {
        val active = activeNativeBandProof ?: return false
        if (active.handle != rollingNativeHandle || active.attachEpoch != rollingNativeAttachEpoch ||
            rollingNativeFatal ||
            !directSurfaceReady || width <= 0 ||
            activeNativeBandDirectValidatedSceneId != active.sceneId ||
            activeNativeBandDirectValidatedVisualGeneration != visualGeneration ||
            activeNativeBandDirectValidatedStructureEpoch != traversalStructureEpoch
        ) return false
        val scaleY = active.width.toFloat() / width.toFloat()
        val sourceTop = (scrollOffset - active.bandOrigin) * scaleY
        return sourceTop.isFinite() && sourceTop >= 0f &&
            sourceTop <= active.height - active.viewportSourceHeight
    }

    private fun renderDirectSurfaceFrame(
        frameTimeNanos: Long,
        frameTimelineVsyncId: Long = 0L,
        expectedPresentationTimeNanos: Long = 0L,
    ) {
        var nextFrameChoreographer: Choreographer? = null
        var admissionNativeHandle = 0L
        val admission = synchronized(stateLock) {
            directFrameCallbackPosted = false
            directCallbackHadAdmission = false
            if (!renderRunning || !directSurfaceReady || frameSchedulingSuppressed ||
                rollingTextureSurface?.isValid != true
            ) {
                null
            } else {
                // MotionEvent has already applied the exact physical finger position. This
                // callback may submit that position, but never invent an in-between viewport.
                directCallbackObservedDragTargetRevision = dragTargetRevision
                directCallbackObservedPhysicalGestureRevision = physicalGestureRevision
                directCallbackObservedAtNanos = System.nanoTime()
                // Request the next display callback before doing any draw/submission work. This is
                // important on the host-GPU emulator: requesting it near the end of this callback
                // frequently misses the next vsync even though native submission itself is <2ms.
                if (shouldKeepDirectCadenceArmedLocked() &&
                    !directFrameCallbackPosted &&
                    rollingNativeHandle != 0L &&
                    rollingNativeAttachEpoch > 0L
                ) {
                    directChoreographer?.let { choreographer ->
                        directFrameCallbackPosted = true
                        nextFrameChoreographer = choreographer
                    }
                }
                val admittedFrame = if (
                    framePipe == FramePipe.INVALIDATION_POSTED && inFlightToken != 0L
                ) {
                    admissionNativeHandle = rollingNativeHandle
                    inFlightEpoch to inFlightToken
                } else {
                    null
                }
                directCallbackHadAdmission = admittedFrame != null
                admittedFrame
            }
        }
        // This callback already runs on ReaderSurfaceProducer. Register the successor now, with no
        // reader lock held, rather than placing it behind image-install/prewarm messages in this
        // Looper's queue.
        nextFrameChoreographer?.let(::postReservedDirectFrameCallback)
        if (admission == null) {
            synchronized(stateLock) {
                // A sparse host/device MOVE can be physically committed before the next MOVE
                // arrives. There is then no frame to submit, so close only after every requested
                // viewport version has committed.
                if (shouldClosePhysicalMotionInterval(
                        traceActive = physicalScrollTraceCookie != 0,
                        scrollerFinished = scroller.isFinished,
                        requiredVersion = physicalMotionRequiredVersion,
                        committedVersion = committedVersion
                    )
                ) {
                    endPhysicalScrollTraceLocked()
                    statsLastCallbackStartNs = 0L
                    statsLastPostEndNs = 0L
                    statsLastCallbackGestureRevision = 0L
                    statsLastCallbackMotionCookie = 0
                }
            }
            return
        }

        // Native owns one bounded pending command. Kotlin coalesces every newer absolute input
        // position while that slot is occupied instead of accepting and then retiring a real
        // proof. A posted deferred command counts as occupied before it reaches JNI, closing the
        // producer-vs-commit-Looper race. The next moving deadline or prior presentation callback
        // retries this same still-admitted token without manufacturing a dropped frame.
        val deferredCommandCount = deferredNativeCommandsInFlight.get()
        val noDeferredCommand = deferredCommandCount == 0
        val nativeCapacityReady = !firstNativeSubmitAccepted ||
            (admissionNativeHandle != 0L && runCatching {
                NtkRollingNativeBridge.nativeHasFrameMailboxCapacity(admissionNativeHandle)
            }.getOrDefault(false))
        val nativeMailboxReady = noDeferredCommand && nativeCapacityReady
        if (!nativeMailboxReady) {
            synchronized(stateLock) {
                directCallbackHadAdmission = false
            }
            // An idle HOME resume can reserve its first proof token while native is still
            // processing the preceding attach command. There is no moving cadence and no prior
            // presentation callback in that state, so merely retaining INVALIDATION_POSTED loses
            // every future wake. Re-arm through the bounded producer deadline; the atomic mailbox
            // wake coalesces duplicates and retries at display cadence until attach/capacity is
            // real, without replacing the admitted token.
            postNativeMailboxAdmissionWake()
            return
        }

        var rendered = false
        try {
            // Canvas submission is intentionally absent. Hardware Canvas re-enters HWUI's
            // RenderThread/BLAST wait and software Canvas round-trips the entire color buffer
            // through gfxstream. The native lane queues an AHardwareBuffer transaction and later
            // returns the exact SurfaceControl OnCommit identity for this token.
            rendered = renderFrame(
                frameTimeNanos,
                null,
                directSurface = true,
                frameTimelineVsyncId = frameTimelineVsyncId,
                expectedPresentationTimeNanos = expectedPresentationTimeNanos,
            )
        } catch (failure: Throwable) {
            Log.e(
                TAG,
                    "reader_direct_surface_submit_failed epoch=${admission.first}," +
                    "token=${admission.second},valid=" +
                    (rollingTextureSurface?.isValid == true),
                failure
            )
        }
        synchronized(stateLock) {
            // Admission describes what the callback saw at entry, but late-input replacement is
            // about whether that callback actually submitted pixels. A state-null/rejected turn
            // owns no frame and must not block the next real MOVE from replacing the pending
            // cadence callback. Successful submissions retain the one-frame-per-callback guard.
            if (!rendered) directCallbackHadAdmission = false
            if (rendered) {
                closeSubmittedPhysicalCallbackCadenceLocked(drawnVersion)
            }
            if (!nativeTexturePrewarmPaused && nativeTexturePrewarmDirty &&
                !nativeTexturePrewarmFlushPosted && !nativeTexturePrewarmSubmissionInFlight
            ) {
                requestResidentNativeTexturePrewarmLocked(newPixelOrWindowIntent = false)
            }
            // Close after submission/computation so the final moving setBuffer belongs to the
            // physical interval. A later MOVE starts a new interval without counting a stationary
            // finger hold as a missed display frame.
            if (shouldClosePhysicalMotionInterval(
                    traceActive = physicalScrollTraceCookie != 0,
                    scrollerFinished = scroller.isFinished,
                    requiredVersion = physicalMotionRequiredVersion,
                    committedVersion = committedVersion
                )
            ) {
                endPhysicalScrollTraceLocked()
                statsLastCallbackStartNs = 0L
                statsLastPostEndNs = 0L
                statsLastCallbackGestureRevision = 0L
                statsLastCallbackMotionCookie = 0
            }
        }
        if (!rendered) {
            recoverDirectSurfaceSubmission(admission.first, admission.second)
        }
    }

    private fun revealNativeSurfaceAfterPresentedFrame(
        expectedAttachEpoch: Long,
        expectedStructureEpoch: Long,
    ) {
        // This method is called on every successful native BUFFER_QUEUE presentation. Reserve a
        // single main-thread owner before posting; after the first exact buffer is visible the
        // producer takes the O(1) fast path and creates no Handler work at all.
        val offer = synchronized(stateLock) {
            // Reject a late producer callback before it can overwrite the pending request for a
            // newer Surface attachment. clearFramePipeLocked uses this same stateLock -> gate
            // order, while the main drain releases the gate monitor before taking stateLock.
            if (rollingNativeAttachEpoch != expectedAttachEpoch || expectedAttachEpoch <= 0L ||
                nativePresentedStructureEpoch != expectedStructureEpoch ||
                traversalStructureEpoch != expectedStructureEpoch || rollingNativeFatal
            ) return@synchronized NativeSurfaceRevealDispatchGate.OfferResult(false, 0L)
            nativeSurfaceRevealDispatchGate.offer(
                NativeSurfaceRevealDispatchGate.Request(
                    expectedAttachEpoch,
                    expectedStructureEpoch,
                ),
                nativeSurfaceContentRevealed,
            )
        }
        if (!offer.shouldPost) return
        if (!mainHandler.post(nativeSurfaceRevealDispatchRunnable)) {
            nativeSurfaceRevealDispatchGate.onPostRejected(offer.reservation)
        }
    }

    private fun drainNativeSurfaceReveal() {
        check(Looper.myLooper() == Looper.getMainLooper())
        val request = nativeSurfaceRevealDispatchGate.take() ?: return
        var staleStructureRetry: Pair<Long, Long>? = null
        val reveal = synchronized(stateLock) {
            val current = rollingNativeAttachEpoch == request.attachEpoch &&
                request.attachEpoch > 0L && !rollingNativeFatal &&
                directSurfaceReady && nativePresentationVisible &&
                nativePresentedStructureEpoch == request.structureEpoch &&
                traversalStructureEpoch == request.structureEpoch &&
                nativeSurfaceView.visibility == View.VISIBLE
            if (current && !nativeSurfaceContentRevealed) {
                nativeSurfaceContentRevealed = true
                true
            } else {
                // The first replacement buffer can latch at the same time an adjacent manifest
                // extends the page table. The stale buffer is correctly rejected, but its dirty
                // version was already consumed. Without a new submission the transparent native
                // child survives HOME return indefinitely even though the renderer and pixels are
                // healthy. Re-arm one ordinary frame from the current immutable structure.
                val mayRetryCurrentStructure = !nativeSurfaceContentRevealed &&
                    rollingNativePresentationEnabled && !rollingNativeFatal &&
                    directSurfaceReady && rollingNativeHandle != 0L &&
                    rollingNativeAttachEpoch > 0L && renderRunning && pages.isNotEmpty() &&
                    nativeSurfaceView.visibility == View.VISIBLE
                if (mayRetryCurrentStructure) {
                    staleStructureRetry = request.structureEpoch to traversalStructureEpoch
                    advanceDesiredVersionLocked()
                    pendingPixelReasons = pendingPixelReasons or DIRTY_INVALIDATION
                    renderRequested = true
                    scheduleFrameLocked()
                    stateLock.notifyAll()
                }
                false
            }
        }
        if (!reveal) {
            staleStructureRetry?.let { (from, to) ->
                Log.d(
                    TAG,
                    "reader_native_surface_reveal_stale_retry from=$from,to=$to," +
                        "attach=${request.attachEpoch}",
                )
            }
            return
        }
        // The exact buffer is already latched. Switching alpha now cannot expose an empty or
        // stale Surface, and the HWUI fallback remains the owner until this point.
        nativeSurfaceView.alpha = 1f
        invalidate()
        (parent as? View)?.invalidate()
        postInvalidateOnAnimation()
        Log.d(
            TAG,
            "reader_native_surface_revealed_after_present " +
                "attach=${request.attachEpoch},structure=${request.structureEpoch}",
        )
    }

    /**
     * Native has already proved that the visible pixels match the retained band. Only the
     * SurfaceView parent transform changes here. The registered root frame-commit callback is the
     * fail-closed proof for the exact ViewRoot frame that synchronizes that SurfaceView geometry.
     */
    @Keep
    fun onNtkRollingBandActivated(
        token: Long,
        producerSceneId: Long,
        structureEpoch: Long,
    ) {
        if (token <= 0L || structureEpoch <= 0L) return
        synchronized(stateLock) {
            if (producerSceneId <= 0L) {
                activeNativeBandProof = null
                activeNativeBandDirectValidatedSceneId = 0L
                activeNativeBandDirectValidatedVisualGeneration = Long.MIN_VALUE
                activeNativeBandDirectValidatedStructureEpoch = 0L
                return
            }
            activeNativeBandCallbackCount++
            val candidate = synchronized(activeNativeBandCandidateLock) {
                activeNativeBandCandidates.remove(producerSceneId)
            }
            if (candidate == null) {
                activeNativeBandCandidateMissCount++
                if (activeNativeBandCandidateMissCount <= 4L ||
                    activeNativeBandCandidateMissCount % 30L == 0L
                ) {
                    Log.i(
                        TAG,
                        "reader_active_band_candidate_miss scene=$producerSceneId," +
                            "structure=$structureEpoch,candidates=${synchronized(activeNativeBandCandidateLock) { activeNativeBandCandidates.size }}," +
                            "callbacks=$activeNativeBandCallbackCount",
                    )
                }
                return
            }
            if (candidate.structureEpoch != structureEpoch ||
                candidate.handle != rollingNativeHandle ||
                candidate.attachEpoch != rollingNativeAttachEpoch ||
                rollingNativeFatal || !directSurfaceReady
            ) return
            activeNativeBandProof = candidate
            activeNativeBandDirectValidatedSceneId = 0L
            activeNativeBandDirectValidatedVisualGeneration = Long.MIN_VALUE
            activeNativeBandDirectValidatedStructureEpoch = 0L
            if (activeNativeBandCallbackCount <= 4L ||
                activeNativeBandCallbackCount % 30L == 0L
            ) {
                Log.i(
                    TAG,
                    "reader_active_band_installed scene=$producerSceneId," +
                        "structure=$structureEpoch,origin=${candidate.bandOrigin}," +
                        "items=${candidate.items.size}",
                )
            }
            // Candidates older than the now-presented scene can never become active. Preserve
            // only newer in-flight precompositions within the fixed metadata bound.
            synchronized(activeNativeBandCandidateLock) {
                val iterator = activeNativeBandCandidates.entries.iterator()
                while (iterator.hasNext()) {
                    if (iterator.next().key < producerSceneId) iterator.remove()
                }
            }
        }
    }

    @Keep
    fun onNtkRollingGeometryFrameRequested(
        token: Long,
        sourceTop: Int,
        sourceHeight: Int,
        geometryBaseSourceTop: Int,
        frameTimelineVsyncId: Long,
        expectedPresentationTimeNanos: Long,
    ): Boolean {
        if (token <= 0L || sourceTop < 0 || sourceHeight <= 0) {
            onNtkRollingFrameDropped(token, NATIVE_FRAME_DROP_PRESENT_FAILED)
            return true
        }
        val alreadyPresentedDirectly = synchronized(stateLock) {
            directActiveBandNativeFollowupTokens.remove(token)
        }
        if (alreadyPresentedDirectly) return true
        val request = FrameSyncedGeometryRequest(
            token,
            sourceTop,
            sourceHeight,
            geometryBaseSourceTop,
            frameTimelineVsyncId,
            expectedPresentationTimeNanos,
        )
        return submitFrameSyncedGeometryRequest(request)
    }

    private fun submitFrameSyncedGeometryRequest(request: FrameSyncedGeometryRequest): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.VANILLA_ICE_CREAM) {
            onNtkRollingFrameDropped(request.token, NATIVE_FRAME_DROP_PRESENT_FAILED)
            return true
        }

        var deferred = false
        var duplicate = false
        var backpressured = false
        val plan = synchronized(stateLock) {
            val submission = pendingFrameCommits[request.token]
                ?.takeIf { it.surfaceControlSubmission }
            if (submission == null) {
                if (framePipe == FramePipe.INVALIDATION_POSTED &&
                    inFlightToken == request.token && request.token != 0L
                ) {
                    // The native worker can request a position before nativeSubmit() returns and
                    // the producer publishes its immutable Kotlin proof. Hold only that uniquely
                    // admitted token; registration consumes it immediately after JNI returns.
                    earlyFrameSyncedGeometryRequests[request.token] = request
                    deferred = true
                }
                null
            } else if (request.token in frameSyncedGeometryInFlightTokens) {
                duplicate = true
                null
            } else if (frameSyncedGeometryInFlightTokens.size >=
                MAX_FRAME_SYNCED_GEOMETRY_IN_FLIGHT
            ) {
                // One root draw may acknowledge only one distinct crop. Retain the native FIFO
                // head until its committed listener releases this slot.
                backpressured = true
                null
            } else {
                val child = rollingJavaGeometrySurfaceControl
                val viewportHeight = rollingNativeViewportHeight
                val valid = submission.nativeSurfaceEpoch > 0L &&
                    submission.nativeSurfaceEpoch == rollingNativeAttachEpoch &&
                    !rollingNativeFatal && directSurfaceReady &&
                    child != null && child.isValid && viewportHeight > 0 &&
                    request.sourceTop <= rollingNativeHeight - request.sourceHeight
                if (!valid) {
                    null
                } else {
                    // Move the native geometry container itself, not the SurfaceView parent.
                    // Its native full-buffer transaction installed geometryBaseSourceTop as an
                    // absolute position, so every later crop also uses the absolute source top.
                    // Java SurfaceControl accepts fractional positions and preserves exact motion.
                    val positionY = -(
                        request.sourceTop.toDouble() * viewportHeight.toDouble() /
                            request.sourceHeight.toDouble()
                        ).toFloat()
                    frameSyncedGeometryInFlightTokens.add(request.token)
                    frameSyncedGeometrySubmissionOrder[request.token] = null
                    FrameSyncedGeometryPlan(request, child, positionY)
                }
            }
        }
        if (deferred || duplicate) return true
        if (backpressured) return false
        if (plan == null) {
            onNtkRollingFrameDropped(request.token, NATIVE_FRAME_DROP_PRESENT_FAILED)
            return true
        }
        return applyFrameSyncedGeometryTransaction(plan)
    }

    @RequiresApi(Build.VERSION_CODES.VANILLA_ICE_CREAM)
    private fun applyFrameSyncedGeometryTransaction(
        plan: FrameSyncedGeometryPlan,
    ): Boolean {
        val stillCurrent = synchronized(stateLock) {
            plan.request.token in frameSyncedGeometryInFlightTokens &&
                pendingFrameCommits[plan.request.token]?.surfaceControlSubmission == true &&
                rollingJavaGeometrySurfaceControl === plan.child && plan.child.isValid &&
                rollingNativeAttachEpoch > 0L && directSurfaceReady
        }
        if (!stillCurrent) {
            synchronized(stateLock) {
                frameSyncedGeometryInFlightTokens.remove(plan.request.token)
                frameSyncedGeometrySubmissionOrder.remove(plan.request.token)
            }
            return true
        }
        val transaction = SurfaceControl.Transaction()
        try {
            transaction.addTransactionCommittedListener(
                frameSyncedGeometryCommittedExecutor,
            ) {
                val committedUptimeNanos =
                    frameSyncedGeometryCommitIngressUptimeNanos.get()
                        ?: SystemClock.elapsedRealtimeNanos()
                completeFrameSyncedGeometryPresentation(
                    plan.request.token,
                    committedUptimeNanos,
                )
            }
            val desiredPresentNanos = plan.request.expectedPresentationTimeNanos
            val nowMonotonicNanos = System.nanoTime()
            if (plan.request.frameTimelineVsyncId > 0L) {
                transaction.setFrameTimeline(plan.request.frameTimelineVsyncId)
            } else if (desiredPresentNanos > nowMonotonicNanos &&
                desiredPresentNanos - nowMonotonicNanos <=
                    MAX_FRAME_SYNCED_GEOMETRY_PRESENT_LEAD_NANOS
            ) {
                // The producer Choreographer's frame-timeline id is thread-scoped and can be
                // stale after the native renderer hand-off. Its CLOCK_MONOTONIC presentation
                // time is portable, however, and prevents an otherwise un-timed transaction
                // from sitting until a much later host-compositor batch.
                transaction.setDesiredPresentTimeNanos(desiredPresentNanos)
            }
            transaction.setPosition(plan.child, 0f, plan.positionY)
            transaction.apply()
        } catch (failure: RuntimeException) {
            synchronized(stateLock) {
                frameSyncedGeometryInFlightTokens.remove(plan.request.token)
                frameSyncedGeometrySubmissionOrder.remove(plan.request.token)
            }
            Log.e(
                TAG,
                "reader_direct_geometry_transaction_failed token=${plan.request.token}",
                failure,
            )
            onNtkRollingFrameDropped(plan.request.token, NATIVE_FRAME_DROP_PRESENT_FAILED)
        } finally {
            transaction.close()
        }
        return true
    }

    /** SurfaceFlinger may complete position-only transactions LIFO; order cadence only. */
    private fun takeCompletedGeometryCadencePrefix(
        proof: CompletedDrawProof,
    ): List<CompletedDrawProof> = synchronized(stateLock) {
            if (!frameSyncedGeometrySubmissionOrder.containsKey(proof.frameToken)) {
                return@synchronized emptyList()
            }
            frameSyncedGeometrySubmissionOrder[proof.frameToken] = proof
            val completed = ArrayList<CompletedDrawProof>()
            val iterator = frameSyncedGeometrySubmissionOrder.entries.iterator()
            while (iterator.hasNext()) {
                val entry = iterator.next()
                val ready = entry.value ?: break
                completed.add(ready)
                iterator.remove()
            }
            completed
        }

    private fun completeFrameSyncedGeometryPresentation(
        token: Long,
        presentedUptimeNanos: Long,
    ) {
        val submission = synchronized(stateLock) {
            if (!frameSyncedGeometryInFlightTokens.remove(token)) return@synchronized null
            pendingFrameCommits[token]?.takeIf {
                it.surfaceControlSubmission && it.nativeSurfaceEpoch > 0L &&
                    it.nativeSurfaceEpoch == rollingNativeAttachEpoch &&
                    !rollingNativeFatal && directSurfaceReady
            }
        } ?: return
        if (presentedUptimeNanos <= 0L) {
            onNtkRollingFrameDropped(token, NATIVE_FRAME_DROP_PRESENT_FAILED)
            return
        }
        val reveal = synchronized(stateLock) {
            if (traversalStructureEpoch == submission.proof.structureEpoch) {
                nativePresentationVisible = true
                nativePresentedStructureEpoch = submission.proof.structureEpoch
                submission.nativeSurfaceEpoch to submission.proof.structureEpoch
            } else null
        }
        reveal?.let { (attachEpoch, structureEpoch) ->
            revealNativeSurfaceAfterPresentedFrame(attachEpoch, structureEpoch)
        }
        onFrameCommitted(
            submission.frameEpoch,
            token,
            surfaceControlLatchObserved = true,
            surfaceControlPresentedUptimeNanos = presentedUptimeNanos,
            nativePresentationKind = NATIVE_PRESENTATION_SURFACE_CONTROL,
            allowNativeProducerThread = true,
            orderedGeometryCadence = true,
        )
    }

    @Keep
    fun onNtkRollingFrameLatched(
        token: Long,
        latchNanos: Long,
        observedNanos: Long,
        presentationKind: Int
    ) {
        // ASurfaceTransaction reports CLOCK_MONOTONIC timestamps, whereas the Java telemetry
        // session uses elapsedRealtimeNanos. Convert by subtracting the native callback latency
        // from the Java receipt time instead of assuming the absolute clocks share an epoch.
        val callbackReceivedUptimeNanos = SystemClock.elapsedRealtimeNanos()
        val presentedUptimeNanos = surfaceLatchPresentedUptimeNanos(
            callbackReceivedUptimeNanos,
            latchNanos,
            observedNanos
        )
        // Both BufferQueue and SurfaceControl callbacks already run after native ownership proof.
        // Consume that proof on the callback thread so neither the main Looper nor the shared
        // scene-submission Handler can batch otherwise on-time compositor acknowledgements.
        completeOrBufferNativePresentation(
            token,
            presentedUptimeNanos,
            presentationKind,
            allowBuffer = true,
        )
    }

    private fun completeOrBufferNativePresentation(
        token: Long,
        presentedUptimeNanos: Long,
        presentationKind: Int,
        allowBuffer: Boolean,
    ) {
        // A newer band may finish after this token already presented an exact crop from the old
        // overlap. onNtkRollingBandActivated has installed the new scene before this callback;
        // consume only the duplicate token outcome, never publish two cadence proofs.
        val directFollowupCompleted = synchronized(stateLock) {
            directActiveBandNativeFollowupTokens.remove(token)
        }
        if (directFollowupCompleted) return
        var unmatchedDiagnostic: String? = null
        val submission = synchronized(stateLock) {
            val registered = pendingFrameCommits[token]
                ?.takeIf { it.surfaceControlSubmission }
            if (registered == null && allowBuffer &&
                framePipe == FramePipe.INVALIDATION_POSTED &&
                token == inFlightToken && token != 0L
            ) {
                // Exactly one frame can own the posted admission. A callback for that token is
                // therefore safe to hold until renderFrame installs the corresponding immutable
                // proof; unrelated or stale native callbacks remain fail-closed.
                // A failure is terminal for this native token and wins over any contradictory
                // early presentation callback. Otherwise the latest presentation evidence is
                // safe to retain until renderFrame publishes the immutable Kotlin proof.
                if (earlyNativeOutcomes[token] !is EarlyNativeOutcome.PresentFailed) {
                    earlyNativeOutcomes[token] = EarlyNativeOutcome.Presented(
                        presentedUptimeNanos,
                        presentationKind,
                    )
                }
            }
            if (registered == null && token !in earlyNativeOutcomes) {
                // Page delivery, focus, or Surface lifecycle work can retire the Kotlin proof
                // while the native producer is already swapping that exact buffer. The swap is
                // real, but it cannot be identity-qualified after its proof was retired. Do not
                // leave that first real-pixel buffer as the only submission forever: coalesce one
                // fresh proof-bearing frame from the current immutable page state. This performs
                // no loading/prewarming and never qualifies the unmatched buffer itself.
                if (renderRunning && pages.isNotEmpty() && framePipe == FramePipe.IDLE &&
                    directSurfaceReady && rollingNativeHandle != 0L &&
                    rollingNativeAttachEpoch > 0L && !rollingNativeFatal
                ) {
                    renderRequested = true
                    scheduleFrameLocked()
                }
                unmatchedNativePresentationCount++
                if (unmatchedNativePresentationCount == 1L ||
                    unmatchedNativePresentationCount % NATIVE_PRESENTATION_DIAGNOSTIC_INTERVAL == 0L
                ) {
                    unmatchedDiagnostic =
                        "reader_native_presentation_unmatched count=$unmatchedNativePresentationCount," +
                            "token=$token,kind=$presentationKind,pipe=$framePipe," +
                            "inFlight=$inFlightToken,pending=${pendingFrameCommits.size}," +
                            "running=$renderRunning,surface=$directSurfaceReady," +
                            "attach=$rollingNativeAttachEpoch,requested=$renderRequested"
                }
            }
            registered
        }
        unmatchedDiagnostic?.let { Log.w(TAG, it) }
        if (submission == null) return
        if (presentedUptimeNanos <= 0L) {
            onNtkRollingFrameDropped(token, NATIVE_FRAME_DROP_PRESENT_FAILED)
            return
        }
        val reveal = synchronized(stateLock) {
            if (rollingNativeAttachEpoch == submission.nativeSurfaceEpoch &&
                submission.nativeSurfaceEpoch > 0L && !rollingNativeFatal &&
                traversalStructureEpoch == submission.proof.structureEpoch
            ) {
                nativePresentationVisible = true
                nativePresentedStructureEpoch = submission.proof.structureEpoch
                submission.nativeSurfaceEpoch to submission.proof.structureEpoch
            } else null
        }
        reveal?.let { (attachEpoch, structureEpoch) ->
            revealNativeSurfaceAfterPresentedFrame(attachEpoch, structureEpoch)
        }
        onFrameCommitted(
            submission.frameEpoch,
            token,
            surfaceControlLatchObserved =
                presentationKind == NATIVE_PRESENTATION_SURFACE_CONTROL,
            surfaceControlPresentedUptimeNanos = presentedUptimeNanos,
            nativePresentationKind = presentationKind,
            allowNativeProducerThread = true,
        )
    }

    /**
     * The native CPU worker has completed a real off-screen band buffer. Request one ordinary
     * immutable product frame so the renderer can bind that buffer to the current viewport and
     * retire its acquire-fence ownership even when the reader is otherwise idle.
     */
    @Keep
    fun onNtkRollingPrecomposedBandReady() {
        synchronized(stateLock) {
            if (!renderRunning || frameSchedulingSuppressed || pages.isEmpty() ||
                !directSurfaceReady || rollingNativeHandle == 0L ||
                rollingNativeAttachEpoch <= 0L || rollingNativeFatal
            ) return
            advanceDesiredVersionLocked()
            pendingPixelReasons = pendingPixelReasons or DIRTY_ANIMATION
            renderRequested = true
            scheduleFrameLocked()
            stateLock.notifyAll()
        }
    }

    @Keep
    fun onNtkRollingFrameDropped(token: Long, reason: Int) {
        synchronized(stateLock) {
            directActiveBandNativeFollowupTokens.remove(token)
        }
        if (reason == NATIVE_FRAME_DROP_MAILBOX_SUPERSEDED ||
            reason == NATIVE_FRAME_DROP_LIFECYCLE_RETIRED
        ) {
            // Mailbox replacement already installed a newer native command before this callback.
            // Retire only the old immutable proof: rewinding drawnVersion or scheduling a retry
            // here would manufacture another producer frame, immediately replace the command that
            // superseded this token, and amplify a brief host-compositor stall into a retry loop.
            // Lifecycle retirement likewise has its own clear/reattach owner and must not revive
            // work from the retired backend.
            synchronized(stateLock) {
                if (reason == NATIVE_FRAME_DROP_MAILBOX_SUPERSEDED) {
                    nativeMailboxSupersededRetirements++
                } else {
                    nativeLifecycleRetirements++
                }
                pendingFrameCommits.remove(token)
                earlyFrameSyncedGeometryRequests.remove(token)
                frameSyncedGeometryInFlightTokens.remove(token)
                frameSyncedGeometrySubmissionOrder.remove(token)
                stateLock.notifyAll()
            }
            return
        }
        // A real presentation failure has no successor guarantee. The native worker can report it
        // after accepting the command but before nativeSubmit() returns and the Kotlin proof is
        // installed. Buffer only the unique currently admitted token; stale failures remain
        // fail-closed, while renderFrame consumes this outcome immediately after proof publication.
        val epoch = synchronized(stateLock) {
            earlyFrameSyncedGeometryRequests.remove(token)
            frameSyncedGeometryInFlightTokens.remove(token)
            frameSyncedGeometrySubmissionOrder.remove(token)
            val registered = pendingFrameCommits[token]
            val ownsPostedAdmission = registered == null &&
                framePipe == FramePipe.INVALIDATION_POSTED &&
                token == inFlightToken && token != 0L
            if (registered == null && !ownsPostedAdmission) {
                // A structure or lifecycle turn already retired this proof before an asynchronous
                // post/callback completed. The command never owns a presentable frame anymore;
                // counting it as a physical presentation failure manufactures an error and can
                // redrive work into the replacement Surface.
                null
            } else {
                if (reason == NATIVE_FRAME_DROP_PRESENT_FAILED) {
                    nativePresentFailedRetirements++
                } else {
                    nativeUnknownRetirements++
                }
                if (registered != null) return@synchronized registered.frameEpoch
                earlyNativeOutcomes[token] = EarlyNativeOutcome.PresentFailed(reason)
                null
            }
        } ?: return
        recoverDirectSurfaceSubmission(epoch, token)
    }

    @Keep
    fun onNtkRollingRendererFatal(
        failedNativeHandle: Long,
        failedCreationGeneration: Long,
        reason: String,
    ) {
        // The renderer owns an immutable Kotlin-issued creation identity. Do not acquire
        // stateLock on this synchronous JNI ingress: nativeCreate can still be running while its
        // caller owns that lock, and a failed create is destroyed/joined before JNI returns.
        mainHandler.post {
            var retiredHandle = 0L
            var retiredSubmissionCount = 0
            var recreateNative = false
            var recoveryGeneration = 0L
            val shouldRetire = synchronized(stateLock) {
                if (!ownsRollingNativeFatalCallback(
                        failedNativeHandle = failedNativeHandle,
                        currentNativeHandle = rollingNativeHandle,
                        failedCreationGeneration = failedCreationGeneration,
                        currentCreationGeneration = rollingNativeCreateGeneration,
                        recoveryPending = rollingNativeRecoveryPending,
                    )
                ) {
                    false
                } else {
                    retiredHandle = rollingNativeHandle
                    retiredSubmissionCount = pendingFrameCommits.values.count {
                        it.surfaceControlSubmission
                    }
                    // The failure belongs to this physical backend instance, not the reader
                    // session. Retire its handle before destruction so late callbacks cannot
                    // qualify frames produced by the replacement renderer.
                    rollingNativeHandle = 0L
                    advanceRollingNativeSurfaceEpochLocked()
                    rollingNativeAttachEpoch = 0L
                    physicalMoveProducerReady = false
                    releaseRollingJavaChildSurfaceControlLocked()
                    rollingNativeSurfaceIdentity = 0
                    rollingNativeWidth = 0
                    rollingNativeHeight = 0
                    rollingNativeViewportWidth = 0
                    rollingNativeViewportHeight = 0
                    rollingNativePreparedWidth = 0
                    rollingNativePreparedHeight = 0
                    nativePresentationVisible = false
                    nativeSurfaceContentRevealed = false
                    nativePresentedStructureEpoch = 0L
                    rollingNativeRecoveryAttempts += 1
                    rollingNativeRecoveryGeneration += 1L
                    if (rollingNativeRecoveryGeneration <= 0L) {
                        rollingNativeRecoveryGeneration = 1L
                    }
                    recoveryGeneration = rollingNativeRecoveryGeneration
                    recreateNative = shouldRecreateRollingNativeRenderer(
                        rollingNativeRecoveryAttempts,
                    )
                    nativeRendererFatals++
                    if (recreateNative) {
                        nativeRendererRecreates++
                    } else {
                        nativePermanentFallbacks++
                    }
                    rollingNativeFatal = true
                    rollingNativeRecoveryPending = recreateNative
                    rollingNativeDestroyInFlightCount += 1
                    clearFramePipeLocked(preserveDirty = true)
                    if (recreateNative) {
                        renderRequested = false
                    } else if (pages.isNotEmpty()) {
                        // The View-lifetime recreation budget is exhausted. A successful native
                        // frame does not replenish it: keep the valid parent HWUI renderer as the
                        // permanent session fallback instead of entering a recreate/fail loop.
                        renderRequested = true
                        scheduleFrameLocked()
                    }
                    stateLock.notifyAll()
                    true
                }
            }
            if (!shouldRetire) return@post
            // Never leave the last native buffer covering the valid HWUI fallback while its
            // backend is being replaced or has exhausted its bounded recovery budget.
            nativeSurfaceView.alpha = 0f
            resetNativeSurfaceViewBandTransform()
            if (!recreateNative) nativeSurfaceView.visibility = View.GONE
            Log.w(
                TAG,
                "reader_native_surface_control_reset reason=$reason " +
                    "pending=$retiredSubmissionCount,recreate=$recreateNative," +
                    "attempts=$rollingNativeRecoveryAttempts"
            )

            val destroyAndRecover = Runnable {
                try {
                    NtkRollingNativeBridge.nativeDestroy(retiredHandle)
                } finally {
                    completeRollingNativeDestroy()
                }
                if (recreateNative &&
                    finishRollingNativeRecoveryAfterDestroy(recoveryGeneration)
                ) {
                    // State completion above is deliberately independent of this removable UI
                    // callback. onDetachedFromWindow may clear the main queue; a later Surface
                    // lifecycle can still create the replacement because fatal/pending are already
                    // released. The generation check prevents an old post from reviving native
                    // rendering after a newer fatal selected permanent HWUI fallback.
                    mainHandler.post {
                        val current = synchronized(stateLock) {
                            rollingNativeRecoveryGeneration == recoveryGeneration &&
                                !rollingNativeRecoveryPending && !rollingNativeFatal
                        }
                        if (current) completeRollingNativeRecovery(reason)
                    }
                }
            }
            if (!ReaderBitmapRetirementDispatcher.dispatchWork(destroyAndRecover::run)) {
                Thread(destroyAndRecover, "ReaderSurfaceNativeRecovery").apply {
                    isDaemon = true
                    priority = Thread.NORM_PRIORITY
                    start()
                }
            }
        }
    }

    /** Completes renderer ownership after nativeDestroy/join; contains no View/UI operation. */
    private fun finishRollingNativeRecoveryAfterDestroy(expectedGeneration: Long): Boolean {
        return synchronized(stateLock) {
            if (!ownsRollingNativeRecoveryCompletion(
                    expectedGeneration = expectedGeneration,
                    currentGeneration = rollingNativeRecoveryGeneration,
                    recoveryPending = rollingNativeRecoveryPending,
                    nativeFatal = rollingNativeFatal,
                    nativeHandle = rollingNativeHandle,
                )
            ) return@synchronized false
            rollingNativeRecoveryPending = false
            rollingNativeFatal = false
            firstNativeSubmitAccepted = false
            stateLock.notifyAll()
            true
        }
    }

    private fun completeRollingNativeRecovery(reason: String) {
        val reattach = synchronized(stateLock) {
            if (rollingNativeRecoveryPending || rollingNativeFatal) return@synchronized null
            // Idempotent with the non-removable destroy-thread transition above. Keeping the UI
            // phase side-effect free with respect to newer fatal generations is the key invariant.
            rollingNativeRecoveryPending = false
            rollingNativeFatal = false
            firstNativeSubmitAccepted = false
            val surface = rollingTextureSurface
            val canReattach = isAttachedToWindow && renderRunning && directSurfaceReady &&
                surface?.isValid == true
            if (canReattach) {
                Triple(checkNotNull(surface), width, height)
            } else {
                null
            }
        }
        Log.i(
            TAG,
            "reader_native_surface_control_reset_complete reason=$reason " +
                "reattach=${reattach != null}"
        )
        if (reattach != null) {
            attachRollingNativeSurface(reattach.first, reattach.second, reattach.third)
        }
    }

    private fun recoverDirectSurfaceSubmission(epoch: Long, token: Long) {
        synchronized(stateLock) {
            if (epoch != lifecycleEpoch || pendingFrameCommits[token]?.frameEpoch != epoch) return
            pendingFrameCommits.remove(token)
            if (token == inFlightToken && epoch == inFlightEpoch) {
                releasePostedAdmissionLocked(preserveDirty = true)
            }
            drawnVersion = latestSubmittedVersionLocked()
            if (pages.isNotEmpty()) renderRequested = true
            // This method posts the eventual retry to main; no View mutation occurs on the native
            // callback thread itself.
            scheduleNoStateRetryLocked()
            stateLock.notifyAll()
        }
    }

    private fun windowRequestLocked(
        busy: Boolean,
        forceDispatch: Boolean = false,
        visibleLoadingRedrive: Boolean = false,
    ): WindowRequest? {
        if (pages.isEmpty() || width <= 0 || height <= 0) return null
        val anchor = anchorPageLocked()
        val first = max(0, anchor - ReaderPipelinePolicy.windowBefore(busy))
        val last = min(pages.lastIndex, anchor + ReaderPipelinePolicy.windowAfter(busy))
        val physicalFirst = firstVisiblePageLocked(scrollOffset).coerceIn(0, pages.lastIndex)
        val physicalLast = firstVisiblePageLocked(
            (scrollOffset + height.toFloat() - 1f).coerceAtLeast(scrollOffset),
        ).coerceIn(physicalFirst, pages.lastIndex)
        val liveReverseEvidence = NtkReverseWindowEvidencePolicy.capture(
            busy = busy,
            activeDirection = activeInputDirection,
            firstVisiblePage = firstVisiblePageLocked(scrollOffset)
                .coerceIn(0, pages.lastIndex),
        )
        if (liveReverseEvidence.reverseFirstPageHint >= 0) {
            pendingReverseWindowFirstPageHint = if (pendingReverseWindowFirstPageHint >= 0) {
                minOf(
                    pendingReverseWindowFirstPageHint,
                    liveReverseEvidence.reverseFirstPageHint,
                )
            } else {
                liveReverseEvidence.reverseFirstPageHint
            }
        }
        val boundaryPx = height * NEAR_BOUNDARY_SCREENFULS
        val nearStart = scrollOffset <= boundaryPx ||
            anchor <= NEAR_BOUNDARY_PAGE_THRESHOLD
        val remainingPx = contentHeight - (scrollOffset + height)
        val nearEnd = remainingPx <= boundaryPx ||
            anchor >= pages.size - NEAR_BOUNDARY_PAGE_THRESHOLD
        val progress = progressPositionLocked() ?: return null
        val nearChanged = nearStart != lastNearStart || nearEnd != lastNearEnd
        var notifyNearStart = nearStart && nearStart != lastNearStart
        var notifyNearEnd = nearEnd && nearEnd != lastNearEnd
        if (!forceDispatch && busy && lastRequestedBusy) {
            val now = SystemClock.uptimeMillis()
            val anchorMoved = lastAnchor < 0 || abs(anchor - lastAnchor) >= BUSY_WINDOW_ANCHOR_STEP
            val intervalElapsed = now - lastBusyWindowDispatchMs >= BUSY_WINDOW_MIN_DISPATCH_MS
            if ((notifyNearStart || notifyNearEnd) &&
                now - lastBusyNearDispatchMs < BUSY_NEAR_BOUNDARY_MIN_DISPATCH_MS
            ) {
                notifyNearStart = false
                notifyNearEnd = false
            }
            if (!anchorMoved && !intervalElapsed && !nearChanged &&
                pendingReverseWindowFirstPageHint < 0
            ) return null
        }
        if (!forceDispatch && anchor == lastAnchor && busy == lastRequestedBusy && !nearChanged &&
            pendingReverseWindowFirstPageHint < 0
        ) return null
        if (busy && (notifyNearStart || notifyNearEnd)) {
            lastBusyNearDispatchMs = SystemClock.uptimeMillis()
        }
        lastAnchor = anchor
        lastNearStart = nearStart
        lastNearEnd = nearEnd
        lastRequestedBusy = busy
        if (busy) lastBusyWindowDispatchMs = SystemClock.uptimeMillis()
        val reverseEvidence = NtkReverseWindowEvidencePolicy.merge(
            NtkReverseWindowEvidencePolicy.Evidence(
                directionHint = if (pendingReverseWindowFirstPageHint >= 0) {
                    DIRECTION_PREVIOUS
                } else {
                    0
                },
                reverseFirstPageHint = pendingReverseWindowFirstPageHint,
            ),
            liveReverseEvidence,
        )
        return WindowRequest(
            first,
            last,
            anchor,
            physicalFirst,
            physicalLast,
            progress.page,
            progress.offset,
            busy,
            nearStart,
            nearEnd,
            notifyNearStart,
            notifyNearEnd,
            reverseEvidence.directionHint,
            reverseEvidence.reverseFirstPageHint,
            visibleLoadingRedrive = visibleLoadingRedrive,
        )
    }

    private fun dispatchWindowRequest(request: WindowRequest?, fromInput: Boolean = false) {
        if (request == null) return
        synchronized(stateLock) {
            val previous = pendingWindowRequest
            val previousEvidence = previous?.let {
                NtkReverseWindowEvidencePolicy.Evidence(
                    it.directionHint,
                    it.reverseFirstPageHint,
                )
            }
            val cadenceSuppressedEvidence = NtkReverseWindowEvidencePolicy.Evidence(
                directionHint = if (pendingReverseWindowFirstPageHint >= 0) {
                    DIRECTION_PREVIOUS
                } else {
                    0
                },
                reverseFirstPageHint = pendingReverseWindowFirstPageHint,
            )
            val requestEvidence = NtkReverseWindowEvidencePolicy.merge(
                cadenceSuppressedEvidence,
                NtkReverseWindowEvidencePolicy.Evidence(
                    request.directionHint,
                    request.reverseFirstPageHint,
                ),
            )
            val evidence = NtkReverseWindowEvidencePolicy.merge(
                previousEvidence,
                requestEvidence,
            )
            pendingReverseWindowFirstPageHint = -1
            pendingWindowRequest = request.copy(
                directionHint = evidence.directionHint,
                reverseFirstPageHint = evidence.reverseFirstPageHint,
            )
            if (windowDispatchPosted) return
            windowDispatchPosted = true
        }
        val deliver = Runnable {
            val latest = synchronized(stateLock) {
                windowDispatchPosted = false
                val next = pendingWindowRequest
                pendingWindowRequest = null
                next
            } ?: return@Runnable
            deliverWindowRequest(latest)
        }
        val busyDispatch = fromInput || request.busy
        if (busyDispatch) {
            postOnAnimation(deliver)
        } else {
            mainHandler.post(deliver)
        }
    }

    private fun deliverWindowRequest(latest: WindowRequest) {
        val current = synchronized(stateLock) {
            refreshWindowRequestViewportLocked(latest)
        }
        val currentListener = listener ?: return
        if (current.blockedForwardPage >= 0) {
            currentListener.onBlockedForwardPageRequested(current.blockedForwardPage)
        }
        currentListener.onWindowChanged(
            current.firstPage,
            current.lastPage,
            current.anchorPage,
            current.physicalFirstPage,
            current.physicalLastPage,
            current.progressPage,
            current.progressOffset,
            current.busy,
            current.directionHint,
            current.reverseFirstPageHint,
        )
        if (current.visibleLoadingRedrive) {
            currentListener.onVisibleLoadingWindowRequested(
                current.firstPage,
                current.lastPage,
                current.anchorPage,
                current.physicalFirstPage,
                current.physicalLastPage,
                current.busy,
                current.directionHint,
            )
        }
        if (current.notifyNearStart) currentListener.onNearBoundary(DIRECTION_PREVIOUS, current.anchorPage)
        if (current.notifyNearEnd) currentListener.onNearBoundary(DIRECTION_NEXT, current.anchorPage)
    }

    /** Must be called with [stateLock] held immediately before a main-thread delivery. */
    private fun refreshWindowRequestViewportLocked(request: WindowRequest): WindowRequest {
        if (pages.isEmpty() || width <= 0 || height <= 0) return request
        // A request may be captured by input and delivered one frame later. Pixel/geometry actors
        // can enqueue another request in that interval, so the payload is an invalid place to own
        // the toolbar page or decode anchor. Re-sample the one authoritative Surface coordinate at
        // delivery while retaining the accumulated direction/boundary evidence.
        val busy = lastBusy
        val anchor = anchorPageLocked()
        val first = max(0, anchor - ReaderPipelinePolicy.windowBefore(busy))
        val last = min(pages.lastIndex, anchor + ReaderPipelinePolicy.windowAfter(busy))
        val physicalFirst = firstVisiblePageLocked(scrollOffset).coerceIn(0, pages.lastIndex)
        val physicalLast = firstVisiblePageLocked(
            (scrollOffset + height.toFloat() - 1f).coerceAtLeast(scrollOffset),
        ).coerceIn(physicalFirst, pages.lastIndex)
        val progress = progressPositionLocked() ?: return request
        val boundaryPx = height * NEAR_BOUNDARY_SCREENFULS
        val nearStart = scrollOffset <= boundaryPx ||
            anchor <= NEAR_BOUNDARY_PAGE_THRESHOLD
        val remainingPx = contentHeight - (scrollOffset + height)
        val nearEnd = remainingPx <= boundaryPx ||
            anchor >= pages.size - NEAR_BOUNDARY_PAGE_THRESHOLD
        return request.copy(
            firstPage = first,
            lastPage = last,
            anchorPage = anchor,
            physicalFirstPage = physicalFirst,
            physicalLastPage = physicalLast,
            progressPage = progress.page,
            progressOffset = progress.offset,
            busy = busy,
            nearStart = nearStart,
            nearEnd = nearEnd,
            notifyNearStart = request.notifyNearStart && nearStart,
            notifyNearEnd = request.notifyNearEnd && nearEnd,
        )
    }

    private fun dispatchBoundaryRequest(request: BoundaryRequest?) {
        if (request == null) return
        postOnAnimationDelayed({
            listener?.onBoundaryReached(request.direction, request.anchorPage)
        }, BOUNDARY_DISPATCH_POST_FRAME_DELAY_MS)
    }

    private fun anchorPageLocked(): Int {
        rebuildLayoutLocked()
        val probe = scrollOffset + height * 0.35f
        return firstVisiblePageLocked(probe).coerceIn(0, pages.lastIndex)
    }

    private fun pageOffsetLocked(index: Int): Int {
        if (index < 0 || index >= pages.size) return 0
        rebuildLayoutLocked()
        return (pageTopOrElseLocked(index, 0f) - scrollOffset).toInt()
    }

    private fun applyLockedRestorePositionLocked() {
        val target = lockedRestorePage
        if (target !in 0 until pages.size) return
        if (physicalInputOwnsViewportLocked()) {
            // Restore is launch/lifecycle state. It can never overwrite a coordinate already
            // owned by touch, fling, or a retained edge-limited physical destination.
            clearLockedRestorePositionLocked()
            clearDirectWifiForwardOnlyInitialResumeContractLocked()
            return
        }
        val preserveForwardOnlyUntilPhysicalReveal =
            directWifiForwardOnlyInitialResumeEnabled &&
                directWifiForwardOnlyInitialResumePage == target &&
                !directWifiForwardOnlyInitialResumeRevealQualified
        val preserveUntilBookmarkGeometryResolves =
            directWifiForwardOnlyInitialResumeEnabled &&
                directWifiForwardOnlyInitialResumePage == target &&
                !pageHasCompleteActualPixelsLocked(pages[target])
        if (SystemClock.uptimeMillis() > lockedRestoreUntilMs &&
            !preserveForwardOnlyUntilPhysicalReveal &&
            !preserveUntilBookmarkGeometryResolves
        ) {
            clearLockedRestorePositionLocked()
            return
        }
        rebuildLayoutLocked()
        val restoreOffset = repairedDirectWifiInitialRestoreOffsetLocked(target)
        val desiredScroll = pageTopOrElseLocked(target, 0f) - restoreOffset
        val maxScroll = maxScrollLocked()
        val restoredScroll = desiredScroll.coerceIn(0f, maxScroll)
        setScrollOffsetLocked(restoredScroll)
        // A different forward page can become drawable a few milliseconds before the bookmark
        // page, and exact next-p0 can arrive long after the old four-second safety window. Keep the
        // immutable bookmark coordinate until the complete source-qualified transition viewport is
        // proven. User input clears the lock independently, so this never fights an intentional
        // scroll and needs no network-speed-dependent timeout.
        if (
            !preserveForwardOnlyUntilPhysicalReveal &&
            !preserveUntilBookmarkGeometryResolves &&
            hasDrawnContentFrame &&
            pageHasDrawableContentLocked(target) &&
            abs(restoredScroll - desiredScroll) <= RESTORE_POSITION_EPSILON_PX
        ) {
            clearLockedRestorePositionLocked()
        }
    }

    private fun clearLockedRestorePositionLocked() {
        lockedRestorePage = -1
        lockedRestoreOffset = 0
        lockedRestoreUntilMs = 0L
    }

    private fun physicalInputOwnsViewportLocked(): Boolean = physicalInputOwnsViewport(
        preContentGestureActive = preContentGestureActive,
        preContentForwardIntentPending =
            preContentForwardIntentPx > SCROLL_OFFSET_EPSILON_PX,
        blockedForwardIntentPending = blockedForwardIntentTarget.isFinite(),
        pointerDown = pointerDown,
        dragging = dragging,
        scrollerFinished = scroller.isFinished,
        recentScrollSettling = isRecentScrollSettlingLocked(),
    )

    /** Ends the one-shot cold-resume classifier without disabling the episode texture profile. */
    private fun clearDirectWifiForwardOnlyInitialResumeContractLocked() {
        directWifiForwardOnlyInitialResumePage = -1
        directWifiForwardOnlyInitialResumeOffset = 0
        directWifiForwardOnlyInitialResumeRevealQualified = false
        directWifiForwardOnlyTerminalTailRevealQualified = false
    }

    private fun viewportAnchorLocked(): ViewportAnchor? {
        if (pages.isEmpty() || width <= 0 || height <= 0) return null
        rebuildLayoutLocked()
        val maxScroll = maxScrollLocked()
        val page = if (maxScroll > 0f && scrollOffset >= maxScroll - BOUNDARY_EPSILON_PX) {
            pages.lastIndex
        } else {
            firstVisiblePageLocked(scrollOffset + height * PROGRESS_PAGE_PROBE_SCREEN_RATIO)
                .coerceIn(0, pages.lastIndex)
        }
        return ViewportAnchor(
            page = page,
            pageTopInViewportPx = pageTopOrElseLocked(page, 0f) - scrollOffset,
        )
    }

    private fun progressPositionLocked(): ProgressPosition? {
        if (pages.isEmpty() || width <= 0 || height <= 0) return null
        rebuildLayoutLocked()
        val maxScroll = maxScrollLocked()
        if (maxScroll > 0f && scrollOffset >= maxScroll - BOUNDARY_EPSILON_PX) {
            val lastPage = pages.lastIndex
            return ProgressPosition(lastPage, pageOffsetLocked(lastPage))
        }
        val page = firstVisiblePageLocked(scrollOffset + height * PROGRESS_PAGE_PROBE_SCREEN_RATIO)
            .coerceIn(0, pages.lastIndex)
        return ProgressPosition(page, pageOffsetLocked(page))
    }

    private fun restoreViewportAnchorLocked(
        anchor: ViewportAnchor?,
        reason: String,
        index: Int = -1,
        oldHeight: Float = 0f,
        newHeight: Float = 0f
    ) {
        if (restoreLifecycleViewportAnchorAfterGeometryLocked(reason, index, oldHeight, newHeight)) {
            return
        }
        val target = anchor?.page ?: return
        if (target !in pages.indices) return
        rebuildLayoutLocked()
        val before = scrollOffset
        val desired = pageTopOrElseLocked(target, 0f) - anchor.pageTopInViewportPx
        // A height/bounds mutation changes the document coordinate beneath the user's finger or
        // OverScroller; it is not user motion. Refusing this rebase while input is active keeps the
        // numeric offset stable but visibly replaces the current source page with a predecessor.
        // Structural ownership rebases the active input origins below, so the next MOVE/tick
        // continues from the same physical pixels without a jump or a velocity reset.
        setStructuralScrollOffsetLocked(desired)
        clampScrollLocked()
        if (abs(scrollOffset - before) > HEIGHT_CHANGE_EPSILON_PX) {
            Log.d(
                TAG,
                "reader_viewport_anchor_restore reason=$reason index=$index anchor=$target " +
                    "anchorOffset=${anchor.pageTopInViewportPx} " +
                    "old=${oldHeight.toInt()} new=${newHeight.toInt()} " +
                    "from=${before.toInt()} to=${scrollOffset.toInt()} lastBusy=$lastBusy"
            )
        }
    }

    /** Reprojects the HOME-owned content identity before any numeric page anchor may take over. */
    private fun restoreLifecycleViewportAnchorAfterGeometryLocked(
        reason: String,
        index: Int,
        oldHeight: Float,
        newHeight: Float,
    ): Boolean {
        if (!lifecycleRestoreInputPending ||
            !lifecycleViewportAnchorPageTopPx.isFinite()
        ) return false
        val identity = lifecycleViewportAnchorIdentity ?: return false
        val target = pages.indexOfFirst { page ->
            val current = page.committedIdentity
            current != null &&
                current.normalizedEpisodePath == identity.normalizedEpisodePath &&
                current.sourcePageIndex == identity.sourcePageIndex &&
                current.canonicalAsset == identity.canonicalAsset &&
                current.manifestDigest == identity.manifestDigest &&
                current.manifestPageCount == identity.manifestPageCount
        }
        if (target < 0) return false
        rebuildLayoutLocked()
        val before = scrollOffset
        val desired = pageTopOrElseLocked(target, 0f) - lifecycleViewportAnchorPageTopPx
        setStructuralScrollOffsetLocked(desired)
        clampScrollLocked()
        if (abs(scrollOffset - before) > HEIGHT_CHANGE_EPSILON_PX) {
            Log.d(
                TAG,
                "reader_lifecycle_geometry_anchor_restore reason=$reason index=$index " +
                    "path=${identity.normalizedEpisodePath},source=${identity.sourcePageIndex}," +
                    "page=$target,top=$lifecycleViewportAnchorPageTopPx," +
                    "old=${oldHeight.toInt()},new=${newHeight.toInt()}," +
                    "from=${before.toInt()},to=${scrollOffset.toInt()}",
            )
        }
        return true
    }

    private fun clampScrollLocked() {
        val maxScroll = effectiveMaxScrollLocked(maxScrollLocked())
        val minScroll = if (prependedRevealHoldPage in pages.indices) {
            min(pageTopOrElseLocked(prependedRevealHoldPage, 0f), maxScroll)
        } else {
            0f
        }.coerceAtMost(maxScroll)
        setScrollOffsetLocked(scrollOffset.coerceIn(minScroll, maxScroll))
        repairUnsafeDrawableViewportLocked("bounds_clamp")
    }

    private fun clampForwardScrollLocked() {
        val contentMaxScroll = effectiveMaxScrollLocked(maxScrollLocked())
        val maxScroll = effectiveMaxScrollLocked(
            if (limitScrollToDrawablePrefix) forwardScrollLimitLocked() else maxScrollLocked()
        )
        val minScroll = if (prependedRevealHoldPage in pages.indices) {
            min(pageTopOrElseLocked(prependedRevealHoldPage, 0f), maxScroll)
        } else {
            0f
        }.coerceAtMost(maxScroll)
        val before = scrollOffset
        val clamped = scrollOffset.coerceIn(minScroll, maxScroll)
        val contentBoundsCorrection = shouldApplyContentMaxShrinkCorrection(
            scrollOffset,
            contentMaxScroll,
            contentMaxScroll
        )
        val activeOrRecentInput = pointerDown ||
            dragging ||
            !scroller.isFinished ||
            (lastScrollInteractionMs > 0L &&
                SystemClock.uptimeMillis() - lastScrollInteractionMs <= HEIGHT_CHANGE_SCROLL_ADJUST_QUIET_MS)
        if (contentBoundsCorrection) {
            // A content-height shrink can leave the current viewport physically beyond the new
            // end. This is bounds repair, not a user-direction reversal, and must remove the
            // exposed terminal strip immediately even while a forward gesture is active.
            setStructuralScrollOffsetLocked(contentMaxScroll)
        } else if (
            clamped < scrollOffset - SCROLL_OFFSET_EPSILON_PX &&
            activeOrRecentInput
        ) {
            scheduleBlockedForwardWindowRequestLocked()
        } else {
            setScrollOffsetLocked(clamped)
        }
        if (
            !isNextBoundaryGeometryHeldLocked() &&
            limitScrollToDrawablePrefix &&
            scrollOffset < before - SCROLL_OFFSET_EPSILON_PX
        ) {
            scheduleBlockedForwardWindowRequestLocked()
        }
        repairUnsafeDrawableViewportLocked("forward_clamp")
    }

    /**
     * A bookmark page is selected by the progress probe, so a valid saved page/offset pair always
     * leaves meaningful pixels from that page in the resumed viewport. Old placeholder geometry
     * can violate that invariant after the original dimensions arrive (for example, a short manga
     * page paired with a large negative offset). In the direct-Wi-Fi forward-only cold path there
     * are intentionally no predecessor pixels to fill such a viewport. Keep the stable saved page
     * identity and repair only the impossible offset after that page's complete original pixels
     * establish its real draw height. Progressive HWUI admission is deliberately independent:
     * another forward page may reveal first without invalidating the still-pending bookmark
     * correction. This changes neither surface admission nor reveal timing.
     */
    private fun repairedDirectWifiInitialRestoreOffsetLocked(target: Int): Int {
        val savedOffset = lockedRestoreOffset
        if (!directWifiForwardOnlyInitialResumeEnabled ||
            target != lockedRestorePage ||
            target !in pages.indices || width <= 0 || height <= 0
        ) return savedOffset
        val page = pages[target]
        if (page.pendingResolveType != PENDING_NONE ||
            !pageHasCompleteActualPixelsLocked(page)
        ) return savedOffset
        val pageHeight = pageDrawHeightLocked(page)
        val repairedOffset = repairForwardOnlyRestoreOffset(
            savedOffset,
            pageHeight,
            height,
        )
        if (repairedOffset == savedOffset) return savedOffset
        lockedRestoreOffset = repairedOffset
        if (directWifiForwardOnlyInitialResumePage == target) {
            directWifiForwardOnlyInitialResumeOffset = repairedOffset
        }
        Log.d(
            TAG,
            "reader_initial_restore_offset_repaired page=$target saved=$savedOffset " +
                "repaired=$repairedOffset pageHeight=${pageHeight.toInt()} viewportHeight=$height"
        )
        return repairedOffset
    }

    private fun applyPreparedStartAnchorLocked(clearPending: Boolean) {
        val target = pendingPreparedStartPage
        if (target !in pages.indices) return
        val viewportHeight = if (height > 0) height else pendingPreparedViewportHeight
        val desiredScroll = pageTopOrElseLocked(target, 0f) - pendingPreparedStartOffset
        val maxScroll = max(0f, contentHeight - max(1, viewportHeight))
        scrollOffset = desiredScroll.coerceIn(0f, maxScroll)
        if (clearPending) clearPreparedStartAnchorLocked()
    }

    private fun clearPreparedStartAnchorLocked() {
        pendingPreparedStartPage = -1
        pendingPreparedStartOffset = 0
        pendingPreparedViewportWidth = 0
        pendingPreparedViewportHeight = 0
    }

    private fun scheduleVisibleLoadingHoldRetryLocked() {
        if (visibleLoadingHoldRetryPosted) return
        visibleLoadingHoldRetryPosted = true
        mainHandler.postDelayed({
            var livenessRequest: WindowRequest? = null
            synchronized(stateLock) {
                visibleLoadingHoldRetryPosted = false
                if (!renderRunning || pages.isEmpty()) return@synchronized
                if (shouldBlockInitialEmptyFrameLocked()) return@synchronized
                val now = SystemClock.uptimeMillis()
                if (now - lastVisibleLoadingWindowRedriveAtMs >=
                    VISIBLE_LOADING_WINDOW_REDRIVE_MS
                ) {
                    livenessRequest = windowRequestLocked(
                        busy = lastBusy,
                        forceDispatch = true,
                        visibleLoadingRedrive = true,
                    )
                    if (livenessRequest != null) {
                        lastVisibleLoadingWindowRedriveAtMs = now
                    }
                }
                renderRequested = true
                scheduleFrameLocked()
                stateLock.notifyAll()
            }
            dispatchWindowRequest(livenessRequest)
        }, VISIBLE_LOADING_HOLD_RETRY_MS)
    }

    private fun maybeReleasePrependedReadyHoldLocked(index: Int) {
        if (prependedReadyHoldRequired <= 0 || prependedReadyHoldInserted <= 0) return
        if (index !in 0 until prependedReadyHoldInserted) return
        var ready = 0
        val end = min(prependedReadyHoldInserted, pages.size)
        for (i in 0 until end) {
            val page = pages[i]
            if (page.cardText != null) continue
            if (page.bitmap != null || page.tiles.isNotEmpty()) ready++
            if (ready >= prependedReadyHoldRequired) {
                clearPrependedReadyHoldLocked()
                return
            }
        }
    }

    private fun clearPrependedReadyHoldLocked() {
        prependedReadyHoldInserted = 0
        prependedReadyHoldRequired = 0
        if (prependedRevealHoldPage >= 0) prependedRevealHoldPage = -1
    }

    private fun maxScrollLocked(): Float {
        val viewportHeight = if (height > 0) height else pendingPreparedViewportHeight
        val contentMax = max(0f, totalHeightLocked() - max(1, viewportHeight))
        val forwardOnlyTarget = directWifiForwardOnlyInitialResumePage
        if (!directWifiForwardOnlyInitialResumeEnabled ||
            !surfaceAttachmentDeferredUntilActualPixels ||
            forwardOnlyTarget !in pages.indices
        ) return contentMax
        // This is a temporary pre-presentation bound only. It creates no motion and disappears as
        // soon as the exact forward pages make the ordinary content max large enough.
        val forwardOnlyScroll = pageTopOrElseLocked(forwardOnlyTarget, contentMax) -
            directWifiForwardOnlyInitialResumeOffset
        return max(contentMax, forwardOnlyScroll)
    }

    private fun forwardScrollLimitLocked(scheduleBlocked: Boolean = true): Float {
        val fullMaxScroll = maxScrollLocked()
        if (!limitScrollToDrawablePrefix || pages.isEmpty() || height <= 0) return fullMaxScroll
        if (allPagesHaveDrawableContentLocked()) return fullMaxScroll
        val firstRelevant = firstVisiblePageLocked(scrollOffset).coerceIn(0, pages.lastIndex)
        var start = firstRelevant
        while (start > 0 && pageTopOrElseLocked(start, 0f) > scrollOffset) {
            if (!pageHasDrawableContentLocked(start - 1)) break
            start--
        }
        if (!drawableViewportCleanAtScrollLocked(scrollOffset)) {
            if (scheduleBlocked) scheduleBlockedForwardWindowRequestLocked()
            return scrollOffset.coerceIn(0f, fullMaxScroll)
        }
        // firstVisiblePageLocked intentionally treats an exact bottom-edge equality as visible so
        // reverse-boundary and progress probes do not skip a page. The forward drawable fence has
        // a different contract: a page whose content bottom is at (or fractionally behind) the
        // viewport top occupies no physical pixel and cannot block motion away from it. This is
        // common after an immediate reverse: p6 can remain the inclusive first index while the
        // clean viewport is wholly p7/p8. Skip only these non-overlapping leading pages; a missing
        // page with even one real viewport pixel remains protected by the clean-viewport gate.
        while (start <= pages.lastIndex &&
            isPageBehindOrAtViewportTop(
                pageTopOrElseLocked(start, 0f) + pageDrawHeightLocked(pages[start]),
                scrollOffset,
                SCROLL_OFFSET_EPSILON_PX,
            )
        ) {
            start++
        }
        val edgeFillPx = if (inlineRealPixelsOnly) 0 else COVERAGE_EDGE_FILL_PX
        for (index in start..pages.lastIndex) {
            val adjacentPrefixBottom = adjacentExactPrefixBottomLocked(index)
            if (adjacentPrefixBottom != null &&
                !pageHasCompleteDrawableContentLocked(index)
            ) {
                if (scheduleBlocked) scheduleBlockedForwardWindowRequestLocked()
                return min(
                    fullMaxScroll,
                    adjacentPrefixBottom - height + edgeFillPx,
                ).coerceAtLeast(0f)
            }
            if (!pageHasDrawableContentLocked(index)) {
                if (scheduleBlocked) scheduleBlockedForwardWindowRequestLocked()
                val missingTop = pageTopOrElseLocked(index, fullMaxScroll + height)
                return min(fullMaxScroll, missingTop - height + edgeFillPx)
                    .coerceAtLeast(0f)
            }
        }
        return fullMaxScroll
    }

    /** Must be called with [stateLock] held. */
    private fun hasSealedInitialExactStructureLocked(): Boolean {
        val firstIdentity = pages.firstOrNull()?.committedIdentity ?: return false
        val episodePath = firstIdentity.normalizedEpisodePath
        val manifestDigest = firstIdentity.manifestDigest
        val manifestPageCount = firstIdentity.manifestPageCount
        if (episodePath.isBlank() || manifestDigest.isBlank() ||
            manifestPageCount <= 0 || manifestPageCount != pages.size
        ) return false
        for (index in pages.indices) {
            val page = pages[index]
            val identity = page.committedIdentity ?: return false
            if (page.cardText != null || page.errorText != null ||
                identity.displayPageIndex != index || identity.sourcePageIndex != index ||
                identity.normalizedEpisodePath != episodePath ||
                identity.manifestDigest != manifestDigest ||
                identity.manifestPageCount != manifestPageCount ||
                identity.canonicalAsset.isBlank()
            ) return false
        }
        return true
    }

    /**
     * Read-only exact-manifest proof for the Activity's progress owner. A fully identity-bound
     * table is not the legacy partial ACK runway and must not be clamped to its prefix.
     */
    fun hasSealedInitialExactStructure(): Boolean = synchronized(stateLock) {
        hasSealedInitialExactStructureLocked()
    }

    private fun capForwardInputScrollLocked(
        rawNext: Float,
        direction: Int,
        physicalGestureTarget: Float = rawNext,
    ): Float {
        if (direction == DIRECTION_PREVIOUS) clearBlockedForwardIntentLocked()
        if (!limitScrollToDrawablePrefix || direction != DIRECTION_NEXT) return rawNext
        if (pages.isEmpty() || height <= 0) return rawNext
        val episodeScopedNext = targetAfterAcknowledgedEpisodeBoundaryLocked(
            rawNext,
            physicalGestureTarget,
        )
        val tailLimit = physicalEpisodeTailHoldLimitLocked(episodeScopedNext, direction)
        val requestedNext = tailLimit?.let { min(episodeScopedNext, it) } ?: episodeScopedNext
        // Physical input owns only the desired coordinate. Installing pending Bitmap/tile owners
        // can retire resources, rebuild layout and restore anchors; doing that while main holds
        // stateLock lets a preempted input callback block the urgent display producer for hundreds
        // of milliseconds. prepareRenderWork applies the exact same pending pixels before it
        // builds a frame. Until then, fail closed at the current drawable limit and retain the
        // user's blocked intent for the producer-owned resume.
        val pendingDrawableResolve = hasPendingPageResolvesLocked()
        if (pendingDrawableResolve) renderRequested = true
        if (allPagesHaveDrawableContentLocked()) return requestedNext
        val maxScroll = maxScrollLocked()
        // A clean destination is not sufficient proof for a physical forward gesture. A large
        // MOVE/fling sample can land on an already-drawable successor runway after jumping over
        // one or more pressure-retired pages in the current episode. Surface then keeps the last
        // clean frame while Session observes a window beyond the real blocker, so the skipped
        // current-episode pixels can no longer reclaim their decode slots. The continuous
        // drawable limit below starts at the current viewport and is therefore the authority for
        // every forward sample, including a clean-looking destination.
        val limit = forwardScrollLimitLocked(scheduleBlocked = false)
        if (isForwardDestinationWithinDrawableInterval(requestedNext, limit)) {
            return requestedNext
        }
        val boundedPhysicalIntent = tailLimit?.let {
            min(physicalGestureTarget, it)
        } ?: physicalGestureTarget
        if (pointerDown || dragging) {
            rememberBlockedForwardIntentLocked(boundedPhysicalIntent)
        } else {
            // Reaching a missing drawable after finger-up terminates the kinetic segment at this
            // exact clean cap. Pixels arriving later may widen the next gesture's range, but must
            // never manufacture a fresh autonomous scroll segment.
            clearBlockedForwardIntentLocked()
        }
        scheduleBlockedForwardWindowRequestLocked()
        if (shouldLogForwardCapLocked()) {
            val blockedForward = blockedForwardTargetPageLocked()
            Log.d(
                TAG,
                "reader_forward_cap raw=${rawNext.toInt()} limit=${limit.toInt()} " +
                    "scroll=${scrollOffset.toInt()} first=${firstVisiblePageLocked(scrollOffset)} " +
                    "blocked=$blockedForward " +
                    "blockedTop=${drawablePageTopLocked(blockedForward).toInt()} " +
                    "globalMissing=${firstMissingDrawablePageLocked()} max=${maxScrollLocked().toInt()}"
            )
        }
        // If exact tail geometry resolved behind the viewport, the ordinary no-backstep cap would
        // preserve an already escaped coordinate. A still-missing tail can place its drawable
        // limit slightly before the episode hold itself; return that stricter bound so the View
        // first waits for the canonical tail pixels, then advances to the clean-tail proof point.
        val escapedTail = tailLimit != null &&
            scrollOffset > tailLimit + SCROLL_OFFSET_EPSILON_PX
        return if (escapedTail) min(requestedNext, limit) else max(scrollOffset, limit)
    }

    /** Must be called with [stateLock] held. */
    private fun targetAfterAcknowledgedEpisodeBoundaryLocked(
        requestedTarget: Float,
        physicalGestureTarget: Float,
    ): Float {
        if (requestedTarget <= physicalGestureTarget + SCROLL_OFFSET_EPSILON_PX) {
            return requestedTarget
        }
        val hold = physicalEpisodeTailHold ?: return requestedTarget
        if (abs(scrollOffset - hold.scrollLimit) > SCROLL_OFFSET_EPSILON_PX) {
            return requestedTarget
        }
        val acknowledged = NtkPhysicalEpisodeTailHoldPolicy
            .isPriorGestureAcknowledgementObservable(
                acknowledgedGestureRevision = cleanPhysicalEpisodeTailGestureRevisions[hold.key],
                currentGestureRevision = physicalGestureRevision,
                presentedUptimeNanos = cleanPhysicalEpisodeTailPresentedNanos[hold.key] ?: 0L,
                nowUptimeNanos = SystemClock.elapsedRealtimeNanos(),
                minimumDwellNanos = CLEAN_PHYSICAL_EPISODE_TAIL_MIN_DWELL_NANOS,
            )
        val scoped = NtkPhysicalEpisodeTailHoldPolicy.targetAfterAcknowledgedEpisodeBoundary(
            requestedTarget = requestedTarget,
            physicalGestureTarget = physicalGestureTarget,
            boundaryOffset = hold.scrollLimit,
            priorGestureAcknowledgementObservable = acknowledged,
            epsilonPx = SCROLL_OFFSET_EPSILON_PX,
        )
        if (scoped < requestedTarget - SCROLL_OFFSET_EPSILON_PX) {
            // The old absolute intent is now terminal. If the successor's own drawable prefix
            // later blocks this new gesture, capForwardInputScrollLocked records only its real
            // successor-relative travel as a fresh intent.
            clearBlockedForwardIntentLocked()
            Log.d(
                TAG,
                "reader_forward_carry_rebased_at_episode_boundary " +
                    "from=${requestedTarget.toInt()},to=${scoped.toInt()}," +
                    "boundary=${hold.scrollLimit.toInt()},gesture=$physicalGestureRevision",
            )
        }
        return scoped
    }

    /** Must be called with stateLock held. */
    private fun physicalEpisodeTailHoldLimitLocked(
        rawNext: Float,
        direction: Int,
    ): Float? {
        if (physicalGestureRevision <= 0L || direction != DIRECTION_NEXT ||
            !rawNext.isFinite() || rawNext <= scrollOffset + SCROLL_OFFSET_EPSILON_PX
        ) return null
        rebuildLayoutLocked()
        // Once a gesture has been parked, retain that exact physical coordinate for the rest of
        // the gesture without rediscovering the tail in a concurrently growing/rebased page
        // table. A successor append can otherwise move the local scan window past the tail and
        // let later MOVE samples from the same finger cross immediately after its ACK.
        physicalEpisodeTailHold?.let { hold ->
            NtkPhysicalEpisodeTailHoldPolicy.retainedSameGestureHoldLimit(
                direction = direction,
                forwardDirection = DIRECTION_NEXT,
                requestedOffset = rawNext,
                holdLimit = hold.scrollLimit,
                holdGestureRevision = physicalEpisodeTailHoldGestureRevision,
                currentGestureRevision = physicalGestureRevision,
                epsilonPx = SCROLL_OFFSET_EPSILON_PX,
            )?.let { return it }
        }
        val boundedTarget = rawNext.coerceIn(0f, maxScrollLocked())
        val currentFirst = firstVisiblePageLocked(scrollOffset).coerceIn(0, pages.lastIndex)
        val targetFirst = firstVisiblePageLocked(boundedTarget).coerceIn(0, pages.lastIndex)
        val scanFirst = max(0, min(currentFirst, targetFirst) - 1)
        val scanLast = min(pages.lastIndex, max(currentFirst, targetFirst) + 2)
        for (index in scanFirst..scanLast) {
            val identity = pages[index].committedIdentity ?: continue
            val key = exactEpisodeTailKey(identity) ?: continue
            if (identity.sourcePageIndex != identity.manifestPageCount - 1) continue
            // A committed manifest identity proves where the episode ends, not that its final
            // pixels exist. Creating the clean-tail hold for an unresolved final page clamps the
            // requested coordinate to the same drawable-prefix limit and prevents the ordinary
            // blocked-page request below from ever naming that page. Let the drawable-prefix path
            // own the gesture until the complete canonical tail is actually installed.
            if (!pageHasCompleteDrawableContentLocked(index)) continue
            val next = pages.getOrNull(index + 1)
            val nextIdentity = next?.committedIdentity
            val successorIsSameTailFragment = nextIdentity != null &&
                exactEpisodeTailKey(nextIdentity) == key &&
                nextIdentity.sourcePageIndex == identity.sourcePageIndex
            if (!NtkPhysicalEpisodeTailHoldPolicy.isBoundaryAfterExactTail(
                    successorIsSameTailFragment = successorIsSameTailFragment,
                )
            ) continue
            val pageBottom = pageTopOrElseLocked(index, Float.MAX_VALUE) +
                pageDrawHeightLocked(pages[index])
            val boundaryOffset = (pageBottom - height).coerceAtLeast(0f)
            val heldInCurrentGesture = physicalEpisodeTailHold?.key == key &&
                physicalEpisodeTailHoldGestureRevision == physicalGestureRevision
            val acknowledgedRevision = cleanPhysicalEpisodeTailGestureRevisions[key]
            val acknowledgedPresentedNanos = cleanPhysicalEpisodeTailPresentedNanos[key] ?: 0L
            val acknowledged = acknowledgedRevision != null &&
                acknowledgedRevision < physicalGestureRevision &&
                NtkPhysicalEpisodeTailHoldPolicy.isAcknowledgementObservable(
                    presentedUptimeNanos = acknowledgedPresentedNanos,
                    nowUptimeNanos = SystemClock.elapsedRealtimeNanos(),
                    minimumDwellNanos = CLEAN_PHYSICAL_EPISODE_TAIL_MIN_DWELL_NANOS,
                )
            if (!NtkPhysicalEpisodeTailHoldPolicy.shouldHoldCrossing(
                    direction = direction,
                    forwardDirection = DIRECTION_NEXT,
                    currentOffset = scrollOffset,
                    requestedOffset = rawNext,
                    boundaryOffset = boundaryOffset,
                    tailAcknowledged = acknowledged,
                    heldInCurrentGesture = heldInCurrentGesture,
                    epsilonPx = SCROLL_OFFSET_EPSILON_PX,
                )
            ) {
                if (NtkPhysicalEpisodeTailHoldPolicy.isNewAcknowledgedBoundaryCrossing(
                        currentOffset = scrollOffset,
                        requestedOffset = rawNext,
                        boundaryOffset = boundaryOffset,
                        tailAcknowledged = acknowledged,
                        heldInCurrentGesture = heldInCurrentGesture,
                        epsilonPx = SCROLL_OFFSET_EPSILON_PX,
                    )
                ) {
                    acknowledgedBoundaryCrossedInPhysicalGesture = true
                }
                if (acknowledged && physicalEpisodeTailHold?.key == key &&
                    physicalEpisodeTailHoldGestureRevision != physicalGestureRevision
                ) {
                    physicalEpisodeTailHold = null
                    physicalEpisodeTailHoldGestureRevision = 0L
                }
                continue
            }
            val enteringNewHeldGesture = physicalEpisodeTailHold?.key != key ||
                physicalEpisodeTailHoldGestureRevision != physicalGestureRevision
            physicalEpisodeTailHold = PhysicalEpisodeTailBoundary(
                key = key,
                displayPageIndex = index,
                scrollLimit = boundaryOffset,
            )
            physicalEpisodeTailHoldGestureRevision = physicalGestureRevision
            // The successor can append another page after the first held proof was requested.
            // That advances the structure epoch, so Activity correctly rejects the old proof. A
            // later real gesture at the same coordinate must request a new proof bound to the
            // current structure instead of being suppressed forever by the stale request key.
            if (!acknowledged && enteringNewHeldGesture) {
                physicalEpisodeTailProofRequestedKey = null
            } else if (physicalEpisodeTailProofRequestedKey != key) {
                physicalEpisodeTailProofRequestedKey = null
            }
            val holdLogNowMs = SystemClock.elapsedRealtime()
            if (lastPhysicalEpisodeTailHoldLogGestureRevision != physicalGestureRevision &&
                holdLogNowMs - lastPhysicalEpisodeTailHoldLogAtMs >= 1_000L
            ) {
                lastPhysicalEpisodeTailHoldLogGestureRevision = physicalGestureRevision
                lastPhysicalEpisodeTailHoldLogAtMs = holdLogNowMs
                Log.d(
                    TAG,
                    "reader_physical_episode_tail_hold path=${key.normalizedEpisodePath} " +
                        "source=${identity.sourcePageIndex},page=$index," +
                        "limit=${boundaryOffset.toInt()},raw=${rawNext.toInt()}," +
                        "acknowledged=$acknowledged,gesture=$physicalGestureRevision",
                )
            }
            return boundaryOffset
        }
        return null
    }

    /** Must be called with stateLock held after capForwardInputScrollLocked(). */
    private fun isCleanPhysicalEpisodeTailHoldAppliedLocked(boundedOffset: Float): Boolean {
        val hold = physicalEpisodeTailHold ?: return false
        return physicalEpisodeTailHoldGestureRevision == physicalGestureRevision &&
            abs(boundedOffset - hold.scrollLimit) <= SCROLL_OFFSET_EPSILON_PX &&
            drawableViewportCleanAtScrollLocked(boundedOffset)
    }

    /** Must be called with [stateLock] held after the physical input cap was applied. */
    private fun heldPhysicalEpisodeTailDrawLimitLocked(): Int? {
        val hold = physicalEpisodeTailHold ?: return null
        if (abs(scrollOffset - hold.scrollLimit) > SCROLL_OFFSET_EPSILON_PX) return null
        return hold.displayPageIndex.takeIf { it in pages.indices }
    }

    /**
     * A range removal renumbers retained pages and changes their document coordinates. Preserve a
     * live exact-tail hold by content identity, not by its obsolete display index/scroll offset.
     * The structure epoch changes after this method, so any previously requested proof must be
     * resubmitted against the rebased structure.
     */
    private fun rebasePhysicalEpisodeTailHoldAfterRemovalLocked(
        startIndex: Int,
        endExclusive: Int,
    ) {
        val hold = physicalEpisodeTailHold ?: return
        val removedCount = (endExclusive - startIndex).coerceAtLeast(0)
        val rebasedIndex = when {
            hold.displayPageIndex < startIndex -> hold.displayPageIndex
            hold.displayPageIndex >= endExclusive -> hold.displayPageIndex - removedCount
            else -> -1
        }
        val retainedIdentity = pages.getOrNull(rebasedIndex)?.committedIdentity
        if (retainedIdentity == null || exactEpisodeTailKey(retainedIdentity) != hold.key ||
            retainedIdentity.sourcePageIndex != retainedIdentity.manifestPageCount - 1
        ) {
            physicalEpisodeTailHold = null
            physicalEpisodeTailHoldGestureRevision = 0L
            if (physicalEpisodeTailProofRequestedKey == hold.key) {
                physicalEpisodeTailProofRequestedKey = null
            }
            return
        }
        val rebasedLimit = (
            pageTopOrElseLocked(rebasedIndex, Float.MAX_VALUE) +
                pageDrawHeightLocked(pages[rebasedIndex]) - height
            ).coerceAtLeast(0f)
        physicalEpisodeTailHold = hold.copy(
            displayPageIndex = rebasedIndex,
            scrollLimit = rebasedLimit,
        )
        if (physicalEpisodeTailProofRequestedKey == hold.key) {
            physicalEpisodeTailProofRequestedKey = null
        }
    }

    private fun exactEpisodeTailKey(identity: CommittedPageIdentity): ExactEpisodeTailKey? {
        if (identity.normalizedEpisodePath.isEmpty() || identity.manifestPageCount <= 0 ||
            identity.manifestDigest.length != 64 ||
            identity.sourcePageIndex !in 0 until identity.manifestPageCount
        ) return null
        return ExactEpisodeTailKey(
            normalizedEpisodePath = identity.normalizedEpisodePath,
            manifestDigest = identity.manifestDigest,
            manifestPageCount = identity.manifestPageCount,
        )
    }

    private fun rememberBlockedForwardIntentLocked(
        target: Float,
        allowBeyondCurrentDocument: Boolean = false,
    ) {
        if (!target.isFinite() || target <= scrollOffset + SCROLL_OFFSET_EPSILON_PX) return
        val now = SystemClock.uptimeMillis()
        val sameLiveGestureIntent = blockedForwardIntentTarget.isFinite() &&
            blockedForwardIntentGestureRevision == physicalGestureRevision &&
            now <= blockedForwardIntentExpiresAtMs &&
            now <= blockedForwardIntentHardExpiresAtMs
        val currentMaximum = maxScrollLocked()
        val maximumTarget = if (allowBeyondCurrentDocument) {
            max(currentMaximum, target)
        } else {
            currentMaximum
        }
        val boundedTarget = target.coerceIn(0f, maximumTarget)
        val accumulatedTarget = accumulateBlockedForwardTarget(
            previousTarget = blockedForwardIntentTarget,
            carriedTarget = blockedForwardIntentGestureCarryTarget,
            gestureBaseOffset = blockedForwardIntentGestureBaseOffset,
            gestureTarget = boundedTarget,
            maximumTarget = maximumTarget,
        )
        blockedForwardIntentTarget = if (
            blockedForwardIntentTarget.isFinite() &&
            blockedForwardIntentGestureRevision == physicalGestureRevision
        ) {
            max(blockedForwardIntentTarget, accumulatedTarget)
        } else {
            accumulatedTarget
        }
        blockedForwardIntentGestureRevision = physicalGestureRevision
        if (!sameLiveGestureIntent) {
            blockedForwardIntentExpiresAtMs = now + BLOCKED_FORWARD_INTENT_TTL_MS
            blockedForwardIntentHardExpiresAtMs = now + BLOCKED_FORWARD_INTENT_MAX_WAIT_MS
        }
        scheduleBlockedForwardIntentExpiryLocked()
    }

    private fun seedPreContentForwardIntentLocked() {
        if (preContentForwardIntentPx <= SCROLL_OFFSET_EPSILON_PX || pages.isEmpty()) return
        rebuildLayoutLocked()
        val maximumTarget = maxScrollLocked()
        val flingTravel = if (preContentForwardVelocityY > minVelocity && maximumTarget > 0f) {
            OverScroller(context).run {
                fling(
                    0,
                    0,
                    0,
                    preContentForwardVelocityY,
                    0,
                    0,
                    0,
                    maximumTarget.toInt(),
                )
                finalY.toFloat()
            }
        } else {
            0f
        }
        // Normal input first applies the finger's drag and then starts OverScroller from that
        // resulting coordinate. Preserve the same sum while content is absent; taking only the
        // larger term shortened a real fast swipe to roughly one viewport.
        val retainedTravel = (preContentForwardIntentPx + flingTravel)
            .coerceAtMost(maximumTarget)
        val target = (scrollOffset + retainedTravel)
            .coerceIn(0f, maxScrollLocked())
        preContentForwardIntentPx = 0f
        preContentForwardVelocityY = 0
        if (target <= scrollOffset + SCROLL_OFFSET_EPSILON_PX) return
        blockedForwardIntentTarget = if (blockedForwardIntentTarget.isFinite()) {
            max(blockedForwardIntentTarget, target)
        } else {
            target
        }
        blockedForwardIntentGestureRevision = physicalGestureRevision
        blockedForwardIntentExpiresAtMs =
            SystemClock.uptimeMillis() + BLOCKED_FORWARD_INTENT_TTL_MS
        blockedForwardIntentHardExpiresAtMs =
            SystemClock.uptimeMillis() + BLOCKED_FORWARD_INTENT_MAX_WAIT_MS
        scheduleBlockedForwardIntentExpiryLocked()
        scheduleBlockedForwardWindowRequestLocked()
        scheduleBlockedForwardIntentResumeLocked()
        Log.d(
            TAG,
            "reader_pre_content_forward_intent_seeded target=${target.toInt()}," +
                "pages=${pages.size}",
        )
    }

    /**
     * Repeated upward swipes are relative movement, even while exact pixels temporarily cap the
     * viewport. Carry the unconsumed target into the new gesture; a reverse drag clears it in
     * [capForwardInputScrollLocked], while an absolute scrollbar seek clears it on DOWN.
     */
    private fun carryBlockedForwardIntentIntoGestureLocked() {
        val now = SystemClock.uptimeMillis()
        if (!blockedForwardIntentTarget.isFinite() || now > blockedForwardIntentExpiresAtMs) {
            if (blockedForwardIntentTarget.isFinite()) clearBlockedForwardIntentLocked()
            blockedForwardIntentGestureCarryTarget = Float.NaN
            blockedForwardIntentGestureBaseOffset = scrollOffset
            return
        }
        blockedForwardIntentGestureCarryTarget = max(
            scrollOffset,
            blockedForwardIntentTarget,
        )
        blockedForwardIntentGestureBaseOffset = scrollOffset
        blockedForwardIntentGestureRevision = physicalGestureRevision
        blockedForwardIntentExpiresAtMs = now + BLOCKED_FORWARD_INTENT_TTL_MS
        blockedForwardIntentHardExpiresAtMs = now + BLOCKED_FORWARD_INTENT_MAX_WAIT_MS
        scheduleBlockedForwardIntentExpiryLocked()
    }

    private fun clearBlockedForwardIntentLocked() {
        mainHandler.removeCallbacks(blockedForwardIntentResumeRunnable)
        mainHandler.removeCallbacks(blockedForwardIntentExpiryRunnable)
        blockedForwardIntentTarget = Float.NaN
        blockedForwardIntentGestureRevision = 0L
        blockedForwardIntentExpiresAtMs = 0L
        blockedForwardIntentHardExpiresAtMs = 0L
        blockedForwardIntentResumePosted = false
        blockedForwardIntentGestureCarryTarget = Float.NaN
        blockedForwardIntentGestureBaseOffset = scrollOffset
    }

    private fun hasLiveBlockedForwardIntentLocked(
        nowMs: Long = SystemClock.uptimeMillis(),
    ): Boolean {
        return blockedForwardIntentTarget.isFinite() &&
            blockedForwardIntentGestureRevision == physicalGestureRevision &&
            (nowMs <= blockedForwardIntentExpiresAtMs ||
                (nowMs < blockedForwardIntentHardExpiresAtMs &&
                    blockedForwardRequestOutstandingLocked())) &&
            blockedForwardIntentTarget > scrollOffset + SCROLL_OFFSET_EPSILON_PX
    }

    private fun scheduleBlockedForwardIntentResumeLocked() {
        if (!blockedForwardIntentTarget.isFinite() || blockedForwardIntentResumePosted) return
        blockedForwardIntentResumePosted = true
        mainHandler.post(blockedForwardIntentResumeRunnable)
    }

    private fun resumeBlockedForwardIntent() {
        val request = synchronized(stateLock) {
            blockedForwardIntentResumePosted = false
            if (!renderRunning || pages.isEmpty() || pointerDown || dragging || !scroller.isFinished) {
                return@synchronized null
            }
            val now = SystemClock.uptimeMillis()
            if (blockedForwardIntentGestureRevision != physicalGestureRevision ||
                blockedForwardIntentExpiredLocked(now)
            ) {
                clearBlockedForwardIntentLocked()
                val stillMoving = isScrollBusyAfterSample(
                    pointerDown = pointerDown,
                    dragging = dragging,
                    scrollerFinished = scroller.isFinished,
                    blockedForwardIntentPending = false,
                )
                return@synchronized setBusyLocked(stillMoving)
            }
            rebuildLayoutLocked()
            if (hasPendingPageResolvesLocked()) applyVisiblePendingDrawableResolvesLocked()
            if (blockedForwardIntentTarget <= scrollOffset + SCROLL_OFFSET_EPSILON_PX) {
                clearBlockedForwardIntentLocked()
                val stillMoving = isScrollBusyAfterSample(
                    pointerDown = pointerDown,
                    dragging = dragging,
                    scrollerFinished = scroller.isFinished,
                    blockedForwardIntentPending = false,
                )
                return@synchronized setBusyLocked(stillMoving)
            }
            val pendingTarget = blockedForwardIntentTarget
            // A delayed drawable-prefix resume is still motion owned by the original physical
            // gesture. It must obey the same exact episode-tail boundary as a live MOVE/fling;
            // otherwise pixels that arrive after finger-up can replay a large accumulated target
            // through an entire successor episode and retire the predecessor before the user ever
            // saw it. A later real gesture may cross only after the ordinary clean-tail proof.
            val episodeTailLimit = physicalEpisodeTailHoldLimitLocked(
                pendingTarget,
                DIRECTION_NEXT,
            )
            val target = blockedForwardResumeTarget(pendingTarget, episodeTailLimit)
            if (target <= scrollOffset + SCROLL_OFFSET_EPSILON_PX) {
                val stoppedAtEpisodeTail = episodeTailLimit != null &&
                    pendingTarget > target + SCROLL_OFFSET_EPSILON_PX
                if (stoppedAtEpisodeTail) {
                    clearBlockedForwardIntentLocked()
                    requestCleanPhysicalEpisodeTailProofLocked(scrollOffset)
                }
                val stillMoving = isScrollBusyAfterSample(
                    pointerDown = pointerDown,
                    dragging = dragging,
                    scrollerFinished = scroller.isFinished,
                    blockedForwardIntentPending = false,
                )
                return@synchronized setBusyLocked(stillMoving)
            }
            val limit = forwardScrollLimitLocked(scheduleBlocked = false)
            val resumedOffset = blockedForwardResumeOffset(
                currentOffset = scrollOffset,
                pendingTarget = target,
                drawableLimit = limit,
            )
            if (
                resumedOffset <= scrollOffset + SCROLL_OFFSET_EPSILON_PX ||
                !drawableViewportCleanAtScrollLocked(resumedOffset)
            ) {
                scheduleBlockedForwardWindowRequestLocked()
                return@synchronized null
            }
            val animatedOffset = min(
                resumedOffset,
                scrollOffset + max(1f, height * BLOCKED_FORWARD_RESUME_MAX_VIEWPORT_FRACTION),
            )
            val distance = animatedOffset - scrollOffset
            val startY = scrollOffset.toInt()
            activeScrollerOffsetShift = scrollOffset - startY
            activeInputDirection = DIRECTION_NEXT
            boundaryArmedDirection = DIRECTION_NEXT
            scroller.startScroll(
                0,
                startY,
                0,
                distance.roundToInt().coerceAtLeast(1),
                blockedForwardResumeDurationMs(distance, max(1, height)),
            )
            val busyRequest = setBusyLocked(true)
            renderRequested = true
            scheduleFrameLocked()
            if (animatedOffset >= target - SCROLL_OFFSET_EPSILON_PX) {
                clearBlockedForwardIntentLocked()
            } else {
                // The absolute gesture deadline was fixed when this intent first met a missing
                // drawable. Progress must not keep extending a finger-up fling indefinitely.
                scheduleBlockedForwardWindowRequestLocked()
            }
            Log.d(
                TAG,
                "reader_forward_cap_resumed to=${animatedOffset.toInt()} " +
                    "target=${target.toInt()} limit=${limit.toInt()}"
            )
            stateLock.notifyAll()
            busyRequest ?: windowRequestLocked(true)
        }
        dispatchWindowRequest(request)
    }

    private fun scheduleBlockedForwardIntentExpiryLocked() {
        mainHandler.removeCallbacks(blockedForwardIntentExpiryRunnable)
        if (!blockedForwardIntentTarget.isFinite()) return
        val delayMs = (blockedForwardIntentExpiresAtMs - SystemClock.uptimeMillis())
            .coerceAtLeast(1L)
        mainHandler.postDelayed(blockedForwardIntentExpiryRunnable, delayMs)
    }

    private fun expireBlockedForwardIntent() {
        val request = synchronized(stateLock) {
            if (!blockedForwardIntentTarget.isFinite()) return@synchronized null
            val now = SystemClock.uptimeMillis()
            if (now < blockedForwardIntentExpiresAtMs) {
                scheduleBlockedForwardIntentExpiryLocked()
                return@synchronized null
            }
            if (!blockedForwardIntentExpiredLocked(now)) return@synchronized null
            clearBlockedForwardIntentLocked()
            val stillMoving = isScrollBusyAfterSample(
                pointerDown = pointerDown,
                dragging = dragging,
                scrollerFinished = scroller.isFinished,
                blockedForwardIntentPending = false,
            )
            setBusyLocked(stillMoving)
        }
        dispatchWindowRequest(request)
    }

    /**
     * A direct image attempt can consume the old 3.5 s soft lease before its fallback transport
     * publishes pixels. Keep the user's already-issued motion alive only while the exact blocked
     * page request is demonstrably outstanding, and never beyond the ordinary 30 s read bound.
     */
    private fun blockedForwardIntentExpiredLocked(nowMs: Long): Boolean {
        if (nowMs <= blockedForwardIntentExpiresAtMs) return false
        val requestOutstanding = blockedForwardRequestOutstandingLocked()
        if (requestOutstanding && nowMs < blockedForwardIntentHardExpiresAtMs) {
            blockedForwardIntentExpiresAtMs = min(
                blockedForwardIntentHardExpiresAtMs,
                nowMs + BLOCKED_FORWARD_INTENT_TTL_MS,
            )
            scheduleBlockedForwardIntentExpiryLocked()
            return false
        }
        return true
    }

    private fun blockedForwardRequestOutstandingLocked(): Boolean {
        if (nextBoundaryAppendInFlight || boundaryDispatchInFlight) return true
        val blocked = blockedForwardTargetPageLocked()
        val blockedPage = pages.getOrNull(blocked) ?: return false
        return blockedPage.loading || blockedPage.pendingResolveType != PENDING_NONE ||
            blocked == lastBlockedForwardPage || blockedForwardDispatchPosted
    }

    private fun shouldLogForwardCapLocked(): Boolean {
        val now = SystemClock.uptimeMillis()
        if (now - lastForwardCapLogMs < FORWARD_CAP_LOG_INTERVAL_MS) return false
        lastForwardCapLogMs = now
        return true
    }

    private fun firstMissingDrawablePageLocked(): Int {
        for (index in pages.indices) {
            if (!pageHasCompleteDrawableContentLocked(index)) return index
        }
        return -1
    }

    private fun blockedForwardTargetPageLocked(): Int {
        if (pages.isEmpty()) return -1
        val visible = firstVisiblePageLocked(scrollOffset).coerceIn(0, pages.lastIndex)
        return (visible..pages.lastIndex).firstOrNull { index ->
            !pageHasCompleteDrawableContentLocked(index)
        } ?: -1
    }

    private fun firstMissingDrawableTopLocked(): Float {
        val page = firstMissingDrawablePageLocked()
        return if (page in pages.indices) pageTopOrElseLocked(page, -1f) else -1f
    }

    private fun drawablePageTopLocked(index: Int): Float {
        return if (index in pages.indices) pageTopOrElseLocked(index, -1f) else -1f
    }

    private fun drawableViewportCleanAtScrollLocked(position: Float): Boolean {
        if (pages.isEmpty() || height <= 0) return false
        val viewBottom = position + height
        var index = firstVisiblePageLocked(position).coerceIn(0, pages.lastIndex)
        while (index > 0 && pageTopOrElseLocked(index, 0f) > position) index--
        var coveredBottom = position
        var sawDrawable = false
        while (index < pages.size) {
            val pageTop = pageTopOrElseLocked(index, 0f)
            val pageBottom = pageTop + pageDrawHeightLocked(pages[index])
            if (pageTop >= viewBottom) break
            if (pageBottom > position && pageTop < viewBottom) {
                if (!pageHasDrawableContentLocked(index)) return false
                val adjacentPrefixBottom = adjacentExactPrefixBottomLocked(index)
                if (adjacentPrefixBottom != null &&
                    min(viewBottom, pageBottom) > adjacentPrefixBottom + COVERAGE_EDGE_FILL_PX
                ) return false
                sawDrawable = true
                coveredBottom = max(
                    coveredBottom,
                    min(viewBottom, min(pageBottom, adjacentPrefixBottom ?: pageBottom)),
                )
                if (coveredBottom >= viewBottom - COVERAGE_EDGE_FILL_PX) return true
            }
            index++
        }
        return sawDrawable && coveredBottom >= viewBottom - COVERAGE_EDGE_FILL_PX
    }

    /** First physical Y not backed by drawable pixels inside [position]'s viewport. */
    private fun firstDrawableViewportGapLocked(position: Float): Float? {
        if (pages.isEmpty() || height <= 0) return position
        val viewportBottom = position + height
        var index = firstVisiblePageLocked(position).coerceIn(0, pages.lastIndex)
        while (index > 0 && pageTopOrElseLocked(index, 0f) > position) index--
        var coveredBottom = position
        while (index < pages.size && coveredBottom < viewportBottom) {
            val pageTop = pageTopOrElseLocked(index, 0f)
            val pageBottom = pageTop + pageDrawHeightLocked(pages[index])
            if (pageTop >= viewportBottom) break
            if (pageBottom > position) {
                if (pageTop > coveredBottom + SCROLL_OFFSET_EPSILON_PX) {
                    return coveredBottom
                }
                if (!pageHasDrawableContentLocked(index)) {
                    return max(position, pageTop)
                }
                val exactBottom = min(
                    pageBottom,
                    adjacentExactPrefixBottomLocked(index) ?: pageBottom,
                )
                val drawableStart = max(position, pageTop)
                if (drawableStart > coveredBottom + SCROLL_OFFSET_EPSILON_PX ||
                    exactBottom <= coveredBottom + SCROLL_OFFSET_EPSILON_PX
                ) {
                    return max(position, min(viewportBottom, pageTop))
                }
                coveredBottom = max(coveredBottom, min(viewportBottom, exactBottom))
            }
            index++
        }
        return coveredBottom.takeIf { it < viewportBottom - SCROLL_OFFSET_EPSILON_PX }
    }

    /**
     * Exact dimensions can shorten a just-entered page while the following page is still empty.
     * That is a structural coordinate correction, not reverse user input: retain the last fully
     * covered viewport instead of submitting a transient black strip.
     */
    private fun repairUnsafeDrawableViewportLocked(reason: String) {
        if (!limitScrollToDrawablePrefix || pages.isEmpty() || height <= 0 ||
            drawableViewportCleanAtScrollLocked(scrollOffset)
        ) return
        val before = scrollOffset
        var candidate = before
        var cleanCandidate: Float? = null
        val repairLogNow = SystemClock.uptimeMillis()
        val shouldLogRepair = Log.isLoggable(TAG, Log.DEBUG) &&
            repairLogNow - lastDrawableViewportRepairLogAtMs >=
            DRAWABLE_VIEWPORT_REPAIR_LOG_INTERVAL_MS
        val repairTrace = if (shouldLogRepair) StringBuilder() else null
        for (attempt in 0 until pages.size + 2) {
            val gap = firstDrawableViewportGapLocked(candidate)
            if (repairTrace != null && repairTrace.length < 2_000) {
                val first = firstVisiblePageLocked(candidate).coerceIn(0, pages.lastIndex)
                val last = firstVisiblePageLocked(
                    (candidate + height.toFloat() - 1f).coerceAtLeast(candidate),
                ).coerceIn(first, pages.lastIndex)
                repairTrace.append("#").append(attempt)
                    .append("@").append(candidate.toInt())
                    .append(" gap=").append(gap?.toInt() ?: -1)
                    .append(" view=").append(first).append('-').append(last)
                for (index in first..last) {
                    val page = pages[index]
                    repairTrace.append(";").append(index)
                        .append("[").append(if (pageHasDrawableContentLocked(index)) 'd' else '-')
                        .append(if (pageHasCompleteDrawableContentLocked(index)) 'c' else '-')
                        .append(",top=").append(pageTopOrElseLocked(index, 0f).toInt())
                        .append(",bottom=").append(
                            (pageTopOrElseLocked(index, 0f) + pageDrawHeightLocked(page)).toInt(),
                        )
                        .append(",prefix=").append(adjacentExactPrefixBottomLocked(index)?.toInt() ?: -1)
                        .append(']')
                }
                repairTrace.append(' ')
            }
            if (gap == null) {
                cleanCandidate = candidate
                break
            }
            if (candidate <= SCROLL_OFFSET_EPSILON_PX) break
            var next = (gap - height).coerceAtLeast(0f)
            if (next >= candidate - SCROLL_OFFSET_EPSILON_PX) {
                next = (candidate - height).coerceAtLeast(0f)
            }
            candidate = next
        }
        val repaired = cleanCandidate ?: candidate.takeIf {
            drawableViewportCleanAtScrollLocked(it)
        } ?: return
        if (repaired >= before - SCROLL_OFFSET_EPSILON_PX) return
        setStructuralScrollOffsetLocked(repaired)
        scheduleBlockedForwardWindowRequestLocked()
        if (shouldLogRepair) {
            lastDrawableViewportRepairLogAtMs = repairLogNow
            Log.d(
                TAG,
                "reader_drawable_viewport_repaired reason=$reason " +
                    "from=${before.toInt()} to=${repaired.toInt()} trace=$repairTrace",
            )
        }
    }

    private fun scheduleBlockedForwardWindowRequestLocked() {
        if (pages.isEmpty() || width <= 0 || height <= 0) return
        val firstBlocked = blockedForwardTargetPageLocked()
        if (firstBlocked !in pages.indices) return
        val now = SystemClock.uptimeMillis()
        if (
            firstBlocked == lastBlockedForwardPage &&
            (blockedForwardDispatchPosted ||
                now - lastBlockedForwardRequestAtMs < BLOCKED_FORWARD_REQUEST_THROTTLE_MS)
        ) {
            return
        }
        lastBlockedForwardPage = firstBlocked
        lastBlockedForwardRequestAtMs = now
        val physicalFirst = firstVisiblePageLocked(scrollOffset).coerceIn(0, pages.lastIndex)
        val physicalLast = firstVisiblePageLocked(
            (scrollOffset + height.toFloat() - 1f).coerceAtLeast(scrollOffset),
        ).coerceIn(physicalFirst, pages.lastIndex)
        val physicalIntent = HostExactHardwareTilePoolPressurePolicy
            .physicalViewportIncludingBlockedForwardBody(
                pageCount = pages.size,
                physicalVisibleFirst = physicalFirst,
                physicalVisibleLast = physicalLast,
                blockedForwardPage = firstBlocked,
            )
        pendingBlockedForwardRequest = WindowRequest(
            firstPage = max(0, firstBlocked - 1),
            lastPage = min(
                pages.lastIndex,
                firstBlocked + max(
                    ReaderPipelinePolicy.windowAfter(true),
                    BLOCKED_FORWARD_RUNWAY_AFTER_PAGES
                )
            ),
            anchorPage = firstBlocked,
            // This range still originates from physical input. It may include the first blocked
            // body after one transition card so pressure retirement cannot deadlock the drawable
            // prefix cap before that body ever reaches the literal viewport.
            physicalFirstPage = physicalIntent[0],
            physicalLastPage = physicalIntent[1],
            progressPage = firstBlocked,
            progressOffset = pageOffsetLocked(firstBlocked),
            busy = true,
            nearStart = false,
            nearEnd = firstBlocked >= pages.size - NEAR_BOUNDARY_PAGE_THRESHOLD,
            notifyNearStart = false,
            notifyNearEnd = firstBlocked >= pages.size - NEAR_BOUNDARY_PAGE_THRESHOLD,
            // This anchor names the first body that stopped a real NEXT drag/fling. The
            // drawable-safety repair may concurrently move the literal viewport back to the
            // preceding clean page; without an explicit direction that structural rollback is
            // later mistaken for user reverse input and churns the strict source priority epoch.
            directionHint = DIRECTION_NEXT,
            blockedForwardPage = firstBlocked,
        )
        if (blockedForwardDispatchPosted) return
        blockedForwardDispatchPosted = true
        val deliver = Runnable {
            val latest = synchronized(stateLock) {
                blockedForwardDispatchPosted = false
                val next = pendingBlockedForwardRequest
                pendingBlockedForwardRequest = null
                next
            } ?: return@Runnable
            deliverWindowRequest(latest)
        }
        if (Looper.myLooper() == Looper.getMainLooper()) {
            mainHandler.post(deliver)
        } else {
            mainHandler.post(deliver)
        }
    }

    private fun markBlockedDrawableResolvedLocked(index: Int) {
        if (index == lastBlockedForwardPage && pageHasCompleteDrawableContentLocked(index)) {
            lastBlockedForwardPage = -1
            lastBlockedForwardRequestAtMs = 0L
        }
        if (pageHasCompleteDrawableContentLocked(index)) {
            scheduleBlockedForwardIntentResumeLocked()
        }
    }

    private fun shouldSuppressDrawablePrefixFlingLocked(wasReleased: Boolean, dragDistance: Float): Boolean {
        if (!wasReleased || !limitScrollToDrawablePrefix || dragDistance <= touchSlop) return false
        if (width <= 0 || height <= 0 || pages.isEmpty()) return false
        if (!hasDrawnContentFrame && !hasAnyDrawableContentLocked()) return false
        if (allPagesHaveDrawableContentLocked()) return false
        return true
    }

    private fun allPagesHaveDrawableContentLocked(): Boolean {
        if (pages.isEmpty()) return false
        for (index in pages.indices) {
            if (!pageHasCompleteDrawableContentLocked(index)) return false
        }
        return true
    }

    private fun boundaryRequestLocked(clearDirection: Boolean = true): BoundaryRequest? {
        if (boundaryDispatchInFlight) return null
        val direction = boundaryArmedDirection
        if (clearDirection) boundaryArmedDirection = 0
        if (direction == 0 || pages.isEmpty() || width <= 0 || height <= 0) return null
        val cappedMaxScroll = maxScrollLocked()
        val fullMaxScroll = max(0f, totalHeightLocked() - height)
        val atStart = scrollOffset <= BOUNDARY_EPSILON_PX
        val atEnd = scrollOffset >= fullMaxScroll - BOUNDARY_EPSILON_PX
        if (direction == DIRECTION_PREVIOUS && atStart &&
            !pageHasCompleteDrawableContentLocked(0)
        ) {
            // Do not cascade A<-B<-C structure prepends while A/page0 is still an empty
            // placeholder. Its warm/window request remains active; the next physical gesture can
            // cross the boundary after the real first image is installed.
            Log.d(TAG, "reader_boundary_previous_blocked_unresolved_head")
            return null
        }
        if (direction == DIRECTION_NEXT && atEnd) {
            armNextBoundaryGeometryHoldLocked(pages.lastIndex)
        }
        if (
            direction == DIRECTION_NEXT &&
            limitScrollToDrawablePrefix &&
            cappedMaxScroll < fullMaxScroll - BOUNDARY_EPSILON_PX
        ) {
            Log.d(
                TAG,
                "reader_boundary_next_blocked_unresolved_tail " +
                    "scroll=${scrollOffset.toInt()} capped=${cappedMaxScroll.toInt()} full=${fullMaxScroll.toInt()}"
            )
            return null
        }
        val request = when {
            direction == DIRECTION_PREVIOUS && atStart -> BoundaryRequest(direction, 0)
            direction == DIRECTION_NEXT && atEnd -> BoundaryRequest(direction, pages.lastIndex)
            else -> null
        }
        if (request != null) boundaryDispatchInFlight = true
        return request
    }

    private fun totalHeightLocked(): Float {
        rebuildLayoutLocked()
        return contentHeight
    }

    private fun pageDrawHeightLocked(page: Page): Float {
        val viewWidth = max(
            1,
            if (width > 0) width else pendingPreparedViewportWidth
        )
        return pageDrawHeightForViewportWidthLocked(page, viewWidth)
    }

    private fun pageDrawHeightForViewportWidthLocked(page: Page, viewportWidth: Int): Float {
        val viewWidth = max(1, viewportWidth)
        if (page.cardText != null) return TRANSITION_CARD_PAGE_HEIGHT_PX
        if (page.errorText != null) return TRANSITION_CARD_PAGE_HEIGHT_PX
        if (page.frozenLayoutRatio.isFinite() && page.frozenLayoutRatio > 0f) {
            return max(1f, viewWidth * page.frozenLayoutRatio)
        }
        if (page.width > 0 && page.height > 0) {
            val drawWidth = viewWidth
            return max(1f, drawWidth * (page.height / page.width.toFloat()))
        }
        return max(1f, viewWidth * page.placeholderRatio)
    }

    private fun captureViewportReflowAnchorLocked(
        oldWidth: Int,
        oldHeight: Int,
    ): ReaderViewportReflowAnchor? {
        if (pages.isEmpty() || oldWidth <= 0 || oldHeight <= 0 || pageTops.size != pages.size) {
            return null
        }
        // onSizeChanged observes the new View width, while pageTops still describe the old layout.
        // Materialize only accumulated deltas and calculate old page heights explicitly from the
        // supplied width so the capture never mixes two coordinate systems.
        materializeLayoutDeltasLocked()
        val probeFraction = PROGRESS_PAGE_PROBE_SCREEN_RATIO
        val probe = scrollOffset + oldHeight * probeFraction
        var low = 0
        var high = pages.lastIndex
        var page = pages.lastIndex
        while (low <= high) {
            val mid = (low + high) ushr 1
            val bottom = pageTops[mid] +
                pageDrawHeightForViewportWidthLocked(pages[mid], oldWidth) + pageGapPx
            if (probe <= bottom) {
                page = mid
                high = mid - 1
            } else {
                low = mid + 1
            }
        }
        val pageTop = pageTops[page]
        val pageHeight = pageDrawHeightForViewportWidthLocked(pages[page], oldWidth)
        return ReaderViewportReflowAnchor(
            page = page,
            pageFraction = ((probe - pageTop) / pageHeight.coerceAtLeast(1f)).coerceIn(0f, 1f),
            viewportProbeFraction = probeFraction,
        )
    }

    private fun newPageLocked(placeholderRatio: Float = placeholderPageHeightRatio): Page {
        return Page(
            placeholderRatio = placeholderRatio.coerceIn(
                MIN_PLACEHOLDER_PAGE_HEIGHT_RATIO,
                MAX_PLACEHOLDER_PAGE_HEIGHT_RATIO
            )
        )
    }

    /** Page-table mutations own [pageBitmapReferences] and must execute under [stateLock]. */
    private fun addPageLocked(page: Page) {
        page.attachDrawableReferences(pageBitmapReferences, pendingResolvePages)
        pages.add(page)
        if (page.frozenLayoutRatio.isFinite()) deferredLayoutGeometryPages.add(page)
        pagesAvailableForInput = true
    }

    /** Page-table mutations own [pageBitmapReferences] and must execute under [stateLock]. */
    private fun addPageLocked(index: Int, page: Page) {
        page.attachDrawableReferences(pageBitmapReferences, pendingResolvePages)
        pages.add(index, page)
        if (page.frozenLayoutRatio.isFinite()) deferredLayoutGeometryPages.add(page)
        pagesAvailableForInput = true
    }

    /** Page-table mutations own [pageBitmapReferences] and must execute under [stateLock]. */
    private fun removePageAtLocked(index: Int): Page {
        val removed = pages.removeAt(index)
        deferredLayoutGeometryPages.remove(removed)
        removed.detachDrawableReferences()
        pagesAvailableForInput = pages.isNotEmpty()
        return removed
    }

    /** Page-table mutations own [pageBitmapReferences] and must execute under [stateLock]. */
    private fun removePageRangeLocked(startIndex: Int, endExclusive: Int) {
        pages.subList(startIndex, endExclusive).forEach { page ->
            deferredLayoutGeometryPages.remove(page)
            page.detachDrawableReferences()
        }
        pages.subList(startIndex, endExclusive).clear()
        pagesAvailableForInput = pages.isNotEmpty()
    }

    /** Page-table mutations own [pageBitmapReferences] and must execute under [stateLock]. */
    private fun clearPagesLocked() {
        pages.forEach(Page::detachDrawableReferences)
        pages.clear()
        deferredLayoutGeometryPages.clear()
        lifecycleRestoreInputPending = false
        lifecycleViewportAnchorIdentity = null
        lifecycleViewportAnchorPageTopPx = Float.NaN
        pagesAvailableForInput = false
    }

    private fun representativeResolvedPageRatioLocked(): Float {
        if (pages.isEmpty()) {
            return placeholderPageHeightRatio.coerceIn(
                MIN_PLACEHOLDER_PAGE_HEIGHT_RATIO,
                MAX_PLACEHOLDER_PAGE_HEIGHT_RATIO
            )
        }
        val ratios = ArrayList<Float>(pages.size)
        for (page in pages) {
            if (page.cardText != null || page.errorText != null) continue
            if (page.width <= 0 || page.height <= 0) continue
            ratios.add(
                (page.height / page.width.toFloat()).coerceIn(
                    MIN_PLACEHOLDER_PAGE_HEIGHT_RATIO,
                    MAX_PLACEHOLDER_PAGE_HEIGHT_RATIO
                )
            )
        }
        if (ratios.isEmpty()) {
            return placeholderPageHeightRatio.coerceIn(
                MIN_PLACEHOLDER_PAGE_HEIGHT_RATIO,
                MAX_PLACEHOLDER_PAGE_HEIGHT_RATIO
            )
        }
        ratios.sort()
        return ratios[ratios.size / 2]
    }

    private fun resolvedPageDrawHeightLocked(pageWidth: Int, pageHeight: Int): Float {
        val viewWidth = max(1, width)
        if (pageWidth > 0 && pageHeight > 0) {
            val drawWidth = viewWidth
            return max(1f, drawWidth * (pageHeight / pageWidth.toFloat()))
        }
        return max(1f, viewWidth * placeholderPageHeightRatio)
    }

    private fun layoutBoundsForDrawableLocked(page: Page, drawableWidth: Int, drawableHeight: Int): Pair<Int, Int> {
        val safeDrawableWidth = max(1, drawableWidth)
        val safeDrawableHeight = max(1, drawableHeight)
        if (
            page.width > 0 &&
            page.height > 0 &&
            shouldPreserveLayoutBoundsForDrawableLocked(
                page.width,
                page.height,
                safeDrawableWidth,
                safeDrawableHeight
            )
        ) {
            return Pair(page.width, page.height)
        }
        if (
            page.pendingWidth > 0 &&
            page.pendingHeight > 0 &&
            (page.pendingResolveType == PENDING_BOUNDS || page.pendingResolveType == PENDING_SIZE) &&
            shouldPreserveLayoutBoundsForDrawableLocked(
                page.pendingWidth,
                page.pendingHeight,
                safeDrawableWidth,
                safeDrawableHeight
            )
        ) {
            return Pair(page.pendingWidth, page.pendingHeight)
        }
        return Pair(safeDrawableWidth, safeDrawableHeight)
    }

    private fun shouldPreserveLayoutBoundsForDrawableLocked(
        layoutWidth: Int,
        layoutHeight: Int,
        drawableWidth: Int,
        drawableHeight: Int
    ): Boolean {
        if (layoutWidth <= 0 || layoutHeight <= 0 || drawableWidth <= 0 || drawableHeight <= 0) return false
        val layoutRatio = layoutHeight / layoutWidth.toFloat()
        val drawableRatio = drawableHeight / drawableWidth.toFloat()
        val ratioTolerance = max(0.05f, drawableRatio * 0.12f)
        if (abs(layoutRatio - drawableRatio) > ratioTolerance) return false
        val layoutDrawHeight = resolvedPageDrawHeightLocked(layoutWidth, layoutHeight)
        val drawableDrawHeight = resolvedPageDrawHeightLocked(drawableWidth, drawableHeight)
        return layoutDrawHeight + HEIGHT_CHANGE_EPSILON_PX >= drawableDrawHeight
    }

    private fun shouldDeferHeightChangingResolveLocked(
        oldTop: Float,
        oldHeight: Float,
        newHeight: Float,
        hasCurrentDrawable: Boolean
    ): Boolean {
        if (!hasDrawnContentFrame) return false
        if (!isScrollMovingLocked()) return false
        if (oldHeight <= 0f || abs(newHeight - oldHeight) <= HEIGHT_CHANGE_EPSILON_PX) return false
        if (!hasCurrentDrawable) return false
        val viewBottom = scrollOffset + max(1, height)
        if (oldTop >= viewBottom + COVERAGE_EDGE_FILL_PX) return false
        return true
    }

    private fun shouldDeferInitialDrawableSizeLocked(
        oldTop: Float,
        oldHeight: Float,
        newHeight: Float,
        hasCurrentDrawable: Boolean
    ): Boolean {
        if (hasCurrentDrawable) return false
        if (!isRecentGeometrySensitiveScrollLocked()) return false
        if (oldHeight <= 0f || abs(newHeight - oldHeight) <= HEIGHT_CHANGE_EPSILON_PX) return false
        val viewportBottom = scrollOffset + max(1, height)
        val oldBottom = oldTop + oldHeight
        if (oldBottom <= scrollOffset - COVERAGE_EDGE_FILL_PX) return true
        return oldBottom > scrollOffset + COVERAGE_EDGE_FILL_PX &&
            oldTop < viewportBottom - COVERAGE_EDGE_FILL_PX
    }

    private fun armNextBoundaryGeometryHoldLocked(anchorPage: Int) {
        rebuildLayoutLocked()
        nextBoundaryAppendInFlight = true
        nextBoundaryHoldUntilMs = SystemClock.uptimeMillis() + NEXT_BOUNDARY_GEOMETRY_HOLD_MS
        nextBoundaryHoldMinScroll = max(nextBoundaryHoldMinScroll, scrollOffset)
        nextBoundaryHoldAnchorPage = anchorPage.coerceIn(0, pages.lastIndex)
    }

    private fun isNextBoundaryGeometryHeldLocked(now: Long = SystemClock.uptimeMillis()): Boolean {
        return nextBoundaryAppendInFlight || now <= nextBoundaryHoldUntilMs
    }

    private fun effectiveMaxScrollLocked(rawMax: Float): Float {
        val nonNegativeRaw = rawMax.coerceAtLeast(0f)
        var effective = nonNegativeRaw
        val now = SystemClock.uptimeMillis()
        if (isNextBoundaryGeometryHeldLocked(now)) {
            val holdMin = nextBoundaryHoldMinScroll.coerceAtLeast(0f)
            if (holdMin <= nonNegativeRaw || drawableViewportCleanAtScrollLocked(holdMin)) {
                effective = max(effective, holdMin)
            }
        }
        return effective
    }

    private fun shouldFreezeGeometryForNextBoundaryLocked(
        index: Int,
        oldTop: Float,
        oldHeight: Float,
        newHeight: Float
    ): Boolean {
        if (!isNextBoundaryGeometryHeldLocked()) return false
        if (abs(newHeight - oldHeight) <= HEIGHT_CHANGE_EPSILON_PX) return false
        val anchor = nextBoundaryHoldAnchorPage.takeIf { it in pages.indices } ?: anchorPageLocked()
        val tailWindowStart = max(0, anchor - 2)
        val oldBottom = oldTop + oldHeight
        return index >= tailWindowStart ||
            oldBottom >= scrollOffset - height ||
            oldTop <= scrollOffset + height * 2f
    }

    private fun isScrollMovingLocked(): Boolean {
        return lastBusy || pointerDown || dragging || !scroller.isFinished || isRecentScrollSettlingLocked()
    }

    private fun clearPendingResolveLocked(
        page: Page,
        retained: Iterable<Bitmap> = emptyList(),
    ) {
        val currentAndRetained = buildList {
            addAll(retained)
            page.bitmap?.let(::add)
            page.tiles.forEach { tile -> add(tile.bitmap) }
        }
        retirePendingPageDrawableLocked(page, currentAndRetained)
        page.pendingResolveType = PENDING_NONE
        page.pendingBitmap = null
        page.pendingTiles = emptyList()
        page.pendingWidth = 0
        page.pendingHeight = 0
    }

    /** Pixel/request lifecycle is independent from the document-layout lifetime. */
    private fun clearDeferredLayoutGeometryLocked(page: Page) {
        page.frozenLayoutRatio = Float.NaN
        deferredLayoutGeometryPages.remove(page)
    }

    /**
     * Freezes only document layout while source dimensions and original proof remain exact.
     * The ordinary pending-resolve pass removes this ratio after all physical motion settles.
     */
    private fun freezeAuthoritativeLayoutUntilInputSettlesLocked(
        page: Page,
        oldDrawHeight: Float,
    ) {
        val viewWidth = max(1, if (width > 0) width else pendingPreparedViewportWidth)
        page.frozenLayoutRatio =
            (oldDrawHeight / viewWidth.toFloat()).coerceAtLeast(1f / viewWidth)
        // Width/height and proof already describe the authoritative source. Register only the
        // deferred document geometry; pixel readiness and forward traversal remain immediate.
        deferredLayoutGeometryPages.add(page)
        schedulePendingResolveRetryLocked(markLayoutDirty = false)
    }

    private fun hasDeferredLayoutGeometryLocked(): Boolean =
        deferredLayoutGeometryPages.isNotEmpty()

    private fun hasAnyDeferredGeometryWorkLocked(): Boolean =
        hasPendingPageResolvesLocked() || hasDeferredLayoutGeometryLocked()

    private fun deferredLayoutGeometryIndexesLocked(): List<Int> {
        if (deferredLayoutGeometryPages.isEmpty()) return emptyList()
        val indexes = ArrayList<Int>(deferredLayoutGeometryPages.size)
        for (page in deferredLayoutGeometryPages) {
            val index = pages.indexOf(page)
            if (index >= 0) indexes.add(index)
        }
        indexes.sort()
        return indexes
    }

    private fun hasPendingPageResolvesLocked(): Boolean {
        return pendingResolvePages.isNotEmpty()
    }

    /**
     * Takes a stable display-order snapshot before applying work because resolving a page removes
     * it from [pendingResolvePages]. This allocates only when real pending work exists; the normal
     * physical-scroll path exits from the registry's O(1) empty check.
     */
    private fun pendingResolveIndexesLocked(drawablesOnly: Boolean = false): List<Int> {
        if (pendingResolvePages.isEmpty()) return emptyList()
        val indexes = ArrayList<Int>(pendingResolvePages.size)
        for (page in pendingResolvePages) {
            if (drawablesOnly &&
                page.pendingResolveType != PENDING_BITMAP &&
                page.pendingResolveType != PENDING_TILES
            ) {
                continue
            }
            val index = pages.indexOf(page)
            if (index >= 0) indexes.add(index)
        }
        indexes.sort()
        return indexes
    }

    private fun isRecentScrollSettlingLocked(): Boolean {
        return lastScrollInteractionMs > 0L &&
            SystemClock.uptimeMillis() - lastScrollInteractionMs <= HEIGHT_CHANGE_SCROLL_ADJUST_QUIET_MS
    }

    private fun schedulePendingResolveRetryLocked(markLayoutDirty: Boolean = true) {
        if (markLayoutDirty) layoutDirty = true
        if (pendingResolveRetryPosted) return
        pendingResolveRetryPosted = true
        mainHandler.postDelayed({
            synchronized(stateLock) {
                pendingResolveRetryPosted = false
                if (!hasAnyDeferredGeometryWorkLocked()) return@synchronized
                renderRequested = true
                scheduleFrameLocked()
                stateLock.notifyAll()
            }
        }, HEIGHT_CHANGE_SCROLL_ADJUST_QUIET_MS + 32L)
    }

    private fun applyPendingPageResolvesLocked(): Boolean {
        if (pages.isEmpty() || !hasAnyDeferredGeometryWorkLocked()) return false
        if (isNextBoundaryGeometryHeldLocked()) {
            if (hasAnyDeferredGeometryWorkLocked()) {
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
            }
            return false
        }
        rebuildLayoutLocked()
        val viewportAnchor = viewportAnchorLocked() ?: return false
        val recentScrollSettling = isRecentScrollSettlingLocked()
        if (recentScrollSettling) {
            if (hasAnyDeferredGeometryWorkLocked()) {
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
            }
            return false
        }
        if (!shouldRestoreAnchorAfterPendingResolves(
                lastBusy = lastBusy,
                pointerDown = pointerDown,
                dragging = dragging,
                scrollerFinished = scroller.isFinished,
                recentScrollSettling = recentScrollSettling
            )
        ) {
            if (hasAnyDeferredGeometryWorkLocked()) {
                schedulePendingResolveRetryLocked(markLayoutDirty = false)
            }
            return false
        }
        var appliedCount = 0
        for (index in deferredLayoutGeometryIndexesLocked()) {
            val page = pages.getOrNull(index) ?: continue
            val oldHeight = pageDrawHeightLocked(page)
            clearDeferredLayoutGeometryLocked(page)
            val newHeight = pageDrawHeightLocked(page)
            updatePageHeightDeltaLocked(index, newHeight - oldHeight)
            appliedCount++
        }
        for (index in pendingResolveIndexesLocked()) {
            if (!shouldApplyPendingPageResolveLocked(index)) continue
            if (applyPendingPageResolveLocked(index)) appliedCount++
        }
        if (appliedCount > 0) {
            structuralScrollAdjustUntilMs = max(
                structuralScrollAdjustUntilMs,
                SystemClock.uptimeMillis() + RESTORE_POSITION_LOCK_MS
            )
            val beforeRestore = scrollOffset
            restoreViewportAnchorLocked(viewportAnchor, "pending_resolve")
            Log.d(
                TAG,
                "reader_pending_resolve_restore applied=$appliedCount anchor=${viewportAnchor.page} " +
                    "anchorOffset=${viewportAnchor.pageTopInViewportPx} " +
                    "from=${beforeRestore.toInt()} to=${scrollOffset.toInt()} " +
                    "lastBusy=$lastBusy pointerDown=$pointerDown dragging=$dragging " +
                    "scrollerFinished=${scroller.isFinished} recentSettling=$recentScrollSettling"
            )
        }
        return appliedCount > 0
    }

    private fun applyVisiblePendingDrawableResolvesLocked(): Boolean {
        if (pages.isEmpty() || pendingResolvePages.isEmpty()) return false
        val hasVisiblePendingDrawable = hasVisiblePendingDrawableWithoutContentLocked()
        if (isNextBoundaryGeometryHeldLocked() && !hasVisiblePendingDrawable) {
            if (hasPendingPageResolvesLocked()) schedulePendingResolveRetryLocked(markLayoutDirty = false)
            return false
        }
        if (shouldDeferVisiblePendingDrawableResolvesLocked()) {
            schedulePendingResolveRetryLocked(markLayoutDirty = false)
            return false
        }
        rebuildLayoutLocked()
        val viewportAnchor = viewportAnchorLocked() ?: return false
        if (isRecentScrollSettlingLocked() && !hasVisiblePendingDrawable) {
            if (hasPendingPageResolvesLocked()) schedulePendingResolveRetryLocked(markLayoutDirty = false)
            return false
        }
        var appliedCount = 0
        for (index in pendingResolveIndexesLocked(drawablesOnly = true)) {
            val page = pages[index]
            if (shouldApplyPendingPageResolveLocked(index) && applyPendingPageResolveLocked(index)) {
                appliedCount++
            }
        }
        if (appliedCount <= 0) return false
        structuralScrollAdjustUntilMs = max(
            structuralScrollAdjustUntilMs,
            SystemClock.uptimeMillis() + RESTORE_POSITION_LOCK_MS
        )
        val beforeRestore = scrollOffset
        restoreViewportAnchorLocked(viewportAnchor, "visible_pending_resolve")
        renderRequested = true
        Log.d(
            TAG,
            "reader_visible_pending_resolve_restore applied=$appliedCount anchor=${viewportAnchor.page} " +
                "anchorOffset=${viewportAnchor.pageTopInViewportPx} " +
                    "from=${beforeRestore.toInt()} to=${scrollOffset.toInt()}"
        )
        return true
    }

    private fun shouldDeferVisiblePendingDrawableResolvesLocked(): Boolean {
        val now = SystemClock.uptimeMillis()
        val activeScroll = lastBusy ||
            pointerDown ||
            dragging ||
            !scroller.isFinished ||
            isRecentScrollStatsActiveLocked(now)
        if (!activeScroll) return false
        if (hasVisiblePendingDrawableWithoutContentLocked()) return false
        return lastVisibleCoverageIsClean()
    }

    private fun hasVisiblePendingDrawableWithoutContentLocked(): Boolean {
        if (pages.isEmpty() || pendingResolvePages.isEmpty() || height <= 0) return false
        rebuildLayoutLocked()
        val viewportTop = scrollOffset
        val viewportBottom = scrollOffset + max(1, height)
        for (index in pendingResolveIndexesLocked(drawablesOnly = true)) {
            val page = pages[index]
            if (page.bitmap != null || page.tiles.isNotEmpty()) continue
            val pageTop = pageTopOrElseLocked(index, 0f)
            val pageBottom = pageTop + pageDrawHeightLocked(page)
            if (
                pageBottom > viewportTop + COVERAGE_EDGE_FILL_PX &&
                pageTop < viewportBottom - COVERAGE_EDGE_FILL_PX
            ) {
                return true
            }
        }
        return false
    }

    private fun shouldApplyPendingPageResolveLocked(index: Int): Boolean {
        val page = pages.getOrNull(index) ?: return false
        if (page.pendingResolveType == PENDING_NONE) return false
        val pageTop = pageTopOrElseLocked(index, 0f)
        val pageBottom = pageTop + pageDrawHeightLocked(page)
        val viewportTop = scrollOffset
        val viewportBottom = scrollOffset + max(1, height)
        val hasCurrentDrawable = page.bitmap != null || page.tiles.isNotEmpty()
        if (
            hasCurrentDrawable &&
            page.pendingResolveType != PENDING_BOUNDS &&
            isRecentGeometrySensitiveScrollLocked() &&
            pageTop < viewportBottom + height
        ) {
            Log.d(
                TAG,
                "reader_pending_resolve_geometry_deferred index=$index top=${pageTop.toInt()} " +
                    "bottom=${pageBottom.toInt()} scroll=${scrollOffset.toInt()} height=$height"
            )
            return false
        }
        val intersectsViewport = pageBottom > viewportTop + COVERAGE_EDGE_FILL_PX &&
            pageTop < viewportBottom - COVERAGE_EDGE_FILL_PX
        if (intersectsViewport) {
            if (
                !hasCurrentDrawable &&
                (page.pendingResolveType == PENDING_BITMAP || page.pendingResolveType == PENDING_TILES)
            ) {
                return true
            }
            Log.d(
                TAG,
                "reader_pending_resolve_visible_deferred index=$index top=${pageTop.toInt()} " +
                    "bottom=${pageBottom.toInt()} scroll=${scrollOffset.toInt()} height=$height"
            )
            return false
        }
        return true
    }

    private fun isRecentGeometrySensitiveScrollLocked(): Boolean {
        val now = SystemClock.uptimeMillis()
        return lastBusy ||
            pointerDown ||
            dragging ||
            !scroller.isFinished ||
            now <= programmaticScrollStatsUntilMs ||
            (lastScrollInteractionMs > 0L &&
                now - lastScrollInteractionMs <= ACTIVE_GEOMETRY_RESOLVE_QUIET_MS)
    }

    private fun shouldDeferOffscreenBoundsOnlyResolveLocked(oldTop: Float): Boolean {
        if (height <= 0) return false
        val viewportBottom = scrollOffset + height
        return oldTop > viewportBottom + height * OFFSCREEN_BOUNDS_ONLY_DEFER_VIEWPORTS
    }

    private fun applyPendingPageResolveLocked(index: Int): Boolean {
        val page = pages.getOrNull(index) ?: return false
        val type = page.pendingResolveType
        if (type == PENDING_NONE) return false
        val oldHeight = pageDrawHeightLocked(page)
        val pendingWidth = page.pendingWidth
        val pendingHeight = page.pendingHeight
        val hasCurrentDrawable = page.bitmap != null || page.tiles.isNotEmpty()
        if (
            hasCurrentDrawable &&
            type != PENDING_BITMAP &&
            type != PENDING_TILES &&
            pendingWidth > 0 &&
            pendingHeight > 0
        ) {
            val pendingDrawHeight = resolvedPageDrawHeightLocked(pendingWidth, pendingHeight)
            if (abs(pendingDrawHeight - oldHeight) <= ACTIVE_DRAWABLE_BOUNDS_DELTA_SUPPRESS_PX) {
                clearPendingResolveLocked(page)
                return false
            }
        }
        when (type) {
            PENDING_SIZE -> {
                if (page.bitmap == null && page.tiles.isEmpty()) {
                    clearPendingResolveLocked(page)
                    return false
                }
            }
            PENDING_BITMAP -> {
                val bitmap = page.pendingBitmap ?: return false
                if (hasSameBitmapIdentity(page, bitmap) &&
                    page.width == max(1, pendingWidth) &&
                    page.height == max(1, pendingHeight) &&
                    !page.loading &&
                    page.cardText == null &&
                    page.errorText == null
                ) {
                    clearPendingResolveLocked(page)
                    return false
                }
                invalidateRetainedPageNodeIfBitmapChanged(index, page, bitmap)
                retireCurrentPageDrawableLocked(page, listOf(bitmap))
                page.bitmap = bitmap
                page.tiles = emptyList()
            }
            PENDING_TILES -> {
                val tiles = page.pendingTiles
                if (hasSameTilesIdentity(page, tiles) &&
                    page.width == max(1, pendingWidth) &&
                    page.height == max(1, pendingHeight) &&
                    !page.loading &&
                    page.cardText == null &&
                    page.errorText == null
                ) {
                    clearPendingResolveLocked(page)
                    return false
                }
                invalidateRetainedPageNodeIfTilesChanged(index, page, tiles)
                retireCurrentPageDrawableLocked(page, tiles.map(ReaderTile::bitmap))
                page.bitmap = null
                page.tiles = tiles
            }
            PENDING_BOUNDS -> {
                if (page.cardText != null || page.errorText != null) {
                    clearPendingResolveLocked(page)
                    return false
                }
            }
        }
        if (type == PENDING_SIZE || type == PENDING_BOUNDS) {
            invalidatePreparedRenderSceneStateLocked()
        }
        page.width = max(1, pendingWidth)
        page.height = max(1, pendingHeight)
        page.loading = false
        page.cardText = null
        page.errorText = null
        clearPendingResolveLocked(page)
        noteResolvedPageAspectLocked(page.width, page.height)
        val newHeight = pageDrawHeightLocked(page)
        updatePageHeightDeltaLocked(index, newHeight - oldHeight)
        return true
    }

    private fun noteResolvedPageAspectLocked(pageWidth: Int, pageHeight: Int) {
        if (pageWidth <= 0 || pageHeight <= 0) return
        val ratio = (pageHeight / pageWidth.toFloat()).coerceIn(
            MIN_PLACEHOLDER_PAGE_HEIGHT_RATIO,
            MAX_PLACEHOLDER_PAGE_HEIGHT_RATIO
        )
        placeholderPageHeightRatio =
            placeholderPageHeightRatio * (1f - PLACEHOLDER_RATIO_LEARNING_RATE) +
                ratio * PLACEHOLDER_RATIO_LEARNING_RATE
    }

    private fun rebuildLayoutLocked() {
        if (!layoutDirty && pageTops.size == pages.size && pageTopDeltas.size == pages.size) return
        if (pageTops.size != pages.size) pageTops = FloatArrayList(pages.size)
        if (pageTopDeltas.size != pages.size) pageTopDeltas = RangeAddPointQuery(pages.size)
        var top = 0f
        for (i in pages.indices) {
            pageTops[i] = top
            top += pageDrawHeightLocked(pages[i]) + pageGapPx
        }
        contentHeight = max(0f, top - pageGapPx)
        pageTopDeltas.clear()
        layoutDirty = false
    }

    private fun appendEmptyPagesLocked(additionalCount: Int) {
        if (additionalCount <= 0) return
        materializeLayoutDeltasLocked()
        val appendedPlaceholderRatio = representativeResolvedPageRatioLocked()
        var top = if (pages.isEmpty()) 0f else contentHeight + pageGapPx
        repeat(additionalCount) {
            val page = newPageLocked(appendedPlaceholderRatio)
            addPageLocked(page)
            if (pageTops.size != pages.size) pageTops = pageTops.copyWithSize(pages.size)
            if (pageTopDeltas.size != pages.size) pageTopDeltas = pageTopDeltas.copyWithSize(pages.size)
            pageTops[pages.lastIndex] = top
            top += pageDrawHeightLocked(page) + pageGapPx
        }
        contentHeight = max(0f, top - pageGapPx)
        layoutDirty = false
    }

    private fun updatePageHeightDeltaLocked(index: Int, delta: Float) {
        if (abs(delta) <= 0.01f) return
        structuralScrollAdjustUntilMs = max(
            structuralScrollAdjustUntilMs,
            SystemClock.uptimeMillis() + RESTORE_POSITION_LOCK_MS
        )
        if (layoutDirty || pageTops.size != pages.size || pageTopDeltas.size != pages.size ||
            index !in pages.indices
        ) {
            // A structural mutation already invalidated the base coordinates. Let its one full
            // rebuild absorb this resolve instead of layering a delta onto an obsolete table.
            layoutDirty = true
            return
        }
        // Every Page freezes its own placeholderRatio when it is created. Resolving this page
        // therefore changes only its height and the tops of the suffix; the learned ratio affects
        // future pages, not existing unresolved geometry. Keep the base array immutable and apply
        // the exact suffix shift through the range-add/point-query tree. This avoids rebuilding all
        // accumulated chapters on the next physical MOVE for every independently resolved image.
        pageTopDeltas.add(index + 1, delta)
        contentHeight = max(0f, contentHeight + delta)
    }

    private fun applyPageHeightChangeLocked(index: Int, oldTop: Float, oldHeight: Float, delta: Float) {
        if (abs(delta) <= 0.01f) return
        structuralScrollAdjustUntilMs = max(
            structuralScrollAdjustUntilMs,
            SystemClock.uptimeMillis() + RESTORE_POSITION_LOCK_MS
        )
        val oldBottom = oldTop + oldHeight
        val recentScrollSettling = isRecentScrollSettlingLocked()
        if (shouldAdjustScrollForChangedPageHeight(
                lastBusy = lastBusy,
                pointerDown = pointerDown,
                dragging = dragging,
                scrollerFinished = scroller.isFinished,
                recentScrollSettling = recentScrollSettling,
                oldBottom = oldBottom,
                scrollOffset = scrollOffset
            )
        ) {
            setStructuralScrollOffsetLocked(scrollOffset + delta)
        }
        updatePageHeightDeltaLocked(index, delta)
    }

    private fun firstVisiblePageLocked(position: Float): Int {
        if (pages.isEmpty()) return 0
        rebuildLayoutLocked()
        var low = 0
        var high = pages.lastIndex
        var result = pages.lastIndex
        while (low <= high) {
            val mid = (low + high) ushr 1
            val bottom = pageTopLocked(mid) + pageDrawHeightLocked(pages[mid]) + pageGapPx
            if (position <= bottom) {
                result = mid
                high = mid - 1
            } else {
                low = mid + 1
            }
        }
        return result
    }

    private fun pageTopLocked(index: Int): Float {
        return pageTops[index] + pageTopDeltas.get(index)
    }

    private fun pageTopOrElseLocked(index: Int, fallback: Float): Float {
        return if (index in 0 until pageTops.size) pageTopLocked(index) else fallback
    }

    private fun materializeLayoutDeltasLocked() {
        if (pageTopDeltas.isEmpty()) return
        for (i in 0 until pageTops.size) {
            pageTops[i] = pageTopLocked(i)
        }
        pageTopDeltas.clear()
    }

    /**
     * Changes only the document coordinate while preserving the same physical viewport. Unlike a
     * user/animation move, a structural rebase may legitimately decrease the numeric offset during
     * an active forward gesture.
     */
    private fun setStructuralScrollOffsetLocked(requested: Float) {
        val before = scrollOffset
        setScrollOffsetLocked(
            requested,
            allowStructuralCoordinateCorrection = true,
        )
        val appliedDelta = scrollOffset - before
        if (abs(appliedDelta) <= SCROLL_OFFSET_EPSILON_PX) return
        // Every live input target is expressed in the same document coordinate as scrollOffset.
        // Rebase all of them atomically with a geometry change; otherwise the next finger sample
        // or scroller tick restores the obsolete coordinate and creates the very jump this method
        // is meant to prevent.
        if (pointerDown || dragging) {
            dragOriginScrollOffset += appliedDelta
        }
        if (!scroller.isFinished) {
            activeScrollerOffsetShift += appliedDelta
        }
        if (blockedForwardIntentTarget.isFinite()) {
            blockedForwardIntentTarget += appliedDelta
        }
        if (blockedForwardIntentGestureCarryTarget.isFinite()) {
            blockedForwardIntentGestureCarryTarget += appliedDelta
        }
    }

    private fun setScrollOffsetLocked(
        requested: Float,
        allowStructuralCoordinateCorrection: Boolean = false
    ) {
        var next = requested
        if (height > 0) {
            val now = SystemClock.uptimeMillis()
            if (scrollOffset > height && next <= SCROLL_OFFSET_EPSILON_PX) {
                Log.w(
                    TAG,
                    "reader_scroll_reset_trace from=${scrollOffset.toInt()} to=${next.toInt()} " +
                        "activeDirection=$activeInputDirection pointer=$pointerDown dragging=$dragging " +
                        "scroller=${!scroller.isFinished}\n${Log.getStackTraceString(Throwable())}"
                )
            }
            val lockedRestoreActive = lockedRestorePage >= 0 &&
                now <= lockedRestoreUntilMs
            if (!allowStructuralCoordinateCorrection &&
                lockedRestoreActive && lockedRestorePage in pages.indices
            ) {
                rebuildLayoutLocked()
                val restoreMin = (pageTopOrElseLocked(lockedRestorePage, 0f) - lockedRestoreOffset)
                    .coerceAtLeast(0f)
                if (scrollOffset >= restoreMin - RESTORE_POSITION_EPSILON_PX && next < restoreMin) {
                    next = restoreMin
                }
            }
            if (
                (activeInputDirection == DIRECTION_NEXT ||
                    ((pointerDown || dragging) && activeInputDirection != DIRECTION_PREVIOUS)) &&
                next < scrollOffset - SCROLL_OFFSET_EPSILON_PX &&
                (pointerDown || dragging || !scroller.isFinished) &&
                !allowStructuralCoordinateCorrection
            ) {
                if (now - lastDirectionClampLogMs >= ACTIVE_DIRECTION_CLAMP_LOG_INTERVAL_MS) {
                    lastDirectionClampLogMs = now
                    Log.d(
                        TAG,
                        "reader_active_forward_backstep_clamped from=${scrollOffset.toInt()} " +
                            "to=${next.toInt()} pointer=$pointerDown dragging=$dragging scroller=${!scroller.isFinished}"
                    )
                }
                next = scrollOffset
            } else if (
                activeInputDirection == DIRECTION_PREVIOUS &&
                next > scrollOffset + SCROLL_OFFSET_EPSILON_PX &&
                (pointerDown || dragging || !scroller.isFinished)
            ) {
                if (now - lastDirectionClampLogMs >= ACTIVE_DIRECTION_CLAMP_LOG_INTERVAL_MS) {
                    lastDirectionClampLogMs = now
                    Log.d(
                        TAG,
                        "reader_active_backward_forwardstep_clamped from=${scrollOffset.toInt()} " +
                            "to=${next.toInt()} pointer=$pointerDown dragging=$dragging scroller=${!scroller.isFinished}"
                    )
                }
                next = scrollOffset
            }
            val delta = next - scrollOffset
            val structuralAdjustActive = now <= structuralScrollAdjustUntilMs
            val programmaticScrollActive = now <= programmaticScrollStatsUntilMs
            val recentUserScrollActive = lastScrollInteractionMs > 0L &&
                now - lastScrollInteractionMs <= HEIGHT_CHANGE_SCROLL_ADJUST_QUIET_MS
            val visibleForJumpCheck = isAttachedToWindow && isShown && windowVisibility == VISIBLE
            if (
                abs(delta) > 0.5f &&
                !lockedRestoreActive &&
                !structuralAdjustActive
            ) {
                lastScrollInteractionMs = now
            }
            if (
                abs(delta) >= height * SCROLL_JUMP_LOG_SCREEN_RATIO &&
                !pointerDown &&
                !dragging &&
                scroller.isFinished &&
                visibleForJumpCheck &&
                !lockedRestoreActive &&
                !structuralAdjustActive &&
                !programmaticScrollActive &&
                !recentUserScrollActive
            ) {
                Log.w(
                    TAG,
                    "reader_scroll_jump delta=${delta.toInt()} from=${scrollOffset.toInt()} to=${next.toInt()} " +
                        "anchor=${if (pages.isEmpty()) -1 else anchorPageLocked()} busy=$lastBusy lockedRestore=$lockedRestorePage"
                )
            }
        }
        val changed = abs(next - scrollOffset) > SCROLL_OFFSET_EPSILON_PX
        scrollOffset = next
        if (changed) {
            markPixelsDirtyLocked(DIRTY_SCROLL)
            if ((inlineRealPixelsOnly || forwardNativeTexturePrewarmEnabled) && pages.isNotEmpty()) {
                val currentAnchor = effectiveNativeTexturePrewarmAnchorLocked(scrollOffset)
                if (currentAnchor != nativeTexturePrewarmAnchorPage) {
                    requestResidentNativeTexturePrewarmLocked()
                }
            }
        }
    }

    private fun directionForDelta(delta: Float): Int {
        return when {
            delta > 0f -> DIRECTION_NEXT
            delta < 0f -> DIRECTION_PREVIOUS
            else -> 0
        }
    }

    private fun shouldDispatchCancelledBoundaryLocked(dragDistance: Float): Boolean {
        val direction = boundaryArmedDirection
        if (direction == 0 || pages.isEmpty() || width <= 0 || height <= 0) return false
        val minDistance = max(
            touchSlop * BOUNDARY_CANCEL_MIN_DRAG_TOUCH_SLOP_MULTIPLIER,
            height * BOUNDARY_CANCEL_MIN_DRAG_SCREEN_RATIO
        )
        if (dragDistance < minDistance) return false
        val maxScroll = maxScrollLocked()
        return when (direction) {
            DIRECTION_PREVIOUS -> scrollOffset <= BOUNDARY_EPSILON_PX
            DIRECTION_NEXT -> scrollOffset >= maxScroll - BOUNDARY_EPSILON_PX
            else -> false
        }
    }

    private fun resetDragTrackingLocked(y: Float) {
        dragOriginY = y
        dragOriginScrollOffset = scrollOffset
    }

    /**
     * Applies the authoritative physical finger position directly. Rendering may coalesce multiple
     * MOVE events into the newest position, but it must never synthesize motion between them.
     */
    private fun applyPhysicalDragPositionLocked(y: Float, eventTimeNs: Long): Boolean {
        val physicalRequestedOffset = dragOriginScrollOffset +
            (dragOriginY - y) * DRAG_SCROLL_MULTIPLIER
        val requestedOffset = carriedForwardDragTarget(
            physicalTarget = physicalRequestedOffset,
            gestureBaseOffset = dragOriginScrollOffset,
            carriedTarget = blockedForwardIntentGestureCarryTarget,
        )
        val direction = directionForDelta(requestedOffset - scrollOffset)
        if (direction == 0) return false
        // Physical intent owns the viewport even when the drawable/document edge prevents this
        // sample from moving a pixel. Late discovery or image delivery must not restore over it.
        clearLockedRestorePositionLocked()
        clearDirectWifiForwardOnlyInitialResumeContractLocked()
        // Record the physical intent before the edge check. A restored rolling reader commonly
        // starts at local scroll offset zero even though earlier source images exist outside the
        // admitted window. Returning here without reverse evidence made that saved floor
        // impossible to reopen; with one resident viewport the next gesture looked frozen too.
        boundaryArmedDirection = direction
        activeInputDirection = direction
        if (direction == DIRECTION_PREVIOUS && pages.isNotEmpty()) {
            val firstVisible = firstVisiblePageLocked(scrollOffset).coerceIn(0, pages.lastIndex)
            pendingReverseWindowFirstPageHint = if (pendingReverseWindowFirstPageHint >= 0) {
                minOf(pendingReverseWindowFirstPageHint, firstVisible)
            } else {
                firstVisible
            }
        }
        if (isAtInputEdgeLocked(direction)) {
            if (direction == DIRECTION_NEXT &&
                physicalRequestedOffset > scrollOffset + SCROLL_OFFSET_EPSILON_PX
            ) {
                // The current table can still end at the outgoing episode while its exact
                // successor is being prepared. Preserve the real remaining finger travel beyond
                // today's maxScroll; publication enlarges the same document and the ordinary
                // drawable/tail gates replay only this gesture-owned distance.
                rememberBlockedForwardIntentLocked(
                    physicalRequestedOffset,
                    allowBeyondCurrentDocument = true,
                )
            }
            if (lifecycleFirstGestureProbeArmed &&
                abs(physicalRequestedOffset - dragOriginScrollOffset) >= 100f
            ) {
                lifecycleFirstGestureProbeArmed = false
                Log.i(
                    "ViewerPerf",
                    "reader_lifecycle_first_input_blocked reason=document_edge," +
                        "scroll=${scrollOffset.toInt()},max=${maxScrollLocked().toInt()}," +
                        "requested=${physicalRequestedOffset.toInt()}",
                )
            }
            return false
        }
        if (!dragging) dragging = true
        setBusyLocked(true)
        lastScrollInteractionMs = (eventTimeNs / NANOS_PER_MILLISECOND)
            .coerceAtLeast(SystemClock.uptimeMillis() - 1L)
        if (dragTargetRevision == Long.MAX_VALUE) {
            dragTargetRevision = 1L
            directCallbackObservedDragTargetRevision = 0L
        } else {
            dragTargetRevision++
        }
        val moved = applyDragOffsetLocked(requestedOffset, physicalRequestedOffset)
        if (lifecycleFirstGestureProbeArmed &&
            abs(physicalRequestedOffset - dragOriginScrollOffset) >= 100f
        ) {
            lifecycleFirstGestureProbeArmed = false
            Log.i(
                "ViewerPerf",
                "reader_lifecycle_first_input_result moved=$moved," +
                    "origin=${dragOriginScrollOffset.toInt()}," +
                    "requested=${physicalRequestedOffset.toInt()}," +
                    "scroll=${scrollOffset.toInt()},max=${maxScrollLocked().toInt()}," +
                    "limit=${forwardScrollLimitLocked(scheduleBlocked = false).toInt()}," +
                    "blocked=${blockedForwardTargetPageLocked()}",
            )
        }
        return moved
    }

    private fun applyDragOffsetLocked(
        requestedOffset: Float,
        physicalGestureTarget: Float = requestedOffset,
    ): Boolean {
        val direction = directionForDelta(requestedOffset - scrollOffset)
        if (direction == 0) return false
        boundaryArmedDirection = direction
        activeInputDirection = direction
        lastScrollInteractionMs = SystemClock.uptimeMillis()
        val before = scrollOffset
        val boundedNext = capForwardInputScrollLocked(
            requestedOffset,
            direction,
            physicalGestureTarget,
        )
        val escapedTailGeometryCorrection =
            NtkPhysicalEpisodeTailHoldPolicy.isEscapedTailGeometryCorrection(
                currentOffset = before,
                boundedOffset = boundedNext,
                holdLimit = physicalEpisodeTailHold?.scrollLimit,
                epsilonPx = SCROLL_OFFSET_EPSILON_PX,
            )
        // A late exact-size resolve can move an episode boundary behind a viewport that reached
        // the old placeholder bottom. physicalEpisodeTailHoldLimitLocked deliberately repairs
        // that escaped crossing, so do not let the generic active-forward backstep guard cancel
        // this one bounded correction. The next no-movement sample still has to produce and pass
        // the ordinary exact clean-tail compositor proof before the successor can be adopted.
        setScrollOffsetLocked(
            boundedNext,
            allowStructuralCoordinateCorrection = escapedTailGeometryCorrection,
        )
        if (!(limitScrollToDrawablePrefix && direction == DIRECTION_NEXT)) {
            clampForwardScrollLocked()
        }
        val moved = abs(scrollOffset - before) > SCROLL_OFFSET_EPSILON_PX
        if (moved) {
            edgeNoMovementStatsSuppressedUntilMs = 0L
            beginPhysicalScrollTraceLocked()
        }
        val tailProofRequired = !moved &&
            requestCleanPhysicalEpisodeTailProofLocked(boundedNext)
        return moved || tailProofRequired
    }

    /** Requests a fresh compositor proof when a gesture is already parked on an exact tail. */
    private fun requestCleanPhysicalEpisodeTailProofLocked(boundedOffset: Float): Boolean {
        val tailProofKey = physicalEpisodeTailHold?.key ?: return false
        if (physicalEpisodeTailProofRequestedKey == tailProofKey ||
            !isCleanPhysicalEpisodeTailHoldAppliedLocked(boundedOffset)
        ) return false
        if (desiredVersion == drawnVersion) advanceDesiredVersionLocked()
        physicalEpisodeTailProofRequestedKey = tailProofKey
        pendingPixelReasons = pendingPixelReasons or DIRTY_ANIMATION
        renderRequested = true
        scheduleFrameLocked()
        beginPhysicalScrollTraceLocked()
        return true
    }

    private fun suppressEdgeNoMovementScrollStatsLocked(nowMs: Long): Boolean {
        if (pages.isEmpty()) return false
        rebuildLayoutLocked()
        if (!isAtInputEdgeLocked(activeInputDirection)) return false
        edgeNoMovementStatsSuppressedUntilMs = max(
            edgeNoMovementStatsSuppressedUntilMs,
            nowMs + PROGRAMMATIC_SCROLL_STATS_RECENT_MS
        )
        programmaticScrollStatsUntilMs = min(programmaticScrollStatsUntilMs, nowMs)
        cancelFrameStatsFinalizeDeadline()
        // Reaching the edge ends pixel movement, but it must not erase the real frames that
        // brought the viewport here. Preserve the completed segment for the telemetry drain.
        if (statsActive) finalizeActiveFrameStatsLocked(log = false)
        return true
    }

    private fun isAtInputEdgeLocked(direction: Int): Boolean {
        if (pages.isEmpty()) return false
        return when (direction) {
            DIRECTION_NEXT -> scrollOffset >= effectiveMaxScrollLocked(maxScrollLocked()) - BOUNDARY_EPSILON_PX
            DIRECTION_PREVIOUS -> scrollOffset <= BOUNDARY_EPSILON_PX
            else -> false
        }
    }

    private fun isNearVisibleLocked(index: Int, extraPages: Int): Boolean {
        if (pages.isEmpty()) return false
        val anchor = anchorPageLocked()
        return index in (anchor - extraPages)..(anchor + extraPages)
    }

    private fun noteInputLocked(event: MotionEvent) {
        HostExactHardwareTilePool.notePhysicalReaderInput()
        statsAwaitingFirstInput = false
        lastScrollInteractionMs = max(lastScrollInteractionMs, SystemClock.uptimeMillis())
        fun addInputTime(uptimeMs: Long) {
            val eventNs = uptimeMsToNanoTime(uptimeMs)
            if (pendingOldestInputNs == 0L || eventNs < pendingOldestInputNs) pendingOldestInputNs = eventNs
            if (eventNs > pendingNewestInputNs) pendingNewestInputNs = eventNs
        }
        for (i in 0 until event.historySize) addInputTime(event.getHistoricalEventTime(i))
        addInputTime(event.eventTime)
        pendingInputEvents++
        pendingHistorySamples += event.historySize
    }

    /** Timing-equivalent counterpart for MOVE samples coalesced by [physicalMoveMailbox]. */
    private fun noteQueuedInputLocked(sample: NtkQueuedPhysicalMove) {
        statsAwaitingFirstInput = false
        lastScrollInteractionMs = max(lastScrollInteractionMs, SystemClock.uptimeMillis())
        val oldestNs = uptimeMsToNanoTime(sample.oldestEventTimeMs)
        val newestNs = uptimeMsToNanoTime(sample.newestEventTimeMs)
        if (pendingOldestInputNs == 0L || oldestNs < pendingOldestInputNs) {
            pendingOldestInputNs = oldestNs
        }
        if (newestNs > pendingNewestInputNs) pendingNewestInputNs = newestNs
        pendingInputEvents += sample.eventCount
        pendingHistorySamples += sample.historySampleCount
    }

    /** Records only input samples whose authoritative position changed reader pixels. */
    private fun notePhysicalPixelInputLocked(
        event: MotionEvent,
        startsContinuousMotion: Boolean = false,
    ) {
        val receivedNs = SystemClock.elapsedRealtimeNanos()
        fun addInputTime(uptimeMs: Long) {
            val eventNs = uptimeMsToElapsedRealtimeNanos(uptimeMs)
            if (pendingPhysicalPixelInputOldestNs == 0L ||
                eventNs < pendingPhysicalPixelInputOldestNs
            ) {
                pendingPhysicalPixelInputOldestNs = eventNs
            }
            if (eventNs > pendingPhysicalPixelInputNewestNs) {
                pendingPhysicalPixelInputNewestNs = eventNs
            }
        }
        for (i in 0 until event.historySize) addInputTime(event.getHistoricalEventTime(i))
        addInputTime(event.eventTime)
        if (pendingPhysicalPixelInputReceivedOldestNs == 0L ||
            receivedNs < pendingPhysicalPixelInputReceivedOldestNs
        ) {
            pendingPhysicalPixelInputReceivedOldestNs = receivedNs
        }
        pendingPhysicalPixelInputReceivedNewestNs = maxOf(
            pendingPhysicalPixelInputReceivedNewestNs,
            receivedNs,
        )
        pendingPhysicalPixelInputStartsContinuousMotion =
            pendingPhysicalPixelInputStartsContinuousMotion || startsContinuousMotion
    }

    private fun noteQueuedPhysicalPixelInputLocked(sample: NtkQueuedPhysicalMove) {
        val oldestNs = uptimeMsToElapsedRealtimeNanos(sample.oldestEventTimeMs)
        val newestNs = uptimeMsToElapsedRealtimeNanos(sample.newestEventTimeMs)
        if (pendingPhysicalPixelInputOldestNs == 0L ||
            oldestNs < pendingPhysicalPixelInputOldestNs
        ) {
            pendingPhysicalPixelInputOldestNs = oldestNs
        }
        if (newestNs > pendingPhysicalPixelInputNewestNs) {
            pendingPhysicalPixelInputNewestNs = newestNs
        }
        if (pendingPhysicalPixelInputReceivedOldestNs == 0L ||
            sample.receivedOldestNanos < pendingPhysicalPixelInputReceivedOldestNs
        ) {
            pendingPhysicalPixelInputReceivedOldestNs = sample.receivedOldestNanos
        }
        pendingPhysicalPixelInputReceivedNewestNs = maxOf(
            pendingPhysicalPixelInputReceivedNewestNs,
            sample.receivedNewestNanos,
        )
    }

    private fun uptimeMsToNanoTime(uptimeMs: Long): Long {
        val nowNs = System.nanoTime()
        val nowUptimeNs = SystemClock.uptimeMillis() * 1_000_000L
        return nowNs - (nowUptimeNs - uptimeMs * 1_000_000L)
    }

    private fun uptimeMsToElapsedRealtimeNanos(uptimeMs: Long): Long {
        val nowElapsedNs = SystemClock.elapsedRealtimeNanos()
        val nowUptimeNs = SystemClock.uptimeMillis() * NANOS_PER_MILLISECOND
        return nowElapsedNs - (nowUptimeNs - uptimeMs * NANOS_PER_MILLISECOND)
    }

    private fun consumePendingPhysicalPixelInputLocked(): PhysicalPixelInputTiming? {
        val oldest = pendingPhysicalPixelInputOldestNs
        val newest = pendingPhysicalPixelInputNewestNs
        val receivedOldest = pendingPhysicalPixelInputReceivedOldestNs
        val receivedNewest = pendingPhysicalPixelInputReceivedNewestNs
        val startsContinuousMotion = pendingPhysicalPixelInputStartsContinuousMotion
        pendingPhysicalPixelInputOldestNs = 0L
        pendingPhysicalPixelInputNewestNs = 0L
        pendingPhysicalPixelInputReceivedOldestNs = 0L
        pendingPhysicalPixelInputReceivedNewestNs = 0L
        pendingPhysicalPixelInputStartsContinuousMotion = false
        if (oldest <= 0L || newest < oldest) return null
        return PhysicalPixelInputTiming(
            oldest,
            newest,
            receivedOldest,
            receivedNewest,
            startsContinuousMotion,
        )
    }

    private fun restorePendingPhysicalPixelInputLocked(input: PhysicalPixelInputTiming?) {
        input ?: return
        pendingPhysicalPixelInputOldestNs = when {
            pendingPhysicalPixelInputOldestNs <= 0L -> input.oldestNs
            else -> minOf(pendingPhysicalPixelInputOldestNs, input.oldestNs)
        }
        pendingPhysicalPixelInputNewestNs = maxOf(
            pendingPhysicalPixelInputNewestNs,
            input.newestNs,
        )
        pendingPhysicalPixelInputReceivedOldestNs = when {
            pendingPhysicalPixelInputReceivedOldestNs <= 0L -> input.receivedOldestNs
            input.receivedOldestNs <= 0L -> pendingPhysicalPixelInputReceivedOldestNs
            else -> minOf(
                pendingPhysicalPixelInputReceivedOldestNs,
                input.receivedOldestNs,
            )
        }
        pendingPhysicalPixelInputReceivedNewestNs = maxOf(
            pendingPhysicalPixelInputReceivedNewestNs,
            input.receivedNewestNs,
        )
        pendingPhysicalPixelInputStartsContinuousMotion =
            pendingPhysicalPixelInputStartsContinuousMotion || input.startsContinuousMotion
    }

    private fun consumePendingInputLocked(): PendingInput? {
        if (pendingInputEvents <= 0 || pendingOldestInputNs <= 0L) return null
        val input = PendingInput(
            oldestNs = pendingOldestInputNs,
            newestNs = pendingNewestInputNs,
            events = pendingInputEvents,
            history = pendingHistorySamples
        )
        pendingOldestInputNs = 0L
        pendingNewestInputNs = 0L
        pendingInputEvents = 0
        pendingHistorySamples = 0
        return input
    }

    private fun recordFrameStats(timing: DrawTiming, active: Boolean) {
        val inputState = synchronized(stateLock) {
            val input = consumePendingInputLocked()
            if (input != null) statsAwaitingFirstInput = false
            input to statsAwaitingFirstInput
        }
        val pendingInput = inputState.first
        val awaitingFirstInput = inputState.second
        if (awaitingFirstInput && pendingInput == null) return
        val coverage = synchronized(stateLock) { lastVisibleCoverageSnapshot }
        if (active) {
            armFrameStatsFinalizeDeadline()
            if (!statsActive) {
                statsActive = true
                clearStatsSamples()
                beginActiveScrollTrace()
            }
            if (timing.posted) {
                val sameMotionSegment = timing.physicalMotionTraceCookie != 0 &&
                    timing.physicalMotionTraceCookie == statsLastCallbackMotionCookie &&
                    timing.physicalGestureRevision == statsLastCallbackGestureRevision
                if (sameMotionSegment && statsLastCallbackStartNs > 0L &&
                    timing.callbackStartNs >= statsLastCallbackStartNs
                ) {
                    statsCallbackSpacingMs.add(
                        nsToMs(timing.callbackStartNs - statsLastCallbackStartNs)
                    )
                }
                if (sameMotionSegment && statsLastPostEndNs > 0L &&
                    timing.postEndNs >= statsLastPostEndNs
                ) {
                    statsPostSpacingMs.add(nsToMs(timing.postEndNs - statsLastPostEndNs))
                }
                if (timing.physicalMotionTraceCookie != 0) {
                    statsLastCallbackStartNs = timing.callbackStartNs
                    statsLastPostEndNs = timing.postEndNs
                    statsLastCallbackGestureRevision = timing.physicalGestureRevision
                    statsLastCallbackMotionCookie = timing.physicalMotionTraceCookie
                }
                statsLockWaitMs.add(timing.lockWaitMs)
                statsDrawMs.add(timing.drawMs)
                statsPostMs.add(timing.postMs)
                statsTotalMs.add(timing.totalMs)
                pendingInput?.let {
                    statsInputOldestMs.add(nsToMs(timing.postEndNs - it.oldestNs))
                    statsInputNewestMs.add(nsToMs(timing.postEndNs - it.newestNs))
                }
                recordPixelMutationFrameStats(timing, coverage)
            } else {
                statsNoCanvasFrames++
            }
            recordFrameCoverageStats(coverage)
            logActiveFrameStatsIfReady()
            return
        }
        if (!statsActive) return
        cancelFrameStatsFinalizeDeadline()
        val snapshot = synchronized(stateLock) {
            finalizeActiveFrameStatsLocked(log = true)
        } ?: return
        logFrameStatsSnapshot(snapshot)
    }

    private fun recordPixelMutationFrameStats(
        timing: DrawTiming,
        coverage: VisibleCoverageSnapshot?
    ) {
        if (timing.mutationWatermark <= 0L) return
        statsMutationOldestToCallbackMs.add(timing.mutationOldestToCallbackMs)
        statsMutationNewestToCallbackMs.add(timing.mutationNewestToCallbackMs)
        statsMutationOldestToPostMs.add(timing.mutationOldestToPostMs)
        statsMutationNewestToPostMs.add(timing.mutationNewestToPostMs)

        val callbackOverBudget = isCausalPixelMutationOverBudget(
            timing.mutationOldestToCallbackMs
        )
        val postOverBudget = isCausalPixelMutationOverBudget(timing.mutationOldestToPostMs)
        if (!callbackOverBudget && !postOverBudget) return
        val phase = if (callbackOverBudget) "callback" else "post"
        val ageMs = if (callbackOverBudget) {
            timing.mutationOldestToCallbackMs
        } else {
            timing.mutationOldestToPostMs
        }
        val nowMs = SystemClock.uptimeMillis()
        if (nowMs - lastPixelMutationGapLogMs < PIXEL_MUTATION_GAP_LOG_INTERVAL_MS) {
            // Every interval remains in the aggregate arrays and therefore in the terminal
            // p95/max/missed-frame evidence. Avoid synchronously formatting and writing a large
            // log line for each animation frame: logcat itself otherwise becomes scroll work.
            suppressedPixelMutationGapLogs++
            return
        }
        val suppressed = suppressedPixelMutationGapLogs
        suppressedPixelMutationGapLogs = 0L
        lastPixelMutationGapLogMs = nowMs
        if (Log.isLoggable(TAG, Log.DEBUG)) {
            Log.d(
                TAG,
                "reader_scroll_callback_gap ms=${fmt(ageMs)} cause=pixel_mutation phase=$phase " +
                "watermark=${timing.mutationWatermark} " +
                "oldestCallbackMs=${fmt(timing.mutationOldestToCallbackMs)} " +
                "newestCallbackMs=${fmt(timing.mutationNewestToCallbackMs)} " +
                "oldestPostMs=${fmt(timing.mutationOldestToPostMs)} " +
                "newestPostMs=${fmt(timing.mutationNewestToPostMs)} " +
                "invalidationCallbackMs=${fmt(timing.invalidationToCallbackMs)} " +
                "invalidationPostMs=${fmt(timing.invalidationToPostMs)} " +
                "suppressedSinceLast=$suppressed " +
                    "coverage=${formatCoverageForGap(coverage)}"
            )
            MainThreadStallMonitor.warn("reader_pixel_mutation_$phase", ageMs)
        }
    }

    private fun logActiveFrameStatsIfReady() {
        val enoughSamples = statsCallbackSpacingMs.size >= MIN_FRAME_SAMPLES ||
            statsPostSpacingMs.size >= MIN_FRAME_SAMPLES ||
            statsTotalMs.size >= MIN_FRAME_SAMPLES
        if (!statsActive || !enoughSamples) return
        val nowMs = SystemClock.uptimeMillis()
        if (isRecentScrollStatsActiveLocked(nowMs)) return
        cancelFrameStatsFinalizeDeadline()
        val snapshot = synchronized(stateLock) {
            finalizeActiveFrameStatsLocked(log = true)
        } ?: return
        logFrameStatsSnapshot(snapshot)
    }

    /**
     * Extends one trailing deadline without removing/reinserting a Handler message per frame.
     * Handler.removeCallbacks performs a linear MessageQueue scan; doing that at native refresh
     * cadence turns any temporary main-thread backlog into an O(queueDepth) feedback loop.
     */
    private fun armFrameStatsFinalizeDeadline() {
        val nowMs = SystemClock.uptimeMillis()
        var reservation = 0L
        val shouldPost = synchronized(stateLock) {
            frameStatsFinalizeDeadlineMs = nowMs + PROGRAMMATIC_SCROLL_STATS_FINALIZE_MS
            if (frameStatsFinalizeScheduled) {
                false
            } else {
                frameStatsFinalizeScheduled = true
                frameStatsFinalizeReservation++
                if (frameStatsFinalizeReservation <= 0L) frameStatsFinalizeReservation = 1L
                reservation = frameStatsFinalizeReservation
                true
            }
        }
        if (!shouldPost) return
        if (!mainHandler.postDelayed(
                { drainFrameStatsFinalizeDeadline(reservation) },
                PROGRAMMATIC_SCROLL_STATS_FINALIZE_MS,
            )
        ) {
            synchronized(stateLock) {
                if (frameStatsFinalizeScheduled &&
                    frameStatsFinalizeReservation == reservation
                ) {
                    frameStatsFinalizeScheduled = false
                    frameStatsFinalizeDeadlineMs = 0L
                }
            }
        }
    }

    private fun drainFrameStatsFinalizeDeadline(reservation: Long) {
        check(Looper.myLooper() == Looper.getMainLooper())
        var repostDelayMs = 0L
        val snapshot = synchronized(stateLock) {
            if (!frameStatsFinalizeScheduled || frameStatsFinalizeReservation != reservation) {
                return@synchronized null
            }
            val remainingMs = frameStatsFinalizeDeadlineMs - SystemClock.uptimeMillis()
            if (remainingMs > 0L) {
                repostDelayMs = remainingMs
                return@synchronized null
            }
            frameStatsFinalizeScheduled = false
            frameStatsFinalizeDeadlineMs = 0L
            finalizeActiveFrameStatsLocked(log = true)
        }
        if (repostDelayMs > 0L) {
            if (!mainHandler.postDelayed(
                    { drainFrameStatsFinalizeDeadline(reservation) },
                    repostDelayMs,
                )
            ) {
                synchronized(stateLock) {
                    if (frameStatsFinalizeReservation == reservation) {
                        frameStatsFinalizeScheduled = false
                        frameStatsFinalizeDeadlineMs = 0L
                    }
                }
            }
            return
        }
        snapshot?.let(::logFrameStatsSnapshot)
    }

    private fun cancelFrameStatsFinalizeDeadline() {
        synchronized(stateLock) {
            if (!frameStatsFinalizeScheduled) return
            frameStatsFinalizeScheduled = false
            frameStatsFinalizeDeadlineMs = 0L
            // Do not scan/remove from the main MessageQueue on the touch hot path. The queued
            // callback carries its reservation and becomes a cheap no-op. A later segment gets a
            // new reservation, so an old callback can never finalize fresh stats prematurely.
            frameStatsFinalizeReservation++
            if (frameStatsFinalizeReservation <= 0L) frameStatsFinalizeReservation = 1L
        }
    }

    /** Must hold [stateLock]. Invalidates even a callback already dequeued by the main Looper. */
    private fun invalidateFrameStatsFinalizeDeadlineLocked() {
        frameStatsFinalizeScheduled = false
        frameStatsFinalizeDeadlineMs = 0L
        // Do not scan/remove from the main MessageQueue on the touch hot path. The queued callback
        // carries its reservation and becomes a cheap no-op. Teardown also advances this identity
        // after its blanket queue removal so reattach can reserve and post a fresh deadline.
        frameStatsFinalizeReservation++
        if (frameStatsFinalizeReservation <= 0L) frameStatsFinalizeReservation = 1L
    }

    private fun finalizeActiveFrameStatsLocked(log: Boolean): FrameStatsSnapshot? {
        if (!statsActive) return lastFrameStatsSnapshot
        val callbackIntervals = statsCallbackSpacingMs.snapshot()
        val postIntervals = statsPostSpacingMs.snapshot()
        val lockWait = statsLockWaitMs.snapshot()
        val draw = statsDrawMs.snapshot()
        val post = statsPostMs.snapshot()
        val total = statsTotalMs.snapshot()
        val renderTotal = statsDrawMs.snapshot()
        val inputOldest = statsInputOldestMs.snapshot()
        val inputNewest = statsInputNewestMs.snapshot()
        val mutationOldestToCallback = statsMutationOldestToCallbackMs.snapshot()
        val mutationNewestToCallback = statsMutationNewestToCallbackMs.snapshot()
        val mutationOldestToPost = statsMutationOldestToPostMs.snapshot()
        val mutationNewestToPost = statsMutationNewestToPostMs.snapshot()
        val noCanvas = statsNoCanvasFrames
        val coalesced = statsCoalescedRequests
        val maxMissingPx = statsMaxMissingPx
        val maxPlaceholderPx = statsMaxPlaceholderPx
        val maxVisibleLoading = statsMaxVisibleLoading
        statsActive = false
        endActiveScrollTrace()
        statsLastCallbackStartNs = 0L
        statsLastPostEndNs = 0L
        statsLastCallbackGestureRevision = 0L
        statsLastCallbackMotionCookie = 0
        statsLastScrollOffset = Float.NaN
        statsMotionStarted = false
        clearStatsSamples()
        if (callbackIntervals.isEmpty() && postIntervals.isEmpty() && total.isEmpty()) return null
        callbackIntervals.sort()
        postIntervals.sort()
        lockWait.sort()
        draw.sort()
        post.sort()
        total.sort()
        renderTotal.sort()
        inputOldest.sort()
        inputNewest.sort()
        mutationOldestToCallback.sort()
        mutationNewestToCallback.sort()
        mutationOldestToPost.sort()
        mutationNewestToPost.sort()
        val nominalBudget = frameBudgetMs()
        val measuredBudget = if (callbackIntervals.size >= MIN_FRAME_SAMPLES) {
            percentile(callbackIntervals, 0.50f).coerceIn(nominalBudget * 0.90f, nominalBudget * 1.25f)
        } else {
            nominalBudget
        }
        val schedulerIntervals = callbackIntervals
        val sampleCount = max(max(schedulerIntervals.size, postIntervals.size), total.size)
        val renderP95ForBudget = percentile(renderTotal, 0.95f)
        val strictOverBudget = if (renderP95ForBudget > SUSTAINED_SLOW_FRAME_LOG_BUDGET_MS) {
            renderTotal.count { it > SUSTAINED_SLOW_FRAME_LOG_BUDGET_MS }
        } else {
            0
        }
        val missedThreshold = measuredBudget * MISSED_VSYNC_FACTOR
        val missedIntervals = schedulerIntervals.count { it > missedThreshold }
        var missedFrames = 0
        for (interval in schedulerIntervals) {
            if (interval > missedThreshold) {
                missedFrames += max(1, kotlin.math.floor(interval / measuredBudget - 1f).toInt())
            }
        }
        val droppedFrames = if (renderP95ForBudget > SUSTAINED_SLOW_FRAME_LOG_BUDGET_MS) {
            renderTotal.count { it > SUSTAINED_SLOW_FRAME_LOG_BUDGET_MS }
        } else {
            0
        }
        var droppedFrameDebt = 0
        if (renderP95ForBudget > SUSTAINED_SLOW_FRAME_LOG_BUDGET_MS) {
            for (duration in renderTotal) droppedFrameDebt += max(0, kotlin.math.floor(duration / SUSTAINED_SLOW_FRAME_LOG_BUDGET_MS).toInt())
        }
        val strictPercent = if (renderTotal.isEmpty()) 0f else strictOverBudget * 100f / renderTotal.size
        val missedPercent = if (schedulerIntervals.isEmpty()) 0f else missedIntervals * 100f / schedulerIntervals.size
        val droppedPercent = if (total.isEmpty()) 0f else droppedFrames * 100f / total.size
        val callbackP95 = percentile(callbackIntervals, 0.95f)
        val callbackMax = maxOrZero(callbackIntervals)
        val prepP95 = percentile(lockWait, 0.95f)
        val prepMax = maxOrZero(lockWait)
        val drawP95 = percentile(draw, 0.95f)
        val drawMax = maxOrZero(draw)
        val totalP95 = percentile(renderTotal, 0.95f)
        val totalMax = maxOrZero(renderTotal)
        val inputOldestP95 = percentile(inputOldest, 0.95f)
        val inputOldestMax = maxOrZero(inputOldest)
        val inputNewestP95 = percentile(inputNewest, 0.95f)
        val inputNewestMax = maxOrZero(inputNewest)
        val mutationCallbackOverBudget = mutationOldestToCallback.count {
            isCausalPixelMutationOverBudget(it)
        }
        val mutationCallbackMax = maxOrZero(mutationOldestToCallback)
        val mutationPostOverBudget = mutationOldestToPost.count {
            isCausalPixelMutationOverBudget(it)
        }
        val mutationPostMax = maxOrZero(mutationOldestToPost)
        val mutationNewestCallbackMax = maxOrZero(mutationNewestToCallback)
        val mutationNewestPostMax = maxOrZero(mutationNewestToPost)
        val snapshot = FrameStatsSnapshot(
            samples = sampleCount,
            strictOverBudget = strictOverBudget,
            missedIntervals = missedIntervals,
            missedFrames = missedFrames,
            droppedFrames = droppedFrames,
            droppedFrameDebt = droppedFrameDebt,
            callbackP95 = callbackP95,
            callbackMax = callbackMax,
            prepP95 = prepP95,
            prepMax = prepMax,
            drawP95 = drawP95,
            drawMax = drawMax,
            totalP95 = totalP95,
            totalMax = totalMax,
            maxMissingPx = maxMissingPx,
            maxPlaceholderPx = maxPlaceholderPx,
            maxVisibleLoading = maxVisibleLoading,
            noCanvas = noCanvas,
            coalesced = coalesced,
            inputFrames = inputNewest.size,
            inputOldestToPostP95 = inputOldestP95,
            inputOldestToPostMax = inputOldestMax,
            inputNewestToPostP95 = inputNewestP95,
            inputNewestToPostMax = inputNewestMax,
            mutationFrames = mutationOldestToCallback.size,
            mutationCallbackOverBudget = mutationCallbackOverBudget,
            mutationCallbackMax = mutationCallbackMax,
            mutationPostOverBudget = mutationPostOverBudget,
            mutationPostMax = mutationPostMax,
            mutationNewestCallbackMax = mutationNewestCallbackMax,
            mutationNewestPostMax = mutationNewestPostMax
        )
        lastFrameStatsSnapshot = snapshot
        if (completedFrameStatsSnapshots.size >= MAX_COMPLETED_FRAME_STATS_SEGMENTS) {
            completedFrameStatsSnapshots.removeFirst()
        }
        completedFrameStatsSnapshots.addLast(snapshot)
        if (log) return snapshot
        return snapshot
    }

    private fun logFrameStatsSnapshot(snapshot: FrameStatsSnapshot) {
        // The snapshot remains in completedFrameStatsSnapshots and is consumed by telemetry/tests.
        // Formatting the full diagnostic below allocates several kilobytes and Log.i synchronously
        // writes it after every short gesture. Repeated flicks can begin while that write is still
        // running, turning the observer into the next frame's stall. Detailed per-segment logging
        // is therefore an explicit developer opt-in, never ordinary reader work.
        if (!Log.isLoggable("ReaderFrameStats", Log.DEBUG)) return
        val nominalBudget = frameBudgetMs()
        val strictPercent = if (snapshot.samples == 0) 0f else snapshot.strictOverBudget * 100f / snapshot.samples
        val missedPercent = if (snapshot.samples == 0) 0f else snapshot.missedIntervals * 100f / snapshot.samples
        val droppedPercent = if (snapshot.samples == 0) 0f else snapshot.droppedFrames * 100f / snapshot.samples
        val renderDropped = snapshot.drawP95 > SUSTAINED_SLOW_FRAME_LOG_BUDGET_MS ||
            snapshot.totalP95 > SUSTAINED_SLOW_FRAME_LOG_BUDGET_MS
        Log.i(
            TAG,
            "${if (renderDropped) "surface_jank_v3" else "surface_frame_stats"} " +
                "samples=${snapshot.samples} nominalBudget=${fmt(nominalBudget)} measuredBudget=${fmt(nominalBudget)} " +
                "strictOverBudget=${snapshot.strictOverBudget} strictPct=${fmt(strictPercent)} " +
                "missedIntervals=${snapshot.missedIntervals} missedFrames=${snapshot.missedFrames} missedPct=${fmt(missedPercent)} " +
                "droppedFrames=${snapshot.droppedFrames} droppedFrameDebt=${snapshot.droppedFrameDebt} droppedPct=${fmt(droppedPercent)} " +
                "callbackP95=${fmt(snapshot.callbackP95)} callbackMax=${fmt(snapshot.callbackMax)} " +
                "prepP95=${fmt(snapshot.prepP95)} prepMax=${fmt(snapshot.prepMax)} " +
                "drawP95=${fmt(snapshot.drawP95)} drawMax=${fmt(snapshot.drawMax)} " +
                "totalP95=${fmt(snapshot.totalP95)} totalMax=${fmt(snapshot.totalMax)} " +
                "inputFrames=${snapshot.inputFrames} " +
                "inputOldestToPostP95=${fmt(snapshot.inputOldestToPostP95)} " +
                "inputOldestToPostMax=${fmt(snapshot.inputOldestToPostMax)} " +
                "inputNewestToPostP95=${fmt(snapshot.inputNewestToPostP95)} " +
                "inputNewestToPostMax=${fmt(snapshot.inputNewestToPostMax)} " +
                "mutationFrames=${snapshot.mutationFrames} " +
                "mutationCallbackOverBudget=${snapshot.mutationCallbackOverBudget} " +
                "mutationCallbackMax=${fmt(snapshot.mutationCallbackMax)} " +
                "mutationPostOverBudget=${snapshot.mutationPostOverBudget} " +
                "mutationPostMax=${fmt(snapshot.mutationPostMax)} " +
                "mutationNewestCallbackMax=${fmt(snapshot.mutationNewestCallbackMax)} " +
                "mutationNewestPostMax=${fmt(snapshot.mutationNewestPostMax)} " +
                "maxMissingPx=${snapshot.maxMissingPx} maxPlaceholderPx=${snapshot.maxPlaceholderPx} " +
                "maxVisibleLoading=${snapshot.maxVisibleLoading} " +
                "noCanvas=${snapshot.noCanvas} coalesced=${snapshot.coalesced} " +
                "surfaceEpoch=${snapshot.surfaceEpoch} frameId=${snapshot.frameId} " +
                "latchProofState=${snapshot.latchProofState} " +
                "logicalUnlatchedSubmissions=${snapshot.logicalUnlatchedSubmissions} " +
                "maxLogicalUnlatchedSubmissions=${snapshot.maxLogicalUnlatchedSubmissions} " +
                "oldestUnlatchedAgeNanos=${snapshot.oldestUnlatchedAgeNanos} " +
                "latchQueryError=${snapshot.latchQueryError} " +
                "latchEvidenceDeadlineNanos=${snapshot.latchEvidenceDeadlineNanos} " +
                "cadenceQualificationFailed=${snapshot.cadenceQualificationFailed} " +
                "causalTimestampIdentityOrOrderInvalidFrames=${snapshot.causalTimestampIdentityOrOrderInvalidFrames} " +
                "causalLatchHorizonViolationFrames=${snapshot.causalLatchHorizonViolationFrames} " +
                "latchLostFrames=${snapshot.latchLostFrames} " +
                "latchInvalidStateFrames=${snapshot.latchInvalidStateFrames} " +
                "latchQueryErrorFrames=${snapshot.latchQueryErrorFrames} " +
                "functionalSubmissionSamples=${snapshot.functionalSubmissionSamples} " +
                "functionalSubmissionP95=${fmt(snapshot.functionalSubmissionP95)} " +
                "functionalSubmissionP99=${fmt(snapshot.functionalSubmissionP99)} " +
                "functionalSubmissionMax=${fmt(snapshot.functionalSubmissionMax)} " +
                "functionalSubmissionMissedFrames=${snapshot.functionalSubmissionMissedFrames} " +
